sout=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$REPO_ROOT/src/lib/smoke-test-nonexistent-$$.ts\"}}" | bash .claude/hooks/check-test-exists.sh 2>/dev/null)
