echo ""
echo "=== bash-safety-warn.sh (lesson-derived patterns) ==="
# FIRE: git add -A
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add -A"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git add -A' → warn" "$out" "parallel-session state risk"
# ⚠️ This section's header is a THEME, not an owner — some arms below drive OTHER hooks. This
# capture names bash-safety-warn.sh explicitly so the parse arm guards the hook it claims to.
sout=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add -A"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>/dev/null)
assert_one_json_doc "PARSE: bash-safety-warn.sh 'git add -A' arm → ONE parseable hookSpecificOutput doc, the advisory's prescription survives" "$sout" 'List explicit paths'

# FIRE: git stash
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git stash"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git stash' → warn" "$out" "parallel-session danger"

# FIRE: git push --force (without --force-with-lease)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git push --force origin main"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git push --force' → warn" "$out" "unsafe"

# SAFE: git push --force-with-lease
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git push --force-with-lease origin main"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'git push --force-with-lease' (allowed variant)" "$out"

# SAFE: ls
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"ls"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'ls'" "$out"

# --- commit seat-attribution arm (2026-08-12). `git log --author` is structurally blind on
# this repo (every seat commits under one identity) so it fails CONFIDENTLY, not emptily. The SAFE
# case is the load-bearing one: a rule says a command-string guard's false positives concentrate
# in contexts that MENTION the pattern instead of running it, and a guard MANUFACTURES those
# (docs, tracker rows, this very file). A quote is not a command boundary, which is what keeps
# the mention silent — if that SAFE assertion ever flips, the arm has started taxing prose.
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git log --author=<user> --oneline"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git log --author=' → warn" "$out" "CANNOT ANSWER SEAT ATTRIBUTION"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git log --oneline --author <user>"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on spaced '--author' after other flags → warn" "$out" "CANNOT ANSWER SEAT ATTRIBUTION"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep '"'"'git log --author'"'"' todo.txt"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE quoted MENTION of the pattern (the FP class)" "$out"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git log --oneline -5"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE ordinary 'git log' with no --author" "$out"

# --- DATE-ORDER arm (2026-09-07): `--author-date-order` is an ORDERING
# flag and a measured NO-OP on this tree (one git identity; byte-identical to plain `git log`), so a seat
# typing it under a "my commits" caption gets the whole fleet under a label reading "mine" — 22 of the
# 50 recorded fires were exactly that, the arm's dominant TRUE positives. A first fold read
# them as false positives, cut them with a boundary and PINNED the silence here; this arm inverts that:
# it must FIRE, and the warn must carry the ordering sentence. RED against BOTH prior hooks — the
# later one is silent, the earlier one fires WITHOUT the sentence.
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git log --author-date-order --oneline -5"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git log --author-date-order' (a no-op ordering flag under a 'mine' caption — 22/50 recorded fires)" "$out" "CANNOT ANSWER SEAT ATTRIBUTION"
assert_contains "FIRE on '--author-date-order' carries the ORDERING-flag sentence (the earlier hook fired without it)" "$out" "ORDERING flag, not a filter"

# --- FIRES LOG arm (2026-08-12). This hook shipped FIVE arms and wrote NO record of any fire,
# so every arm was uncalibratable by construction — per-incident TP/FP classification
# and a fresh-context calibrator both need a corpus, and there was none. These two
# assertions pin that the log WRITES on a fire and stays SILENT on a safe command; without the
# silent half a log that recorded everything would pass just as well.
#
# ⛔ ISOLATED FROM THE PRODUCTION CORPUS (2026-08-13). These two arms ASSERT
# a write, so BASH_SAFETY_NO_LOG=1 would defeat them — they get a REDIRECTED
# CLAUDE_PROJECT_DIR instead, which is what the hook resolves its LOG_DIR from (:216).
# The real fires corpus exists for exactly one purpose — a fresh-context seat doing
# per-incident TP/FP classification — and the record shape is {ts,arm,cmd} with NO
# provenance field, so a fixture is byte-indistinguishable from a real invocation. The
# pollution inflates in the KEEP-THE-ARM direction, which is the bias session-cadence.md
# warns about in the grep-blowup tally. The sibling this hook's own comment says it mirrors
# DOES isolate (GREP_BLOWUP_NO_LOG=1, :3031) — the emit block was copied, the isolation was not.
# A fresh temp dir also makes _bsf_before deterministically 0, so these arms cannot suffer the
# shared-log concurrency fragility that a count over a shared log is exposed to.
_bsf_dir=$(mktemp -d)
_bsf_log="$_bsf_dir/.claude/logs/bash-safety-fires.jsonl"
_bsf_before=0
echo '{"tool_name":"Bash","tool_input":{"command":"git stash"}}' | CLAUDE_PROJECT_DIR="$_bsf_dir" bash .claude/hooks/bash-safety-warn.sh >/dev/null 2>&1
_bsf_fired=$( [ -f "$_bsf_log" ] && wc -l < "$_bsf_log" | tr -d ' ' || echo 0 )
assert_contains "bsf: FIRE appends exactly one record to the fires log" "$(( _bsf_fired - _bsf_before ))" "1"
echo '{"tool_name":"Bash","tool_input":{"command":"ls -la"}}' | CLAUDE_PROJECT_DIR="$_bsf_dir" bash .claude/hooks/bash-safety-warn.sh >/dev/null 2>&1
_bsf_safe=$( [ -f "$_bsf_log" ] && wc -l < "$_bsf_log" | tr -d ' ' || echo 0 )
assert_contains "bsf: SAFE command appends NOTHING (log is not a firehose)" "$(( _bsf_safe - _bsf_fired ))" "0"
rm -rf "$_bsf_dir"

# SAFE: explicit file add (not -A / .)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add src/foo.ts src/bar.ts"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE explicit file 'git add'" "$out"

# zsh word-split trap. Recurring cross-session bug — under
# zsh, `git add $VAR` passes a computed file LIST as ONE pathspec (no IFS split) → nothing
# stages, silently. PROMOTED warn→block 2026-06-29 (the warn fired to stderr but went
# unseen → it recurred). Now in block-dangerous.sh (exit 2 + deny JSON). 3 FIRE + 1
# regression + 4 SAFE (FP guards).
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add $PATHS"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "FIRE 'git add \$VAR' → block exit 2" "2" "$ec"
assert_contains "FIRE 'git add \$VAR' → zsh word-split deny" "$out" "zsh word-split trap"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -o $PATHS -m x"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "FIRE 'git commit -o \$VAR' → block exit 2" "2" "$ec"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git rm $FILES"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "FIRE 'git rm \$VAR' → block exit 2" "2" "$ec"

# REGRESSION (2026-06-29 incident): a quoted var-assignment then `git add $P` on a LATER
# line. Proves block-dangerous's jq-extraction sees PAST the P="…" first-quote (the naive
# grep would truncate there → blind to the very bug that triggered the promotion).
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"P=\"a.md b.md\"\ngit add $P\ngit commit -o $P -m \"msg\""}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "FIRE multi-line 'P=…; git add \$P' (real incident) → block exit 2" "2" "$ec"

# SAFE FP-guards: the correct forms must stay silent (exit 0).
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git status --porcelain | xargs git add"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "SAFE 'xargs git add' → exit 0" "0" "$ec"; assert_empty "SAFE 'xargs git add' → silent" "$out"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add ${(f)MINE}"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "SAFE 'git add \${(f)VAR}' (zsh split) → exit 0" "0" "$ec"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add $(git diff --name-only)"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "SAFE 'git add \$(...)' (command-substitution) → exit 0" "0" "$ec"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"for f in a b; do git add $f; done"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "SAFE per-iteration loop 'for f ...; do git add \$f' → exit 0" "0" "$ec"

# SAFE benign MENTION (command-position guard): a `git add $VAR` inside an echo/doc string
# is NOT command-position → must NOT block (the broad first cut wrongly denied this class,
# blocking the promoting session's own verification echo — 2026-06-29).
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"echo \"docs: git add $X is the zsh bug\""}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "SAFE benign mention 'echo \"... git add \$X ...\"' (not cmd-position) → exit 0" "0" "$ec"

# SAFE arg-scope guard (measured FP 2026-07-13): a literal-path `git add`
# in a compound where the ONLY $VAR belongs to a LATER command. The old [^|]* arg match
# spanned `&&`/`;`, attributing that $ to git add → hard-block FP on an innocent command.
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"git add f2 && git commit -qm c2 && export CLAUDE_PROJECT_DIR=\"$T\""}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ec=$?
assert_eq "SAFE literal 'git add f2 && … && export V=\"\$T\"' (\$VAR in a LATER command) → exit 0" "0" "$ec"
assert_empty "SAFE literal add + later \$VAR → silent" "$out"

# v2.8.6 (2026-04-22): `git commit` pre-commit advisory path must not
# crash. Full FIRE/SAFE coverage for the advisories requires a sandbox git
# fixture (deferred). This is the minimal non-crash assertion that catches
# syntax errors or regex drift that zero the new detection paths silently.
echo '{"tool_name":"Bash","tool_input":{"command":"git commit -m test"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh >/dev/null 2>&1
[ $? -eq 0 ] && pass "v2.8.6 git commit path exits 0 (non-crash)" || fail "v2.8.6 git commit path crashed"

# v1.3 (2026-05-23): git-checkout-path-reverts-uncommitted coverage.
# 6 FIRE cases (each catches a distinct destructive form) + 5 SAFE cases (each
# verifies branch-switching invocations stay silent). Regex changes that zero
# any of these will surface here before they slip past production.
# Match pattern: warn includes literal "git checkout <path>" — the verbatim leading
# phrase of the warn message; resilient against the surrounding prose evolving.

# FIRE: `git checkout .` (reverts every tracked file in cwd)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout ."}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout .' " "$out" "git checkout <path>"

# FIRE: `git checkout -- <path>` (explicit revert form)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout -- .claude/docs/architecture.md"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout -- <path>' " "$out" "git checkout <path>"

# FIRE: `git checkout HEAD -- <path>` (revert from HEAD)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout HEAD -- file.md"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout HEAD -- <path>' " "$out" "git checkout <path>"

# FIRE: `git checkout <path-with-slash>` (path-shaped argument)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout src/lib/foo.ts"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout src/lib/foo.ts' " "$out" "git checkout <path>"

# FIRE: `git checkout <path-with-extension>` (file extension makes it path-shaped)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout .claude/docs/state.md"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout .claude/docs/state.md' " "$out" "git checkout <path>"

# FIRE: `git checkout --` (bare double-dash; explicit revert separator)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout -- ."}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout -- .' " "$out" "git checkout <path>"

# SAFE: `git checkout main` (branch switch, no path)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout main"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'git checkout main' (branch switch)" "$out"

# SAFE: `git checkout -b feature/foo` (new branch creation, even with slash in name)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout -b feature/foo"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'git checkout -b feature/foo' (new branch creation)" "$out"

# SAFE: `git checkout -B existing-branch` (force-update existing branch)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout -B existing-branch"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'git checkout -B existing-branch' (branch force-update)" "$out"

# SAFE: `git checkout HEAD~1` (ref-only checkout, no path)
# ⚠️ KNOWN RESIDUAL, DISCLOSED NOT CLOSED (2026-08-13): this command DETACHES HEAD, so it is a
# genuine member of the shared-HEAD hazard the bare-ref arm below covers — but it is asserted SAFE
# here for the PATH-revert obligation, which it satisfies (nothing is reverted). The two
# obligations disagree on this one input. Closing it means overturning this assertion, which is a
# decision rather than an edit, so the bare-ref arm deliberately matches only hex shas and
# `--detach`. Do not "fix" this by widening the arm without re-ruling this assertion.
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout HEAD~1"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'git checkout HEAD~1' (ref-only, no path)" "$out"

# ── bare-ref checkout arm (DETACHES HEAD; shared-HEAD detachment measured 2026-08-13) ──
# Discriminating pair. The FIRE cases were SILENT before this arm shipped (mutation-proven by
# history against `git show HEAD:.claude/hooks/bash-safety-warn.sh`), and the SAFE cases below
# plus the branch-switch assertions above are what stop the arm over-matching into branch names.
# Match token: "DETACHES HEAD" — the verbatim leading phrase, distinct from the arm's
# "git checkout <path>", so a swap of the two arms' messages cannot pass both blocks.

# FIRE: bare sha — THE EXACT COMMAND that detached the fleet's shared HEAD on 2026-08-13
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout 0123abcde"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout <bare sha>' (shared-HEAD detach)" "$out" "DETACHES HEAD"

# FIRE: bare sha with a chained command (the shape a brief actually prescribes)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout 0123abcde && npm test"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout <sha> && ...' (chained)" "$out" "DETACHES HEAD"

# FIRE: explicit --detach
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout --detach"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE on 'git checkout --detach'" "$out" "DETACHES HEAD"

# SAFE-for-this-arm: a path-shaped checkout must keep the message, NOT the detach one.
# This is the PRECEDENCE assertion — the bare-ref arm is ordered after the path arm on purpose.
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git checkout 0123abcde -- src/lib/foo.ts"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "PRECEDENCE 'git checkout <sha> -- <path>' keeps msg" "$out" "git checkout <path>"

# SAFE: `git checkout v2.8.3` (tag checkout — looks path-shaped due to dot but is a ref)
# NOTE: the regex will currently FIRE on this (false positive — v2.8.3 matches the
# `<path-with-extension>` branch). Acceptable per warn-mode: cost of false positive is
# one stderr message; cost of missing dangerous `git checkout v2.8.3 -- file` is real.
# If tag-checkout becomes a common workflow that triggers noise, tighten the regex.
# This assertion is documentation, not a SAFE expectation: skip explicit check.
# (Leaving the comment in-place so the regex tradeoff is visible to future readers.)

# v1.6: secret-file-read → transcript-leak class.
# A reader (or a `<` redirect) over a live-secret file dumps it to stdout → the session
# transcript + model API, so a credential read that way must be rotated. These asserts
# lock the reader alternation, the redirect clause, the boundary char class,
# and the secret-file pattern set against silent regex degradation. Needle
# "SECRET-FILE READ" is the verbatim warn-message prefix.

# FIRE: baseline reader over .env.local
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat .env.local"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'cat .env.local' → secret-file-read warn" "$out" "SECRET-FILE READ"

# FIRE: reader — od streams bytes to stdout
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"od .env.local"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'od .env.local' (reader) → warn" "$out" "SECRET-FILE READ"

# FIRE: reader + secret file — base64 over .aws/credentials
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"base64 .aws/credentials"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'base64 .aws/credentials' (reader + file) → warn" "$out" "SECRET-FILE READ"

# FIRE: secret file — .npmrc (auth token)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat .npmrc"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'cat .npmrc' (secret file) → warn" "$out" "SECRET-FILE READ"

# FIRE: secret file — id_ecdsa private key
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat id_ecdsa"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'cat id_ecdsa' (secret file) → warn" "$out" "SECRET-FILE READ"

# FIRE: boundary class — single-quoted path
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat '"'"'.env.local'"'"'"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE \"cat '.env.local'\" (single-quote boundary) → warn" "$out" "SECRET-FILE READ"

# FIRE: redirect read — `< file` with NO reader token
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"mapfile < .env.local"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'mapfile < .env.local' (redirect, no reader) → warn" "$out" "SECRET-FILE READ"

# FIRE: redirect substitution form — `$(<file)`
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"echo $(<.env.local)"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_contains "FIRE 'echo \$(<.env.local)' (substitution redirect) → warn" "$out" "SECRET-FILE READ"

# FIRE: quoted-path parse (jq) — this arm's scope is the jq parse of the quoted
# form, so it asserts only where jq is present. Keeps the suite
# green on a jq-less runner.
if command -v jq >/dev/null 2>&1; then
  out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat \".env.local\""}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
  assert_contains "FIRE quoted 'cat \".env.local\"' (jq-parse) → warn" "$out" "SECRET-FILE READ"
else
  pass "quoted-path skipped (jq absent — this arm covers the jq parse only)"
fi

# SAFE: template env files are excluded structurally (no real values)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat .env.example"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'cat .env.example' (template excluded) → silent" "$out"

out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat .env.sample"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'cat .env.sample' (template excluded) → silent" "$out"

# SAFE: a non-secret config file does not match the secret-file pattern
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"cat config/app.json"}}' | BASH_SAFETY_NO_LOG=1 bash .claude/hooks/bash-safety-warn.sh 2>&1)
assert_empty "SAFE 'cat config/app.json' (non-secret) → silent" "$out"

# SAFE: a non-reader op on a secret file (no reader token, no redirect) stays silent
