assert_empty "SAFE '-o' shortform → silent" "$out"

# SAFE: -- pathspec separator (no --only flag but explicit pathspec scopes)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -m \"msg\" -- path/to/file.ts"}}' | COMMIT_PATHSPEC_WARN_FAKE_STAGED_COUNT=5 bash .claude/hooks/commit-pathspec-warn.sh 2>&1)
assert_empty "SAFE '--' pathspec separator → silent" "$out"

# SAFE: --amend (different semantic — amends prior commit, doesn't reabsorb)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit --amend --no-edit"}}' | COMMIT_PATHSPEC_WARN_FAKE_STAGED_COUNT=5 bash .claude/hooks/commit-pathspec-warn.sh 2>&1)
assert_empty "SAFE commit-pathspec-warn: '--amend' with a pathspec → silent" "$out"

# SAFE: single-file commit (staged-count < 2 threshold — small absorption risk)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -m \"msg\""}}' | COMMIT_PATHSPEC_WARN_FAKE_STAGED_COUNT=1 bash .claude/hooks/commit-pathspec-warn.sh 2>&1)
assert_empty "SAFE single-file staged (count=1) → silent" "$out"

# SAFE: not a git commit invocation
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git status --porcelain"}}' | COMMIT_PATHSPEC_WARN_FAKE_STAGED_COUNT=5 bash .claude/hooks/commit-pathspec-warn.sh 2>&1)
assert_empty "SAFE non-commit invocation → silent" "$out"

# SAFE: per-invocation escape via SKIP_COMMIT_PATHSPEC_WARN=1
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -m \"msg\""}}' | SKIP_COMMIT_PATHSPEC_WARN=1 COMMIT_PATHSPEC_WARN_FAKE_STAGED_COUNT=5 bash .claude/hooks/commit-pathspec-warn.sh 2>&1)
assert_empty "SAFE SKIP_COMMIT_PATHSPEC_WARN=1 escape → silent" "$out"


echo ""
echo "=== commit-review-warn.sh (PostToolUse Bash — unreviewed-commit-before-push reminder) ==="
# FIRE: git commit touching src/ + unpushed. The git-state probes (HEAD touched
# src/, unpushed count) are injected via COMMIT_REVIEW_WARN_TEST_SRC=1 since the
# real repo state varies per run (same pattern as commit-pathspec's FAKE count).
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -o -m \"feat\" -- src/foo.ts"}}' | COMMIT_REVIEW_WARN_TEST_SRC=1 bash .claude/hooks/commit-review-warn.sh 2>&1)
assert_contains "FIRE on 'git commit' touching src/ + unpushed → warn" "$out" "commit-review-warn"
assert_contains "FIRE includes the delegate-to-hub suggestion" "$out" "mail-send"
sout=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -o -m \"feat\" -- src/foo.ts"}}' | COMMIT_REVIEW_WARN_TEST_SRC=1 bash .claude/hooks/commit-review-warn.sh 2>/dev/null)
assert_one_json_doc "PARSE: commit-review-warn.sh FIRE arm → ONE parseable hookSpecificOutput doc, the mail-send delegate command survives" "$sout" 'scripts/session-manifest.py mail-send'

# SAFE: --amend (re-touches an already-handled commit)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit --amend --no-edit"}}' | COMMIT_REVIEW_WARN_TEST_SRC=1 bash .claude/hooks/commit-review-warn.sh 2>&1)
assert_empty "SAFE commit-review-warn: '--amend' → silent" "$out"

# SAFE: not a git commit invocation
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git status --porcelain"}}' | COMMIT_REVIEW_WARN_TEST_SRC=1 bash .claude/hooks/commit-review-warn.sh 2>&1)
assert_empty "SAFE non-commit (git status) → silent" "$out"

# SAFE: per-invocation escape via SKIP_COMMIT_REVIEW_WARN=1
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -o -m \"x\" -- src/foo.ts"}}' | COMMIT_REVIEW_WARN_TEST_SRC=1 SKIP_COMMIT_REVIEW_WARN=1 bash .claude/hooks/commit-review-warn.sh 2>&1)
assert_empty "SAFE SKIP_COMMIT_REVIEW_WARN=1 escape → silent" "$out"

# COMMAND POSITION: real commits in every spelling the pre-anchor regex caught
# must still fire (the private-index route is commit-tree + update-ref); a MENTION in prose must not.
while IFS='|' read -r _want _c; do
  _o=$(python3 -c 'import json,sys; print(json.dumps({"tool_name":"Bash","tool_input":{"command":sys.argv[1].replace("\\n","\n")}}))' "$_c" | COMMIT_REVIEW_WARN_TEST_SRC=1 bash .claude/hooks/commit-review-warn.sh 2>/dev/null)
  _got=0; case "$_o" in *commit-review-warn*) _got=1 ;; esac
  assert_eq "commit-review-warn position: [$_c] → fire=$_want" "$_want" "$_got"
done <<'CRW'
1|npx tsc --noEmit && git commit -o -m x -- src/a.ts
1|C=$(git commit-tree "$T" -p "$H0" -F m) && git update-ref HEAD "$C"
1|GIT_INDEX_FILE=/tmp/i git commit -q -F m
1|if [ -s m ]; then true; else git commit --allow-empty -m m; fi
1|printf 'src/a.ts\n' | xargs git commit -m x --
0|python3 scripts/session-manifest.py mail-send --to x <<'EOF'\nplease run git commit -o on it\nEOF
0|grep -n 'git commit' .claude/hooks/commit-review-warn.sh
0|python3 scripts/session-manifest.py mail-send --to x <<'EOF'\ngit commit -o -m x -- a.ts\nEOF
0|cat > /tmp/m.txt <<'EOF'\ngit commit-tree is the private-index route\nEOF
1|bash <<'EOF'\ngit commit -m real\nEOF
CRW

echo ""
echo "=== dup-durable-append-warn.sh (PreToolUse Edit+Bash — durable dup-append guard) ==="
# Fixture: a durable-shaped file (name ends MEMORY.md so DURABLE_RE matches).
# ASCII-only headings (no em-dash) to keep grep -Fx byte-matching robust in CI.
DUP_FX="/tmp/dup-smoke-$$-MEMORY.md"
printf '## 2026-06-10 false-absence corrective write\nbody\n\n## 2026-06-09 in-app notification bell\nother\n' > "$DUP_FX"

# FIRE: Edit re-adds an existing heading (absent from old_string)
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## 2026-06-10 false-absence corrective write\\nre-added\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: Edit re-adds existing heading → warn" "$out" "dup-durable-append-warn:"
assert_contains "FIRE: names the duplicated heading" "$out" " false-absence corrective write"
sout=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## 2026-06-10 false-absence corrective write\\nre-added\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>/dev/null)
assert_one_json_doc "PARSE: dup-durable-append-warn.sh Edit-dup arm → ONE parseable hookSpecificOutput doc, the cross-confirm command survives" "$sout" 'git show HEAD:<file>'

# FIRE: Bash heredoc re-appends an existing entry (the documented MEMORY-append path)
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> $DUP_FX <<EOF\\n\\n## 2026-06-09 in-app notification bell\\nre-appended\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: Bash heredoc re-appends existing entry → warn" "$out" "dup-durable-append-warn:"

# FIRE: the operator is WRAPPED for an inner shell — the silent-miss regression.
# neutralize() blanks `>` inside a TERMINATED quote, so `bash -c "cat >> <router>"` went SILENT
# at HEAD while firing at the parent commit (measured 2026-08-26, four-arm control: plain fired at
# both, quoted fired only at the parent). The header promises the guard degrades to a spurious
# warning and NEVER to a silent miss; this arm is what makes that true rather than stated.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"bash -c \\\"cat >> $DUP_FX\\\" <<EOF\\n\\n## 2026-06-09 in-app notification bell\\nre-appended\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: shell-wrapped append operator still warns (no silent miss)" "$out" "dup-durable-append-warn:"

# SAFE: Edit adds a genuinely-new heading
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## 2026-06-11 a brand new lesson title here\\nbody\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: Edit adds new heading → silent" "$out"

# SAFE: in-place edit of an existing entry (heading in BOTH old + new → not a dup)
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"old_string\":\"## 2026-06-10 false-absence corrective write\\nbody\",\"new_string\":\"## 2026-06-10 false-absence corrective write\\nrevised body\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: in-place edit of existing entry → silent" "$out"

# SAFE: non-durable file path (DURABLE_RE miss)
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"/tmp/src/foo.ts\",\"old_string\":\"a\",\"new_string\":\"## 2026-06-10 false-absence corrective write\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: non-durable file → silent" "$out"

# ── heredoc-stripper regressions ──
# An earlier change stripped heredoc BODIES before target extraction to kill a mention-class FP, and two
# legal shell forms defeated its whole-line exit test. When `inbody` never cleared, every LATER
# command line was dropped from extraction, so a REAL append went SILENT — a false POSITIVE traded
# for two silent false NEGATIVES. Both reproduced before the fold; both must stay caught.
# THE DISCRIMINATING DETAIL: the redirect must be on a line AFTER the heredoc block. A fixture with
# the redirect FIRST passes under the bug (line 1 is read before the stuck state matters) and is
# the vacuous version of this arm — do not "simplify" these by moving the append up.

# FIRE: `<<-EOF` permits a TAB-INDENTED terminator, so `\tEOF` never equalled `EOF`
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat <<-EOF\\n\\ttext\\n\\tEOF\\ncat >> $DUP_FX <<'EOF'\\n\\n## 2026-06-09 in-app notification bell\\nre-appended\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: <<-EOF tab-terminator then real append (silent-miss regression)" "$out" "dup-durable-append-warn:"

# FIRE: `<<<word` is a HERESTRING, not a heredoc — it was misparsed from its 2nd and 3rd `<`
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat <<<word\\ncat >> $DUP_FX <<'EOF'\\n\\n## 2026-06-09 in-app notification bell\\nre-appended\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: herestring then real append (silent-miss regression)" "$out" "dup-durable-append-warn:"

# SAFE: a DOUBLE-quoted delimiter must still strip its body — the charclass accepted only `'`,
# so `<<"EOF"` left the body unstripped and re-opened the mention-class FP by a second route.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> /tmp/notes.md <<\\\"EOF\\\"\\ndocs: cat >> $DUP_FX <<EOF\\n## 2026-06-09 in-app notification bell\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: <<\"EOF\" quoted delimiter, mention only → silent (FP route 2)" "$out"

# SAFE: Write tool intentionally uncovered (full-file overwrite would FP on every heading)
out=$(printf '%s' "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"content\":\"## 2026-06-10 false-absence corrective write\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: Write tool not covered → silent" "$out"

# SAFE: generic short heading ("### Memory Update") is excluded by the specificity filter → ~0 FP
printf '\n### Memory Update\ngeneric section\n' >> "$DUP_FX"
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n### Memory Update\\nanother generic block\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: generic short heading excluded → silent" "$out"

# SAFE: per-invocation escape via SKIP_DUP_DURABLE_WARN=1
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_FX\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## 2026-06-10 false-absence corrective write\\nx\"}}" | SKIP_DUP_DURABLE_WARN=1 bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: SKIP_DUP_DURABLE_WARN=1 escape → silent" "$out"

# ── LIVE APPEND PATH (added 2026-08-06 with the DURABLE_RE fix) ──────────────────
# The two-tier split moved every lesson body OUT of MEMORY.md into MEMORY-ARCHIVE-*.md
# shards + the WATCH-TIER / ADOPTION-QUEUE registers. The prior DURABLE_RE anchored
# `MEMORY\.md$`, matching ONLY the router — the one file the router's own text says
# never receives an append — so the guard was silent on 100% of the live path.
# ⚠ WHY THE ARMS ABOVE COULD NOT CATCH IT: their fixture is named `*-MEMORY.md`, which
# matches the OLD regex and the NEW one alike. The suite reported 568 PASS both before
# and after a guard that was completely silent. A guard's coverage is bounded by its
# fixture NAMES, not by its assertion count — when a real path's SHAPE changes, add a
# fixture with the new shape or the suite keeps certifying the old world.
DUP_SHARD="/tmp/dup-smoke-$$-MEMORY-ARCHIVE-2026-08-02-2026-08-06.md"
printf '## 2026-08-03 a real shard heading\nbody\n\n## 2026-08-04 another\nother\n' > "$DUP_SHARD"
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_SHARD\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## 2026-08-03 a real shard heading\\nre-added\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: dup into a MEMORY-ARCHIVE shard (the LIVE append path) → warn" "$out" "dup-durable-append-warn:"

out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_SHARD\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## L9999 a heading never seen anywhere before\\nbody\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: novel heading in a shard → silent" "$out"

DUP_REG="/tmp/dup-smoke-$$-WATCH-TIER.md"
printf '## 2026-08-01 a watch-tier entry heading\nbody\n\n## 2026-08-02 second entry\nother\n' > "$DUP_REG"
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$DUP_REG\",\"old_string\":\"other\",\"new_string\":\"other\\n\\n## 2026-08-01 a watch-tier entry heading\\nre-added\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: dup into the WATCH-TIER register → warn" "$out" "dup-durable-append-warn:"


# ── ROUTER-APPEND arms (added 2026-08-13) ───────────────────────────────────────
# Guards the SECOND hazard on these same surfaces: an ENTRY appended to a two-tier
# ROUTER instead of its current shard. Everything below a router's
# `ROUTER PREAMBLE ENDS` marker is REGENERATED, so `--roll` deletes such an entry
# and still prints "conservation: OK".
# WHY WRITE-TIME AND NOT JUST `--scan-routers`: six rescue events on five dates in
# the six days AFTER that detector shipped — detection fires when a
# human runs the scan, days later; this fires on the write.
# FIXTURE SHAPE IS DERIVED FROM THE OBLIGATION, not from a filename pattern: the
# router fixture is named *CHANGELOG.md precisely so DURABLE_RE does NOT match it,
# which makes these arms speak only for the router check. It carries a real marker
# line and a real "Appends" pointer to a shard that EXISTS, so the remedy-derivation
# arm below exercises the same path the live message uses.
RTR_SHARD="/tmp/dup-smoke-$$-CHANGELOG-ARCHIVE-2026-08-02-2026-08-13.md"
RTR_FX="/tmp/dup-smoke-$$-CHANGELOG.md"
printf '## 2026-08-01 an older entry that already lives in the shard\nbody\n' > "$RTR_SHARD"
{
  printf '<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\n\n'
  printf '## How this file works\n\n'
  printf -- '- **Appends** - new entries go to the CURRENT shard (`%s`), never to this router.\n\n' "$(basename "$RTR_SHARD")"
  printf '## Current shard - digest index (`%s`)\n\n' "$(basename "$RTR_SHARD")"
  printf -- '- [.] 2026-08-01 an older entry\n'
} > "$RTR_FX"

RTR_ENTRY='## 2026-08-13 wrap deep-pass session smokefix\\n- **New lesson** a brand new lesson body.'

# FIRE: Edit an ENTRY into a ROUTER
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_FX\",\"old_string\":\"x\",\"new_string\":\"$RTR_ENTRY\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: Edit an ENTRY into a ROUTER → warn" "$out" "ROUTER-APPEND"

# FIRE: Bash heredoc append into a ROUTER (the channel the live incidents used)
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> $RTR_FX <<EOF\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: Bash heredoc appends an ENTRY to a ROUTER → warn" "$out" "ROUTER-APPEND"

# FIRE: Write an ENTRY into a ROUTER (matcher was already wired; payload used to fall through)
out=$(printf '%s' "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$RTR_FX\",\"content\":\"$RTR_ENTRY\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: Write an ENTRY into a ROUTER → warn" "$out" "ROUTER-APPEND"

# FIRE: the remedy NAMES the derived current shard (derived + existence-checked,
# never hardcoded; a stale remediation string is the pointer that gets FOLLOWED).
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_FX\",\"old_string\":\"x\",\"new_string\":\"$RTR_ENTRY\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: remedy names the DERIVED current shard" "$out" "$(basename "$RTR_SHARD")"

# SAFE: the SAME entry into the CURRENT SHARD — the correct destination.
# This is the arm that matters most: an unanchored marker-grep matches PROSE ABOUT
# the marker, so a naive detector fires on the one file that SHOULD receive appends.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> $RTR_SHARD <<EOF\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: same entry into the CURRENT SHARD → silent" "$out"

# SAFE: a shard that QUOTES a router preamble inside a ```fence is NOT a router (measured and
# closed 2026-08-14). NOTE WHY THIS ARM EXISTS SEPARATELY FROM THE ONE ABOVE:
# that arm's comment claims to cover "an unanchored marker-grep matches PROSE ABOUT the
# marker", but its fixture ($RTR_SHARD, built at the top of this block) carries NO marker
# line at all — so it passes identically with or without fence-awareness and could never
# witness the defect it names. This fixture puts a REAL column-0 marker inside a fence,
# which is the shape live shards actually have (they carry 4-10 column-0 fences each).
# DISCRIMINATING: pre-fix this arm FIRED, with the remedy naming the very file being
# appended to; every FIRE arm above is unaffected either way.
RTR_FENCED="/tmp/dup-smoke-$$-CHANGELOG-ARCHIVE-2026-08-13-2026-08-14.md"
{
  printf '## 2026-08-13 a shard entry that documents the router shape\n'
  printf 'A two-tier router looks like this:\n\n'
  printf '```markdown\n'
  printf '<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\n'
  printf '```\n\nbody\n'
} > "$RTR_FENCED"
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> $RTR_FENCED <<'EOF'\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: fenced marker does NOT arm a shard as a ROUTER" "$out"

# A second false positive (filed 2026-08-13, closed 2026-08-24). The warning ASSERTS the entry
# landed "below its regeneration marker" and nothing checked it, so an edit into the
# VERBATIM PREAMBLE — above the marker, the one region the regenerator does not touch —
# drew the same warning and sent the author to a shard for an edit that belonged where it
# was. NEEDS ITS OWN FIXTURE: $RTR_FX carries the marker on LINE 1, so it has no preamble
# and cannot express this shape at all. Both arms share one fixture on purpose — the FIRE
# arm is what stops the SAFE arm being vacuous (a fixture that never fires would pass
# whether or not the guard exists). DISCRIMINATING: pre-fix the SAFE arm FIRED.
RTR_PRE="/tmp/dup-smoke-$$-PREAMBLE-CHANGELOG.md"
{
  printf '# meta CHANGELOG - router\n\n'
  printf 'This paragraph is the VERBATIM preamble; the regenerator never rewrites it.\n'
  printf 'ANCHOR-IN-PREAMBLE\n'
  printf '<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\n\n'
  printf -- '- **Appends** - new entries go to the CURRENT shard (`%s`), never to this router.\n' "$(basename "$RTR_SHARD")"
  printf 'ANCHOR-BELOW-MARKER\n'
} > "$RTR_PRE"
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_PRE\",\"old_string\":\"ANCHOR-IN-PREAMBLE\",\"new_string\":\"ANCHOR-IN-PREAMBLE\\n$RTR_ENTRY\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: entry added ABOVE the marker, in the verbatim preamble" "$out"
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_PRE\",\"old_string\":\"ANCHOR-BELOW-MARKER\",\"new_string\":\"ANCHOR-BELOW-MARKER\\n$RTR_ENTRY\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: same fixture, entry added BELOW the marker → warn" "$out" "ROUTER-APPEND"

# FIRE: a SPANNING anchor — old_string starts ABOVE the marker and runs THROUGH it, so the
# added heading lands BELOW. The first predicate compared the anchor's START line and
# went silent here: 8 false negatives, reachable on 12 of the 13 live routers
# (reproduced locally before folding). The two arms above
# CANNOT see this class — both anchor entirely on one side of the marker — which is why it
# needs its own arm rather than a wider fixture. DISCRIMINATING: silent against the first predicate.
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_PRE\",\"old_string\":\"ANCHOR-IN-PREAMBLE\\n<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\",\"new_string\":\"ANCHOR-IN-PREAMBLE\\n<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\\n$RTR_ENTRY\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: SPANNING anchor crosses the marker → warn (not a preamble edit)" "$out" "ROUTER-APPEND"

# FIRE under INHERITED ERREXIT. Line 68 of the hook RESTORES a caller's `set -e`, so every
# grep in that block runs with errexit live — and `grep` exits 1 on no match, which for a
# bare assignment is fatal. Measured: a mid-line anchor (which `grep -Fxn`
# cannot match as a whole line, the COMMON case) took the whole hook to rc=1 with zero
# output and no stderr — a warn-mode guard vanishing silently. Every substitution in that
# block now carries `|| true`. DISCRIMINATING: this arm is EMPTY against the pre-fix hook.
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_PRE\",\"old_string\":\"IN-PREAMBLE\",\"new_string\":\"IN-PREAMBLE\\n$RTR_ENTRY\"}}" | bash -c 'set -e; export SHELLOPTS; exec bash .claude/hooks/dup-durable-append-warn.sh' 2>&1)
assert_contains "FIRE: mid-line anchor under inherited errexit → warn (not a silent rc=1)" "$out" "ROUTER-APPEND"
rm -f "$RTR_PRE"

# MULTI-ROUTER (pre-existing since the guard's birth commit; reproduced + fixed 2026-08-25).
# check_router_append is called once per TARGET and each call scans the WHOLE command, so
# with N router targets: (a) every heading was collected N times — 2 distinct headings
# produced FOUR bullets, and (b) ROUTER_TARGET was last-write-wins, so only the LAST router
# was named and the remedy shard was derived from it. (b) is the harmful half: the warning
# told the author to file the FIRST router's entry into the SECOND router's shard, and the
# named file is the pointer a reader FOLLOWS.
# Two fixtures with DISTINCT headings on purpose — identical headings cannot separate
# "deduped correctly" from "cross-attributed", which is how the duplication hid.
RTR_A="/tmp/dup-smoke-$$-ALPHA-CHANGELOG.md"
RTR_B="/tmp/dup-smoke-$$-BETA-CHANGELOG.md"
RTR_AS="/tmp/dup-smoke-$$-ALPHA-CHANGELOG-ARCHIVE-2026-08-02-2026-08-13.md"
RTR_BS="/tmp/dup-smoke-$$-BETA-CHANGELOG-ARCHIVE-2026-08-02-2026-08-13.md"
printf '## 2026-08-01 older\nbody\n' > "$RTR_AS"
printf '## 2026-08-01 older\nbody\n' > "$RTR_BS"
for _p in "A:$RTR_A:$RTR_AS" "B:$RTR_B:$RTR_BS"; do
  _n="${_p%%:*}"; _rest="${_p#*:}"; _r="${_rest%%:*}"; _s="${_rest#*:}"
  {
    printf '# %s router\n\n' "$_n"
    printf '<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\n\n'
    printf -- '- **Appends** - new entries go to the CURRENT shard (`%s`), never to this router.\n' "$(basename "$_s")"
  } > "$_r"
done
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> $RTR_A <<EOF\\n## 2026-08-25 ALPHA-ONLY entry\\nEOF\\ncat >> $RTR_B <<EOF\\n## 2026-08-25 BETA-ONLY entry\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: multi-router names the FIRST router too (not last-write-wins)" "$out" "$(basename "$RTR_A")"
assert_contains "FIRE: multi-router names the SECOND router" "$out" "$(basename "$RTR_B")"
# ⛔ BOTH shards, not one. This arm was named "EACH router" and asserted only ALPHA's — a
# quantifier its own enumeration refutes, sitting in the arm's own name, and RTR_BS was seeded
# and deleted without ever appearing in an assert. A mutant was built as the MIRROR of the bug this arm
# guards (every shard derived from the FIRST target instead of the last) and ALL FOUR ARMS
# PASSED: both routers named, both shards printing ALPHA, BETA's entry misfiled into ALPHA's
# shard — the same harmful half the fix removed. Reproduced here before folding.
assert_contains "FIRE: multi-router gives EACH router its OWN shard (ALPHA)" "$out" "$(basename "$RTR_AS")"
assert_contains "FIRE: multi-router gives EACH router its OWN shard (BETA — the half that was unasserted)" "$out" "$(basename "$RTR_BS")"
assert_eq "FIRE: multi-router de-duplicates headings (2 distinct, not targets x headings)" "2" "$(printf '%s' "$out" | grep -c '•')"
rm -f "$RTR_A" "$RTR_B" "$RTR_AS" "$RTR_BS"

# SAFE: appends CORRECTLY to the shard while the heredoc BODY quotes a router redirect.
# The first false-positive arm (fresh-context calibration 2026-08-13): target extraction used to read the
# WHOLE command string, so a write-up QUOTING `>> <router>` was flagged against a file the
# command never touches — and the remedy told it to append to the shard it was already
# appending to. Six live files carry that idiom, incl. the documented lesson-append recipe,
# so the FP concentrates in exactly the documentation burst this guard provokes.
# DISCRIMINATING: pre-fix this arm FIRED; the FIRE arms above are unaffected either way,
# so only this one separates "reads the command line" from "reads the whole string".
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat >> $RTR_SHARD <<'EOF'\\n$RTR_ENTRY\\nthe old recipe said: cat >> $RTR_FX\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: heredoc body QUOTES a router redirect → silent" "$out"

# ⛔ ITS OTHER HALF — THE MENTION ON A COMMAND LINE, which looked closed because the arm
# directly above passes. The heredoc stripper never touched command lines, so a payload whose
# first line is `# never do: cat >> <router>` fired ROUTER-APPEND against a router it never
# touched (reproduced at HEAD before the fix). Closed by `neutralize()`, which blanks a `>`
# inside a quoted region or after an unquoted `#` — an OPERATOR-POSITION test, not a filter.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"# never do: cat >> $RTR_FX\\ncat >> $RTR_SHARD <<'EOF'\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: COMMENT on a command line mentions a router redirect → silent (half 2)" "$out"
# ⚠️ THE ARM THAT RULES OUT THE CHEAP FIX. Stripping `#`-comments would pass the arm above and
# STILL fail this one, because a mention sits just as happily in a quoted argument. Both are
# closed by one mechanism only because the test is operator-position rather than location.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"echo \\\"never do: cat >> $RTR_FX\\\"\\ncat >> $RTR_SHARD <<'EOF'\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: QUOTED ARGUMENT mentions a router redirect → silent (kills the #-strip fix)" "$out"
# ⛔ FAIL-SAFE CONTROL, and it is the arm that keeps this fix from becoming a silent miss.
# An UNTERMINATED quote is unparseable, so neutralize() returns the line UNCHANGED and the
# guard degrades to a possible false POSITIVE — never to silence. The asymmetry is the whole
# design: a spurious warning costs one re-read, a missed one costs the entry, because the
# router is regenerated and an append landing there is wiped with no signal.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"echo \\\"unterminated >> quote\\ncat >> $RTR_FX <<'EOF'\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FAIL-SAFE: unterminated quote still FIRES on a genuine router append" "$out" "ROUTER-APPEND"
# ⛔ VARIABLE-TARGET + BODY-FROM-FILE APPENDS (2026-09-25). All 4 entries stranded in one
# expert's memory router on 2026-09-22..24 entered as `M=<router>; cat >> "$M"` or a
# function's `cat <file> >> "$f"`, and this guard was silent on every one: the extracted target was
# the literal `$M`, and a body read from a file carries no heading. DISCRIMINATING: the first three
# FIRE arms were silent before the fix; the SAFE arms pin that resolution is last-assignment-wins
# and that a `>` restore stays heading-gated.
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"M=$RTR_FX; cat >> \\\"\$M\\\" <<'EOF'\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: M=<router>; cat >> \"\$M\" heredoc → warn (variable target resolved)" "$out" "ROUTER-APPEND"
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"cat /tmp/entry.md >> $RTR_FX\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: cat <file> >> <router> — no heading in the command → warn" "$out" "ROUTER-APPEND"
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"f=$RTR_FX; cat /tmp/entry.md >> \\\"\${f}\\\"\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_contains "FIRE: f=<router>; cat <file> >> \"\${f}\" → warn" "$out" "ROUTER-APPEND"
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"M=$RTR_FX; M=$RTR_SHARD; cat >> \\\"\$M\\\" <<'EOF'\\n$RTR_ENTRY\\nEOF\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: variable reassigned router→shard, last assignment wins → silent" "$out"
out=$(printf '%s' "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"git show HEAD:x > $RTR_FX\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: '>' restore of a router with no entry heading → silent" "$out"

# SAFE: a STRUCTURAL router heading is not an entry (date-at-start predicate excludes it)
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_FX\",\"old_string\":\"## How this file works\",\"new_string\":\"## How this file works\\n- a clarification.\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: structural router heading edited → silent" "$out"

# SAFE: in-place edit — heading present in BOTH old and new is not an add
out=$(printf '%s' "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$RTR_FX\",\"old_string\":\"$RTR_ENTRY\",\"new_string\":\"$RTR_ENTRY\\n- extra line\"}}" | bash .claude/hooks/dup-durable-append-warn.sh 2>&1)
assert_empty "SAFE: in-place edit of an existing entry → silent" "$out"

rm -f "$RTR_FX" "$RTR_SHARD"

rm -f "$DUP_FX" "$DUP_SHARD" "$DUP_REG"

