# Owner-cannot-track row: a boundary before "losing (it|track)" and "can't" keeps the row off
# "closing it" / "applicant tracking" (the pre-fix form fired on all four SAFE prompts below), and the
# jq-absent fallback turns a JSON "\n" into a space so a "losing it" after a newline still fires.
# Mutation-checked: drop either boundary -> a SAFE arm reds; drop the `s/\\n/ /g` -> the jq-absent arm reds.
_tim_ct='CORRECTION STREAM IS COVERING FOR'
for _tim_p in "i am losing it here" "i can't follow you" "ok losing track again"; do
  _tim_o=$(printf '{"prompt":"%s"}' "$_tim_p" | bash .claude/hooks/trigger-index-match.sh 2>/dev/null)
  assert_contains "FIRE: owner-cannot-track row on '$_tim_p'" "$_tim_o" "$_tim_ct"
done
for _tim_p in "closing it now" "disclosing it to the team" "applicant tracking system" "a significant track record here"; do
  _tim_o=$(printf '{"prompt":"%s"}' "$_tim_p" | bash .claude/hooks/trigger-index-match.sh 2>/dev/null)
  assert_not_contains "SAFE: owner-cannot-track row stays off a word that only CONTAINS the phrase ('$_tim_p')" "$_tim_o" "$_tim_ct"
done
_tim_bash="$(command -v bash)"; _tim_nojq="$(mktemp -d)"
for _tim_t in cat grep head sed tr sort mktemp python3 rm; do ln -s "$(command -v "$_tim_t")" "$_tim_nojq/$_tim_t"; done
assert_eq "control: jq is NOT on the jq-absent PATH" "" "$(PATH="$_tim_nojq" command -v jq)"
_tim_o=$(printf '{"prompt":"first line\\nlosing it"}' | PATH="$_tim_nojq" "$_tim_bash" .claude/hooks/trigger-index-match.sh 2>/dev/null)
assert_contains "FIRE with jq ABSENT: a newline before 'losing it' reads as a space (grep fallback)" "$_tim_o" "$_tim_ct"
rm -rf "$_tim_nojq"

