# ── FIRES LOG arms for lib/fires-log.sh (2026-09-13)
# block-dangerous.sh and warn-large-tracker-read.sh DENIED and kept no record, so neither could be
# calibrated. Each arm drives a REAL deny and demands exactly ONE record plus the arm that fired. Each call
# UNSETS HOOK_FIRES_LOG_DIR (exported at the top of this suite so fixture arms never reach the real logs) and
# PINS CLAUDE_PROJECT_DIR to a fresh fixture root: a `cd` alone would leave the lib resolving the REAL
# worktree, and the arm would then measure production state while passing (the TENTH vacuous-control way).
# _hfl_fresh_root prints a fresh EMPTY temp dir or nothing: every arm below writes into its root and then
# `rm -rf`s it, and a failed mktemp leaves `cd ""` resolving to the suite cwd — the shared repo.
_hfl_fresh_root() {
  local d
  d=$(cd "$(mktemp -d)" && pwd -P) || return 0
  if [ -n "$d" ] && [ "$d" != "/" ] && [ -d "$d" ] && [ -z "$(ls -A "$d")" ]; then printf '%s' "$d"; fi
}
# _hfl_records <log>: "records=<N> arm=<a> sid=<s> agent_id=<g>", read off the LAST record: the whole verdict an
# arm compares. A key the record LACKS prints `none`, so a missing sid never reads like an empty one.
_hfl_records() {
  python3 -c 'import json, sys
try:
    rows = [r for r in open(sys.argv[1], encoding="utf-8").read().split("\n") if r.strip()]
except OSError:
    rows = []
last = json.loads(rows[-1]) if rows else {}
print("records=%d arm=%s sid=%s agent_id=%s" % (len(rows), last.get("arm", "none"), last.get("sid", "none"), last.get("agent_id", "none")))' "$1" 2>/dev/null
}
_bdf_root=$(_hfl_fresh_root)
_bdf_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_bdf_root" ]; then
  echo '{"session_id":"smoke-sid-bd","agent_id":"smoke-agent-bd","tool_name":"Bash","tool_input":{"command":"git add $PATHS"}}' \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_bdf_root" bash .claude/hooks/block-dangerous.sh >/dev/null 2>&1
  _bdf_rc=$?
  _bdf_got="rc=$_bdf_rc $(_hfl_records "$_bdf_root/.claude/logs/block-dangerous-fires.jsonl")"
  rm -rf "$_bdf_root"
fi
# rc=2 is in the expectation so the arm also proves the deny itself still happened. sid and agent_id must be the
# PAYLOAD's `session_id` and `agent_id`: records without them could not be tied to a session at all (a held item from
# review).
assert_eq "block-dangerous: a DENY appends exactly one fires record, carrying its arm and the payload's session and agent ids" \
  "rc=2 records=1 arm=zsh-wordsplit sid=smoke-sid-bd agent_id=smoke-agent-bd" "$_bdf_got"
unset _bdf_root _bdf_rc _bdf_got
# A block_reason deny records an ASCII SLUG as `arm` and its prose as `reason`, so the counting idiom lib/fires-log.sh
# documents reads it. The grep below IS that idiom. While the prose was the arm, json.dumps stored its em-dash as
# \u2014 and the idiom read 0 on the live records.
_bdslug_root=$(_hfl_fresh_root)
_bdslug_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_bdslug_root" ]; then
  echo '{"session_id":"smoke-sid-slug","tool_name":"Bash","tool_input":{"command":"rm -rf /"}}' \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_bdslug_root" bash .claude/hooks/block-dangerous.sh >/dev/null 2>&1
  _bdslug_rc=$?
  _bdslug_log="$_bdslug_root/.claude/logs/block-dangerous-fires.jsonl"
  _bdslug_got="rc=$_bdslug_rc idiom=$(grep -cF '"arm":"root-wipe"' "$_bdslug_log" 2>/dev/null) reason=$(python3 -c 'import json, sys
r = json.loads(open(sys.argv[1], encoding="utf-8").read().splitlines()[-1])
print("prose" if r.get("reason", "").startswith("rm -rf on root filesystem") else "missing")' "$_bdslug_log" 2>/dev/null)"
  rm -rf "$_bdslug_root"
fi
assert_eq "block-dangerous: a block_reason DENY records an ASCII arm slug the documented counting idiom reads, with the prose in its own key" \
  "rc=2 idiom=1 reason=prose" "$_bdslug_got"
unset _bdslug_root _bdslug_rc _bdslug_log _bdslug_got
# NEGATIVE CONTROL: an ALLOWED command writes no record. Without it, a record written on an
# allow path (the corpus pollution this library exists to prevent) passes every arm above.
_bdsafe_root=$(_hfl_fresh_root)
_bdsafe_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_bdsafe_root" ]; then
  _bdsafe_out=$(echo '{"session_id":"smoke-sid-safe","tool_name":"Bash","tool_input":{"command":"ls -la"}}' \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_bdsafe_root" bash .claude/hooks/block-dangerous.sh 2>/dev/null)
  _bdsafe_rc=$?
  _bdsafe_got="rc=$_bdsafe_rc stdout-bytes=${#_bdsafe_out} fires-logs=$(find "$_bdsafe_root" -name '*-fires.jsonl' 2>/dev/null | wc -l | tr -d ' ')"
  rm -rf "$_bdsafe_root"
fi
assert_eq "block-dangerous: an ALLOWED command writes no fires record (negative control)" \
  "rc=0 stdout-bytes=0 fires-logs=0" "$_bdsafe_got"
unset _bdsafe_root _bdsafe_out _bdsafe_rc _bdsafe_got

# --- block-dangerous: kill-option-order (2026-10-05) ---
# A pkill / pgrep / killall with an option AFTER its pattern. macOS's BSD tools stop option parsing at the
# first pattern, so a sub-agent's `pkill -f cat -U $(id -u) -n` matched 'cat', '-U', '501' and '-n' as four
# patterns and SIGTERMed most of the machine. The arm is a PARSER (lib/kill-option-order.py), so the
# SAFE arms pin that a MENTION (a heredoc mail body, an echo/grep argument) never fires: the class a
# raw-string matcher would block. Payload commands carry no quotes so they fit inside single-quoted JSON.
assert_eq "kill-option-order.py --self-test passes (its arms call scan(), the function the hook runs)" "0" \
  "$(python3 .claude/hooks/lib/kill-option-order.py --self-test >/dev/null 2>&1; echo $?)"
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"pkill -f cat -U $(id -u) -n 2>/dev/null"}}' | bash .claude/hooks/block-dangerous.sh 2>/dev/null); ko_ec=$?
assert_eq "FIRE pkill with -U/-n AFTER the pattern (the 2026-10-05 shape) → exit 2" "2" "$ko_ec"
assert_one_json_doc "PARSE: kill-option-order deny → ONE parseable doc naming the arm" "$ko_out" 'kill-option-order'
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"pgrep -x Finder -q"}}' | bash .claude/hooks/block-dangerous.sh 2>/dev/null); ko_ec=$?
assert_eq "FIRE pgrep with a flag after the pattern → exit 2" "2" "$ko_ec"
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"killall node -u <user>"}}' | bash .claude/hooks/block-dangerous.sh 2>/dev/null); ko_ec=$?
assert_eq "FIRE killall with an option after the name, no other tool name → exit 2 (the pre-filter's killall branch)" "2" "$ko_ec"
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"pkill -f a -n; pgrep -x b -q"}}' | bash .claude/hooks/block-dangerous.sh 2>/dev/null)
assert_one_json_doc "PARSE: a two-finding deny names the second finding's count" "$ko_out" '1 more kill command'
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"pkill -n -U 501 -f cat"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ko_ec=$?
assert_eq "SAFE pkill with every option before the pattern → exit 0" "0" "$ko_ec"
assert_empty "SAFE pkill with every option before the pattern → silent" "$ko_out"
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"mail-send --to x <<EOF\npkill -f cat -U 501 -n\nEOF"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ko_ec=$?
assert_eq "SAFE the shape quoted inside a heredoc mail body → exit 0 (a mention, not a run)" "0" "$ko_ec"
ko_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep -nF pkill notes.md; echo pkill -f cat -n"}}' | bash .claude/hooks/block-dangerous.sh 2>&1); ko_ec=$?
assert_eq "SAFE the shape as an echo/grep argument → exit 0" "0" "$ko_ec"
# A deny records arm=kill-option-order; a CRASHED helper lets the command through and records
# arm=kill-option-order-helper-failed (the documented fail-open). The second half runs a COPY of the hook
# beside a stub helper that exits 1, so it measures that branch rather than this tree's healthy helper.
_bdko_root=$(_hfl_fresh_root)
_bdko_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_bdko_root" ]; then
  echo '{"session_id":"smoke-sid-ko","tool_name":"Bash","tool_input":{"command":"pkill -f cat -n"}}' \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_bdko_root" bash .claude/hooks/block-dangerous.sh >/dev/null 2>&1
  _bdko_rc=$?
  _bdko_got="rc=$_bdko_rc $(_hfl_records "$_bdko_root/.claude/logs/block-dangerous-fires.jsonl")"
  mkdir -p "$_bdko_root/hooks/lib"
  cp .claude/hooks/block-dangerous.sh "$_bdko_root/hooks/"
  cp .claude/hooks/lib/fires-log.sh "$_bdko_root/hooks/lib/"
  printf 'import sys\nsys.exit(1)\n' > "$_bdko_root/hooks/lib/kill-option-order.py"
  echo '{"session_id":"smoke-sid-ko","tool_name":"Bash","tool_input":{"command":"pkill -f cat -n"}}' \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_bdko_root" bash "$_bdko_root/hooks/block-dangerous.sh" >/dev/null 2>&1
  _bdko_rc2=$?
  _bdko_got="$_bdko_got | crashed-helper rc=$_bdko_rc2 $(_hfl_records "$_bdko_root/.claude/logs/block-dangerous-fires.jsonl")"
  rm -rf "$_bdko_root"
fi
assert_eq "block-dangerous: a kill-option-order DENY records its arm; a crashed helper ALLOWS and records helper-failed" \
  "rc=2 records=1 arm=kill-option-order sid=smoke-sid-ko agent_id= | crashed-helper rc=0 records=2 arm=kill-option-order-helper-failed sid=smoke-sid-ko agent_id=" "$_bdko_got"
unset _bdko_root _bdko_rc _bdko_rc2 _bdko_got ko_out ko_ec

# --- block-dangerous: THE SAME jq FAIL-OPEN CLASS AS THE PUSH GUARD ---
# ⛔ `block-push-without-approval.sh` "Mirrors block-dangerous.sh's jq-first extraction", so the two
# guards share one obligation: an unconditional parse flag and an ABSENCE-keyed tripwire would let a
# broken jq wave a destructive command through, in the one guard whose failure cannot be undone. The
# flag requires rc=0 AND a non-empty extraction; these arms pin both directions.
_bdjq_rig="$(cd "$(mktemp -d)" && pwd -P)"
mkdir -p "$_bdjq_rig/bin"
# Built from `command -v`, not absolute paths: the
# absolute form silently skips a binary that is not at the literal path, which voids the arm quietly.
for _bdjq_p in bash sh cat grep head sed dirname python3 date mkdir tr cut wc find rm awk ls basename sort uniq stat env printf; do
  _bdjq_s=$(command -v "$_bdjq_p" 2>/dev/null) && ln -sf "$_bdjq_s" "$_bdjq_rig/bin/$_bdjq_p"
done
printf '#!/bin/sh\nexit 1\n' > "$_bdjq_rig/bin/jq"; chmod 755 "$_bdjq_rig/bin/jq"
assert_eq "block-dangerous jq rig: the fixture's own grep works before any arm below is read (a rig missing its grep makes every arm die at rc=127, and rc=127 reads exactly like the deny being hunted)" \
  "1" "$(env PATH="$_bdjq_rig/bin" /bin/sh -c 'echo x | grep -c x' 2>/dev/null)"
printf '%s' '{"tool_name":"Bash","tool_input":{"command":"rm -rf /"}}' | env PATH="$_bdjq_rig/bin" /bin/bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "FIRE block-dangerous, jq PRESENT BUT BROKEN + a catastrophic op → exit 2 (a broken parse must never become a silent ALLOW in the guard whose failure is irreversible)" "2" "$?"
printf '%s' '{"tool_name":"Bash","tool_input":{"cmd":"rm -rf /"}}' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "FIRE block-dangerous, HEALTHY jq + UNRECOGNISED payload shape + a catastrophic op → exit 2 (empty at rc=0 must reach the raw tripwire; no broken binary required to reach this one)" "2" "$?"
printf '%s' '{"tool_name":"Bash","tool_input":{"cmd":"echo hello"}}' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "SAFE block-dangerous, healthy jq + unrecognised shape + a SAFE command → exit 0 (the sweep must not turn an unparsed payload into a deny)" "0" "$?"
printf '%s' '' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "SAFE block-dangerous, empty stdin → exit 0 (jq returns empty at rc=0 here too, and an empty payload carries nothing to block)" "0" "$?"
# The kill-option-order arm under the same broken jq: the grep fallback mangles a quoted pattern, so the
# helper sees `pkill -f \` and cannot judge it. It must not deny on mangled text, and it must leave a
# record saying it ran blind.
_bdjq_root=$(_hfl_fresh_root)
_bdjq_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_bdjq_root" ]; then
  printf '%s' '{"session_id":"smoke-sid-p37","tool_name":"Bash","tool_input":{"command":"pkill -f \"cat\" -U 501 -n"}}' \
    | env -u HOOK_FIRES_LOG_DIR PATH="$_bdjq_rig/bin" CLAUDE_PROJECT_DIR="$_bdjq_root" /bin/bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
  _bdjq_rc=$?
  _bdjq_n=$(grep -c -F '"arm":"kill-option-order-unparsed"' "$_bdjq_root/.claude/logs/block-dangerous-fires.jsonl" 2>/dev/null); _bdjq_n=${_bdjq_n:-0}
  _bdjq_got="rc=$_bdjq_rc unparsed=$_bdjq_n"
  rm -rf "$_bdjq_root"
fi
assert_eq "block-dangerous, jq BROKEN + a quoted mis-ordered pkill → allowed, and arm=kill-option-order-unparsed recorded" "rc=0 unparsed=1" "$_bdjq_got"
unset _bdjq_root _bdjq_rc _bdjq_n _bdjq_got
rm -rf "$_bdjq_rig"
unset _bdjq_rig _bdjq_p _bdjq_s

echo ""
echo "=== block-dangerous.sh + block-push-without-approval.sh on MONITOR payloads (scripts/wire-monitor-guards.py) ==="
# A Monitor input carries EITHER `command` (a shell runs it, so both guards judge it as they judge Bash) OR
# `ws` (a WebSocket watch, no shell: the one legitimate no-command payload). The two ws arms go red if the
# ws exit above either tripwire is removed: the description names a verb and the raw tripwire denied it.
_mon() { python3 -c 'import json,sys; print(json.dumps({"tool_name":"Monitor","tool_input":json.loads(sys.argv[1])}))' "$1"; }
_mon_rm="r""m -rf"
for _mh in block-dangerous block-push-without-approval; do
  out=$(_mon '{"command":"python3 scripts/session-manifest.py mail-listen --poll 30","description":"mail","persistent":true}' | PUSH_GUARD_NO_LOG=1 bash ".claude/hooks/$_mh.sh" 2>/dev/null)
  assert_eq "SAFE Monitor mail-listen arm → $_mh exit 0, silent" "0:" "$?:$out"
  out=$(_mon "{\"ws\":{\"url\":\"wss://example.com/x\"},\"description\":\"events after git push origin main and $_mon_rm /tmp/x\",\"timeout_ms\":60000}" | PUSH_GUARD_NO_LOG=1 bash ".claude/hooks/$_mh.sh" 2>/dev/null)
  assert_eq "SAFE Monitor ws form, description names a push and a removal → $_mh exit 0, silent (no shell runs)" "0:" "$?:$out"
done
out=$(_mon '{"command":"git push origin main","description":"x"}' | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>/dev/null)
assert_eq "FIRE Monitor command git push origin main → push guard exit 2" "2" "$?"
assert_contains "FIRE Monitor push → a real deny document" "$out" '"permissionDecision": "deny"'
out=$(_mon "{\"command\":\"$_mon_rm /\",\"description\":\"x\"}" | bash .claude/hooks/block-dangerous.sh 2>/dev/null)
assert_eq "FIRE Monitor command root wipe → block-dangerous exit 2" "2" "$?"
unset _mh _mon_rm

echo ""
echo "=== block-push-without-approval.sh (Bash HARD-BLOCK on push/CI-trigger w/o owner approval) ==="
# FIRE: git push → exit 2 + deny JSON
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git push origin main"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "FIRE git push → exit 2" "2" "$ec"
assert_contains "FIRE git push → deny message" "$out" "BLOCKED by block-push-without-approval"
sout=$(echo '{"tool_name":"Bash","tool_input":{"command":"git push origin main"}}' | bash .claude/hooks/block-push-without-approval.sh 2>/dev/null)
assert_one_json_doc "PARSE: block-push-without-approval.sh git-push deny arm → ONE parseable hookSpecificOutput doc, the ALLOW_PUSH=1 escape survives" "$sout" 'triggers a CI run'   # real-deny-only token: the jq-absent FAIL-CLOSED branch also carries the escape text

# FIRE: gh pr comment (Dependabot CI-trigger vector) → exit 2
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"gh pr comment 12 --body \"@dependabot rebase\""}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "FIRE gh pr comment → exit 2" "2" "$ec"

# FIRE: a quoted arg BEFORE the push verb.
# `git commit -m "msg" && git push` is the most common real push composition, and a
# naive-grep extraction truncates the command at the first escaped quote, so the push verb is
# never seen. jq-first extraction (mirroring block-dangerous.sh) must see past the quote. Every
# other FIRE fixture above places the verb BEFORE any quote, so this arm is the one that covers it.
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"git commit -m \"msg\" && git push origin main"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "FIRE quoted-arg-then-push 'git commit -m \"msg\" && git push' → exit 2 (extraction sees past the quote)" "2" "$ec"
assert_contains "FIRE quoted-arg-then-push → deny message" "$out" "BLOCKED by block-push-without-approval"

# FIRE: the ALLOW_PUSH marker QUOTED INSIDE another command must NOT count as approval —
# the escape is valid only at command position (start of command/line or after ; & |).
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"echo \"ALLOW_PUSH=1 noted\" && git push origin main"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "FIRE quoted ALLOW_PUSH mention + git push → exit 2 (marker only counts at command position)" "2" "$ec"

# --- jq PRESENT BUT BROKEN ---
# ⛔ THE GUARD MUST ASK "DID THE PARSE WORK?", NOT ONLY "IS jq INSTALLED?". A present-but-failing jq
# returns empty; credited as a successful parse, it would skip the fail-closed tripwire (which keys on
# JQ_USED != 1) and fall to the empty-command early exit, allowing a `git push` payload at rc=0 with
# zero output. These arms pin the refusal.
# ⛔ BUILD THE RIG FROM `command -v`, NOT ABSOLUTE PATHS. A shell function shadowing `grep` is an
# interactive-shell artifact and DOES NOT CROSS A SHEBANG — this suite is `#!/usr/bin/env bash`, so
# `command -v grep` returns a path here and that hazard cannot fire.
# ⛔ AND THE ABSOLUTE-PATH FORM IS STRICTLY WORSE: `ln -sf` on a path that does not exist on
# the machine silently SKIPS that binary, so the rig loses a tool with no error and the arm goes
# VOID rather than red (a missing `stat` makes a marker check return false and read as "the finding
# does not reproduce", one step from retracting a true finding). The control must still read 1
# BEFORE any arm here is believed.
_bpj_rig="$(cd "$(mktemp -d)" && pwd -P)"
mkdir -p "$_bpj_rig/bin"
for _bpj_p in bash sh cat grep head sed dirname python3 date mkdir tr cut wc find rm awk ls basename sort uniq stat env printf; do
  _bpj_s=$(command -v "$_bpj_p" 2>/dev/null) && ln -sf "$_bpj_s" "$_bpj_rig/bin/$_bpj_p"
done
printf '#!/bin/sh\nexit 1\n' > "$_bpj_rig/bin/jq"; chmod 755 "$_bpj_rig/bin/jq"
assert_eq "push-guard jq rig: the fixture's own grep works before any arm below is read (a rig missing its grep makes every arm die at rc=127, which reads exactly like the deny being hunted)" \
  "1" "$(env PATH="$_bpj_rig/bin" /bin/sh -c 'echo x | grep -c x' 2>/dev/null)"
_bpj_out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"git push origin main"}}' | env PATH="$_bpj_rig/bin" /bin/bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" 2>&1)
assert_eq "FIRE jq PRESENT BUT BROKEN + git push → exit 2 (the tripwire keys on the PARSE failing, not on jq being absent)" \
  "2" "$?"
assert_contains "FIRE jq PRESENT BUT BROKEN → the jq-absent FAIL-CLOSED deny, i.e. an unusable parse routes to the same refusal as a missing jq" "$_bpj_out" "FAIL-CLOSED"
# ⛔ THE NO-OVER-BLOCK HALF: a payload carrying no command at all must still ALLOW.
# This hook is registered under the `Bash` matcher (and `Monitor`, once
# scripts/wire-monitor-guards.py has run) ONLY, so it never receives a Read, Edit or Glob payload, and an
# emptiness gate is therefore both safe and NECESSARY (see the arms below it). These arms pin that a
# command-less payload must not be refused.
_bpj_out=$(printf '%s' '{"tool_name":"Read","tool_input":{"file_path":"README.md"}}' | env PATH="$_bpj_rig/bin" /bin/bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" 2>&1)
assert_eq "SAFE jq BROKEN + a payload with NO command field (a Read) → exit 0, NOT a deny — an unusable parse must not refuse calls that carry no command at all" "0" "$?"
assert_empty "SAFE jq BROKEN + no command field → silent" "$_bpj_out"
_bpj_out=$(printf '%s' '{"tool_name":"Read","tool_input":{"file_path":"README.md"}}' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" 2>&1)
assert_eq "SAFE working jq + a payload with NO command field → exit 0 (the empty-value path stays ALLOW for real non-Bash calls; this is the regression the exit-code gate must not cause)" "0" "$?"
# --- THE CLASS THE EXIT-CODE GATE DOES NOT CLOSE: a HEALTHY jq returning EMPTY at rc=0 ---
# ⛔ NOTHING HAS TO BE BROKEN FOR THIS ONE. With the real system jq, malformed input exits non-zero
# (the single shape the exit-code gate closes), but EMPTY STDIN and VALID JSON OF AN UNRECOGNISED
# SHAPE both return empty at rc=0. So if the harness ever renames or re-nests the Bash payload's command key,
# jq returns empty at rc=0, the parse is CREDITED, the fail-closed tripwire is skipped, and a push verb
# sitting verbatim in the raw bytes would walk straight through with a perfectly healthy jq. The
# exit-code gate alone closes only the malformed-payload arm.
_bpj_out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"cmd":"git push origin main"}}' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" 2>&1)
assert_eq "FIRE healthy jq + UNRECOGNISED payload shape carrying git push → exit 2 (an empty extraction at rc=0 must route to the raw tripwire, never to the allow)" \
  "2" "$?"
assert_contains "FIRE healthy jq + unrecognised shape → routes to the SAME fail-closed refusal as a missing jq" "$_bpj_out" "FAIL-CLOSED"
_bpj_out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"cmd":"echo hello"}}' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" 2>&1)
assert_eq "SAFE healthy jq + unrecognised shape carrying a SAFE command → exit 0 (the fallback must not manufacture a deny out of an unparsed payload)" "0" "$?"
rm -rf "$_bpj_rig"
unset _bpj_rig _bpj_p _bpj_s _bpj_out

# --- THE SAME FAIL-OPEN CLASS WITH THE REAL SYSTEM jq AND NO RIG AT ALL ---
# ⭐ THESE ARE THE ARMS THAT MATTER, AND THEY ARE BETTER THAN THE RIG ARMS ABOVE. The rig exercises a
# broken jq BINARY — a state this hook's own docblock calls "~never taken in normal operation", and
# one whose rigs go void easily. These three shapes reach the identical fail-open with the
# ORDINARY system jq, no PATH surgery, no symlinks, nothing to go void: jq exits non-zero (malformed)
# or returns empty at rc=0 (wrong shape), the parse is not credited, and the raw-payload tripwire runs.
# Each must DENY at rc=2. A harness that ever truncates, re-nests or re-types the Bash payload lands here.
for _bpn_case in truncated string-toolinput not-json; do
  case "$_bpn_case" in
    truncated)       _bpn_fire='{"tool_name":"Bash","tool_input":{"command":"git push origin main"' ; _bpn_safe='{"tool_name":"Bash","tool_input":{"command":"echo hello"' ;;
    string-toolinput) _bpn_fire='{"tool_name":"Bash","tool_input":"git push origin main"}'          ; _bpn_safe='{"tool_name":"Bash","tool_input":"echo hello"}' ;;
    not-json)        _bpn_fire='git push origin main'                                              ; _bpn_safe='echo hello' ;;
  esac
  printf '%s' "$_bpn_fire" | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
  assert_eq "FIRE real jq, no rig — a $_bpn_case payload carrying git push → exit 2 (nothing on the machine has to be broken to reach this shape)" "2" "$?"
  printf '%s' "$_bpn_safe" | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
  assert_eq "SAFE real jq, no rig — the same $_bpn_case shape carrying a safe command → exit 0 (the tripwire must match the VERB in the raw bytes, not merely fire on an unparsed payload)" "0" "$?"
done
unset _bpn_case _bpn_fire _bpn_safe

# --- THE EMPTINESS GATE'S PREMISE, MADE CHECKABLE -------------------------------------------------
# ⛔ BOTH GUARDS CREDIT A PARSE ONLY ON rc=0 *AND* A NON-EMPTY COMMAND. The non-empty half is safe
# ONLY because these two hooks are registered under the `Bash` and `Monitor` matchers and no other:
# a Bash payload always carries a command, and a Monitor payload carries exactly one non-empty
# command or `ws` (the tool refuses both and neither at validation, which runs before any PreToolUse
# hook),
# and each hook exits 0 by name on the ws form ABOVE its emptiness gate, with a working jq. So under
# these two matchers an empty extraction means the parse missed the command, with ONE exception:
# validation counts truthy fields, so an empty-string `command` beside `ws` passes, keeps both keys,
# misses the by-name exit (keyed on the `command` KEY being absent) and takes the tripwire, a false
# deny when its description names a verb and never a missed op. Wire either hook to any OTHER matcher
# and that reasoning inverts
# — a Read, Edit or Glob payload has no command by design, the gate refuses to credit the parse, the
# raw tripwire runs on every such call, and the guard becomes a fleet-wide OVER-BLOCK.
# ⛔ NOTHING ELSE IN THE TREE WOULD FAIL. That is the whole point of this arm: the correctness
# property lives in one file and the fact it depends on lives in ANOTHER, with no mechanism tying
# them together — the same shape, one level out: a gate whose premise lives in another file. This arm IS the
# mechanism. If it goes red, do not "update the expected value": the gate's premise has moved and
# the gate needs re-deriving.
# WHAT RE-DERIVING MEANS. When scripts/wire-monitor-guards.py adds the two `Monitor` registrations,
# an arm that reads "the `Bash` matcher ALONE" and expects the two Bash entries only goes red on
# the push that carries the wiring. The gate for that matcher is the
# Monitor `ws` exit in each hook, with the "SAFE Monitor ws form" arms in this file's MONITOR payloads
# section, which go red if either exit is removed; the set pinned below is widened only after
# reading both hooks' ws exit at HEAD. ⛔ THE ORDER IS THE RULE FOR THE NEXT MATCHER:
# derive the gate for that matcher's no-command payloads first, pin it with a SAFE/FIRE pair, and
# only then widen this set, in the same change that wires it. The pin and the wiring travel together
# on dev; this arm reads red, correctly, on a branch that cherry-picks the wiring without the pin
# (a hotfix cut from main) and on a tree whose settings.json lost the Monitor entries.
_mx_reg=$(python3 -c '
import json
s = json.load(open(".claude/settings.json"))
out = []
for ev, entries in (s.get("hooks") or {}).items():
    for e in entries:
        m = e.get("matcher", "")
        for h in (e.get("hooks") or []):
            c = h.get("command", "")
            for name in ("block-push-without-approval.sh", "block-dangerous.sh"):
                if name in c:
                    out.append(name[:-3] + ":" + ev + ":" + m)
print(" ".join(sorted(set(out))))' 2>/dev/null)
assert_eq "the two command-parsing guards are registered under the Bash and Monitor matchers and no other — the fact the non-empty half of their parse gate rests on (Monitor's no-command ws form is cleared by name in each hook), pinned here because it lives in a different file and nothing else would fail if it moved" \
  "block-dangerous:PreToolUse:Bash block-dangerous:PreToolUse:Monitor block-push-without-approval:PreToolUse:Bash block-push-without-approval:PreToolUse:Monitor" "$_mx_reg"
unset _mx_reg

# --- A NON-STRING `command` --------------
# ⛔ `jq -r` PRETTY-PRINTS a non-string, so an emptiness gate alone would credit an ARRAY or OBJECT `command` as a
# successful parse, skip the raw tripwire, and leave the precise match unable to see a verb wrapped in JSON
# punctuation. Every FIRE arm below must deny, for both shapes on the push guard and the array shape on the
# catastrophe guard. The two array SAFE arms are what stop
# the fix degrading into "deny every non-string": an argv vector of a harmless command must still pass,
# and an argv vector that opens with the approval marker must still escape.
_nsb() { python3 -c 'import json,sys; print(json.dumps({"tool_name":"Bash","tool_input":{"command":json.loads(sys.argv[1])}}))' "$1"; }
_nsb '["git","push","origin","main"]' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
assert_eq "FIRE push guard — an ARRAY command (an argv vector) carrying git push → exit 2 (the filter must not credit pretty-printed JSON as the command)" "2" "$?"
_nsb '{"v":"git push origin main"}' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
assert_eq "FIRE push guard — an OBJECT command carrying git push → exit 2 (a command that is neither a string nor an array takes the fail-closed path)" "2" "$?"
_nsb '["echo","hello"]' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
assert_eq "SAFE push guard — an ARRAY command carrying a harmless argv → exit 0 (the fix joins an array; it does not deny one)" "0" "$?"
_nsb '["ALLOW_PUSH=1","git","push","origin","main"]' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
assert_eq "SAFE push guard — an ARRAY command that opens with ALLOW_PUSH=1 → exit 0 (joining keeps the approval escape reachable on the argv shape)" "0" "$?"
_nsb '["rm","-rf","/"]' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "FIRE catastrophe guard — an ARRAY command (an argv vector) carrying rm -rf / → exit 2 (the type-aware filter joins the argv before matching)" "2" "$?"
_nsb '{"v":"rm -rf /"}' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "FIRE catastrophe guard — an OBJECT command carrying rm -rf / → exit 2 (must not rely on a pattern matching inside pretty-printed text)" "2" "$?"
_nsb '["echo","hello"]' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
assert_eq "SAFE catastrophe guard — an ARRAY command carrying a harmless argv → exit 0" "0" "$?"
unset -f _nsb

# --- THE RAW TRIPWIRE'S BREADTH -------
# The six SAFE arms in the loop above DO discriminate a STRUCTURAL over-block — forcing the tripwire's
# condition true reds all six — and they are BLIND to the tripwire's REGEX BREADTH, because their safe
# command carries no verb at all: widened to a bare verb, the suite stays green under
# that mutation. These near-miss arms carry the verb WORD without its head, on the same three
# degraded shapes, so a widened tripwire goes red here. The breadth axis is where a tripwire like this
# gets mis-calibrated, so this is the edit most likely to be made in a hurry.
for _tb_case in truncated string-toolinput not-json; do
  case "$_tb_case" in
    truncated)        _tb_push='{"tool_name":"Bash","tool_input":{"command":"echo push notes"' ; _tb_rm='{"tool_name":"Bash","tool_input":{"command":"rm -f build.log"' ;;
    string-toolinput) _tb_push='{"tool_name":"Bash","tool_input":"echo push notes"}'          ; _tb_rm='{"tool_name":"Bash","tool_input":"rm -f build.log"}' ;;
    not-json)         _tb_push='echo push notes'                                              ; _tb_rm='rm -f build.log' ;;
  esac
  printf '%s' "$_tb_push" | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1
  assert_eq "SAFE push guard, degraded $_tb_case payload — the verb word without its head (echo push notes) → exit 0 (red if the raw tripwire is widened to a bare verb)" "0" "$?"
  printf '%s' "$_tb_rm" | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" >/dev/null 2>&1
  assert_eq "SAFE catastrophe guard, degraded $_tb_case payload — rm on a relative file (rm -f build.log) → exit 0 (red if the raw tripwire is widened to a bare rm)" "0" "$?"
done
unset _tb_case _tb_push _tb_rm

# --- THE FAIL-CLOSED REASON NAMES ITS REAL CAUSE ------
# With jq INSTALLED, a payload jq cannot use reaches the fail-closed branch, and the deny used to say "jq is not
# installed": a first remedy that is a no-op, followed by the approval escape as the second. Same deny, same
# rc — these arms read the REASON the blocked seat is handed. Their twins on the no-jq path pin the other branch.
_rc_out=$(printf '%s' '{"tool_name":"Bash","tool_input":"git push origin main"}' | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" 2>/dev/null)
assert_contains "FIRE push guard, healthy jq + a string tool_input → still the FAIL-CLOSED deny" "$_rc_out" "FAIL-CLOSED"
assert_not_contains "push guard, healthy jq + an unusable payload → the deny does NOT claim jq is missing" "$_rc_out" "jq is not installed"
assert_contains "push guard, healthy jq + an unusable payload → the deny names the real cause" "$_rc_out" "jq is installed but did not return a usable command"
_rc_out=$(printf '%s' '{"tool_name":"Bash","tool_input":"rm -rf /"}' | bash "$REPO_ROOT/.claude/hooks/block-dangerous.sh" 2>/dev/null)
assert_contains "FIRE catastrophe guard, healthy jq + a string tool_input → still the FAIL-CLOSED deny" "$_rc_out" "FAIL-CLOSED"
assert_not_contains "catastrophe guard, healthy jq + an unusable payload → the deny does NOT claim jq is missing" "$_rc_out" "jq is not installed"
assert_contains "catastrophe guard, healthy jq + an unusable payload → the deny names the real cause" "$_rc_out" "jq is installed but did not return a usable command"
unset _rc_out

# SAFE: ALLOW_PUSH=1 owner-approved escape → exit 0 silent
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"ALLOW_PUSH=1 git push origin main"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE ALLOW_PUSH=1 git push → exit 0" "0" "$ec"
assert_empty "SAFE ALLOW_PUSH=1 git push → silent" "$out"

# SAFE: command-position escape after a separator (re-approval compound) → exit 0
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"cd /tmp/x && ALLOW_PUSH=1 git push origin main"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE 'cd x && ALLOW_PUSH=1 git push' (escape after separator) → exit 0" "0" "$ec"

# SAFE: local commit (free) → exit 0 silent
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git commit -o -m \"msg\" file.ts"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE git commit → exit 0" "0" "$ec"
assert_empty "SAFE git commit → silent" "$out"

# SAFE: read-only gh → exit 0 silent
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"gh pr view 12 --json statusCheckRollup"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE gh pr view → exit 0" "0" "$ec"
assert_empty "SAFE gh pr view → silent" "$out"

# ── BRANCHING POLICY: the guard classifies a `git push` by its TARGET. Only what can reach
# production stays gated.
# SAFE: a push to dev / a feature branch → exit 0 silent (session-discretion)
for _c in 'git push origin dev' 'git push -u origin dev' 'git push origin feat/x' 'git push origin HEAD:refs/heads/dev'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "SAFE '$_c' → exit 0 (non-main target)" "0" "$ec"
  assert_empty "SAFE '$_c' → silent" "$out"
done
# SAFE: opening a promote PR is session-discretion; the MERGE stays gated (next section's FIRE arm)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"gh pr create --base main --head dev --title t"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE gh pr create → exit 0 (opening a PR is session-discretion; the merge is gated)" "0" "$ec"
assert_empty "SAFE gh pr create → silent" "$out"
# FIRE: every spelling whose DESTINATION is main, and every rewrite/delete that could reach it
for _c in 'git push origin HEAD:main' 'git push origin dev:main' 'git push origin +dev:refs/heads/main' 'git push --force origin dev' 'git push origin --delete dev' 'gh pr merge --merge 12' 'gh pr reopen 12'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (reaches main / rewrites)" "2" "$ec"
done
# FIRE: a refspec carrying `$` is unreadable to a
# literal-token guard — `git push origin "$SRC"` would read `$SRC` as a branch name while
# SRC held main. Fail closed on any variable or substitution; push by literal branch name.
for _c in 'git push origin \"$SRC\"' 'git push origin $SRC' 'git push -u origin \"${SRC}\"' 'git push origin \"$(git branch --show-current)\"'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (a variable refspec cannot be classified — fail closed)" "2" "$ec"
done
# FIRE: the REST/graphql route to a merge, a protection change, a dispatch, a rerun or a
# repo-settings write. A write method or a field (-f/-F/--input ⇒ POST) on those endpoints denies.
for _c in 'gh api -X PUT repos/o/r/pulls/5/merge' 'gh api repos/{owner}/{repo}/pulls/5/merge -f merge_method=merge' 'gh api -X DELETE repos/o/r/branches/main/protection' 'gh api -X PATCH repos/o/r -f allow_auto_merge=false' 'gh api -X POST repos/o/r/actions/workflows/test.yml/dispatches -f ref=main' 'gh api -X POST repos/o/r/actions/runs/123/rerun' 'gh api graphql -f query=mutation{mergePullRequest(input:{pullRequestId:x}){clientMutationId}}'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (gh api write to a merge/protection/workflow/repo-settings endpoint)" "2" "$ec"
done
# FIRE: a VAR= prefix, an if/then wrap,
# a second push after an allowed one, a pr merge after an allowed push, a quoted -X, the merges endpoint and a
# refs PATCH must all deny. gh api is inverted — every non-GET denies except an inline read-only
# graphql query — so a write to any other endpoint (issues) denies too, by design.
for _c in 'FOO=1 git push origin main' 'SKIP_BAND_BUDGET_CHECK=1 git push origin main' 'if true; then git push origin main; fi' 'git push origin dev && git push origin main' 'git push origin dev && gh pr merge 12 --merge' "gh api -X 'PUT' repos/o/r/pulls/5/merge" 'gh api -X POST repos/o/r/merges -f base=main -f head=dev' 'gh api -X PATCH repos/o/r/git/refs/heads/main -f sha=abc' 'gh api -X POST repos/o/r/issues -f title=x'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (prefix / wrap / chained / quoted method / inverted gh api)" "2" "$ec"
  assert_contains "FIRE '$_c' → a real deny, not a crash" "$out" '"permissionDecision": "deny"'
done
# FIRE: an empty-source refspec DELETES its destination, exactly
# like --delete — an empty paste into /promote's `<H_PRE>:refs/heads/dev` would delete dev
# on GitHub and close the open promote PR.
for _c in 'git push origin :refs/heads/dev' 'git push origin :dev'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (an empty source deletes the branch)" "2" "$ec"
  assert_contains "FIRE '$_c' → a real deny, not a crash" "$out" '"permissionDecision": "deny"'
done
# FIRE: a push
# followed by a redirect or a comment, a redirection next to a refspec, a branch
# switched inside the same command, gh api short-flag clusters, the word graphql appearing outside the query,
# an ALLOW_PUSH=1 set in one segment of a chained command, gh flags before the subcommand, shell wrappers,
# and the verbs (update-branch, workflow enable, alias, curl to the API) must all deny.
for _c in 'git push origin main > push.log 2>&1' 'git push origin main # push to prod' 'git push --force origin main # push' 'git push origin main>out.txt' 'git checkout main && git push' 'git switch main && git push' 'gh api -iX PUT repos/o/r/pulls/5/merge' 'gh api -if base=main -if head=dev repos/o/r/merges' "gh api -X PUT repos/o/r/pulls/5/merge -f query={x} -H 'X-Note: graphql'" 'ALLOW_PUSH=1 gh run rerun --failed 1 && gh pr merge 5 --merge' 'gh -R o/r pr merge 5' 'gh pr -R o/r merge 5' 'bash -lc \"git push origin main\"' '/usr/bin/env git push origin main' 'gh pr update-branch 5' 'gh workflow enable test.yml'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (a shape that must deny)" "2" "$ec"
  assert_contains "FIRE '$_c' → a real deny, not a crash" "$out" '"permissionDecision": "deny"'
done
# FIRE: a QUOTED `#`/`>` read as a comment or redirect
# (git lets the positional remote override --repo), a quoted `;` cutting the
# segment, a `|` inside a quoted --jq cutting the gh api segment, a quoted " -X GET" overriding the real
# method, curl short-flag clusters, a nested command riding the rerun approval, and a marker on the
# context-changing segment.
for _c in "git push --repo '#x' origin main" "git push --repo '>' origin main" "git push -o '#' origin main" "git push -o 'a;b' origin main" "gh api repos/o/r/merges --jq '.a | .b' -f base=main" "gh api -X PUT repos/o/r/pulls/5/merge -H 'X-A: -X GET'" 'curl -sX PUT https://api.github.com/repos/o/r/pulls/5/merge' 'curl -sLX POST https://api.github.com/repos/o/r/actions/runs/1/rerun' 'ALLOW_PUSH=1 gh run rerun --failed 1 $(gh pr merge 5)' 'ALLOW_PUSH=1 git checkout main && git push'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (quoted-span and cluster shapes)" "2" "$ec"
  assert_contains "FIRE '$_c' → a real deny, not a crash" "$out" '"permissionDecision": "deny"'
done
# FIRE: more than 100 segments denies with its OWN reason, not "could not be resolved".
_c="$(printf 'git push origin dev && %.0s' $(seq 1 100))git push origin dev"
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
assert_contains "FIRE 101 dev pushes → the segment-cap reason" "$out" 'more than 100 push segments'
# SAFE: a quoted push option on dev, and a GET whose --jq holds a pipe.
for _c in "git push -o 'ci.skip' origin dev" "gh api repos/o/r/pulls/5 --jq '.head | .sha'"; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "SAFE '$_c' → exit 0 (a quoted span on a dev push or a read)" "0" "$ec"
done
# FIRE: an ESCAPED or UNCLOSED quote before the refspec can cut
# the push segment short, so on a dev checkout the bare-push fallback would read the CURRENT branch and allow
# `… origin main`; the same cut would hide `-X PUT` from gh api. The payload is built by json.dumps because these
# commands carry double quotes and backslashes. This suite runs on dev, which is the case that matters.
_pg_payload() { python3 -c 'import json,sys; print(json.dumps({"tool_name":"Bash","tool_input":{"command":sys.argv[1]}}))' "$1"; }
for _c in 'git push -o "a\"b" origin main' 'git push --push-option="a\"b" origin main' 'git push -o "\"" origin main' "git push -o it\\'s origin main" 'git push -o a\" origin main' "git push -o 'unclosed origin main" 'gh api repos/o/r/pulls/5/merge -H "x\"y" -X PUT' "gh api repos/o/r/pulls/5/merge -H x\\'y -X PUT"; do
  out=$(_pg_payload "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "FIRE '$_c' → exit 2 (escaped or unclosed quote)" "2" "$ec"
  assert_contains "FIRE '$_c' → a real deny, not a crash" "$out" '"permissionDecision": "deny"'
done
# SAFE: the same escaped quote on a dev push.
out=$(_pg_payload 'git push -o "a\"b" origin dev' | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
assert_eq "SAFE escaped quote on a dev push → exit 0" "0" "$?"
# TIMING: a timed-out hook is an ALLOW, and bash ${var//…} is super-linear. 8,000 words, and
# 4,000 backslash-newlines before a main push, must each deny in a few seconds.
# The measured seconds go in the ACTUAL value, never the label: smoke-mutation-matrix.sh compares ✓ labels
# as exact strings, so a label reading "took 1s" in the baseline and "took 2s" on the re-run is a dropped
# label, and the gate then refuses every verdict as SUITE-FLAKY / SUITE-STATE-DEPENDENT.
_c="git push origin dev $(printf 'a %.0s' $(seq 1 8000))main"
_t0=$SECONDS
out=$(_pg_payload "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?; _dt=$((SECONDS-_t0))
assert_eq "FIRE 8,000 words before main → exit 2" "2" "$ec"
assert_eq "TIMING 8,000 words → under 5 s" "under 5 s" "$([ "$_dt" -lt 5 ] && echo 'under 5 s' || echo "took ${_dt}s")"
_c="echo x$(printf ' \\\n%.0s' $(seq 1 4000)); git push origin main"
_t0=$SECONDS
out=$(_pg_payload "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?; _dt=$((SECONDS-_t0))
assert_eq "FIRE 4,000 backslash-newlines then a main push → exit 2" "2" "$ec"
assert_eq "TIMING 4,000 backslash-newlines → under 5 s" "under 5 s" "$([ "$_dt" -lt 5 ] && echo 'under 5 s' || echo "took ${_dt}s")"
# SAFE (their controls): the same redirect and comment on a dev push, a read-only graphql query and an
# introspection query that names mutationType, a GET of a ref whose name holds a capital X, and the one
# owner-covered rerun form typed alone.
for _c in 'git push origin dev > push.log 2>&1' 'git push origin dev # push the branch' 'gh api graphql -f query=query{viewer{login}}' 'gh api graphql -f query=query{__schema{mutationType{name}}}' 'gh api repos/x/y/git/ref/heads/fix-Xyz' 'ALLOW_PUSH=1 gh run rerun --failed 1'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "SAFE '$_c' → exit 0 (a dev push, a read, or the one covered rerun)" "0" "$ec"
done
# SAFE: a literal sha to dev (/promote step 1's certified-head push) still passes.
_c='git push origin 0123456789abcdef0123456789abcdef01234567:refs/heads/dev'
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE '$_c' → exit 0 (a literal sha pushed to dev)" "0" "$ec"
# SAFE (the controls for those shapes): the same shapes aimed at dev pass silently.
for _c in 'FOO=1 git push origin dev' 'if true; then git push origin dev; fi' 'git push origin dev && git push -u origin dev'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "SAFE '$_c' → exit 0 (the prefix/wrap/chain shape on dev)" "0" "$ec"
done
# SAFE (the controls): a GET read of the same endpoints, an explicit --method GET carrying fields, and an
# inline read-only graphql query pass silently — /promote step 0 reads branch protection this way.
for _c in 'gh api repos/o/r/branches/main/protection --jq .x' 'gh api --method GET repos/o/r/commits/abc/check-runs -f filter=latest' 'gh api repos/o/r/pulls/5' 'gh api graphql -f query=query{viewer{login}}'; do
  out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
  ec=$?
  assert_eq "SAFE '$_c' → exit 0 (a read)" "0" "$ec"
  assert_empty "SAFE '$_c' → silent" "$out"
done
# SAFE: prose "(gh api …)" supplies a command-position match while a quoted write example sits elsewhere;
# every command-position segment is judged, so this passes.
_c="echo 'gh api -X PUT repos/o/r/pulls/5/merge' (gh api write to a merge endpoint)"
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "SAFE prose '(gh api …)' beside a quoted write example → exit 0 (each command-position segment judged)" "0" "$ec"
# FIRE: a read chained BEFORE a write — the second segment is judged too
_c="gh api repos/o/r/pulls/5 --jq .x && gh api -X PUT repos/o/r/pulls/5/merge"
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$_c" | PUSH_GUARD_NO_LOG=1 bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "FIRE a gh api read chained before a merge write → exit 2 (every segment is judged, not the first)" "2" "$ec"
# FIRE-OR-SAFE by the CURRENT BRANCH: a bare push carries no branch token (e.g.
# a hotfix worktree sitting on main), so the guard resolves the target from git and FAILS CLOSED
# when it cannot. The hook reads git from ITS cwd, so a throwaway repo on a KNOWN branch drives all
# three states — the expectation comes from the FIXTURE, never from git's answer about this checkout
# (smoke-assert-lint: SELF-GRADING — an arm that derives its expectation from the same
# `symbolic-ref` call the hook makes reads alike for a dead hook and a live one).
_bp_fx="$(mktemp -d)"
(
  cd "$_bp_fx" || exit 1
  git init -q . && git config user.email t@t && git config user.name t
  git commit -q --allow-empty -m base && git branch -M main
) >/dev/null 2>&1
_bp_run() {   # $1 = command; runs the hook with the fixture as cwd, prints rc
  ( cd "$_bp_fx" && printf '{"tool_name":"Bash","tool_input":{"command":"%s"}}' "$1" \
      | bash "$REPO_ROOT/.claude/hooks/block-push-without-approval.sh" >/dev/null 2>&1; echo $? )
}
for _c in 'git push' 'git push origin' 'git push origin HEAD'; do
  assert_eq "bare-target '$_c' with the fixture checked out on MAIN → exit 2 (the current branch IS main)" "2" "$(_bp_run "$_c")"
done
( cd "$_bp_fx" && git switch -q -c dev ) >/dev/null 2>&1
for _c in 'git push' 'git push origin' 'git push origin HEAD'; do
  assert_eq "bare-target '$_c' with the fixture checked out on DEV → exit 0 (session-discretion)" "0" "$(_bp_run "$_c")"
done
( cd "$_bp_fx" && git switch -q --detach ) >/dev/null 2>&1
assert_eq "bare 'git push' with the fixture DETACHED → exit 2 (unresolvable target = fail-closed)" "2" "$(_bp_run 'git push')"
rm -rf "$_bp_fx"
# FIRE: a quoted payload cannot hide the target behind a trailing quote
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"bash -c '"'"'git push origin main'"'"'"}}' | bash .claude/hooks/block-push-without-approval.sh 2>&1)
ec=$?
assert_eq "FIRE bash -c 'git push origin main' → exit 2 (quotes stripped before classification)" "2" "$ec"
# ── FIRES LOG ───────────────────────────────
# This gate is DENY-mode and wrote no record of any kind, so its per-incident TP/FP rate was
# uncalibratable BY CONSTRUCTION (session-cadence.md § READING A GUARD'S FIRES).
# TEMP-DIR ISOLATION, not the PUSH_GUARD_NO_LOG escape: these arms ASSERT a write, so the escape
# would defeat them. CLAUDE_PROJECT_DIR is PINNED to the fixture — a `cd` alone leaves the hook
# resolving the REAL worktree and the arm then measures production state while passing (a
# vacuous control). Temp root canonicalised with `pwd -P` because `mktemp -d` returns the
# symlinked /var spelling here.
_pg_root=$(cd "$(mktemp -d)" && pwd -P)
_pg_log="$_pg_root/.claude/logs/push-guard-fires.jsonl"
echo '{"tool_name":"Bash","tool_input":{"command":"git push origin main"}}' | CLAUDE_PROJECT_DIR="$_pg_root" bash .claude/hooks/block-push-without-approval.sh >/dev/null 2>&1
_pg_fired=$( [ -f "$_pg_log" ] && wc -l < "$_pg_log" | tr -d ' ' || echo 0 )
assert_eq "push-guard: DENY appends exactly one record to the fires log" "1" "$_pg_fired"
# The record must be VALID JSON and must carry the arm — an unparseable ledger fails exactly when
# a future calibrator finally needs it, and an arm-less record cannot answer "which verb fired".
assert_eq "push-guard: the record is parseable JSON carrying its arm" "git push" \
  "$(python3 -c 'import json,sys; print(json.loads(open(sys.argv[1]).readline())["arm"])' "$_pg_log" 2>/dev/null)"
echo '{"tool_name":"Bash","tool_input":{"command":"git status"}}' | CLAUDE_PROJECT_DIR="$_pg_root" bash .claude/hooks/block-push-without-approval.sh >/dev/null 2>&1
_pg_safe=$( [ -f "$_pg_log" ] && wc -l < "$_pg_log" | tr -d ' ' || echo 0 )
assert_eq "push-guard: SAFE command appends NOTHING (the log is not a firehose)" "0" "$(( _pg_safe - _pg_fired ))"
# ⛔ THE ARM THAT MATTERS MORE THAN EITHER OF THE OTHER TWO, and the reference `_bsf_` pattern
# lacks it: an APPROVED push is not a fire. If it entered the corpus, every false-positive rate a
# future calibrator computes off this ledger is inflated by every LEGITIMATE push — and the
# inflation argues in the KEEP-THE-ARM direction, the exact bias session-cadence.md warns about.
echo '{"tool_name":"Bash","tool_input":{"command":"ALLOW_PUSH=1 git push origin main"}}' | CLAUDE_PROJECT_DIR="$_pg_root" bash .claude/hooks/block-push-without-approval.sh >/dev/null 2>&1
_pg_ok=$( [ -f "$_pg_log" ] && wc -l < "$_pg_log" | tr -d ' ' || echo 0 )
assert_eq "push-guard: an APPROVED push is NOT a fire (never enters the FP denominator)" "0" "$(( _pg_ok - _pg_safe ))"
# The logging leg must not reach stdout: the harness discards a hook's stdout wholesale unless it
# is exactly ONE JSON document, so a stray byte here would silently delete the deny envelope.
_pg_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git push origin main"}}' | CLAUDE_PROJECT_DIR="$_pg_root" bash .claude/hooks/block-push-without-approval.sh 2>/dev/null)
assert_one_json_doc "PARSE: push-guard deny arm is STILL exactly one hookSpecificOutput doc with the fires log wired" "$_pg_out" 'ALLOW_PUSH=1'
rm -rf "$_pg_root"

echo ""
echo "=== scan-secrets-writes.sh (Edit/Write WARN on secret patterns) ==="
# FIRE: Anthropic API key in a temp .ts file
tmpfire=$(mktemp -t secret-fire-XXXXXX).ts
printf 'const k = "%s";\n' 'sk-''ant-api03-abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQR' > "$tmpfire"   # fake key, assembled at run time
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpfire\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "FIRE sk-""ant- in .ts → stderr warns Anthropic" "$out" "Anthropic"
sout=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpfire\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>/dev/null)
assert_one_json_doc "PARSE: scan-secrets-writes.sh FIRE arm → ONE parseable hookSpecificOutput doc, the fires-ledger path survives" "$sout" '.claude/logs/secret-scan-fires.jsonl'
rm -f "$tmpfire"

# LEDGER WIRED (write path): the fire above must have appended a ledger line. Without this arm
# an unwired ledger later reads "0 fires in N days" as vacuous evidence (session-cadence.md
# § "ZERO TRUE POSITIVES IN N DAYS" IS VACUOUS IF THE INSTRUMENT WAS NEVER WIRED).
assert_contains "FIRE writes a ledger line (write path)" "$(cat "$SECRET_SCAN_FIRES_LOG" 2>/dev/null)" '"hook":"scan-secrets-writes"' 

# GUARANTEE ARM: under HOOK_SMOKE_EXEC=1
# with NO explicit ledger override, the write is REFUSED — while the warning still emits (the
# guard must never mute the product). PREDICATE, not a shared-file delta: the
# assertion is scoped to the fixture's OWN mktemp path, so a concurrent session's real fire
# cannot FALSE-FAIL it, and a lucky zero delta cannot pass it. Deleting the hook's guard
# writes the fixture path into the live ledger and REDs this.
_sg_ledger="$REPO_ROOT/.claude/logs/secret-scan-fires.jsonl"
tmpsg=$(mktemp -t secret-smokeguard-XXXXXX).ts
printf 'const k = "%s";\n' 'sk-''ant-api03-abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQR' > "$tmpsg"   # fake key, assembled at run time
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpsg\"}}" | HOOK_SMOKE_EXEC=1 SECRET_SCAN_FIRES_LOG= bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "smoke-guard: warn still emits under HOOK_SMOKE_EXEC" "$out" "Anthropic"
if [ -f "$_sg_ledger" ] && grep -qF "$tmpsg" "$_sg_ledger"; then
  fail "smoke-guard: fixture path REACHED the live ledger under HOOK_SMOKE_EXEC ($tmpsg) — the refuse-guard did not hold"
else
  pass "smoke-guard: fixture path absent from live ledger under HOOK_SMOKE_EXEC"
fi
rm -f "$tmpsg"

# SAFE: plain code, no secrets
tmpsafe=$(mktemp -t secret-safe-XXXXXX).ts
echo 'export const greet = "hello";' > "$tmpsafe"
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpsafe\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_empty "SAFE plain .ts → silent" "$out"
rm -f "$tmpsafe"

# SAFE: secret pattern in .md (allowed — docs reference key formats)
tmpmd=$(mktemp -t secret-md-XXXXXX).md
echo 'API keys look like sk-''ant-api03-XXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXXX' > "$tmpmd"
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpmd\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_empty "SAFE secret-pattern in .md → silent (skipped by path)" "$out"
rm -f "$tmpmd"

# FIRE: postgres URL WITH inline password. The commit-path scanner and this write-path scanner
# must cover the same class.
tmppg=$(mktemp -t secret-pg-XXXXXX).ts
echo 'const db = "postgres''ql://user:hunter2''@db.example.com:5432/x";' > "$tmppg"
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmppg\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "FIRE postgres URL w/ password in .ts → warns" "$out" "postgres URL with inline password"
rm -f "$tmppg"

# ⛔ PLACEHOLDER-PASSWORD TIGHTENING.
# A bare regex matches a PLACEHOLDER as readily as a credential, which would make any doc that shows
# a placeholder connection string (`…:<password>@…`) un-scannable: scanning it would buy a permanent
# false positive on a known-good file.
# ⚠️ THE FIRE ARMS BELOW MATTER MORE THAN THE SILENT ONES. Tightening a security pattern
# fails in ONE forbidden direction — a silent false NEGATIVE — so every form deliberately
# left FIRING is pinned here. A future tidy-up that "also excludes REDACTED/PASS/$VAR"
# looks like a completion of this fix and is a regression; these arms RED on it.
_ss_pg() {  # <label> <content> <expect: FIRE|SILENT>
  local f; f=$(mktemp -t secret-pgph-XXXXXX).ts
  printf '%s\n' "$2" > "$f"
  local o; o=$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$f" \
    | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
  if [ "$3" = "FIRE" ]; then
    assert_contains "postgres arm FIRES on $1" "$o" "postgres URL with inline password"
  else
    assert_empty "postgres arm SILENT on $1" "$o"
  fi
  rm -f "$f"
}
# Excluded BY CONSTRUCTION — RFC 3986 forbids these gen-delims unencoded in userinfo, so the
# URI cannot connect and cannot be a leaked credential.
_ss_pg "an angle-bracketed placeholder"            'postgres''ql://u:<password>@h:5432/db'  SILENT
_ss_pg "a brace placeholder"                       'postgres''ql://u:{password}@h:5432/db'  SILENT
_ss_pg "a square-bracket placeholder"              'postgres''ql://u:[placeholder]@h:5432/db'  SILENT
_ss_pg "an all-asterisk mask"                      'postgres''ql://u:***@h:5432/db'         SILENT
# DELIBERATELY still firing — a word or a $-prefix is a LEGAL password, so excluding them
# would trade a false positive for a silent miss.
_ss_pg "the word REDACTED (a legal password)"      'postgres''ql://u:REDACTED@h:5432/db'    FIRE
_ss_pg "a \$VAR-shaped password (may be literal)"  'postgres''ql://u:$ecretPass@h:5432/db'  FIRE
_ss_pg "an UNCLOSED bracket (not a placeholder)"   'postgres''ql://u:<notclosed@h:5432/db'  FIRE
_ss_pg "a bracket INSIDE a real password"          'postgres''ql://u:a<b>c@h:5432/db'       FIRE
_ss_pg "a colon-bearing password (extraction)"     'postgres''ql://u:pa:ss@h:5432/db'       FIRE
_ss_pg "an asterisk inside a real password"        'postgres''ql://u:pass*word@h:5432/db'   FIRE
# ⛔ A REAL password that happens to be bracket-WRAPPED must still fire. A bracket INSIDE a
# password (`a<b>c`, above) is a different case from the wrapped one, and only the wrapped case
# exercises the one failure direction the tightening must not open. The brackets are NOT the test;
# the INTERIOR is. A word-ish interior is a placeholder, anything carrying digits or symbols
# is secret-shaped and fires.
# The secret-shaped interior is composed at run time, so no literal credential sits in this file.
_ss_wrapped() { printf 'postgre%s://u:%sXk9%smQ2!vR7%s@h:5432/db' sql "$1" '$' "$2"; }  # <open> <close>
_ss_pg "a bracket-WRAPPED REAL password"               "$(_ss_wrapped '[' ']')"  FIRE
_ss_pg "an angle-WRAPPED REAL password"                "$(_ss_wrapped '<' '>')"  FIRE
_ss_pg "a brace-WRAPPED REAL password"                 "$(_ss_wrapped '{' '}')"  FIRE
_ss_pg "a bracket-wrapped weak-but-REAL password"      'postgres''ql://u:[hunter2]@h:5432/db'      FIRE
# …and the placeholder side must survive the tightening, incl. multi-word and dotted forms.
_ss_pg "a braced placeholder WORD"                     'postgres''ql://u:{YOUR_PASSWORD}@h:5432/db' SILENT
_ss_pg "a bracketed multi-word placeholder"            'postgres''ql://u:[db pass]@h:5432/db'       SILENT
_ss_pg "a dotted placeholder word"                     'postgres''ql://u:<your.password>@h:5432/db' SILENT
# ⛔ FIVE SHAPES A SIMPLE `user:pass@host` PREDICATE MISSES.
# Each arm below reads SILENT against `postgres(ql)?://[^[:space:]:@/]+:[^[:space:]@/]+@…`, so
# a lib using that pattern turns exactly these five red.
_ss_pg "an UPPERCASE scheme"                           'const d="POSTGRESQL://u:R3alPassw0rd''@db.example.com:5432/x";'  FIRE
_ss_pg "an EMPTY user"                                 'const d="postgres''ql://:R3alPassw0rd''@db.example.com:5432/x";'   FIRE
_ss_pg "a password containing a slash"                 'const d="postgres''ql://u:R3al/Passw0rd''@db.example.com:5432/x";' FIRE
_ss_pg "the ?password= QUERY form"                     'const d="postgres''ql://u''@db.example.com:5432/postgres?password=R3alPassw0rd";' FIRE
_ss_pg "a +dialect scheme (SQLAlchemy)"                'DATABASE_URL=postgresql+psycopg2://u:R3alPassw0rd''@db.example.com:5432/x' FIRE
# …and the widening must not light up what is not a credential. The JSON arm is the one the
# slash alternative would hit without its quote stop: host:PORT/path, then a later `@`.
_ss_pg "a ?password= placeholder"                      'postgres''ql://db.example.com/x?password=<password>'           SILENT
_ss_pg "an UPPERCASE-scheme placeholder"               'POSTGRESQL://u:<password>@h:5432/db'                          SILENT
_ss_pg "a ?password= at a loopback host"               'postgres''ql://localhost:5432/x?password=test'                  SILENT
_ss_pg "a credential-less URL"                         'const d="postgres''ql://db.example.com:5432/x";'               SILENT
_ss_pg "a credential-less URL, then an email in JSON"  '{"db":"post''gres://db.example.com:5432/x","to":"me''@example.com"}' SILENT
_ss_pg "a db_password= param (not the password key)"   'postgres''ql://h/x?db_password=R3alPassw0rd'                    SILENT
_ss_pg "an UPPERCASE scheme + ?PASSWORD= key"          'const d="POSTGRESQL://db.example.com:5432/x?PASSWORD=R3alPassw0rd";' FIRE
# The lib is SOURCED by both scanners. Both are PostToolUse and neither runs `set -e`, so a broken lib
# does not deny a call — it drops each scanner to its FALLBACK regex (pinned below), and an unbound
# variable reached under scan-secrets-writes.sh's `set -u` kills the warning outright (the FIRE arms
# above go red on that). Pin that the lib parses and sources clean in strict mode.
assert_eq "pg-secret lib parses (bash -n)" "0" "$(bash -n .claude/hooks/lib/pg-secret.sh 2>/dev/null; echo $?)"
assert_eq "pg-secret lib sources clean under set -euo pipefail" "ok" \
  "$(bash -c 'set -euo pipefail; . .claude/hooks/lib/pg-secret.sh; type pg_url_has_real_password >/dev/null; echo ok' 2>/dev/null)"
# LENGTH CAP: an over-long hit FIRES instead of feeding the quadratic
# host strips. A placeholder is SILENT under 2 KB, so this arm reds if the cap is removed.
_ss_pg "an over-long hit (length cap, fires)"   "postgres""ql://u:<password>@$(printf 'h%.0s' $(seq 1 3000))"   FIRE
# ⛔ THE FALLBACKS MUST STAY A SUPERSET OF THE LIB — the lib-absent path is the one these arms exist
# for: a fallback that lags the lib would let a missing or unparseable lib silence all five shapes
# above on BOTH scanners. Write path: run the REAL
# hook from a copy whose lib/ has no pg-secret.sh. Commit path: run its OWN fallback function, extracted.
_pgfb_dir="$(mktemp -d)"; mkdir -p "$_pgfb_dir/lib"
cp .claude/hooks/scan-secrets-writes.sh "$_pgfb_dir/"; cp .claude/hooks/lib/warn-emit.sh "$_pgfb_dir/lib/" 2>/dev/null
assert_eq "fallback rig: the copy has NO pg-secret.sh (else the arms below test the lib)" "0" \
  "$([ -f "$_pgfb_dir/lib/pg-secret.sh" ] && echo 1 || echo 0)"
_pgfb_fn="$(sed -n '/^pg_url_has_real_password() {/,/^}/p' .claude/hooks/validate-no-secrets.sh)"
assert_contains "fallback rig: the commit path's fallback function was extracted" "$_pgfb_fn" "grep -q"
for _pgfb in 'POSTGRESQL://u:R3alPassw0rd''@db.example.com:5432/x' 'postgres''ql://:R3alPassw0rd''@db.example.com:5432/x' \
    'postgres''ql://u:R3al/Passw0rd''@db.example.com:5432/x' 'postgres''ql://u''@db.example.com:5432/postgres?password=R3alPassw0rd' \
    'postgresql+psycopg2://u:R3alPassw0rd''@db.example.com:5432/x'; do
  _pgfb_f=$(mktemp -t secret-pgfb-XXXXXX).ts; printf 'const d="%s";\n' "$_pgfb" > "$_pgfb_f"
  assert_contains "WRITE-PATH FALLBACK (lib absent) still FIRES on $_pgfb" \
    "$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$_pgfb_f" | bash "$_pgfb_dir/scan-secrets-writes.sh" 2>&1)" \
    "postgres URL with inline password"
  assert_eq "COMMIT-PATH FALLBACK still FIRES on $_pgfb" "FIRE" \
    "$(bash -c "$_pgfb_fn"'
pg_url_has_real_password "$1" && echo FIRE || echo SILENT' _ "$_pgfb_f" 2>/dev/null)"
  rm -f "$_pgfb_f"
done
# CONTROL: the lib-absent fallback stays silent on a
# credential-less URL, so the FIRE arms above cannot be passing on any postgres URL at all.
_pgfb_f=$(mktemp -t secret-pgfb-XXXXXX).ts; printf 'const d="postgres''ql://db.example.com:5432/x";\n' > "$_pgfb_f"
assert_not_contains "WRITE-PATH FALLBACK (lib absent) CONTROL: silent on a credential-less URL" \
  "$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$_pgfb_f" | bash "$_pgfb_dir/scan-secrets-writes.sh" 2>&1)" \
  "postgres URL with inline password"
rm -f "$_pgfb_f"
rm -rf "$_pgfb_dir"
assert_eq "both scanners carry the SAME fallback line" \
  "$(grep -E '^  grep -qiE .postgres' .claude/hooks/scan-secrets-writes.sh)" \
  "$(grep -E '^  grep -qiE .postgres' .claude/hooks/validate-no-secrets.sh)"
# errexit-safety of the lib itself: a no-match on the userinfo shape must not end the function under a
# caller's `set -e` before the query shape is read.
_pgq=$(mktemp -t secret-pgq-XXXXXX).ts; printf 'x="postgres''ql://u''@db.example.com:5432/x?password=R3alPassw0rd"\n' > "$_pgq"
assert_eq "pg-secret lib: a bare call under set -e on a query-only file returns 0, not an abort" "0" \
  "$(bash -c 'set -e; . .claude/hooks/lib/pg-secret.sh; pg_url_has_real_password "$1"; echo $?' _ "$_pgq" 2>/dev/null)"
rm -f "$_pgq"

# ⛔ THE PATH SHAPE THE SCANNER TREATS AS A CREDENTIAL-REFERENCE DOC IS SCANNED — and SILENCE ALONE
# CANNOT PROVE IT. A skipped file and a scanned-but-clean file both emit nothing, so the load-bearing
# arm is the one that plants a REAL credential under that path shape and requires a FIRE.
_ss_ref=$(mktemp -d)/.claude/project-memory; mkdir -p "$_ss_ref"
printf 'postgres''ql://postgres.<project-ref>:<password>@<pooler-host>:5432/postgres\n' > "$_ss_ref/reference_probe.md"
out=$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$_ss_ref/reference_probe.md" \
  | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_empty "a credential-reference doc with a PLACEHOLDER password → silent (no permanent FP)" "$out"
printf 'postgres''ql://postgres.<project-ref>:R3alPassw0rd''@<pooler-host>:5432/postgres\n' > "$_ss_ref/reference_probe.md"
out=$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$_ss_ref/reference_probe.md" \
  | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "a credential-reference doc with a REAL credential → FIRES (proves SCANNED, not skipped)" "$out" "postgres URL with inline password"
rm -rf "$_ss_ref"
# CONTROL — the `.md` skip stays narrow. Ordinary .md files are outside this scanner's
# scope; only the credential-reference class is inside it.
_ss_md=$(mktemp -t secret-plain-XXXXXX).md
printf 'postgres''ql://u:R3alPassw0rd@h:5432/db\n' > "$_ss_md"
out=$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' "$_ss_md" \
  | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_empty "CONTROL: a plain .md is still skipped (the skip was not widened)" "$out"
rm -f "$_ss_md"

# ⛔ THE SYMLINK-ALIAS CASE.
# A string pattern over an unnormalized path gives ONE inode TWO verdicts when the same
# directory is reachable through a symlink with a different segment name (`memory/` rather
# than `project-memory/`): it FIRES via one spelling and is SILENT via the other. The general form is
# a resolved-ancestor walk, never a string prefix; this arm is that rule
# pinned at this surface. Fixture builds its OWN symlink so the arm does not depend on the
# machine's, and asserts the two spellings AGREE rather than asserting either in isolation.
_ss_ln=$(mktemp -d)
mkdir -p "$_ss_ln/.claude/project-memory"
ln -s ".claude/project-memory" "$_ss_ln/memory-alias"
printf 'postgres''ql://postgres.<project-ref>:R3alPassw0rd''@<pooler-host>:5432/postgres\n' \
  > "$_ss_ln/.claude/project-memory/reference_alias.md"
_ss_direct=$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' \
  "$_ss_ln/.claude/project-memory/reference_alias.md" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
_ss_viaalias=$(printf '{"tool_name":"Write","tool_input":{"file_path":"%s"}}' \
  "$_ss_ln/memory-alias/reference_alias.md" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "credential-reference doc FIRES via the direct path" "$_ss_direct" "postgres URL with inline password"
assert_contains "credential-reference doc FIRES via the SYMLINK ALIAS too (alias resolved)" "$_ss_viaalias" "postgres URL with inline password"
rm -rf "$_ss_ln"

# FIRE: sk-""proj- (OpenAI PROJECT key). The generic
# `sk-[a-zA-Z0-9]{40,}` arm CANNOT reach it: a real key reads sk-""proj-<...> and the `-` at
# offset 5 breaks the alnum run. A COMMIT-path fixture cannot witness the write path, so this
# fixture is here, on the Write channel the live path actually uses.
tmpproj=$(mktemp -t secret-skproj-XXXXXX).ts
printf 'const k = "%s";\n' 'sk-proj-''abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTU' > "$tmpproj"   # fake key, assembled at run time
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpproj\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "FIRE sk-""proj- in .ts → warns (write path)" "$out" "OpenAI project API key"
rm -f "$tmpproj"

# --- PGPASSWORD: the SECOND carrier of the postgres secret
# The postgres arm matches a URI; PGPASSWORD is an ENV ASSIGNMENT with no URI around it, so a URI
# arm alone matches NOTHING for it on either scanner. FOUR STATES x TWO
# CARRIERS, because an `=`-anchored arm passes every shell fixture and is blind to YAML — the
# criterion's extent would be narrower than the claim it certifies.
_pgw() { local f="$1"; printf '%s' "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$f\"}}" \
  | bash .claude/hooks/scan-secrets-writes.sh 2>&1; }
_pgsh=$(mktemp -t pgpw-XXXXXX).sh
_pgyml=$(mktemp -t pgpw-XXXXXX).yml
printf 'PGPASSWORD=FixturePass1 psql -h h\n' > "$_pgsh"
assert_contains "FIRE PGPASSWORD literal, SHELL carrier (=)" "$(_pgw "$_pgsh")" "PGPASSWORD with an inline value"
printf '          PGPASSWORD: FixturePass1\n' > "$_pgyml"
assert_contains "FIRE PGPASSWORD literal, YAML carrier (:) — an =-anchored arm is BLIND here" \
  "$(_pgw "$_pgyml")" "PGPASSWORD with an inline value"
printf 'PGPASSWORD=${DB_PASS} psql -h h\n' > "$_pgsh"
assert_not_contains "SILENT PGPASSWORD=\$VAR (the usual shell idiom)" \
  "$(_pgw "$_pgsh")" "PGPASSWORD with an inline value"
printf 'PGPASSWORD=<password>\n' > "$_pgsh"
assert_not_contains "SILENT PGPASSWORD=<password> (placeholder)" "$(_pgw "$_pgsh")" "PGPASSWORD with an inline value"
printf 'PGPASSWORD=***\n' > "$_pgsh"
assert_not_contains "SILENT PGPASSWORD=*** (mask)" "$(_pgw "$_pgsh")" "PGPASSWORD with an inline value"
printf '          PGPASSWORD: test\n' > "$_pgyml"
assert_not_contains "SILENT PGPASSWORD: test (the CI fixture, a deliberate deviation)" \
  "$(_pgw "$_pgyml")" "PGPASSWORD with an inline value"
# REGRESSION CONTROL — the three REAL carrier files must stay silent on this arm. A fixture table
# can be right while the arm still lights up the repo; this is the reading that decides that.
for _pgf in scripts/integration-test.sh scripts/e2e-local.sh .github/workflows/test.yml; do
  assert_not_contains "SILENT on the live carrier file $_pgf" "$(_pgw "$_pgf")" "PGPASSWORD with an inline value"
done
rm -f "$_pgsh" "$_pgyml"

# --- LOOPBACK EXEMPTION + the SHARED predicate lib ---------------
# Both scanners source one shared postgres predicate file, so the two cannot drift apart (a
# placeholder-interior test added to one is in both). These arms pin
# BOTH the wiring and the behaviour, on BOTH scanners, because a lib that exists but is not
# sourced is the wired-!=-fired class.
assert_eq "shared pg predicate lib EXISTS" "1" "$([ -f .claude/hooks/lib/pg-secret.sh ] && echo 1 || echo 0)"

# ⛔ STAGED-BLOB TRAP. validate-no-secrets materialises the STAGED BLOB to a temp file, and a
# signal inside that window must not leave the staged bytes in TMPDIR, so the hook traps it.
# These arms pin the trap, so deleting it goes red.
assert_eq "validate-no-secrets TRAPS the staged blob (static pin)" \
  "1" "$(grep -cE "^trap .*_vns_blob.*EXIT INT TERM HUP" .claude/hooks/validate-no-secrets.sh)"
_vt_dir="$(mktemp -d)"
# ⛔ THE ARM RUNS THE HOOK'S OWN TRAP LINE (`_vns_blob`), EXTRACTED FROM THE FILE, never a
# hand-typed copy, so a deleted OR a gutted trap cannot pass it.
_VT_TRAP="$(grep -E '^trap .*_vns_blob' .claude/hooks/validate-no-secrets.sh | head -1)"
assert_contains "TRAP arm is not vacuous: the hook's OWN trap line was extracted" "$_VT_TRAP" "_vns_blob"
cat > "$_vt_dir"/probe.sh <<VTPROBE
_vns_blob="\$(mktemp)"; printf "%s" "\$_vns_blob" > "$_vt_dir"/p1
$_VT_TRAP
printf "postgres""ql://u:S3cret""@remote.example.com/x\n" > "\$_vns_blob"; kill -TERM \$\$; sleep 1
VTPROBE
bash "$_vt_dir"/probe.sh 2>/dev/null
assert_eq "TRAP: a signal mid-window leaves NO staged blob on disk (hook's OWN trap line)" \
  "0" "$([ -f "$(cat "$_vt_dir"/p1)" ] && echo 1 || echo 0)"
# ⛔ FALSIFIABILITY CONTROL — the SAME sequence WITHOUT the trap must LEAK. Without this the arm
# above passes for any reason a file might be absent (mktemp failed, the shell never ran), which
# is the vacuous-control shape this suite exists to refuse.
bash -c 'b="$(mktemp)"; printf "%s" "$b" > '"$_vt_dir"'/p2
  printf "postgres""ql://u:S3cret""@remote.example.com/x\n" > "$b"; kill -TERM $$; sleep 1' 2>/dev/null
assert_eq "TRAP CONTROL: the same sequence WITHOUT a trap DOES leak" \
  "1" "$([ -f "$(cat "$_vt_dir"/p2)" ] && echo 1 || echo 0)"
rm -f "$(cat "$_vt_dir"/p2)" 2>/dev/null; rm -rf "$_vt_dir"
for _pgl in scan-secrets-writes validate-no-secrets; do
  assert_contains "WIRING PIN: $_pgl sources the shared pg predicate" \
    "$(cat ".claude/hooks/$_pgl.sh")" "lib/pg-secret.sh"
done
# ⛔ The commit path must NOT carry the postgres member inline — if it does, there are two
# predicates again and they can drift apart.
# ⛔ THIS ARM WAS UNFALSIFIABLE AT BIRTH UNTIL 2026-08-25. Its needle
# carried LITERAL BACKSLASHES the target does not have (`\[^\[:space:\]...`), so it read 0
# against the PARENT too — i.e. it could never have detected the re-inline it exists to catch,
# and its 0 on the shipped file meant nothing. Two things make the replacement sound:
#   (1) -F with the UNBACKSLASHED literal, and
#   (2) the TRAILING `|`, which is the discriminator between the SECRET_RE MEMBER and the
#       FALLBACK function — the shipped file legitimately still contains the bare regex at the
#       fallback (:34), so a needle without the pipe reads 1 on a correct file and would fail
#       for the wrong reason. Measured: bare literal reads 1 on BOTH; with the pipe, 1 on the
#       parent and 0 on shipped.
# ⛔ ATTRIBUTION CORRECTION, because a commit body gets this wrong and a body cannot
# be edited. That commit says the reviewer's "shipped: 0" DID NOT REPRODUCE. It reproduces
# exactly: their needle already carried the trailing pipe, and re-running their stated literal
# gives parent 1 / shipped 0. Their verdict wrote "(grep -cF)" without showing the literal, and
# I INFERRED the bare form rather than asking — so the discrepancy I reported was manufactured
# by my own substitution. The fallback-vs-member trap in (2) is a real and separate finding and
# stands; the refutation attached to it does not. Inferring an instrument you were not shown is
# the same class as the dead needle this arm exists to catch.
_pg_member='postgres(ql)?://[^[:space:]:@/]+:[^[:space:]@/]+@|'
assert_eq "commit path no longer inlines the postgres member in SECRET_RE" \
  "0" "$(grep -cF -- "$_pg_member" .claude/hooks/validate-no-secrets.sh)"
# FALSIFIABILITY CONTROL — the needle must READ 1 where the member provably exists, or the
# assertion above is decoration. The live suite reads it at a pinned historical blob of the hook;
# this copy ships without that history, so the control is not run here.
_pgx=$(mktemp -t pgloop-XXXXXX).ts
_pgw2() { printf '%s' "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$_pgx\"}}" \
  | bash .claude/hooks/scan-secrets-writes.sh 2>&1; }
printf 'const d="postgres''ql://test:test@localhost:5433/x";\n' > "$_pgx"
assert_not_contains "SILENT: loopback host is exempt (write path)" "$(_pgw2)" "postgres URL with inline password"
printf 'const d="postgres''ql://u:pw123@127.0.0.1:5432/x";\n' > "$_pgx"
assert_not_contains "SILENT: 127.0.0.1 is exempt (write path)" "$(_pgw2)" "postgres URL with inline password"
# ⛔ THE CONTROL THAT MAKES THE TWO ABOVE MEAN ANYTHING — same shape, REMOTE host, must FIRE.
# Without it a hook that stopped scanning postgres URLs entirely would pass both silences.
printf 'const d="postgre%s://postgres.smokeref:%s''@pooler.example.net:6543/x";\n' sql "Xk9mQ2""vR7zLp" > "$_pgx"   # synthetic, composed at run time
assert_contains "FIRE: a REAL password at a REMOTE host still fires (control for the exemption)" \
  "$(_pgw2)" "postgres URL with inline password"
rm -f "$_pgx"

# FIRE: pdl_ntfset_ (Paddle WEBHOOK SIGNING SECRET) on the write path.
tmpntf=$(mktemp -t secret-pdlntf-XXXXXX).ts
printf 'const s = "%s";\n' 'pdl_ntfset_''0123456789abcdefghijklmnop' > "$tmpntf"   # fake secret, assembled at run time
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmpntf\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "FIRE pdl_ntfset_ in .ts → warns (write path)" "$out" "Paddle webhook signing secret"
rm -f "$tmpntf"

# FIRE + SILENT: the Paddle LIVE API key. The hook's regex for it is split by shell quoting
# ('pdl_live_''apikey_...') so the line reads clean to a secret-shape scan, and until this pair no
# write-path arm exercised that regex at all. FIRE reds a regex that NARROWED (a whole key no longer
# matches). SILENT reds one that WIDENED: it carries a sandbox key and a live key one character short,
# so a stray space in the split (the second half becomes a FILE operand and `pdl_live_` alone is the
# pattern), a wildcarded prefix or a lowered length bound each make it fire.
tmppl=$(mktemp -t secret-pdllive-XXXXXX).ts
echo 'const k = "pdl_live_''apikey_01hq7xk9m2n4p6r8t0v2w4";' > "$tmppl"
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmppl\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_contains "FIRE a Paddle live API key in .ts → warns (the split-quoted regex joins whole)" "$out" "Paddle live API key"
printf '%s\n' 'const k = "pdl_sbox_''apikey_01hq7xk9m2n4p6r8t0v2w4";' 'const s = "pdl_live_''apikey_01hq7xk9m2n4p6r8t0v";' > "$tmppl"
out=$(echo "{\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$tmppl\"}}" | bash .claude/hooks/scan-secrets-writes.sh 2>&1)
assert_not_contains "SILENT: a sandbox key and a 19-char live key do not fire the live-key arm" "$out" "Paddle live API key"
rm -f "$tmppl"

echo ""
echo "=== check-memory-size.sh (Edit/Write WARN on MEMORY.md size) ==="
# FIRE: synthesize a 700-line MEMORY.md (>WARN=600)
tmpwarn=$(mktemp -d)/MEMORY.md
mkdir -p "$(dirname "$tmpwarn")"
yes 'line' | head -n 700 > "$tmpwarn"
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmpwarn\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE 700-line MEMORY.md → stderr warn-threshold message" "$out" "warn threshold"
sout=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmpwarn\"}}" | bash .claude/hooks/check-memory-size.sh 2>/dev/null)
assert_one_json_doc "PARSE: check-memory-size.sh line-warn arm → ONE parseable hookSpecificOutput doc, the '/meta stale' prescription survives" "$sout" '/meta stale'
rm -rf "$(dirname "$tmpwarn")"

# FIRE: the urgent tier — CONVERTED 2026-08-01 from a 4100-LINE fixture
# asserting "soft budget" to a BYTE fixture asserting the read-cliff band. The old arm
# tested `URGENT=4000` lines, a predicate now retired as structurally blind (skill MEMORY
# runs 139-318 B/line, so it fired 3-4x PAST the cliff and missed 22 of 23 capped files).
# ⚠️ NOT a deletion — deleting it would have silently dropped urgent-tier coverage. Note
# the path had to change too: the old fixture was a bare /tmp/<dir>/MEMORY.md, which the
# byte branch scopes OUT (it keys on */skills/*/MEMORY.md), so a same-path rewrite would
# have asserted against a branch that can never fire. Bytes come from the committed
# fixture file.
tmpurgentroot=$(mktemp -d); tmpurgentdir="$tmpurgentroot/skills/probe"; mkdir -p "$tmpurgentdir"
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmpurgentdir/MEMORY.md"   # 60,967 B > 57,500
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmpurgentdir/MEMORY.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
# ⚠️ TOKEN RE-POINTED 2026-08-17: the pin was "SILENT-TRUNCATION BAND", which is the exact
# phrasing measured FALSE on 2026-08-06 — warn-large-tracker-read.sh ARM B DENIES at this same 57500 threshold
# with paging coordinates, so the reader is told. The assertion was pinning the falsehood in
# place: correcting the hook's message broke this arm, which is the arm working. "OVER-BAND"
# stays DISCRIMINATING against the WARN tier below (whose message says "read-ceiling").
assert_contains "FIRE over-ceiling skill MEMORY.md (60967 B) → stderr OVER-BAND paging notice" "$out" "OVER-BAND"
rm -rf "$tmpurgentroot"

# SAFE: under threshold
tmpok=$(mktemp -d)/MEMORY.md
mkdir -p "$(dirname "$tmpok")"
yes 'line' | head -n 100 > "$tmpok"
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmpok\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_empty "SAFE 100-line MEMORY.md → silent" "$out"
rm -rf "$(dirname "$tmpok")"

# --- ARCHIVE TIER (2026-08-06, PHASE 1 of the meta memory archive split) ---
# MEMORY-ARCHIVE*.md matched NEITHER glob in this hook, so 24 archives (38 KB-405 KB, six already
# past the Read hard-refusal ceiling) were size-unmonitored. Sizes are generated rather than taken
# from a committed fixture on purpose: this hook keys on `wc -c` alone (no density, no content
# parsing), so a 250 KB fixture in the repo would buy nothing the generator does not. That is the
# opposite of the byte-BAND arm above, which needs real prose density and rightly uses a file.
tmparcroot=$(mktemp -d); tmparc="$tmparcroot/skills/probe"; mkdir -p "$tmparc"
# SAFE: a correctly-sized 150 KB shard is silent. This is the DISCRIMINATING row — it is 30,000
# lines, so it also pins that the 600-line SCANNABILITY warn is suppressed for archives. Reusing
# the hot thresholds (57,500) or leaving the line-warn live would fire here, on a file doing
# exactly what the split designed it to do, and an always-noisy warn is a disabled warn.
yes 'line' | head -n 30000 > "$tmparc/MEMORY-ARCHIVE-2026-04-01-2026-05-01.md"   # 150,000 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmparc/MEMORY-ARCHIVE-2026-04-01-2026-05-01.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_empty "SAFE 150000 B / 30000-line archive shard (within the 200 KB design cap) → silent" "$out"
# FIRE: THE DISCRIMINATING ARM (2026-08-07). The threshold was 210000 ("the 200 KB design cap
# plus ~5% headroom") while `--roll`'s own predicate is `bytes > SHARD_CAP_BYTES` (200,000) — so
# 200,000..210,000 was a band in which a roll was DUE and the hook was SILENT, and the live corpus
# was sitting in it (a meta archive shard at 203,900 B, over cap, no warn,
# while `--roll --dry-run` reported "over cap" for that exact file).
# ⛔ THIS ARM IS THE POINT OF THE FIX, NOT DECORATION. The two arms below (220,000 / 260,000) fire
# under BOTH the old and the new threshold, so lowering the number alone leaves the PASS COUNT
# UNCHANGED — the tell that a coverage change has no arm on the new shape. Derive the
# fixture from the OBLIGATION (a shard past the split's cap), never from the pattern.
yes 'line' | head -n 41000 > "$tmparc/MEMORY-ARCHIVE-2026-04-15-2026-05-15.md"   # 205,000 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmparc/MEMORY-ARCHIVE-2026-04-15-2026-05-15.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE 205000 B archive shard (the old 200-210 KB blind band) → past the shard budget" "$out" "shard budget"
# ⛔ THE BOUNDARY PAIR. rollLayout fires on `bytes > shardCap` (STRICTLY greater), so at EXACTLY
# 200,000 B the roll declines "every file is within cap" — a `-ge` here would warn anyway and
# prescribe a command that does nothing. These two arms are the only ones that can tell `-ge`
# from `-gt`; every other archive arm (205k/220k/260k) passes under both. 40000 lines x 5 B.
yes 'line' | head -n 40000 > "$tmparc/MEMORY-ARCHIVE-2026-02-01-2026-02-02.md"                 # exactly 200,000 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmparc/MEMORY-ARCHIVE-2026-02-01-2026-02-02.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_empty "SILENT at EXACTLY 200000 B — the roll would decline, so the warn must not prescribe it" "$out"
yes 'line' | head -n 40000 > "$tmparc/MEMORY-ARCHIVE-2026-03-01-2026-03-02.md"; printf 'x' >> "$tmparc/MEMORY-ARCHIVE-2026-03-01-2026-03-02.md"   # 200,001 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmparc/MEMORY-ARCHIVE-2026-03-01-2026-03-02.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE at 200001 B — one byte over is where the roll actually fires" "$out" "shard budget"
# ⛔ THE BASH CHANNEL — this arm exists because EVERY arm above it is an `Edit` payload, and an
# Edit on a skills MEMORY file is DENIED one event earlier by block-subagent-memory-write.sh,
# whose own deny reason names `>>` as "the ONE canonical path for MEMORY persistence". So until
# 2026-08-07 this hook was wired PostToolUse on `Edit|Write` only and could not fire on the
# channel the writes actually use — measured with the live meta shard 3,900 B over its roll cap
# and every instrument silent. Same fixture as the arm above ON PURPOSE: holding the SIZE constant
# isolates the CHANNEL, so a regression in the matcher wiring REDs here and nowhere else.
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"cat >> %s <<EOF\\nx\\nEOF"}}' "$tmparc/MEMORY-ARCHIVE-2026-04-15-2026-05-15.md" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE 205000 B archive shard via the BASH append channel (>> redirect) → past the shard budget" "$out" "shard budget"
# NEGATIVE CONTROL for the same arm: an ordinary Bash redirect to a non-memory path stays silent.
# Without this, the arm above would pass just as well if the hook fired on EVERY Bash call.
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"echo hi > %s/not-a-memory-file.txt"}}' "$tmparc" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_empty "SILENT: ordinary Bash redirect to a non-memory path (negative control for the channel arm)" "$out"
# ⛔ RELATIVE TARGET FROM A NON-ROOT CWD. The canonical prescribed append is repo-RELATIVE
# (`>> .claude/skills/<expert>/MEMORY.md`, block-subagent-memory-write.sh:131), and the first
# version of the Bash-channel port resolved nothing — so it fired from the repo root and was
# SILENT from any subdir, i.e. unreachable on exactly the path shape the docs prescribe.
# Own git repo so `--show-toplevel` resolves to the fixture and the live tree is never written.
tmprel=$(mktemp -d); ( cd "$tmprel" && git init -q . 2>/dev/null )
mkdir -p "$tmprel/.claude/skills/meta"
yes 'line' | head -n 41000 > "$tmprel/.claude/skills/meta/MEMORY-ARCHIVE-2026-01-01-2026-01-02.md"  # 205,000 B
relpath=".claude/skills/meta/MEMORY-ARCHIVE-2026-01-01-2026-01-02.md"
mkdir -p "$tmprel/subdir"
# CONTROL first: from the root of that repo it must fire, else the fixture proves nothing.
out=$( cd "$tmprel" && printf '{"tool_name":"Bash","tool_input":{"command":"cat >> %s <<EOF\\nx\\nEOF"}}' "$relpath" | bash "$REPO_ROOT/.claude/hooks/check-memory-size.sh" 2>&1 )
assert_contains "FIRE relative target, cwd = repo root (control for the subdir arm)" "$out" "shard budget"
out=$( cd "$tmprel/subdir" && printf '{"tool_name":"Bash","tool_input":{"command":"cat >> %s <<EOF\\nx\\nEOF"}}' "$relpath" | bash "$REPO_ROOT/.claude/hooks/check-memory-size.sh" 2>&1 )
assert_contains "FIRE relative target from a NON-ROOT cwd (repo-root resolution; was silent pre-fix)" "$out" "shard budget"
rm -rf "$tmprel"
# FIRE: comfortably past the shard budget, still under the Read cliff → informational roll-a-shard.
yes 'line' | head -n 44000 > "$tmparc/MEMORY-ARCHIVE-2026-05-01-2026-06-01.md"   # 220,000 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmparc/MEMORY-ARCHIVE-2026-05-01-2026-06-01.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE 220000 B archive shard → past the shard budget" "$out" "shard budget"
# FIRE: past the 250 KB Read hard-refusal ceiling → the tier that actually matters for the 6
# existing over-cap expert archives.
yes 'line' | head -n 52000 > "$tmparc/MEMORY-ARCHIVE-2026-06-01-2026-07-01.md"   # 260,000 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$tmparc/MEMORY-ARCHIVE-2026-06-01-2026-07-01.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE 260000 B archive → ARCHIVE OVER READ-CEILING (Read returns zero content)" "$out" "ARCHIVE OVER READ-CEILING"
rm -rf "$tmparcroot"

# --- LIVE-REGISTER TIER (2026-09-13) ---
# `WATCH-TIER.md` and `ADOPTION-QUEUE.md` matched NEITHER glob in this hook, so both exit 0 before
# any threshold is read — which is WHY the 200 KB shard cap gets crossed silently between curation
# passes (measured 2026-09-13: the register at 213,757 B with `--scan-routers` reporting
# REGISTER-OVER-CAP, and five tracker rows filed on that ONE condition in eighteen days). Sizes are
# generated rather than committed for the same reason the archive tier generates them: the arm keys
# on `wc -c` alone, so a 200 KB fixture in the repo would buy nothing. Temp root canonicalised with
# `pwd -P` (`mktemp -d` returns the symlinked /var spelling here).
_reg_root=$(cd "$(mktemp -d)" && pwd -P); _reg="$_reg_root/skills/meta"; mkdir -p "$_reg"
_regedit() { echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$1\"}}" | bash .claude/hooks/check-memory-size.sh 2>&1; }
# FIRE: past the cap.
yes 'line' | head -n 40200 > "$_reg/WATCH-TIER.md"                                   # 201,000 B
out=$(_regedit "$_reg/WATCH-TIER.md")
assert_contains "FIRE 201000 B WATCH-TIER.md → REGISTER OVER SHARD CAP" "$out" "REGISTER OVER SHARD CAP"
# The REMEDY is the point of a separate arm: `--roll` cannot cut a NAMED live register, so the
# archive tier's "roll a new dated shard" advice would prescribe a command that does nothing here.
assert_contains "FIRE ... prescribes CURATION, not the --roll that cannot cut a named live register" "$out" "Remedy is CURATION"
# ⛔ THE MODEL-CHANNEL / ONE-DOCUMENT ARM. The harness discards a hook's stdout WHOLESALE unless it
# is exactly one JSON document, so a new arm that emitted on stdout would silently delete the
# line-warn's document on any write that trips both. This arm pins the register tier at ZERO
# documents (stderr only, like every other byte tier in this hook).
assert_empty "REGISTER tier writes NOTHING to stdout (cannot concatenate into a second JSON doc)" \
  "$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$_reg/WATCH-TIER.md\"}}" | bash .claude/hooks/check-memory-size.sh 2>/dev/null)"
# ⛔ AND THE SCANNABILITY WARN MUST STAY SUPPRESSED. This fixture is 40,200 lines, so without the
# IS_REGISTER arm in the line-warn guard the hook would emit "consider /meta stale" on EVERY
# register append — an always-noisy warn is a disabled warn, and it would take the MODEL channel
# while the over-cap message (stderr, like every byte tier) does not. Mutating `$IS_REGISTER -eq 0`
# out of that guard REDs this arm and the SAFE arm below.
assert_not_contains "REGISTER: the 600-line SCANNABILITY warn is suppressed (register is thousands of lines BY DESIGN)" "$out" "warn threshold"
# ⛔ THE BASH CHANNEL — this is the arm that makes the file-selection edit non-decorative. An Edit
# on a register is DENIED one event earlier by block-subagent-memory-write.sh, whose deny text
# forces appends through `>>`; so the `>>` channel is the ONLY one a real register write uses, and
# the pre-filter is what lets a register target reach this hook at all.
out=$(printf '{"tool_name":"Bash","tool_input":{"command":"cat >> %s <<EOF\\nx\\nEOF"}}' "$_reg/WATCH-TIER.md" | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "FIRE 201000 B WATCH-TIER.md via the BASH append channel (>> redirect) → over shard cap" "$out" "REGISTER OVER SHARD CAP"
# SAFE: comfortably under.
yes 'line' | head -n 38000 > "$_reg/WATCH-TIER.md"                                   # 190,000 B
assert_empty "SAFE 190000 B / 38000-line register → silent" "$(_regedit "$_reg/WATCH-TIER.md")"
# BAND: the approach tier, on the OTHER register so the arm is not a one-pattern proof.
yes 'line' | head -n 39800 > "$_reg/ADOPTION-QUEUE.md"                               # 199,000 B
out=$(_regedit "$_reg/ADOPTION-QUEUE.md")
assert_contains "BAND 199000 B ADOPTION-QUEUE.md → the approach-tier notice" "$out" "within 2,000 B"
assert_not_contains "BAND ... and NOT the over-cap warn (the two tiers are discriminated)" "$out" "REGISTER OVER SHARD CAP"
# ⛔ BOUNDARY, and it DIVERGES FROM THE ARCHIVE ARM ON PURPOSE. The archive tier uses `-gt` to match
# `rollLayout`'s strictly-greater predicate, because at exactly 200,000 B a roll declines and the
# warn would prescribe a no-op. A register has no such window: `--roll` is a no-op at EVERY size
# here and the remedy is curation, which is always available. Do not "align" this to `-gt` — this
# arm is what tells the two apart, and aligning it re-opens a blind byte at the cap.
yes 'line' | head -n 40000 > "$_reg/ADOPTION-QUEUE.md"                               # exactly 200,000 B
assert_contains "FIRE at EXACTLY 200000 B (register uses -ge; the archive tier's -gt does NOT apply)" "$(_regedit "$_reg/ADOPTION-QUEUE.md")" "REGISTER OVER SHARD CAP"
# NEGATIVE CONTROL: the arm keys on the PATH, never on the NAME. A same-named file outside
# */skills/meta/ is not the register and must stay silent — without this, the arm would pass just
# as well if the hook fired on any file called WATCH-TIER.md.
yes 'line' | head -n 40200 > "$_reg_root/WATCH-TIER.md"                              # 201,000 B, wrong path
assert_empty "SILENT: a 201000 B WATCH-TIER.md OUTSIDE */skills/meta/ (path-keyed, not name-keyed)" "$(_regedit "$_reg_root/WATCH-TIER.md")"
# --- WATCH-TIER PARTS + THE SWEEP PREDICATE (2026-10-10) ---
# The register is SHARDED (WATCH-TIER.md + WATCH-TIER-PART-NN.md, ~51 KB each), so the
# single-file approach tier above (>= 198,000 B) can never fire on it again. For a WATCH-TIER part the
# hook's predicate is the retire sweep's own DUE NOW count, read by running
# `node scripts/watch-tier-retire-sweep.mjs` from the tree root the path implies
# (<root>/.claude/skills/meta/...); when the sweep cannot answer, the FALLBACK is the summed bytes of the
# parts beside the written file against the shard cap. Fixture: a throwaway root carrying a STUB sweep
# whose only job is to print the DUE NOW line, so the arms key on the hook's reading of that line and the
# path → root derivation, never on the real register's state. The parts are tiny so no byte tier speaks.
_wtp_root=$(cd "$(mktemp -d)" && pwd -P); _wtp="$_wtp_root/.claude/skills/meta"; mkdir -p "$_wtp" "$_wtp_root/scripts"
printf 'line\n' > "$_wtp/WATCH-TIER.md"
printf 'line\n' > "$_wtp/WATCH-TIER-PART-01.md"
mkdir -p "$_wtp_root/.claude" && cp -R .claude/hooks "$_wtp_root/.claude/"   # the hook runs only its OWN tree's sweep
_wtpedit() { echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$1\"}}" | bash "$_wtp_root/.claude/hooks/check-memory-size.sh" 2>&1; }
# DUE-NOW — the sweep reports work due: the predicate fires and names the count and the sweep.
printf '%s\n' 'console.log("  DUE NOW  3");' > "$_wtp_root/scripts/watch-tier-retire-sweep.mjs"
out=$(_wtpedit "$_wtp/WATCH-TIER-PART-01.md")
assert_contains "DUE-NOW WATCH-TIER-PART-01.md under a root whose stub sweep prints DUE NOW 3 → predicate fired, count named" "$out" "the retire-if sweep reports DUE NOW 3"
assert_contains "DUE-NOW ... and the remedy names the sweep, --apply second" "$out" "watch-tier-retire-sweep.mjs"
assert_not_contains "DUE-NOW ... and NOT the fallback (the sweep answered, so the byte sum is never consulted)" "$out" "FALLBACK"
# ⛔ THE MODEL CHANNEL (review-found, folded 2026-10-10). This arm pinned stdout EMPTY until then, citing the
# one-JSON-document rule — which forbids TWO documents, not one. The hook runs on PostToolUse, where its own header measured
# bare stderr reaching NO model, so the predicate line goes through warn_emit: stderr AND exactly one additionalContext
# document. One is all a WATCH-TIER write can produce, because the register's line warn is off (IS_REGISTER). Stdout only.
_wtp_sout=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$_wtp/WATCH-TIER-PART-01.md\"}}" | bash "$_wtp_root/.claude/hooks/check-memory-size.sh" 2>/dev/null)
assert_one_json_doc "DUE-NOW ... reaches the MODEL channel: exactly ONE parseable hookSpecificOutput doc carrying the DUE NOW line" "$_wtp_sout" "the retire-if sweep reports DUE NOW 3"
assert_contains "DUE-NOW ... and that doc declares hookEventName PostToolUse (the lib defaults to PreToolUse)" "$_wtp_sout" '"hookEventName": "PostToolUse"'
# NOTHING-DUE — the sweep reports nothing due: silent. A predicate that speaks at 0 is a disabled warn.
printf '%s\n' 'console.log("  DUE NOW  0");' > "$_wtp_root/scripts/watch-tier-retire-sweep.mjs"
assert_empty "NOTHING-DUE WATCH-TIER-PART-01.md, stub sweep DUE NOW 0 → silent" "$(_wtpedit "$_wtp/WATCH-TIER-PART-01.md")"
# FOREIGN ROOT — a payload path must never choose which script the hook executes. The stub leaves a marker when run.
printf '%s\n' 'import fs from "node:fs"; fs.writeFileSync("RAN", "1"); console.log("  DUE NOW  0");' > "$_wtp_root/scripts/watch-tier-retire-sweep.mjs"
_regedit "$_wtp/WATCH-TIER-PART-01.md" >/dev/null
assert_empty "FOREIGN ROOT: the repo's hook does NOT run a fixture root's sweep (no marker)" "$(cat "$_wtp_root/RAN" 2>/dev/null)"
_wtpedit "$_wtp/WATCH-TIER-PART-01.md" >/dev/null
assert_contains "FOREIGN ROOT control: the root's OWN hook copy does run it (marker written)" "$(cat "$_wtp_root/RAN" 2>/dev/null)" "1"
# NODE-FREE PATH — the sweep cannot run, so the FALLBACK sums the parts beside the written file. A shim
# PATH built from the hook's own tool set MINUS node (symlinks, so it holds on any box where the real
# tools live elsewhere); the control arm proves the shim really has no node before either arm reads.
_wtp_shim=$(mktemp -d)
for _wtp_b in bash sh jq python3 git awk sed wc grep head tail cat cut date dirname basename realpath tr sort mktemp; do
  _wtp_p=$(command -v "$_wtp_b" 2>/dev/null) && [ -x "$_wtp_p" ] && ln -s "$_wtp_p" "$_wtp_shim/$_wtp_b"
done
assert_empty "CONTROL: the shim PATH resolves no node" "$(PATH="$_wtp_shim" bash -c 'command -v node' 2>/dev/null)"
assert_contains "CONTROL: the shim PATH still resolves jq (the hook's payload reader)" "$(PATH="$_wtp_shim" bash -c 'command -v jq' 2>/dev/null)" "jq"
# parts UNDER the cap together (190,000 + 1 B) → silent: the fallback has nothing to say.
yes 'line' | head -n 38000 > "$_wtp/WATCH-TIER.md"                                       # 190,000 B
assert_empty "NODE-FREE, parts sum 190,001 B (< 200,000) → silent" \
  "$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$_wtp/WATCH-TIER-PART-01.md\"}}" | PATH="$_wtp_shim" bash .claude/hooks/check-memory-size.sh 2>&1)"
# parts AT the cap together (150,000 + 50,000 B, each far under the single-file tiers) → the fallback fires
# and says WHY the sweep was not read.
yes 'line' | head -n 30000 > "$_wtp/WATCH-TIER.md"                                       # 150,000 B
yes 'line' | head -n 10000 > "$_wtp/WATCH-TIER-PART-01.md"                               #  50,000 B
out=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$_wtp/WATCH-TIER-PART-01.md\"}}" | PATH="$_wtp_shim" bash .claude/hooks/check-memory-size.sh 2>&1)
assert_contains "NODE-FREE, parts sum 200,000 B → FALLBACK fires on the summed bytes" "$out" "FALLBACK"
assert_contains "NODE-FREE ... and names the reason the sweep was not read" "$out" "node is unavailable"
assert_not_contains "NODE-FREE ... a 50,000 B part is NOT 'REGISTER OVER SHARD CAP' (the single-file tier is for the whole file)" "$out" "REGISTER OVER SHARD CAP"
# The FALLBACK line takes the same model channel as DUE-NOW's (stdout only; the shim keeps python3, which warn_emit needs).
_wtp_sout=$(echo "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$_wtp/WATCH-TIER-PART-01.md\"}}" | PATH="$_wtp_shim" bash .claude/hooks/check-memory-size.sh 2>/dev/null)
assert_one_json_doc "NODE-FREE ... the FALLBACK line reaches the MODEL channel: exactly ONE parseable hookSpecificOutput doc carrying it" "$_wtp_sout" "predicate fired: FALLBACK"
assert_contains "NODE-FREE ... and that doc declares hookEventName PostToolUse" "$_wtp_sout" '"hookEventName": "PostToolUse"'
# SWEEP FAILED — node present, the sweep prints a DUE NOW line and exits 1: a failed run is not an answer, so the
# fallback reads the bytes and names the exit (a review lens found it: reading the count whatever the exit
# code left this section 159/0).
printf '%s\n' 'console.log("  DUE NOW  3"); process.exit(1);' > "$_wtp_root/scripts/watch-tier-retire-sweep.mjs"
out=$(_wtpedit "$_wtp/WATCH-TIER-PART-01.md")
assert_contains "SWEEP EXITED 1 (with a DUE NOW line), parts sum 200,000 B → FALLBACK naming the exit" "$out" "the sweep exited 1"
assert_not_contains "SWEEP EXITED 1 ... and its DUE NOW count is NOT reported as the predicate" "$out" "reports DUE NOW 3"
# ROOT NOT FOUND — the same part under a root with NO sweep script: the fallback's reason names the missing root.
rm -f "$_wtp_root/scripts/watch-tier-retire-sweep.mjs"
out=$(_wtpedit "$_wtp/WATCH-TIER-PART-01.md")
assert_contains "NO SWEEP SCRIPT at the root, parts sum 200,000 B → FALLBACK, reason: no <root>/... sweep for this path" "$out" "no <root>/.claude/skills/meta"
rm -rf "$_wtp_root" "$_wtp_shim"
rm -rf "$_reg_root"

echo ""
echo "=== check-memory-budget.sh (project MEMORY.md byte/line cap — PreToolUse) ==="
# FIRE: Write >25600 bytes to the project auto-loaded index → deny (content-driven, no real write)
# CLAUDE_HOOK_SMOKE=1 routes these synthetic fixtures' BLOCK lines to
# memory-budget-block.smoke.log instead of the real one. Without it these two FIRE cases
# were 1565 of 1567 entries in the production log (2026-07-28).
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/project-memory/MEMORY.md","content":"x"*30000}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE byte-cap (30KB Write) → deny" "$out" '"permissionDecision": "deny"'
sout=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/project-memory/MEMORY.md","content":"x"*30000}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>/dev/null)
assert_one_json_doc "PARSE: check-memory-budget.sh byte-cap deny arm → ONE parseable hookSpecificOutput doc, the cold MEMORY-INDEX.md relocation target survives" "$sout" 'MEMORY-INDEX.md'
# ⛔ DISCRIMINATING ARM — 25,200 B sits BETWEEN the retired cap (25600) and the real one (24985).
# The 30KB arm above trips BOTH, so it is INVARIANT across the exact defect this gate exists to
# stop: it passed identically while CAP_BYTES sat 615 ABOVE the harness cliff and the harness was
# silently truncating the always-loaded Trigger Index (measured 2026-08-13). Without this arm the
# suite is blind to the threshold and a future "tidy" back to 25600 reads fully green.
# Mutation-proven: set CAP_BYTES=25600 and THIS arm alone goes RED (the 30KB and 211-line arms
# stay GREEN), which is what proves it discriminates rather than merely fires.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/project-memory/MEMORY.md","content":"x"*25200}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE byte-cap (25.2KB — between retired 25600 and real 24985) → deny" "$out" '"permissionDecision": "deny"'
# SAFE: 24,000 B is under the real cap — must stay silent, or the gate is simply blocking everything.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/project-memory/MEMORY.md","content":"x"*24000}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "SAFE byte-cap (24KB Write, under 24985) → silent allow" "$out"
# GROWTH-ONLY WARN PATH, PARKED-SIBLING DUP — its own fixture, so the arm does not depend on the live
# MEMORY.md happening to quote a token the parked active-recall.md also carries (the 2026-10-13 >&2 fix
# was caught only because a live row happened to quote one). stdout must stay EMPTY on this warn path; the DUP line
# must still reach stderr. Red check: drop the ">&2" from the parked DUP echo -> one non-JSON stdout line.
_cmb_root=$(cd "$(mktemp -d)" && pwd -P)
mkdir -p "$_cmb_root/.claude/rules" "$_cmb_root/.claude/project-memory"
printf -- '---\npaths: [".claude/docs/rules-ARCHIVE/**"]\n---\n| row | about this session here |\n' > "$_cmb_root/.claude/rules/active-recall.md"
python3 - "$_cmb_root" <<'PYCMB'
import json, os, sys
r = sys.argv[1]; m = os.path.join(r, '.claude', 'project-memory', 'MEMORY.md')
pad = ['| filler row %d %s | act | f%d.md |' % (i, 'z' * 100, i) for i in range(170)]
cur = '\n'.join(['# M', '| If about to x | act "this session" now | feedback_x.md |'] + pad[:160]) + '\n'
open(m, 'w').write(cur)
json.dump({'tool_name': 'Write', 'tool_input': {'file_path': m, 'content': cur + '\n'.join(pad[160:]) + '\n'}},
          open(os.path.join(r, 'payload.json'), 'w'))
PYCMB
_cmb_out=$(CLAUDE_PROJECT_DIR="$_cmb_root" CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh < "$_cmb_root/payload.json" 2>"$_cmb_root/err")
assert_empty "SAFE growth-only warn (18-25 KB, parked-sibling DUP) → stdout EMPTY, no non-JSON line" "$_cmb_out"
assert_contains "FIRE growth-only warn → the parked DUP line still reaches stderr (the arm above is not vacuous)" "$(cat "$_cmb_root/err")" "is NOT redundant"
rm -rf "$_cmb_root"
# FIRE: Write >200 lines → deny
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/project-memory/MEMORY.md","content":"\n"*210}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE line-cap (211-line Write) → deny" "$out" '"permissionDecision": "deny"'
# SAFE: small Write → silent allow
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/project-memory/MEMORY.md","content":"# small\n"}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "SAFE small Write → silent allow" "$out"
# UNDER-THRESHOLD: a 30KB Write to a SKILL MEMORY.md stays silent.
# ⚠️ This assertion's RATIONALE changed 2026-08-01. It used to
# read "NOT gated (skill memories aren't auto-loaded/byte-capped)" — the second clause
# was measured-false, and skill MEMORY.md IS now gated by ARM 2 below. The assertion
# still passes, but for a DIFFERENT reason: 30,000 B is under the 46,000 B warn band.
# Kept (it pins the band's lower edge) with the premise corrected rather than deleted.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Write","tool_input":{"file_path":".claude/skills/foo/MEMORY.md","content":"x"*30000}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "UNDER-THRESHOLD skill MEMORY.md (30KB < 46KB warn band) → silent" "$out"

# ── MultiEdit CHANNEL (wired 2026-08-16) ────────────────
# The `MultiEdit)` branch in check-memory-budget.sh has existed since the ARM-3 build and was
# UNREACHABLE: settings.json routed PreToolUse on `Edit|Write` only, so no MultiEdit payload
# ever arrived. Working code, no wiring: the premise inverted.
#
# ⛔ THE FIX IS A SEPARATE MATCHER, NOT A WIDENED ONE, AND THAT IS THE POINT OF THIS BLOCK.
# The `Edit|Write` entry is shared by SIX hooks and only TWO parse MultiEdit
# (check-memory-budget, always-loaded-claim-warn — `grep -ln MultiEdit .claude/hooks/*.sh`).
# Widening the shared matcher would hand four hooks a shape they have never parsed, and TWO of
# the six can DENY fleet-wide. So a dedicated `MultiEdit` entry names only the handlers.
#
# ⚠️ THE OBVIOUS PROBE IS VACUOUS: an UNDER-cap MultiEdit exits 0 and prints nothing — byte-
# identical to a hook that never reached the branch. Only a payload CROSSING the threshold
# separates a live branch from an inert one, which is why the FIRE arm comes first.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"MultiEdit","tool_input":{"file_path":".claude/project-memory/MEMORY.md","edits":[{"old_string":"","new_string":"x"*30000}]}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE MultiEdit byte-cap (30KB across edits) → deny (proves the branch is REACHABLE)" "$out" '"permissionDecision": "deny"'
# NEGATIVE CONTROL: a small MultiEdit stays silent, or the arm above only proves the hook denies
# whatever it is handed rather than that it measures the edit.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"MultiEdit","tool_input":{"file_path":".claude/project-memory/MEMORY.md","edits":[{"old_string":"a","new_string":"b"}]}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "SAFE small MultiEdit → silent allow (negative control for the channel arm)" "$out"
# THE FOUR NON-HANDLERS must stay silent on a MultiEdit payload. This is what makes the
# separate-matcher choice CHECKABLE rather than merely argued: if someone later "simplifies"
# the two entries into one `Edit|Write|MultiEdit`, these four begin receiving a shape they
# never parse, and this is where it surfaces.
# log-memory-writes DOES record this payload (it reads file_path whatever the tool), only its stdout stays silent,
# so it runs against a sandbox ledger: run in place it wrote one `MultiEdit .claude/project-memory/MEMORY.md` row
# per suite run into the fleet-shared ledger (827 of 4,303 rows on 2026-10-06). Same label, same position.
_nh_dir="$(mktemp -d)"
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"MultiEdit","tool_input":{"file_path":".claude/project-memory/MEMORY.md","edits":[{"old_string":"a","new_string":"b"}]}}))' | CLAUDE_HOOK_SMOKE=1 CLAUDE_PROJECT_DIR="$_nh_dir" bash .claude/hooks/log-memory-writes.sh)
assert_empty "SAFE MultiEdit payload → log-memory-writes silent (does not parse MultiEdit)" "$out"
rm -rf "$_nh_dir"
for _nonhandler in block-subagent-memory-write check-test-exists dup-durable-append-warn; do
  out=$(python3 -c 'import json;print(json.dumps({"tool_name":"MultiEdit","tool_input":{"file_path":".claude/project-memory/MEMORY.md","edits":[{"old_string":"a","new_string":"b"}]}}))' | CLAUDE_HOOK_SMOKE=1 bash ".claude/hooks/${_nonhandler}.sh")
  assert_empty "SAFE MultiEdit payload → ${_nonhandler} silent (does not parse MultiEdit)" "$out"
done
# WIRING PIN — the routing itself, read off disk. Every behavioural arm above invokes the hook
# DIRECTLY, so all of them stay green if the settings.json entry is deleted; this is the only
# assertion that can see an unwiring.
_me_hooks=$(python3 -c "
import json
pre=json.load(open('.claude/settings.json'))['hooks']['PreToolUse']
e=[x for x in pre if x.get('matcher')=='MultiEdit']
print('MISSING' if not e else ' '.join(sorted(h['command'].rsplit('/',1)[-1] for h in e[0]['hooks'])))
")
assert_contains "wiring pinned: MultiEdit matcher routes to check-memory-budget" "$_me_hooks" "check-memory-budget.sh"
assert_contains "wiring pinned: MultiEdit matcher routes to always-loaded-claim-warn" "$_me_hooks" "always-loaded-claim-warn.sh"

# WARN-BAND GROWTH PREDICATE (2026-07-28) — the band fires only when the edit GROWS the
# file. Both arms asserted: a warn-that-always-fires carries no information, and a
# one-armed test could not tell the new predicate from the old absolute-size one.
# Deterministic temp fixture matching the */project-memory/MEMORY.md scope, so neither
# assertion rides on the live index's current size.
tmpmemroot=$(mktemp -d); tmpmem="$tmpmemroot/project-memory"; mkdir -p "$tmpmem"
python3 -c "open('$tmpmem/MEMORY.md','w').write('x'*20000)"
out=$(python3 -c "import json;print(json.dumps({'tool_name':'Write','tool_input':{'file_path':'$tmpmem/MEMORY.md','content':'x'*24000}}))" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_contains "FIRE warn-band GROWTH (20KB→24KB, above band) → warns" "$out" 'MEMORY budget'
out=$(python3 -c "import json;print(json.dumps({'tool_name':'Write','tool_input':{'file_path':'$tmpmem/MEMORY.md','content':'x'*19000}}))" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_empty "SAFE warn-band SHRINK (20KB→19KB, above band) → silent (growth-only)" "$out"
rm -rf "$tmpmemroot"

# --- ARM 2: skill-MEMORY no-growth ratchet (2026-08-01) ---
# Fixture BYTES live in a committed FILE (.claude/hooks/fixtures/skill-memory-oversized.md),
# never an inline heredoc: an inline fixture is indistinguishable from the
# invocation it models, and a wired block-mode Bash guard can trip on its own test payload.
# The fixture is copied into a temp tree shaped like .claude/skills/<name>/MEMORY.md so the
# scope glob matches without touching any of the 56 REAL skill memories.
tmpskillroot=$(mktemp -d); tmpskill="$tmpskillroot/.claude/skills/fixture-skill"; mkdir -p "$tmpskill"
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmpskill/MEMORY.md"   # 60,967 B — above the 57,500 ceiling
# FIRE: append one entry to an already-over-ceiling file → grows past ceiling → deny.
out=$(python3 -c "
import json,sys
body=open('.claude/hooks/fixtures/skill-memory-oversized.md').read()+'\n## 2026-08-01 — one more entry\nDecision: this append is what the ratchet must refuse.\n'
print(json.dumps({'tool_name':'Write','tool_input':{'file_path':sys.argv[1],'content':body}}))" "$tmpskill/MEMORY.md" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE ratchet: grow an over-ceiling skill MEMORY → deny" "$out" '"permissionDecision": "deny"'
# The deny reason must carry a COMPUTED same-turn remedy, not generic advice: without the
# bytes-to-free + split command the guard converts a truncation into a DROPPED lesson.
# Asserting the computed skill NAME (not just "deny") is what makes this discriminating —
# a regression to a generic reason string would still satisfy a bare deny-presence check.
assert_contains "FIRE ratchet: deny reason carries the computed split remedy" "$out" "memory-tier-split.mjs fixture-skill"
# SAFE (discriminating): shrink from ABOVE the ceiling → allowed. A naive ABSOLUTE-threshold
# guard fails exactly here, and failing here would block the distillation edits that fix the
# cohort — which is why the predicate is growth, not size.
out=$(python3 -c "
import json,sys
body=open('.claude/hooks/fixtures/skill-memory-oversized.md').read()[:58000]
print(json.dumps({'tool_name':'Write','tool_input':{'file_path':sys.argv[1],'content':body}}))" "$tmpskill/MEMORY.md" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_empty "SAFE ratchet: SHRINK from above the ceiling (60967→58000) → silent allow" "$out"
# SAFE (meta EXEMPTION): the SAME over-ceiling growing append that DENIES for any other
# skill (the FIRE arm above) must be ALLOWED on the meta path. meta/MEMORY.md is a cold
# body store with a separately-governed hot tier, and it
# takes 790 of 1,098 real skill-MEMORY writes — ratcheting it would block the fleet's L#
# persistence path. This arm PINS the carve-out (no bare suppressions): a refactor
# that drops the exemption case turns this RED instead of silently re-arming the block.
# It is discriminating only as a PAIR with the FIRE arm above — same payload shape, one
# path, opposite verdicts.
tmpmetaroot=$(mktemp -d); tmpmetadir="$tmpmetaroot/.claude/skills/meta"; mkdir -p "$tmpmetadir"
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmpmetadir/MEMORY.md"
out=$(python3 -c "
import json,sys
body=open('.claude/hooks/fixtures/skill-memory-oversized.md').read()+'\n## 2026-08-01 — a new L-numbered lesson\nDecision: meta must stay appendable.\n'
print(json.dumps({'tool_name':'Write','tool_input':{'file_path':sys.argv[1],'content':body}}))" "$tmpmetadir/MEMORY.md" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_empty "SAFE meta EXEMPTION: over-ceiling growing append to meta/MEMORY.md → allowed" "$out"
rm -rf "$tmpmetaroot"
rm -rf "$tmpskillroot"

# SAFE: non-MEMORY path
out=$(echo '{"tool_name":"Edit","tool_input":{"file_path":"/tmp/foo.ts"}}' | bash .claude/hooks/check-memory-size.sh 2>&1)
assert_empty "SAFE non-MEMORY path → silent" "$out"

echo ""
echo "=== check-memory-budget.sh BASH channel + check-memory-budget-post.sh (2026-08-12) ==="
# A Bash payload carries `command`, never `file_path`, so before 2026-08-12 this hook exited at
# its first branch on EVERY Bash write and the whole channel was unguarded.
# FIRE: a LITERAL `update-index --cacheinfo` staging an oversize blob -> deny.
smoke_blob=$(python3 -c "import sys;sys.stdout.write('x'*26000)" | git hash-object -w --stdin)
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',.claude/project-memory/MEMORY.md'}}))" "$smoke_blob" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE Bash cacheinfo (26KB blob) -> deny" "$out" '"permissionDecision": "deny"'
# SAFE: same channel, small blob -> silent.
smoke_small=$(python3 -c "import sys;sys.stdout.write('x'*100)" | git hash-object -w --stdin)
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',.claude/project-memory/MEMORY.md'}}))" "$smoke_small" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "SAFE Bash cacheinfo (100B blob) -> silent" "$out"
# ⛔ REGRESSION GUARD FOR A REAL BYPASS (2026-08-12).
# `--cacheinfo` is REPEATABLE — git's synopsis is `[(--cacheinfo <mode>,<object>,<file>)...]` —
# and the arm used to end in `| head -1`, so it inspected only the FIRST triple. A call staging a
# non-MEMORY path first fell out at the *MEMORY*.md filter and the MEMORY triple behind it was
# never read. Reachable by ORDINARY USE: isolating hunks in TWO shared files in one update-index
# call is the normal shape of the recipe this hook polices. Mutation-proven at the fold: this arm
# read ALLOW against the pre-fix hook and DENY after, while all four sibling controls held
# UNCHANGED across both versions (single-cause attribution).
smoke_decoy=$(python3 -c "import sys;sys.stdout.write('d'*10)" | git hash-object -w --stdin)
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',todo.txt --cacheinfo 100644,'+sys.argv[2]+',.claude/project-memory/MEMORY.md'}}))" "$smoke_decoy" "$smoke_blob" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE decoy-FIRST then oversize MEMORY -> deny (multi-triple bypass closed)" "$out" '"permissionDecision": "deny"'
# CONTROL, and it is what makes the arm above attributable: the decoy ALONE must stay silent, so
# the deny above provably came from the SECOND triple and not merely from "two triples present".
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',todo.txt'}}))" "$smoke_decoy" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "SAFE decoy-only cacheinfo (no MEMORY path) -> silent" "$out"
# git ACCEPTS an uppercase sha (`git cat-file -t <UPPER-SHA>` -> commit), so a lowercase-only
# [0-9a-f] class was a second git-sanctioned spelling straight past the guard.
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1].upper()+',.claude/project-memory/MEMORY.md'}}))" "$smoke_blob" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_contains "FIRE UPPERCASE sha, oversize -> deny (git accepts uppercase)" "$out" '"permissionDecision": "deny"'
# SAFE: an ordinary Bash call must not pay for a parse it cannot use.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Bash","tool_input":{"command":"ls -la"}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "SAFE ordinary Bash -> silent (zero-subprocess prefilter)" "$out"
# ⛔ ASSERTED BLINDNESS, not a bug — the codified rule is to assert a known-blind predicate in the
# negative control rather than tighten it. A PreToolUse guard must PREDICT from the command STRING,
# so a sha held in a shell variable (or built in a python f-string, which is how the prescribed
# blob-isolation recipe actually drives it) is unrecoverable at that layer. MEASURED live through
# the harness 2026-08-12: literal sha -> BLOCKED, `$B` -> NOT blocked. That gap is why
# check-memory-budget-post.sh exists; if this assertion ever FAILS, the PreToolUse arm grew a
# capability it cannot have, and the post hook is what should be covering this case.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Bash","tool_input":{"command":"git update-index --cacheinfo 100644,$B,.claude/project-memory/MEMORY.md"}}))' | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh)
assert_empty "ACCEPTED-BLIND variable-sha at PreToolUse -> silent (post hook DETECTS it post-write)" "$out"
# ⛔ THE NAME ABOVE USED TO READ "(post hook covers it)" AND THAT WAS FALSE FOR SKILL MEMORY FILES.
# The post hook checked ONE file — the project index — while 56
# skill MEMORY.md files existed, so a green assertion whose NAME claims coverage was supplying the
# misreading rather than guarding it. The hook now covers both arms; this arm asserts that, so the
# name and the code agree. "DETECTS post-write" not "covers": the post layer warns, it cannot deny.
smoke_ratchet=$(mktemp -d); git -C "$smoke_ratchet" init -q .; mkdir -p "$smoke_ratchet/.claude/skills/foo"
python3 -c "import sys;sys.stdout.write('x'*60000)" > "$smoke_ratchet/.claude/skills/foo/MEMORY.md"
out=$(cd "$smoke_ratchet" && printf '{"tool_name":"Bash","tool_input":{"command":"anything"}}' | CLAUDE_PROJECT_DIR="$smoke_ratchet" bash "$REPO_ROOT/.claude/hooks/check-memory-budget-post.sh" 2>&1)
assert_contains "FIRE post-hook ARM 2 on an over-ceiling SKILL MEMORY -> warns" "$out" "over the Read ceiling"
# Pin the CORRECTED premise (fix of 2026-08-20): correcting the hook's message must break
# this arm — same rationale as the check-memory-size pin at the sibling assert. Without it the
# refuted "silently truncated" wording could return with the suite green.
assert_contains "FIRE post-hook ARM 2 corrected premise pinned" "$out" "ARM B DENIES"
# SAFE: under the ratchet -> silent. And meta/ is EXEMPT even when over, same carve-out as the Pre hook.
python3 -c "import sys;sys.stdout.write('x'*1000)" > "$smoke_ratchet/.claude/skills/foo/MEMORY.md"
mkdir -p "$smoke_ratchet/.claude/skills/meta"
python3 -c "import sys;sys.stdout.write('x'*60000)" > "$smoke_ratchet/.claude/skills/meta/MEMORY.md"
out=$(cd "$smoke_ratchet" && printf '{"tool_name":"Bash","tool_input":{"command":"anything"}}' | CLAUDE_PROJECT_DIR="$smoke_ratchet" bash "$REPO_ROOT/.claude/hooks/check-memory-budget-post.sh" 2>&1)
assert_empty "SAFE post-hook ARM 2: under-ceiling skill + OVER-ceiling meta (exempt) -> silent" "$out"
rm -rf "$smoke_ratchet"
# --- check-memory-budget-post.sh: measures the FILE, so it is blind to how the write was spelled.
# FIRE: a breached index in a scratch repo -> warn on stderr.
smoke_post=$(mktemp -d); git -C "$smoke_post" init -q .; mkdir -p "$smoke_post/.claude/project-memory"
python3 -c "import sys;sys.stdout.write('x'*26000)" > "$smoke_post/.claude/project-memory/MEMORY.md"
out=$(cd "$smoke_post" && printf '{"tool_name":"Bash","tool_input":{"command":"anything"}}' | CLAUDE_PROJECT_DIR="$smoke_post" bash "$REPO_ROOT/.claude/hooks/check-memory-budget-post.sh" 2>&1)
assert_contains "FIRE post-hook on breached index -> warns" "$out" "budget BREACHED"
sout=$(cd "$smoke_post" && printf '{"tool_name":"Bash","tool_input":{"command":"anything"}}' | CLAUDE_PROJECT_DIR="$smoke_post" bash "$REPO_ROOT/.claude/hooks/check-memory-budget-post.sh" 2>/dev/null)
assert_one_json_doc "PARSE: check-memory-budget-post.sh breached-index arm → ONE parseable hookSpecificOutput doc, the cold MEMORY-INDEX.md relocation target survives" "$sout" 'MEMORY-INDEX.md'
# SAFE: an under-cap index -> silent.
python3 -c "import sys;sys.stdout.write('x'*100)" > "$smoke_post/.claude/project-memory/MEMORY.md"
out=$(cd "$smoke_post" && printf '{"tool_name":"Bash","tool_input":{"command":"anything"}}' | CLAUDE_PROJECT_DIR="$smoke_post" bash "$REPO_ROOT/.claude/hooks/check-memory-budget-post.sh" 2>&1)
assert_empty "SAFE post-hook on under-cap index -> silent" "$out"
rm -rf "$smoke_post"

# ── WIRING PIN — the routing itself.
# ⛔ EVERY ARM ABOVE INVOKES THE HOOK BY PATH, so all of them stay green if the settings.json
# entries are deleted. The whole point of that row is the BASH CHANNEL: a heredoc or git-plumbing
# append can push the always-loaded index past the byte gate through a channel an `Edit|Write`
# matcher cannot see, and it HAPPENED — occurrence 1, measured, the index sat over the gate for
# ~67 min. So the routing is the thing worth pinning, and until now nothing could see it vanish.
# The PreToolUse/Bash arm DENIES but only on a literal spelling; the PostToolUse/Bash companion
# measures the FILE and is therefore blind to spelling — it warns rather than denies, and it is
# the only layer that covers every channel. Both are pinned.
_cmb_pre=$(python3 -c "
import json
pre=json.load(open('.claude/settings.json'))['hooks']['PreToolUse']
print(' '.join(sorted(x.get('matcher','') for x in pre
                      if any('check-memory-budget.sh' in h.get('command','') for h in x.get('hooks',[])))))
")
_cmb_post=$(python3 -c "
import json
post=json.load(open('.claude/settings.json'))['hooks']['PostToolUse']
print(' '.join(sorted(x.get('matcher','') for x in post
                      if any('check-memory-budget-post.sh' in h.get('command','') for h in x.get('hooks',[])))))
")
assert_contains "wiring pinned: budget gate routed on Edit|Write" "$_cmb_pre" "Edit|Write"
assert_contains "wiring pinned: budget gate routed on MultiEdit" "$_cmb_pre" "MultiEdit"
assert_contains "wiring pinned: budget gate routed on Bash (the bypass channel)" "$_cmb_pre" "Bash"
assert_contains "wiring pinned: PostToolUse companion routed on Bash (covers every spelling)" "$_cmb_post" "Bash"

echo ""
echo "=== check-memory-budget.sh ARM 3 — always-loaded band per-file pin (2026-08-13) ==="
# ARM 3 warns (never denies) when a write would take CLAUDE.md / AGENTS.md /
# .claude/rules/*.md past its pin in .claude/band-pins.json AND the edit GROWS it.
#
# FIXTURES ARE DERIVED FROM THE OBLIGATION, NOT FROM THE PATTERN. The obligation is
# "text the harness loads on every turn AND re-sends on every sub-agent dispatch",
# and the arm carries NAME-KEYED logic (a pins MAP), so the fixture set must contain
# members the glob-plus-map would not obviously cover:
#   * an UNPINNED .claude/rules/*.md — in the band, absent from the map. Its
#     behaviour is a DESIGN CHOICE (pin defaults to current size, so it is governed
#     from birth), and without this arm a refactor to "unpinned -> silent pass" would
#     be invisible: a new rules file would be born outside the guard.
#   * AGENTS.md — a band member that is NOT under .claude/rules/, so a sweep derived
#     from the rules glob alone would miss it entirely.
#   * a .claude/rules/*.txt — matches the hot-path prefilter's band HINT but is not
#     a band file, which is what separates "the prefilter admitted it" from "the
#     classifier accepted it".
# The tree is a temp dir addressed via CLAUDE_PROJECT_DIR + BAND_PINS_FILE, so no
# assertion rides on the live band's current sizes and no real rules file is touched.
smoke_bandroot=$(mktemp -d)
mkdir -p "$smoke_bandroot/.claude/rules"
python3 -c "import sys;sys.stdout.write('x'*5000)" > "$smoke_bandroot/.claude/rules/fixture-band.md"
python3 -c "import sys;sys.stdout.write('y'*3000)" > "$smoke_bandroot/.claude/rules/fixture-unpinned.md"
python3 -c "import sys;sys.stdout.write('n'*2000)" > "$smoke_bandroot/.claude/rules/fixture-notes.txt"
python3 -c "import sys;sys.stdout.write('o'*9000)" > "$smoke_bandroot/.claude/rules/fixture-overpin.md"
python3 -c "import sys;sys.stdout.write('u'*3000)" > "$smoke_bandroot/.claude/rules/fixture-underpin.md"
# fixture-atpin: 4800 B against a 5000 B pin. Added 2026-08-24 with ARM 3b. The proj==pin
# boundary arm below USED to ride fixture-underpin (3000 -> 5000), but that is a 2000 B edit and
# ARM 3b now claims any edit over 400 B — so the boundary arm would have been testing 3b instead
# of the -gt operator it was written for. A fixture whose headroom is SMALLER than the per-entry
# threshold is what keeps the pin boundary independently reachable.
python3 -c "import sys;sys.stdout.write('p'*4800)" > "$smoke_bandroot/.claude/rules/fixture-atpin.md"
python3 -c "import sys;sys.stdout.write('a'*4000)" > "$smoke_bandroot/AGENTS.md"
python3 -c "import sys;sys.stdout.write('q'*1000)" > "$smoke_bandroot/notes.md"
# CLAUDE.md + a REAL archive twin: the only fixture on which band_archive() and the naive
# `${stem}-cases.md` formula it replaced DISAGREE. Every other band key here is a synthetic
# `fixture-*` whose archive does not exist, so both the resolver's CREATE branch and the naive
# formula emit the same string and NO assertion over them can discriminate — measured 2026-08-24:
# reverting band_archive() to the naive formula left the suite
# BYTE-IDENTICALLY green, 831/0 both ways, while the live bug it fixes was wrong on 3 of 21 files.
# Here the resolver must say CLAUDE-md-cases.md and the naive formula says CLAUDE-cases.md.
mkdir -p "$smoke_bandroot/.claude/docs/rules-ARCHIVE"
python3 -c "import sys;sys.stdout.write('c'*3000)" > "$smoke_bandroot/CLAUDE.md"
printf 'archive twin\n' > "$smoke_bandroot/.claude/docs/rules-ARCHIVE/CLAUDE-md-cases.md"
printf '{"pins":{".claude/rules/fixture-band.md":5000,"AGENTS.md":4000,".claude/rules/fixture-overpin.md":5000,".claude/rules/fixture-underpin.md":5000,".claude/rules/fixture-atpin.md":5000,"CLAUDE.md":5000}}' > "$smoke_bandroot/.claude/band-pins.json"
band() {  # band <json-payload-producing-python-argv...>  -> hook output, stdout+stderr
  CLAUDE_HOOK_SMOKE=1 CLAUDE_PROJECT_DIR="$smoke_bandroot" \
  BAND_PINS_FILE="$smoke_bandroot/.claude/band-pins.json" \
  bash "$REPO_ROOT/.claude/hooks/check-memory-budget.sh" 2>&1
}
bandedit() { # bandedit <file> <old-bytes> <new-bytes>
  python3 -c "import json,sys;print(json.dumps({'tool_name':'Edit','tool_input':{'file_path':sys.argv[1],'old_string':'x'*int(sys.argv[2]),'new_string':'x'*int(sys.argv[3])}}))" "$@"
}

# FIRE: an Edit that grows a pinned band file past its pin (5000 -> 5200).
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-band.md" 10 210 | band)
assert_contains "FIRE band: Edit grows a pinned rules file past its pin -> warns" "$out" "band growth"
# ...and the warn must carry the DISPLACEMENT remedy, not generic "trim this".
# Asserting the computed archive PATH is what makes this discriminating: a regression
# to a bare "file is large" string would still satisfy a "band growth" presence check.
assert_contains "FIRE band: warn names the computed rules-ARCHIVE destination" "$out" "rules-ARCHIVE/fixture-band-cases.md"
# ...and it must never deny. This arm is the whole posture in one assertion: a
# denied rules edit would also block the CORRECTION of a wrong always-loaded sentence.
assert_not_contains "FIRE band: warns and NEVER denies (warn-mode posture pinned)" "$out" "permissionDecision"
# SAFE (discriminating): a SHRINK from above the pin. An absolute-threshold guard
# fails exactly here, and failing here would warn at the displacement edits the warn
# itself asks for — the dead-guard shape ARM 1's growth clause exists to prevent.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-band.md" 210 10 | band)
assert_empty "SAFE band: SHRINK from above the pin (5000->4800) -> silent" "$out"
# SAFE: a same-size rewrite is not growth.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-band.md" 100 100 | band)
assert_empty "SAFE band: same-size rewrite -> silent (growth is the predicate)" "$out"
# ⛔ THE PAIR BELOW IS THE ONLY THING THAT TESTS THE GROWTH PRECONDITION, and it was
# ADDED because the mutation pass found the gap: deleting `[ proj > cur ] || exit 0`
# left the whole block GREEN. The two SAFE arms above are OVER-DETERMINED — their
# fixtures have pin == cur, so the PIN check alone already rejects them and the growth
# clause never has to do any work. The discriminating fixture is a band file sitting
# ABOVE its pin (9000 B against a 5000 B pin — a file that grew and has not been
# displaced yet, which is the steady state this arm exists for).
#   SAFE: shrinking 9000 -> 8000 is still 3000 B over the pin. An absolute-threshold
#   guard warns here — at a DISPLACEMENT EDIT, which is the exact dead-guard shape
#   ARM 1 was measured suffering (warned across 4.75 KB of growth because it fired on
#   the prunes it was asking for). Silence here is the whole design.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-overpin.md" 1200 200 | band)
assert_empty "SAFE band: SHRINK while still ABOVE the pin (9000->8000) -> silent" "$out"
#   FIRE: same file, same over-pin state, opposite DIRECTION. Only as a pair do these
#   discriminate growth-gating from absolute-thresholding — either alone is satisfied
#   by a guard that ignores direction entirely.
#   ⚠️ THE GROWTH IS 300 B, NOT 1000, SINCE 2026-08-24 — deliberately UNDER ARM 3b's 400 B
#   per-entry threshold. At 1000 B this arm now routes to 3b and never reaches the pin arm, so it
#   would have silently stopped testing the thing its own comment says it tests. Keep it sub-400.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-overpin.md" 200 500 | band)
assert_contains "FIRE band: GROWTH while above the pin (9000->9300) -> warns" "$out" "band growth"
# FIRE: an UNPINNED band file. Pin defaults to the current on-disk size, so a new
# rules file is governed from birth rather than being invisible until enrollment.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-unpinned.md" 10 210 | band)
assert_contains "FIRE band: UNPINNED rules file governed at its current size" "$out" "pin of 3000 B"
# FIRE: AGENTS.md — a band member outside the .claude/rules/ glob.
out=$(bandedit "$smoke_bandroot/AGENTS.md" 10 210 | band)
assert_contains "FIRE band: AGENTS.md (band member outside the rules glob)" "$out" "band growth: AGENTS.md"
# SAFE: CREATION. No file on disk -> not growth of the band's existing text.
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Write','tool_input':{'file_path':sys.argv[1],'content':'z'*50000}}))" "$smoke_bandroot/.claude/rules/does-not-exist.md" | band)
assert_empty "SAFE band: creating a NEW rules file -> silent (creation is not growth)" "$out"
# SAFE: a path that satisfies the prefilter's band HINT but is not a band file.
# Separates "the hot-path prefilter admitted the payload" from "band_rel accepted it".
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-notes.txt" 10 210 | band)
assert_empty "SAFE band: .claude/rules/*.txt (hint matches, classifier rejects) -> silent" "$out"
# SAFE: an ordinary source file is ignored entirely.
out=$(bandedit "$smoke_bandroot/notes.md" 10 210 | band)
assert_empty "SAFE band: non-band path -> silent" "$out"
# ⛔ THE ONE-SIDED-ORACLE CLOSER. An always-fire mutant
# (delete the pin comparison at check-memory-budget.sh's `proj > pin` line) left the
# ENTIRE suite GREEN, because every SAFE arm above is rejected by an EARLIER predicate
# — growth, creation-exemption, classifier, prefilter — and no fixture ever reached
# the pin comparison and was rejected BY it. These two are that fixture: a pinned band
# file sitting BELOW its pin (3000 B against 5000). They are the only arms that RED
# under the always-fire mutant, and assert_empty (whole-output) is token-rot-immune —
# the FIRE arms above are the built-in positive control that the warn text exists.
#   SAFE: growth that stays UNDER the pin (3000 -> 3300). Only the pin check says no.
#   ⚠️ 300 B, not 500, since 2026-08-24 — see the fixture-atpin note above. Above 400 B this arm
#   is rejected by ARM 3b instead of by the pin comparison, which destroys its whole purpose as
#   the one-sided-oracle closer: it would go RED under a mutant it is supposed to catch and GREEN
#   under one it is not.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-underpin.md" 10 310 | band)
assert_empty "SAFE band: GROWTH below the pin (3000->3300, pin 5000) -> silent (pin check is the sole rejector)" "$out"
#   SAFE boundary: growth to EXACTLY the pin (proj == pin). Pins the -gt operator —
#   a -ge drift would warn at the displacement target size itself. Rides fixture-atpin (4800 B
#   against a 5000 pin) so the whole move is 200 B and stays clear of ARM 3b.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-atpin.md" 10 210 | band)
assert_empty "SAFE band: growth to EXACTLY the pin (proj==pin) -> silent (-gt, not -ge)" "$out"

# ── ARM 3b — PER-EDIT size against the band's own 150-400 B contract (2026-08-24) ──────────────
# The arm the pin governor structurally cannot be: the pin asks "is this FILE at a new high-water
# mark", 3b asks "is this ENTRY oversized". They come apart in both directions, and the fixtures
# below are chosen to be exactly those cases rather than to re-cover the pin arm.
#
# FIRE: a 3 KB entry into a file with 2 KB of PIN HEADROOM (3000 -> 6000 against a 5000 pin would
# hit both; 3000 -> 3600 hits ONLY 3b). This is the case found to be unmeasured: the
# author has headroom, ships an oversized entry, and every existing governor is silent.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-underpin.md" 10 610 | band)
assert_contains "FIRE 3b: oversized ENTRY below the pin (+600 B) -> warns where the pin arm cannot" "$out" "band ENTRY size"
assert_contains "FIRE 3b: warn states the measured entry size" "$out" "adds 600 B"
# ...and names a DESTINATION. A warn that only says "too big" is the shape the pin arm's ~280
# recorded fires already proved gets ignored — the redirect is the mechanism, not decoration.
assert_contains "FIRE 3b: warn names the archive destination, not just the problem" "$out" "rules-ARCHIVE/fixture-underpin-cases.md"
# ⛔ AND THE ARM ABOVE CANNOT TELL band_archive() FROM THE BUG IT REPLACED — this one can.
# On a `fixture-*` key the resolver's CREATE branch and the naive `${stem}-cases.md` emit the
# SAME string, so the assertion passes under both programs. CLAUDE.md is the discriminating key:
# resolver -> CLAUDE-md-cases.md (the twin exists), naive formula -> CLAUDE-cases.md (never has).
# REDs on a revert to the naive formula; that revert was previously suite-invisible.
out=$(bandedit "$smoke_bandroot/CLAUDE.md" 10 610 | band)
assert_contains "FIRE 3b: band_archive RESOLVES the twin (CLAUDE.md -> CLAUDE-md-cases.md, not CLAUDE-cases.md)" "$out" "rules-ARCHIVE/CLAUDE-md-cases.md"
assert_not_contains "FIRE 3b: and never emits the naive formula's nonexistent path" "$out" "rules-ARCHIVE/CLAUDE-cases.md"
# ⛔ THE ANTI-SUPPRESSION CLAUSE IS LOAD-BEARING TEXT, NOT COMMENTARY. Without it in the MESSAGE,
# a hurried reader takes this arm as "do not correct wrong always-loaded rules" — which would cost
# more than every byte the arm saves. Asserting it here makes deleting it a RED.
assert_contains "FIRE 3b: warn says a REPLACEMENT passes (must not read as 'do not correct rules')" "$out" "REPLACES PASSES SILENTLY"
assert_not_contains "FIRE 3b: warns and NEVER denies" "$out" "permissionDecision"
# ONE WRITE, ONE WARN. Over the pin AND over 400 B: 3b fires and the pin arm must NOT also print.
# Two stderr blocks per write is how a guard gets filtered out; the pin fact rides inline instead.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-overpin.md" 200 1200 | band)
assert_contains "FIRE 3b: over-pin AND oversized -> the ENTRY warn is the one that prints" "$out" "band ENTRY size"
assert_not_contains "FIRE 3b: ...and the pin arm does NOT also print (one write, one warn)" "$out" "band growth:"
assert_contains "FIRE 3b: ...but the pin fact is carried INLINE, not dropped" "$out" "past its pin"
# SAFE boundary: exactly 400 B is silent. Pins -gt against a -ge drift, in the unit the contract
# is written in — 400 is the corpus's stated UPPER BOUND, so a compliant 400 B entry must pass.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-underpin.md" 10 410 | band)
assert_empty "SAFE 3b: an entry of EXACTLY 400 B -> silent (-gt, not -ge; 400 is compliant)" "$out"
# ⛔ SAFE: THE CORRECTION CASE, and the single most important arm here. A 5 KB replacement of a
# wrong always-loaded sentence is net-zero and must be COMPLETELY silent. If this ever REDs, the
# guard has started taxing the highest-value write in the corpus.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-underpin.md" 5000 5000 | band)
assert_empty "SAFE 3b: a 5000 B correction that REPLACES -> silent (net growth is the predicate)" "$out"
# SAFE: a displacement — 5000 B out, 4000 B in. Net negative, large payload, must stay silent.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-underpin.md" 5000 4000 | band)
assert_empty "SAFE 3b: a displacement (-1000 B net) with a 4000 B payload -> silent" "$out"
# ESCAPE GRANULARITY: SKIP_BAND_ENTRY_WARN silences 3b ALONE and must leave the pin arm standing.
# A per-arm escape that silently disabled the sibling arm would be a bare suppression.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-overpin.md" 200 1200 | CLAUDE_HOOK_SMOKE=1 CLAUDE_PROJECT_DIR="$smoke_bandroot" BAND_PINS_FILE="$smoke_bandroot/.claude/band-pins.json" SKIP_BAND_ENTRY_WARN=1 bash "$REPO_ROOT/.claude/hooks/check-memory-budget.sh" 2>&1)
assert_not_contains "SAFE 3b: SKIP_BAND_ENTRY_WARN=1 silences the ENTRY arm" "$out" "band ENTRY size"
assert_contains "SAFE 3b: ...and the PIN arm still fires (per-arm escape, not a blanket off-switch)" "$out" "band growth"
# Write and MultiEdit reach 3b too — proj_bytes is computed per-channel above, so a channel that
# lost its delta would go silently un-governed. Write: content 900 B larger than the 3000 B file.
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Write','tool_input':{'file_path':sys.argv[1],'content':'w'*3900}}))" "$smoke_bandroot/.claude/rules/fixture-underpin.md" | band)
assert_contains "FIRE 3b: Write channel (3000->3900) -> warns" "$out" "adds 900 B"
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'MultiEdit','tool_input':{'file_path':sys.argv[1],'edits':[{'old_string':'u','new_string':'u'+'z'*250},{'old_string':'u','new_string':'u'+'z'*250}]}}))" "$smoke_bandroot/.claude/rules/fixture-underpin.md" | band)
assert_contains "FIRE 3b: MultiEdit channel sums its hunks (250+250) -> warns" "$out" "adds 500 B"
# SAFE: MultiEdit whose hunks CANCEL (one +300, one -300). A per-hunk threshold would fire here;
# the contract is on the file's NET growth, so this must be silent.
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'MultiEdit','tool_input':{'file_path':sys.argv[1],'edits':[{'old_string':'u','new_string':'u'+'z'*300},{'old_string':'u'*301,'new_string':'u'}]}}))" "$smoke_bandroot/.claude/rules/fixture-underpin.md" | band)
assert_empty "SAFE 3b: MultiEdit hunks that CANCEL (+300/-300) -> silent (NET, not per-hunk)" "$out"

# --- Bash APPEND channel. The fixture's EVENT is derived from the channel the band's
# writes actually TRAVEL, not from the channel a sibling arm happens to be wired to:
# ARM 2's deny text, block-subagent-memory-write.sh's deny text, and ARM 3's own warn
# all prescribe a Bash `>>` append as the sanctioned way to land durable text. An arm
# that exercised only `--cacheinfo` would certify the guard against an event the band's
# writers rarely generate (measured precedent: a prior arm sent "tool_name":"Edit" for
# a channel whose live path is Bash).
bandappend() { python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'cat >> '+sys.argv[1]+chr(32)+\"<<'EOF'\nmore narrative\nEOF\"}}))" "$1"; }
out=$(bandappend "$smoke_bandroot/.claude/rules/fixture-band.md" | band)
assert_contains "FIRE band: Bash >> append to a rules file -> warns" "$out" "Bash>>"
# The append channel BOUNDS the size, it does not measure it — the warn must say so
# rather than fabricate an exact figure. `>5000` is the honest form.
assert_contains "FIRE band: append warn reports a BOUND (>N), not a fabricated exact size" "$out" "would be >5000 B"
# SAFE: same channel, non-band target.
out=$(bandappend "$smoke_bandroot/notes.md" | band)
assert_empty "SAFE band: Bash >> append to a non-band file -> silent" "$out"
# SAFE (use-vs-mention, and the hot-path control): a command that NAMES a band file
# with no redirect must not pay for the parse. `grep .claude/rules/...` is one of the
# most common commands any seat runs.
out=$(python3 -c 'import json;print(json.dumps({"tool_name":"Bash","tool_input":{"command":"grep -c FOO .claude/rules/tests-unit.md"}}))' | band)
assert_empty "SAFE band: rules path MENTIONED, no redirect -> silent (prefilter exits)" "$out"
# SAFE: the escape valve, on the payload that provably fires without it.
out=$(bandedit "$smoke_bandroot/.claude/rules/fixture-band.md" 10 210 | CLAUDE_HOOK_SMOKE=1 CLAUDE_PROJECT_DIR="$smoke_bandroot" BAND_PINS_FILE="$smoke_bandroot/.claude/band-pins.json" SKIP_BAND_GROWTH_WARN=1 bash "$REPO_ROOT/.claude/hooks/check-memory-budget.sh" 2>&1)
assert_empty "SAFE band: SKIP_BAND_GROWTH_WARN=1 silences the FIRE payload" "$out"

# --- Bash cacheinfo channel for band paths. Runs against the REAL repo (blob sizes
# come from the object store, and .claude/rules/actions.md is the smallest band file),
# so these two do not use the temp tree.
smoke_bandblob=$(python3 -c "import sys;sys.stdout.write('z'*9000)" | git hash-object -w --stdin)
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',.claude/rules/actions.md'}}))" "$smoke_bandblob" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_contains "FIRE band: cacheinfo staging a 9KB blob at a band path -> warns" "$out" "Bash-cacheinfo"
smoke_bandsmall=$(python3 -c "import sys;sys.stdout.write('z'*100)" | git hash-object -w --stdin)
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',.claude/rules/actions.md'}}))" "$smoke_bandsmall" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_empty "SAFE band: cacheinfo staging a 100B blob at a band path -> silent" "$out"
# ⛔ ARM 1 NON-REGRESSION, and this is the arm that matters most in this block.
# ARM 1/2's cacheinfo loop keeps the single LARGEST *MEMORY*.md triple. Folding band
# paths into that loop would have let a 133 KB rules blob shadow an oversize MEMORY
# blob and silently re-open the multi-triple bypass closed earlier — so ARM 3
# runs its own pass with no shared state. One command, both payloads, BOTH verdicts:
# a band warn AND the MEMORY deny. If either count goes to 0, one arm ate the other.
smoke_bandmem=$(python3 -c "import sys;sys.stdout.write('x'*26000)" | git hash-object -w --stdin)
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'git update-index --cacheinfo 100644,'+sys.argv[1]+',.claude/rules/actions.md --cacheinfo 100644,'+sys.argv[2]+',.claude/project-memory/MEMORY.md'}}))" "$smoke_bandblob" "$smoke_bandmem" | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/check-memory-budget.sh 2>&1)
assert_contains "FIRE mixed: band blob + oversize MEMORY blob -> band arm still warns" "$out" "band growth"
assert_contains "FIRE mixed: band blob + oversize MEMORY blob -> ARM 1 still DENIES" "$out" '"permissionDecision": "deny"'

# --- --refresh-pins: the ONLY writer of the pins map, and it ratchets DOWN only.
# All four properties on one output, because they are one contract: a mode that could
# RAISE a pin would make the pin track the growth it exists to surface.
smoke_pinroot=$(mktemp -d); mkdir -p "$smoke_pinroot/.claude/rules"
python3 -c "import sys;sys.stdout.write('a'*4000)" > "$smoke_pinroot/.claude/rules/shrunk.md"
python3 -c "import sys;sys.stdout.write('b'*9000)" > "$smoke_pinroot/.claude/rules/grew.md"
python3 -c "import sys;sys.stdout.write('c'*100)"  > "$smoke_pinroot/.claude/rules/brand-new.md"
printf '{"pins":{".claude/rules/shrunk.md":8000,".claude/rules/grew.md":5000,".claude/rules/gone.md":123}}' > "$smoke_pinroot/.claude/band-pins.json"
CLAUDE_PROJECT_DIR="$smoke_pinroot" BAND_PINS_FILE="$smoke_pinroot/.claude/band-pins.json" \
  bash "$REPO_ROOT/.claude/hooks/check-memory-budget.sh" --refresh-pins >/dev/null 2>&1
out=$(jq -c '.pins' "$smoke_pinroot/.claude/band-pins.json" 2>&1)
# Needles are keyed on the repo-RELATIVE path, which is the map's key shape. A bare
# `"shrunk.md":4000` does NOT match `".claude/rules/shrunk.md":4000` — the leading
# quote is not there — and that mistake cost three RED arms against correct code on
# the first run of this block.
assert_contains "FIRE refresh-pins: a SHRUNK file ratchets its pin DOWN (8000->4000)" "$out" 'rules/shrunk.md":4000'
assert_contains "FIRE refresh-pins: a GROWN file KEEPS its old smaller pin (no raise)" "$out" 'rules/grew.md":5000'
assert_contains "FIRE refresh-pins: an unpinned band file is ENROLLED at current size" "$out" 'rules/brand-new.md":100'
# The three arms above are this one's POSITIVE CONTROL: an absent/empty/error `$out`
# would satisfy a bare not-contains forever, so the DROP is only meaningful because
# the same string is simultaneously proven to hold three real pins.
assert_not_contains "FIRE refresh-pins: a pin whose file left the band is DROPPED" "$out" "gone.md"
# CORRUPT map must REFUSE, never reseed (2026-08-13): a present-but-unparseable pins
# file used to take the first-seed branch and replace every ratcheted floor with the file's
# CURRENT size, under the identical success message. Sandbox-proven live before the fix:
# pin 100 -> corrupt the JSON -> refresh -> pin became 10984, exit 0.
smoke_pinroot2=$(mktemp -d); mkdir -p "$smoke_pinroot2/.claude/rules"
python3 -c "import sys;sys.stdout.write('d'*4000)" > "$smoke_pinroot2/.claude/rules/victim.md"
printf 'garbage{{{' > "$smoke_pinroot2/.claude/band-pins.json"
rc=0
out=$(CLAUDE_PROJECT_DIR="$smoke_pinroot2" BAND_PINS_FILE="$smoke_pinroot2/.claude/band-pins.json" \
  bash "$REPO_ROOT/.claude/hooks/check-memory-budget.sh" --refresh-pins 2>&1) || rc=$?
assert_eq "FIRE refresh-pins CORRUPT map: refuses (rc=1), never reseeds" "1" "$rc"
assert_contains "FIRE refresh-pins CORRUPT map: names the refusal + the file" "$out" "unparseable"
after=$(cat "$smoke_pinroot2/.claude/band-pins.json")
assert_eq "FIRE refresh-pins CORRUPT map: the corrupt file is left untouched (no silent overwrite)" "garbage{{{" "$after"
rm -rf "$smoke_pinroot2"
rm -rf "$smoke_pinroot" "$smoke_bandroot"
unset -f band bandedit bandappend

echo "=== warn-large-tracker-read.sh (full Read of big project-memory tracker — PreToolUse Read warn) ==="
# ⛔ RESOLVE THIS FIXTURE BY SIZE, NEVER BY NAME (2026-09-09). These arms named
# a project-memory tracker until a peer two-tiered that file into a 9,225 B router. The guard
# then went CORRECTLY silent and both arms went red — and because .githooks/pre-push runs this
# suite on any push touching .claude/hooks/, .claude/orchestrator/, .githooks/, settings.json or a
# top-level scripts/*.{mjs,py,sh}, THE FLEET'S NEXT PUSH WAS REFUSED by a test fixture rather than
# by a broken hook. The assertion is about a project-memory file OVER TRACKER_THRESHOLD; name that
# PROPERTY, not a path another seat can split out from under it. Largest match wins, for margin.
# ⚠️ TAB-SEPARATED, and `awk` rather than `wc -c < f`: BSD `wc` SPACE-PADS its output, so the
# obvious `printf '%s %s' "$(wc -c < "$f")" "$f" | cut -d' ' -f2-` returns the padding plus the
# size plus the path — the value then fails `[ -f ]` and this resolver would red the suite it is
# here to repair. Caught by running it before committing. (bash-environment.md, BSD userland.)
# The resolver itself ($_BIG_TRACKER / $_BIG_TRACKER_REL) runs in the preamble, above the first section header,
# because warn-channel's STDOUT-ONLY arms read it too and a --for/--only run may not select this section.
# Fail LOUD on an unavailable fixture: an arm that cannot run is an instrument failure, never a pass.
[ -n "$_BIG_TRACKER" ] && [ -f "$_BIG_TRACKER" ] \
  || fail "smoke fixture: no .claude/project-memory/*.md over 50 KB — the large-tracker arms CANNOT RUN (instrument failure, not a silent guard)"
# FIRE: full Read of the ~195KB flows tracker → stderr warn (warn-mode, exit 0)
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_BIG_TRACKER_REL"'"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_contains "FIRE full Read of >50KB tracker → warn" "$out" "large-tracker Read"
# SAFE: partial read (offset+limit) is already surgical → silent
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_BIG_TRACKER_REL"'","limit":20}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE partial Read (limit) → silent" "$out"
# SAFE: small project-memory file (MEMORY.md is byte-capped <25KB, under 50KB) → silent
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":".claude/project-memory/MEMORY.md"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE small project-memory file (<50KB) → silent" "$out"
# SCOPE-SKIP: a non-project-memory path is not gated
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"src/app/layout.tsx"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SCOPE-SKIP non-tracker path → silent" "$out"

# --- ARM A, plans/ sub-kind ---
# The plan file is the POST-COMPACTION RE-READ PATH, and this hook held zero plans/ arms, so a
# recovering session reading its own plan got a silent PREFIX at the moment its context was gone.
# Measured before wiring: 441 Read calls on plans/ paths fleet-wide, 105 UNBOUNDED (a FLOOR — the
# sub-agent plane is not in that count), against 7 for the SKILL.md specs that already hold an arm.
# ⛔ FIXTURE BY SIZE, NEVER BY NAME — the same rule the tracker arms above learned the hard way when
# a peer two-tiered the named file out from under them and refused the fleet's next push.
_BIG_PLAN=$(find "$REPO_ROOT/plans" -name '*.md' -type f -size +50k -exec wc -c {} + \
  | awk '$2 != "" && $2 != "total" {printf "%s\t%s\n", $1, $2}' | sort -rn | head -1 | cut -f2)
[ -n "$_BIG_PLAN" ] && [ -f "$_BIG_PLAN" ] \
  || fail "smoke fixture: no plans/*.md over 50 KB — the large-plan arms CANNOT RUN (instrument failure, not a silent guard)"
_BIG_PLAN_REL="plans/${_BIG_PLAN#"$REPO_ROOT/plans/"}"
# FIRE: an unbounded Read of an over-band plan warns and offers a MEASURED window.
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_BIG_PLAN_REL"'"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_contains "FIRE read-guard: unbounded Read of an over-band plan → warn" "$out" "large-plan Read"
# DISCRIMINATING: it must say plan, NOT spec. This is the arm that proves WR_NOUN is wired rather
# than the spec payload merely being reachable — without it, reverting WR_NOUN stays green.
assert_not_contains "FIRE read-guard: the plan payload says plan, never spec" "$out" "large-spec Read"
# The advised window must fit the band it enforces — same property as the spec/archive arms.
assert_tail_window_fits_band "FIRE read-guard: plan advised window FITS the band" "$out" "$_BIG_PLAN" "$(read_guard_band)"
# SCOPE-SKIP, near-miss: a `src/plans.md` is NOT a plan file. The case pattern crosses slashes, so
# this is the control that proves the arm is anchored on the DIRECTORY and not on the substring.
# ⛔ THE FIXTURE MUST EXIST AND BE OVER-BAND, AND THAT IS THE WHOLE ARM. The first version passed a
# BARE `src/plans.md`, which does not exist in this repo — and the hook's `[ -f "$FILE_PATH" ] || exit 0`
# short-circuits BEFORE the case statement, so the arm was silent for a reason that has nothing
# to do with the glob. Measured 2026-09-13 by mutation: broadening the glob to `plans*.md|*/plans*.md`
# left the whole suite at 1400 PASS / 0 FAIL — the control could not fail, which is the ELEVENTH
# vacuous-control way (the mutation sat outside the predicate's field of view). Four direct arms with
# controls both ways: real glob + EXISTING near-miss → 0 fires; MUTANT glob + EXISTING near-miss → fires;
# MUTANT glob + NONEXISTENT path → still 0, which is the reading that proved the shipped arm blind.
# `pwd -P` because `mktemp -d` returns the symlinked spelling and path-identity arms go dark under it.
_NM_DIR="$(cd "$(mktemp -d)" && pwd -P)"
[ -n "$_NM_DIR" ] || fail "smoke fixture: mktemp -d gave nothing — the scope-skip control CANNOT fail"
mkdir -p "$_NM_DIR/src"
cp "$_BIG_PLAN" "$_NM_DIR/src/plans.md"
[ -s "$_NM_DIR/src/plans.md" ] \
  || fail "smoke fixture: near-miss copy is empty — the scope-skip control CANNOT fail (instrument failure, not a silent guard)"
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_NM_DIR/src/plans.md"'"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SCOPE-SKIP read-guard: an EXISTING over-band src/plans.md is not a plan file → silent" "$out"
rm -rf "$_NM_DIR"

# --- ARM A, plans/ IN-THE-BAND population (2026-09-13) ---
# ⛔ THE FIXTURE IS SELECTED FROM THE BAND, AND THAT IS THE WHOLE ARM. The plan arms above pick
# `sort -rn | head -1` — the LARGEST file — which is drawn from the population the payload already
# handles and STRUCTURALLY EXCLUDES the 14 files it got wrong (the TWELFTH vacuous-control way: a
# positive control drawn from the handled population cannot detect the excluded one). The branch
# FIRES at TRACKER_THRESHOLD and SIZES its window at SKILLMEM_THRESHOLD, so in that 6,300 B gap the
# old single payload asserted a truncation that was not happening and prescribed `offset=1
# limit=<every line>` under a step labelled TAIL. Measured at HEAD: 120 plan files fire, 14 in the
# gap. `assert_tail_window_fits_band` could not catch it either — offset=1 skips the maximality
# check and 53,572 <= 57,500 passes.
_BAND_PLAN=$(find "$REPO_ROOT/plans" -name '*.md' -type f -size +50k -size -57501c 2>/dev/null | head -1)
[ -n "$_BAND_PLAN" ] && [ -f "$_BAND_PLAN" ] \
  || fail "smoke fixture: no plans/*.md in the (51200, 57500] band — the in-band arms CANNOT RUN (instrument failure, not a silent guard)"
_BAND_PLAN_REL="plans/${_BAND_PLAN#"$REPO_ROOT/plans/"}"
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_BAND_PLAN_REL"'"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
# It still FIRES — the file is over the advisory line, so silence would be the opposite defect.
assert_contains "FIRE read-guard: an in-band plan still warns" "$out" "large-plan Read"
# … but it must NOT assert a truncation that is not happening.
assert_not_contains "FIRE read-guard: an in-band plan is NOT told the read returns a prefix" "$out" "does NOT return it whole"
# … and it must NOT hand back a whole-file window under a TAIL label.
assert_not_contains "FIRE read-guard: an in-band plan gets no offset=1 whole-file window" "$out" "offset=1 limit="
# The plan-only CLAIM-SCOPE line (by rule, a session-wide claim derives over the
# WHOLE plan). Paired with the spec arm below, this IS the mutation proving it is noun-gated.
assert_contains "FIRE read-guard: the plan payload scopes session-wide claims" "$out" "DERIVES OVER THE WHOLE PLAN"
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_BIG_PLAN_REL"'"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_contains "FIRE read-guard: an over-band plan IS told the read returns a prefix" "$out" "does NOT return it whole"
# ⛔ THE NOUN-GATE'S NEGATIVE HALF, AND IT IS WHAT MAKES THE ARM ABOVE DISCRIMINATE. The claim-scope
# line is a fact about PLANS, not about specs, so a SPEC payload must not carry it. Without this arm
# the positive above passes whether or not the gate exists — an unconditional line satisfies it.
# Fixture by SIZE, never by name, for the reason the tracker arms learned: a peer can two-tier the
# named file out from under the arm.
_BIG_SPEC=$(find "$REPO_ROOT/.claude/skills" -name 'SKILL.md' -type f -size +57k -exec wc -c {} + \
  | awk '$2 != "" && $2 != "total" {printf "%s\t%s\n", $1, $2}' | sort -rn | head -1 | cut -f2)
[ -n "$_BIG_SPEC" ] && [ -f "$_BIG_SPEC" ] \
  || fail "smoke fixture: no over-band SKILL.md — the noun-gate negative CANNOT RUN (instrument failure)"
_BIG_SPEC_REL=".claude/skills/${_BIG_SPEC#"$REPO_ROOT/.claude/skills/"}"
out=$(echo '{"tool_name":"Read","tool_input":{"file_path":"'"$_BIG_SPEC_REL"'"}}' | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_contains "FIRE read-guard: an over-band spec still warns" "$out" "large-spec Read"
assert_not_contains "FIRE read-guard: the SPEC payload carries no plan-only claim-scope line" "$out" "DERIVES OVER THE WHOLE PLAN"

# --- ARM B: skill-MEMORY unbounded-read DENY (2026-08-01) ---
# Note the failure mode differs from ARM A above: trackers WARN (exit-0 stderr), skill
# memories DENY. Deliberate — exit-0 stderr reaches the user transcript but never the
# MODEL (check-memory-budget.sh:158-161), so on a sub-agent's own Read a warn would be
# inert by construction. Fixture bytes come from a committed FILE.
tmpreadroot=$(mktemp -d); tmpread="$tmpreadroot/.claude/skills/fixture-skill"; mkdir -p "$tmpread"
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmpread/MEMORY.md"   # 60,967 B / 1,168 lines
# FIRE: unbounded Read of an over-ceiling skill MEMORY → deny.
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmpread/MEMORY.md" | bash .claude/hooks/warn-large-tracker-read.sh)
assert_contains "FIRE read-guard: unbounded Read of >57.5KB skill MEMORY → deny" "$out" '"permissionDecision": "deny"'
sout=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmpread/MEMORY.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>/dev/null)
assert_one_json_doc "PARSE: warn-large-tracker-read.sh ARM-B deny arm → ONE parseable hookSpecificOutput doc, the COMPUTED paging coordinate survives" "$sout" 'MEASURED to fit the band'
# The paging instruction must be COMPUTED from the real file, not a canned string: 1168
# lines → offset 869 (N-300+1). Pinning the derived offset is what distinguishes a live
# computation from a generic "use offset and limit" reason that would pass a deny check.
# ⛔ THE +1 IS LOAD-BEARING, DO NOT "SIMPLIFY" IT BACK TO N-300 (2026-08-06). A Read of
# offset=O limit=300 covers lines O..O+299, so offset=N-300 covers N-300..N-1 and drops
# line N — the LAST line of a chronological file, i.e. the newest entry's Revisit trigger.
# Measured on a 365-line file: old advice reached 364, new reaches 365.
# These two arms previously PINNED the off-by-one; re-measured, not hand-edited.
assert_tail_window_reaches_eof "FIRE read-guard: advised window is COMPUTED — it ends on the file\x27s last line" "$out" "$tmpread/MEMORY.md"
assert_tail_window_reaches_eof "FIRE read-guard: advised window REACHES the last line (property, drift-proof)" "$out" "$tmpread/MEMORY.md"
assert_tail_window_fits_band "FIRE read-guard: advised window FITS the band it enforces (no self-refusing remedy)" "$out" "$tmpread/MEMORY.md" "$(read_guard_band)"
# --- bounded-read arm: `limit` present does NOT imply surgical (2026-08-01) ---
# The three arms below are a DISCRIMINATING SET, and (c) is the one that matters.
# The old single SAFE arm ({limit:300} → allow) was green, mutation-valid, and
# CERTIFIED THE BUG: this fixture is 52 B/line while the real subject (meta) is
# 239 B/line with a 8,718 B max line, so a 300-line window here is ~15.6 KB and can
# never overflow the band the guard defends. A fixture that cannot exhibit the
# defect cannot witness the fix. Density, not line count, is the axis.
# (a) SAFE: a genuinely surgical window on the SPARSE fixture → allow (unchanged).
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1],'limit':300}}))" "$tmpread/MEMORY.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE read-guard: surgical window (limit=300, ~15.6KB of a 52 B/line file) → allow" "$out"
# (b) FIRE: same fixture, limit spanning the WHOLE file (60,967 B) → deny. Proves the
#     arm measures BYTES; a limit-is-present predicate allows this.
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1],'limit':1168}}))" "$tmpread/MEMORY.md" | bash .claude/hooks/warn-large-tracker-read.sh)
assert_contains "FIRE read-guard: bounded Read whose WINDOW is the whole 60967 B file → deny" "$out" '"permissionDecision": "deny"'
# SAFE: a GARBAGE offset fails OPEN, exactly like a garbage limit. It used to
# normalize to 1, which silently RETARGETED the guard — the caller asked about an
# unparseable region and got a verdict (plus line-numbered advice) about lines 1-300,
# a region they never named. A guard may refuse or stand aside; it must not answer a
# question it was not asked. Pins the fail-open contract the header claims.
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1],'limit':300,'offset':'xyz'}}))" "$tmpread/MEMORY.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE read-guard: garbage offset (\"xyz\") → fail-OPEN silent allow" "$out"
rm -rf "$tmpreadroot"
# (c) FIRE-dense: the DENSITY discriminator. 252 lines x 355 B/line = 89,632 B, so a
#     modest limit=200 still overflows the band. This is the arm the old fixture was
#     structurally incapable of providing, and the one that fails if the window
#     measurement is ever reverted to a line-count heuristic.
tmpdenseroot=$(mktemp -d); tmpdense="$tmpdenseroot/.claude/skills/fixture-skill"; mkdir -p "$tmpdense"
cp .claude/hooks/fixtures/skill-memory-dense.md "$tmpdense/MEMORY.md"
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1],'limit':200}}))" "$tmpdense/MEMORY.md" | bash .claude/hooks/warn-large-tracker-read.sh)
assert_contains "FIRE read-guard DENSE: limit=200 over a 355 B/line file (71016 B window, a strict SUBSET) → deny" "$out" '"permissionDecision": "deny"'
rm -rf "$tmpdenseroot"

# --- ARCHIVE FAMILY (2026-08-06, PHASE 1 of the meta memory archive split) ---
# The ARM-B case ended `/MEMORY.md`, so MEMORY-ARCHIVE*.md matched NEITHER arm and fell straight
# through the `*)` exit — completely ungated. That is this guard's own failure mode aimed at its
# largest possible target: 24 archives exist at 38 KB-405 KB, six already past the 262,144 B
# hard-error ceiling, and the meta split adds ~17 more shards. The threshold is deliberately
# UNCHANGED: the 25k-token cap is a property of the Read tool, not of the file's temperature.
tmparcreadroot=$(mktemp -d); tmparcread="$tmparcreadroot/.claude/skills/fixture-skill"; mkdir -p "$tmparcread"
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmparcread/MEMORY-ARCHIVE-2026-04-14-2026-05-23.md"   # 60,967 B / 1,168 lines
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmparcread/MEMORY-ARCHIVE-2026-04-14-2026-05-23.md" | bash .claude/hooks/warn-large-tracker-read.sh)
assert_contains "FIRE read-guard: unbounded Read of an over-ceiling MEMORY-ARCHIVE shard → deny" "$out" '"permissionDecision": "deny"'
# The paging advice must be COMPUTED for the archive too, not a generic deny — same 1168-300+1=869.
assert_tail_window_reaches_eof "FIRE read-guard: archive advised window is COMPUTED — ends on the last line" "$out" "$tmparcread/MEMORY-ARCHIVE-2026-04-14-2026-05-23.md"
assert_tail_window_reaches_eof "FIRE read-guard: archive advised window REACHES the last line (property)" "$out" "$tmparcread/MEMORY-ARCHIVE-2026-04-14-2026-05-23.md"
assert_tail_window_fits_band "FIRE read-guard: archive advised window FITS the band" "$out" "$tmparcread/MEMORY-ARCHIVE-2026-04-14-2026-05-23.md" "$(read_guard_band)"
# NOT-FIRE: a small archive is silent — the guard keys on measured bytes, never on the name.
cp .claude/hooks/fixtures/skill-memory-small.md "$tmparcread/MEMORY-ARCHIVE-2026-01-01-2026-02-01.md"       # 98 B
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmparcread/MEMORY-ARCHIVE-2026-01-01-2026-02-01.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE read-guard: a small (98 B) archive shard → silent" "$out"
# NOT-FIRE: a same-directory non-memory file stays out of scope even when it is far bigger.
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmparcread/RULES.md"
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmparcread/RULES.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE read-guard: an over-ceiling skills/*/RULES.md is NOT the memory family → silent" "$out"
# FIRE: meta/RULES.md IS in family (2026-08-06). It is 353,008 B — over the 262,144 B hard-error
# ceiling — so an unguarded Read returns a raw refusal and the reader cannot tell missing from
# empty from too-big. It is deliberately NOT split (a router cannot route a fuzzy trigger phrase),
# so the read path is the only place its size can be handled.
# ⚠️ THIS ARM AND THE ONE ABOVE ARE A DISCRIMINATING PAIR, not a duplicate: identical fixture,
# identical size, and the ONLY difference is the skill dir. Same-size/opposite-verdict is what
# proves the guard keys on `meta/` rather than on bytes-plus-a-RULES-name. Widening the pattern to
# `*/RULES.md` would flip the arm above — which is why the scope stayed narrow.
mkdir -p "$tmparcreadroot/.claude/skills/meta"
cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmparcreadroot/.claude/skills/meta/RULES.md"
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmparcreadroot/.claude/skills/meta/RULES.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_contains "FIRE: an over-ceiling skills/meta/RULES.md IS in the read-guard family → paged" "$out" "hookSpecificOutput"
rm -rf "$tmparcreadroot"
# --- THE SIBLINGS THE `MEMORY*` KEY COULD NOT REACH (2026-08-06) ---
# PHASE 1 widened ARM B to the MEMORY family. That key is SHAPE-based, so three files in the
# SAME directory at the SAME size stayed ungated and nobody noticed for hours: the CHANGELOG
# shards (199,661 B — LARGER than any MEMORY shard) and the two registers carved out of
# MEMORY.md, which HAD this coverage while they were inside it and silently lost it by becoming
# their own files. Measured before the fix: MEMORY-ARCHIVE deny / CHANGELOG-ARCHIVE ungated /
# WATCH-TIER ungated / ADOPTION-QUEUE ungated. All three arms below RED against that case block.
# The lesson is the enumeration axis: derive the set from the OBLIGATION (which files are
# oversize and get read whole?), never from the naming family — the family is what hid it.
tmpsibroot=$(mktemp -d); tmpsib="$tmpsibroot/.claude/skills/fixture-skill"; mkdir -p "$tmpsib"
for sibname in "CHANGELOG-ARCHIVE-2026-04-14-2026-06-10.md" "WATCH-TIER.md" "ADOPTION-QUEUE.md" "WATCH-TIER-ARCHIVE.md" "ADOPTION-QUEUE-ARCHIVE.md"; do
  cp .claude/hooks/fixtures/skill-memory-oversized.md "$tmpsib/$sibname"
  out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmpsib/$sibname" | bash .claude/hooks/warn-large-tracker-read.sh)
  assert_contains "FIRE read-guard: unbounded Read of an over-ceiling $sibname -> deny" "$out" '"permissionDecision": "deny"'
done
# NOT-FIRE control: the guard still keys on measured BYTES, not on these names.
cp .claude/hooks/fixtures/skill-memory-small.md "$tmpsib/WATCH-TIER-small.md"
out=$(python3 -c "
import json,sys
print(json.dumps({'tool_name':'Read','tool_input':{'file_path':sys.argv[1]}}))" "$tmpsib/WATCH-TIER-small.md" | bash .claude/hooks/warn-large-tracker-read.sh 2>&1)
assert_empty "SAFE read-guard: a small (98 B) WATCH-TIER-shaped file -> silent" "$out"
rm -rf "$tmpsibroot"

# ── FIRES LOG arm, ARM B (see the fires-log block in the block-dangerous.sh section for the pinning rules and
# the two _hfl_ helpers). A fresh root, so no earlier arm in this section can have written the record counted.
_trf_root=$(_hfl_fresh_root)
_trf_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_trf_root" ]; then
  mkdir -p "$_trf_root/.claude/skills/fixture-skill"
  cp .claude/hooks/fixtures/skill-memory-oversized.md "$_trf_root/.claude/skills/fixture-skill/MEMORY.md"
  _trf_out=$(python3 -c 'import json, sys; print(json.dumps({"session_id": "smoke-sid-tr", "agent_id": "smoke-agent-tr", "tool_name": "Read", "tool_input": {"file_path": sys.argv[1]}}))' \
      "$_trf_root/.claude/skills/fixture-skill/MEMORY.md" \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_trf_root" bash .claude/hooks/warn-large-tracker-read.sh 2>/dev/null)
  _trf_rc=$?
  _trf_got="rc=$_trf_rc deny=$(printf '%s' "$_trf_out" | grep -c -F '"permissionDecision": "deny"') $(_hfl_records "$_trf_root/.claude/logs/memory-read-guard-fires.jsonl")"
  rm -rf "$_trf_root"
fi
assert_eq "warn-large-tracker-read: an ARM B DENY appends exactly one fires record, carrying its arm and the payload's session and agent ids" \
  "rc=0 deny=1 records=1 arm=unbounded sid=smoke-sid-tr agent_id=smoke-agent-tr" "$_trf_got"
unset _trf_root _trf_out _trf_rc _trf_got

# NEGATIVE CONTROL, ARM A: the WARN arm fires many times a session and must write no record;
# a `_wltr_fire` there would fill the deny corpus with advisories. `warned=1` proves this read really took ARM A, so
# the zero cannot come from a payload that never reached it.
_tra_root=$(_hfl_fresh_root)
_tra_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_tra_root" ]; then
  mkdir -p "$_tra_root/.claude/project-memory"
  cp .claude/hooks/fixtures/skill-memory-oversized.md "$_tra_root/.claude/project-memory/tracker.md"
  _tra_out=$(python3 -c 'import json, sys; print(json.dumps({"session_id": "smoke-sid-arma", "tool_name": "Read", "tool_input": {"file_path": sys.argv[1]}}))' \
      "$_tra_root/.claude/project-memory/tracker.md" \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_tra_root" bash .claude/hooks/warn-large-tracker-read.sh 2>/dev/null)
  _tra_rc=$?
  _tra_got="rc=$_tra_rc warned=$(printf '%s\n' "$_tra_out" | grep -c -F 'large-tracker Read') fires-logs=$(find "$_tra_root" -name '*-fires.jsonl' 2>/dev/null | wc -l | tr -d ' ')"
  rm -rf "$_tra_root"
fi
assert_eq "warn-large-tracker-read: the ARM A warn writes no fires record (negative control)" \
  "rc=0 warned=1 fires-logs=0" "$_tra_got"
unset _tra_root _tra_out _tra_rc _tra_got

# NEGATIVE CONTROL, safe read: a skill memory UNDER the band is allowed silently and writes no record.
_trs_root=$(_hfl_fresh_root)
_trs_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_trs_root" ]; then
  mkdir -p "$_trs_root/.claude/skills/fixture-skill"
  cp .claude/hooks/fixtures/skill-memory-small.md "$_trs_root/.claude/skills/fixture-skill/MEMORY.md"
  _trs_out=$(python3 -c 'import json, sys; print(json.dumps({"session_id": "smoke-sid-trsafe", "tool_name": "Read", "tool_input": {"file_path": sys.argv[1]}}))' \
      "$_trs_root/.claude/skills/fixture-skill/MEMORY.md" \
    | env -u HOOK_FIRES_LOG_DIR CLAUDE_PROJECT_DIR="$_trs_root" bash .claude/hooks/warn-large-tracker-read.sh 2>/dev/null)
  _trs_rc=$?
  _trs_got="rc=$_trs_rc stdout-bytes=${#_trs_out} fires-logs=$(find "$_trs_root" -name '*-fires.jsonl' 2>/dev/null | wc -l | tr -d ' ')"
  rm -rf "$_trs_root"
fi
assert_eq "warn-large-tracker-read: an ALLOWED read writes no fires record (negative control)" \
  "rc=0 stdout-bytes=0 fires-logs=0" "$_trs_got"
unset _trs_root _trs_out _trs_rc _trs_got

# ── lib/fires-log.sh FAILURE MODES: no library failure that still loads may change a decision ────────────────────
# Both hooks load the lib in a SUBSHELL on the deny path. These arms copy BOTH hooks beside a
# shaped lib and read each hook's decision on a deny and a safe payload, plus the records written.
# _flc_build <corrupt|exit0|unbound> prints a fresh fixture root holding both hooks, warn-emit, the oversized
# fixture and the shaped lib, or nothing if no fresh root was available.
_flc_build() {
  local r
  r=$(_hfl_fresh_root)
  [ -n "$r" ] || return 0
  mkdir -p "$r/.claude/hooks/lib" "$r/.claude/skills/fixture-skill"
  cp .claude/hooks/block-dangerous.sh .claude/hooks/warn-large-tracker-read.sh "$r/.claude/hooks/"
  cp .claude/hooks/lib/warn-emit.sh "$r/.claude/hooks/lib/"
  case "$1" in
    corrupt) printf 'echo CORRUPT-LIB-STDOUT\nfires_log() {\n  if then\n' > "$r/.claude/hooks/lib/fires-log.sh" ;;
    exit0)   { cat .claude/hooks/lib/fires-log.sh; printf '\nexit 0\n'; } > "$r/.claude/hooks/lib/fires-log.sh" ;;
    unbound) { cat .claude/hooks/lib/fires-log.sh; printf '\n: "$SMOKE_FIRES_LOG_UNBOUND_PROBE"\n'; } > "$r/.claude/hooks/lib/fires-log.sh" ;;
  esac
  cp .claude/hooks/fixtures/skill-memory-oversized.md "$r/.claude/skills/fixture-skill/MEMORY.md"
  printf '%s' "$r"
}
# _flc_run <root> <+e|-e>: "<case>=rc<N>/<deny|empty|BROKEN>" for four cases, then the records under <root>.
# `+e` is plain bash (errexit off), which is how the harness runs a hook; `-e` is the stricter run.
_flc_run() {
  local got="" case_ hook payload out rc shape
  for case_ in bd-deny bd-safe tr-deny tr-safe; do
    case "$case_" in
      bd-deny) hook=block-dangerous.sh; payload='{"tool_name":"Bash","tool_input":{"command":"git add $PATHS"}}' ;;
      bd-safe) hook=block-dangerous.sh; payload='{"tool_name":"Bash","tool_input":{"command":"ls -la"}}' ;;
      tr-deny) hook=warn-large-tracker-read.sh
               payload=$(python3 -c 'import json, sys; print(json.dumps({"tool_name": "Read", "tool_input": {"file_path": sys.argv[1]}}))' "$1/.claude/skills/fixture-skill/MEMORY.md") ;;
      tr-safe) hook=warn-large-tracker-read.sh; payload='{"tool_name":"Read","tool_input":{"file_path":"src/app/layout.tsx"}}' ;;
    esac
    out=$(printf '%s' "$payload" | env -u HOOK_FIRES_LOG_DIR -u SMOKE_FIRES_LOG_UNBOUND_PROBE CLAUDE_PROJECT_DIR="$1" bash "$2" "$1/.claude/hooks/$hook" 2>/dev/null)
    rc=$?
    shape=$(printf '%s' "$out" | python3 -c 'import json, sys
raw = sys.stdin.read()
if not raw.strip():
    print("empty"); sys.exit(0)
try:
    d = json.loads(raw)
    print("deny" if (d.get("hookSpecificOutput") or {}).get("permissionDecision") == "deny" else "BROKEN")
except ValueError:
    print("BROKEN")' 2>/dev/null)
    got="$got $case_=rc$rc/${shape:-BROKEN}"
  done
  printf '%s records=%s' "${got# }" "$(cat "$1"/.claude/logs/*-fires.jsonl 2>/dev/null | grep -c .)"
}
# A lib that PRINTS and then FAILS TO PARSE. `.` is a POSIX special builtin, so under `set -e` a lib that fails to
# parse kills a hook sourcing it in its own shell with rc=2, and rc=2 from a PreToolUse hook is a DENY on every call
# it matches. Run under `bash -e` because both hooks are `set -u` without `-e`: plain bash never reaches that path.
_flc_root=$(_flc_build corrupt)
_flc_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_flc_root" ]; then
  _flc_got=$(_flc_run "$_flc_root" -e)
  rm -rf "$_flc_root"
fi
assert_eq "fires-log lib: a corrupt lib (prints, then fails to parse) changes no decision under bash -e and writes no record" \
  "bd-deny=rc2/deny bd-safe=rc0/empty tr-deny=rc0/deny tr-safe=rc0/empty records=0" "$_flc_got"
unset _flc_root _flc_got
# ⛔ THE TWO SHAPES `bash -n` PASSES. A lib that PARSES and still ends the shell sourcing it (a trailing
# `exit 0`, or a read of an unset variable under the hooks' `set -u`) would turn a deny into an allow if sourced in
# the hook's own shell (rc 0 or rc 1, nothing on either channel, no record), so the hooks load it in a subshell. Each
# shape runs under plain bash AND `bash -e`; block-dangerous must still exit 2 with its deny, the read guard its deny.
for _fls_shape in exit0 unbound; do
  _fls_got="fixture root refused (mktemp did not yield a fresh empty dir)"
  _fls_root=$(_flc_build "$_fls_shape")
  if [ -n "$_fls_root" ]; then
    _fls_got="plain: $(_flc_run "$_fls_root" +e) | bash -e: $(_flc_run "$_fls_root" -e)"
    rm -rf "$_fls_root"
  fi
  assert_eq "fires-log lib: a lib that parses but ends its shell ($_fls_shape) changes no decision under plain bash or bash -e" \
    "plain: bd-deny=rc2/deny bd-safe=rc0/empty tr-deny=rc0/deny tr-safe=rc0/empty records=0 | bash -e: bd-deny=rc2/deny bd-safe=rc0/empty tr-deny=rc0/deny tr-safe=rc0/empty records=0" \
    "$_fls_got"
done
unset _fls_shape _fls_root _fls_got
# A DENY whose payload carries no session_id still denies and still writes its record, with an EMPTY sid. A sid
# read from an unset environment variable would end the hook with rc 1 (an allow); sid comes from
# the payload inside the subshell, so its absence can only empty a field.
_flsid_root=$(_hfl_fresh_root)
_flsid_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_flsid_root" ]; then
  _flsid_out=$(echo '{"tool_name":"Bash","tool_input":{"command":"git add $PATHS"}}' \
    | env -u HOOK_FIRES_LOG_DIR -u CLAUDE_SESSION_ID -u CLAUDE_CODE_SESSION_ID CLAUDE_PROJECT_DIR="$_flsid_root" bash .claude/hooks/block-dangerous.sh 2>/dev/null)
  _flsid_rc=$?
  _flsid_got="rc=$_flsid_rc deny=$(printf '%s' "$_flsid_out" | grep -c -F '"permissionDecision": "deny"') $(_hfl_records "$_flsid_root/.claude/logs/block-dangerous-fires.jsonl")"
  rm -rf "$_flsid_root"
fi
assert_eq "block-dangerous: a DENY whose payload has no session_id still denies and records an empty sid" \
  "rc=2 deny=1 records=1 arm=zsh-wordsplit sid= agent_id=" "$_flsid_got"
unset _flsid_root _flsid_out _flsid_rc _flsid_got
# LIBRARY CONTRACT (held items): a caller's `ts` never replaces the library's timestamp,
# and a record whose values encode past 1,023 B is cut to a line that still parses. 400 x U+26D4 escapes to 2,400 B.
_flk_dir=$(_hfl_fresh_root)
_flk_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_flk_dir" ]; then
  ( . .claude/hooks/lib/fires-log.sh
    HOOK_FIRES_LOG_DIR="$_flk_dir" fires_log contract ts caller-ts sid smoke-sid arm contract-probe \
      cmd "$(python3 -c 'import sys; sys.stdout.buffer.write("\u26d4".encode("utf-8") * 400)')"
  ) >/dev/null 2>&1
  _flk_got=$(python3 -c 'import json, re, sys
lines = [x for x in open(sys.argv[1], "rb").read().split(b"\n") if x]
r = json.loads(lines[-1])
print("records=%d under-1024B=%s maximal=%s ts=%s sid=%s arm=%s cmd-cut=%s" % (len(lines),
    "yes" if all(len(x) + 1 < 1024 for x in lines) else "no",
    "yes" if len(lines[-1]) + 1 + 6 > 1023 else "no",
    "library" if re.match(r"^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$", r.get("ts", "")) else r.get("ts"),
    r.get("sid"), r.get("arm"), "yes" if 0 < len(r.get("cmd", "")) < 400 else "no"))' "$_flk_dir/contract-fires.jsonl" 2>/dev/null)
  rm -rf "$_flk_dir"
fi
# The first cut this fold shipped failed the `maximal` property: it subtracted a BYTE overflow from a
# CHARACTER count, so one U+26D4 (6 B escaped) per character emptied `cmd` instead of keeping the ~160 that fit.
# The line was under the cap either way, so only content could tell the two apart: one more character of this
# value must not fit.
assert_eq "fires-log lib: a caller ts never replaces the timestamp, and an oversized record is cut to the largest line under 1,024 B that still parses" \
  "records=1 under-1024B=yes maximal=yes ts=library sid=smoke-sid arm=contract-probe cmd-cut=yes" "$_flk_got"
unset _flk_dir _flk_got
# CALL-SITE BRACING. The one shape the subshell cannot contain is an unset variable expanded at
# a _bd_fire / _wltr_fire CALL SITE: it is expanded in the hook before the subshell exists and ends the hook with
# rc 1. This arm REDs on a bare `$v`, or a `${v}` with no default, on any call-site line. `*-sites=yes` proves the
# predicate found call sites, so a renamed wrapper cannot pass with nothing scanned.
# ⛔ EVERY library consumer is listed here, not just the first two. A wrapper the predicate does not
# name is not "passing" — it is UNSCANNED, and the `*-sites=yes` legs are what separate the two: a
# renamed or unlisted wrapper reads `none` and REDs rather than reporting a clean `unbraced=none` over
# nothing. `_al_fire` is the case that makes this load-bearing rather than tidy: its call site inside
# deny() expands HIT and BASH_HIT, which are genuinely UNSET on the paths that never reach their
# branch, so a bare `$HIT` there would end that hook with rc 1 under `set -u` — an ALLOW on a
# PreToolUse hook — on exactly the fail-closed path that exists to deny.
_flb_got=$(python3 -c 'import re
bad, sites = [], {}
for path, fn in ((".claude/hooks/block-dangerous.sh", "_bd_fire"),
                 (".claude/hooks/warn-large-tracker-read.sh", "_wltr_fire"),
                 (".claude/hooks/block-push-without-approval.sh", "_pg_fire"),
                 (".claude/hooks/block-subagent-memory-write.sh", "_bsm_fire"),
                 (".claude/hooks/block-subagent-always-loaded-write.sh", "_al_fire")):
    n = 0
    for i, line in enumerate(open(path, encoding="utf-8"), 1):
        if re.match(r"\s*" + fn + r"\s", line):
            n += 1
            if re.search(r"\$[A-Za-z_]|\$\{[A-Za-z_][A-Za-z0-9_]*\}", line):
                bad.append("%s:%d" % (path.rsplit("/", 1)[1], i))
    sites[fn] = n
print("bd-sites=%s tr-sites=%s pg-sites=%s bsm-sites=%s al-sites=%s unbraced=%s" % (
      "yes" if sites["_bd_fire"] else "none", "yes" if sites["_wltr_fire"] else "none",
      "yes" if sites["_pg_fire"] else "none", "yes" if sites["_bsm_fire"] else "none",
      "yes" if sites["_al_fire"] else "none", ",".join(bad) or "none"))' 2>/dev/null)
assert_eq "fires-log call sites: every value at a _bd_fire / _wltr_fire / _pg_fire / _bsm_fire / _al_fire call is braced with a default" \
  "bd-sites=yes tr-sites=yes pg-sites=yes bsm-sites=yes al-sites=yes unbraced=none" "$_flb_got"
unset _flb_got

# ══ THE THREE REMAINING DENY-CAPABLE HOOKS (2026-09-13) ═══════════════════════════════════════
# An earlier change wired block-dangerous.sh and warn-large-tracker-read.sh. These three were not, and
# between them they hold EIGHT deny paths — enumerated by READING each hook, because "the deny path"
# was singular in none of them:
#   block-push-without-approval.sh         jq-absent-fail-closed                          [NEW]
#                                          + the `reason` branch, which ALREADY recorded inline and
#                                            is deliberately left alone (its arms are ~1,400 lines
#                                            above; lib/fires-log.sh says that migration belongs in
#                                            its own commit and is not a behaviour-preserving swap).
#   block-subagent-memory-write.sh         fail-closed-unparseable, protected-path        [NEW]
#   block-subagent-always-loaded-write.sh  bash-write-redirect, bash-unproven-verb,
#                                          fail-closed-unparseable, protected-path        [NEW]
# The last two are PRODUCTION-DEAD — settings.json wires that hook for Edit|Write and MultiEdit
# only, by the design its own header records — but they are live in code and a direct
# invocation reaches them, so they are covered rather than assumed away.
# Every arm pins HOOK_FIRES_LOG_DIR to a throwaway dir. That is the ONE knob the library reads
# BEFORE CLAUDE_PROJECT_DIR, so a fixture arm cannot append to the real calibration corpus.
# _nfl_verdict also json.loads the WHOLE stdout, so every arm doubles as the one-document
# model-channel check: a second document or a stray byte reads deny=0 and REDs.
# ⛔ `agent` IS ASSERTED HERE BECAUSE NOTHING ASSERTED IT — ADDED 2026-09-13.
# Replacing the agent_id extraction with a constant in all three hooks left the
# suite 16 of 16 GREEN while the record on disk named a fabricated agent. `sid` was pinned by every
# arm; only `agent_id` was dark — and these three hooks deliberately use a NEW grep-only extractor,
# so it was three fresh copies with zero coverage. Orchestrator-versus-sub-agent is the one
# discriminator the always-loaded guard's own header says its fire rate turns on, so this was a real
# capability being lost silently. ⚠️ The label at the push-guard arm claimed it checked "the
# payload's session and agent ids" — copied verbatim from a sibling arm that does assert both. The
# label outlived the dropped field, which is the thing no count catches.
_nfl_verdict() {   # <fires-dir> <stem> <rc> <stdout> -> "rc=N deny=N records=N arm=X sid=Y agent=Z"
  python3 -c 'import json, os, sys
d, stem, rc, out = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
try:
    rows = [r for r in open(os.path.join(d, stem + "-fires.jsonl"), encoding="utf-8").read().split("\n") if r.strip()]
except OSError:
    rows = []
last = json.loads(rows[-1]) if rows else {}
try:
    deny = 1 if (json.loads(out).get("hookSpecificOutput") or {}).get("permissionDecision") == "deny" else 0
except ValueError:
    deny = 0
print("rc=%s deny=%d records=%d arm=%s sid=%s agent=%s" % (rc, deny, len(rows),
      last.get("arm", "none"), last.get("sid", "none"), last.get("agent_id", "none")))' "$1" "$2" "$3" "$4"
}
_nfl_none() {      # <fires-dir> <rc> <stdout> -> "rc=N stdout-bytes=N fires-logs=N"
  printf 'rc=%s stdout-bytes=%s fires-logs=%s' "$2" "${#3}" \
    "$(find "$1" -name '*-fires.jsonl' 2>/dev/null | grep -c .)"
}
# A PATH with jq GENUINELY ABSENT.
# ⛔ A broken-jq SHIM must reach the push guard's fail-closed branch just as real absence does: the
# guard gates on the parse's exit code AND requires a non-empty extraction (the same rule as
# block-dangerous.sh), so a degraded parse can never short-circuit to an allow. Never describe a
# fail-open as the guard's contract in a comment here; the arms below assert the refusal.
# `bash` must be symlinked in too, or `env` cannot exec it and the arm reads rc=127 — a VOID reading
# shaped exactly like an early exit (the THIRTEENTH vacuous-control way).
_nfl_nojq=$(cd "$(mktemp -d)" && pwd -P)
for _nfl_b in bash sh cat grep head sed dirname python3 date mkdir tr cut wc find rm awk ls basename sort uniq stat; do
  _nfl_s=$(command -v "$_nfl_b" 2>/dev/null) && ln -sf "$_nfl_s" "$_nfl_nojq/$_nfl_b"
done
# The rig's own positive control. Without it, a PATH that still resolves jq sends every fail-closed
# arm down the ordinary path: it would still deny, so only `records` could tell — and a reader would
# read the RED as a logging bug rather than a dead rig.
assert_eq "fires-log rig: the no-jq PATH really hides jq (without it every fail-closed arm goes DARK)" \
  "jq-absent" "$(PATH="$_nfl_nojq" /bin/bash -c 'command -v jq >/dev/null 2>&1 && echo jq-present || echo jq-absent')"

# ── block-push-without-approval.sh — the jq-absent FAIL-CLOSED branch ────────────────────────
# This is the arm a calibrator most needs and the one that recorded nothing: it fires when the
# parser is degraded and the deny rests on a RAW-payload verb match, so its true/false split cannot
# be guessed. rc=2 is in the expectation so the arm also proves the deny itself still happens.
_nflpg_dir=$(_hfl_fresh_root)
_nflpg_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_nflpg_dir" ]; then
  _nflpg_out=$(echo '{"session_id":"smoke-sid-pg","agent_id":"smoke-agent-pg","tool_name":"Bash","tool_input":{"command":"git push origin main"}}' \
    | env -i PATH="$_nfl_nojq" HOME="$HOME" HOOK_FIRES_LOG_DIR="$_nflpg_dir" /bin/bash .claude/hooks/block-push-without-approval.sh 2>/dev/null)
  _nflpg_got=$(_nfl_verdict "$_nflpg_dir" push-guard "$?" "$_nflpg_out")
  rm -rf "$_nflpg_dir"
fi
assert_eq "push-guard: the jq-absent FAIL-CLOSED deny appends one record with its arm and the payload's session and agent ids" \
  "rc=2 deny=1 records=1 arm=jq-absent-fail-closed sid=smoke-sid-pg agent=smoke-agent-pg" "$_nflpg_got"
# The OTHER branch of the same reason: with jq GENUINELY ABSENT the deny must still say so.
# Without these two pins, forcing the jq-present wording on every path stays green.
assert_contains "push-guard: on the jq-absent path the deny still names the missing jq as its cause" "${_nflpg_out:-}" "jq is not installed"
_nfbd_dir=$(_hfl_fresh_root)
_nfbd_out=""
if [ -n "$_nfbd_dir" ]; then
  _nfbd_out=$(echo '{"session_id":"smoke-sid-bdr","tool_name":"Bash","tool_input":{"command":"rm -rf /"}}' \
    | env -i PATH="$_nfl_nojq" HOME="$HOME" HOOK_FIRES_LOG_DIR="$_nfbd_dir" /bin/bash .claude/hooks/block-dangerous.sh 2>/dev/null)
  rm -rf "$_nfbd_dir"
fi
assert_contains "catastrophe guard: on the jq-absent path the deny still names the missing jq as its cause" "$_nfbd_out" "jq is not installed"
unset _nfbd_dir _nfbd_out
unset _nflpg_dir _nflpg_out _nflpg_got
# NEGATIVE CONTROL: an allowed command under the SAME degraded env writes nothing at all. Without
# it, a record written on an allow path — the corpus pollution the library exists to prevent — would
# pass every positive arm above.
_nflpgs_dir=$(_hfl_fresh_root)
_nflpgs_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_nflpgs_dir" ]; then
  _nflpgs_out=$(echo '{"session_id":"smoke-sid-pgs","tool_name":"Bash","tool_input":{"command":"git status"}}' \
    | env -i PATH="$_nfl_nojq" HOME="$HOME" HOOK_FIRES_LOG_DIR="$_nflpgs_dir" /bin/bash .claude/hooks/block-push-without-approval.sh 2>/dev/null)
  _nflpgs_got=$(_nfl_none "$_nflpgs_dir" "$?" "$_nflpgs_out")
  rm -rf "$_nflpgs_dir"
fi
assert_eq "push-guard: an ALLOWED command writes no fires record on the jq-absent path (negative control)" \
  "rc=0 stdout-bytes=0 fires-logs=0" "$_nflpgs_got"
unset _nflpgs_dir _nflpgs_out _nflpgs_got

# ── block-subagent-memory-write.sh — both deny paths ─────────────────────────────────────────
# ⛔ BOTH of this hook's denies exit 0: the decision travels in the JSON, never in rc, so an arm that
# keys on rc alone cannot tell a deny from an allow here. That is why deny= is read from stdout.
for _nflbsm_case in fail-closed-unparseable protected-path; do
  case "$_nflbsm_case" in
    fail-closed-unparseable) _nflbsm_payload='{"session_id":"smoke-sid-bsm1","agent_id":"smoke-agent-bsm1","tool_name":"Write","tool_input":{"content":"touching .claude/skills/qa-expert/MEMORY.md"}}'; _nflbsm_sid=smoke-sid-bsm1; _nflbsm_agent=smoke-agent-bsm1 ;;
    protected-path)          _nflbsm_payload='{"session_id":"smoke-sid-bsm2","agent_id":"smoke-agent-bsm","tool_name":"Edit","tool_input":{"file_path":"/abs/.claude/skills/foo/MEMORY.md"}}'; _nflbsm_sid=smoke-sid-bsm2; _nflbsm_agent=smoke-agent-bsm ;;
  esac
  _nflbsm_dir=$(_hfl_fresh_root)
  _nflbsm_got="fixture root refused (mktemp did not yield a fresh empty dir)"
  if [ -n "$_nflbsm_dir" ]; then
    _nflbsm_out=$(printf '%s' "$_nflbsm_payload" \
      | env HOOK_FIRES_LOG_DIR="$_nflbsm_dir" bash .claude/hooks/block-subagent-memory-write.sh 2>/dev/null)
    _nflbsm_got=$(_nfl_verdict "$_nflbsm_dir" subagent-memory-block "$?" "$_nflbsm_out")
    rm -rf "$_nflbsm_dir"
  fi
  assert_eq "subagent-memory-write: the $_nflbsm_case DENY appends one record carrying that arm" \
    "rc=0 deny=1 records=1 arm=$_nflbsm_case sid=$_nflbsm_sid agent=$_nflbsm_agent" "$_nflbsm_got"
done
unset _nflbsm_agent _nflbsm_case _nflbsm_payload _nflbsm_sid _nflbsm_dir _nflbsm_out _nflbsm_got
_nflbsms_dir=$(_hfl_fresh_root)
_nflbsms_got="fixture root refused (mktemp did not yield a fresh empty dir)"
if [ -n "$_nflbsms_dir" ]; then
  _nflbsms_out=$(echo '{"session_id":"smoke-sid-bsm3","tool_name":"Edit","tool_input":{"file_path":"/abs/src/lib/foo.ts"}}' \
    | env HOOK_FIRES_LOG_DIR="$_nflbsms_dir" bash .claude/hooks/block-subagent-memory-write.sh 2>/dev/null)
  _nflbsms_got=$(_nfl_none "$_nflbsms_dir" "$?" "$_nflbsms_out")
  rm -rf "$_nflbsms_dir"
fi
assert_eq "subagent-memory-write: an ALLOWED source write writes no fires record (negative control)" \
  "rc=0 stdout-bytes=0 fires-logs=0" "$_nflbsms_got"
unset _nflbsms_dir _nflbsms_out _nflbsms_got

# ── block-subagent-always-loaded-write.sh — all four deny paths ──────────────────────────────
# ⛔ is_protected EXCLUDES any path it can PROVE is outside $ROOT by an inode ancestor walk, so the
# protected file must live INSIDE the pinned root. Pinning CLAUDE_PROJECT_DIR at an empty temp dir
# and passing a repo-relative path makes every one of these arms go DARK, not RED — the walk reaches
# the filesystem root without meeting ROOT, the path reads as "another repo", and the hook correctly
# allows. Measured while writing these arms (the TENTH vacuous-control way, caught by the probe).
_nfl_alroot() {
  local r
  r=$(_hfl_fresh_root) || return 0
  [ -n "$r" ] || return 0
  mkdir -p "$r/.claude/rules" && : > "$r/.claude/rules/copy.md" || return 0
  printf '%s' "$r"
}
for _nflal_case in protected-path fail-closed-unparseable bash-write-redirect bash-unproven-verb; do
  _nflal_root=$(_nfl_alroot)
  _nflal_dir=$(_hfl_fresh_root)
  _nflal_got="fixture root refused (mktemp did not yield a fresh empty dir)"
  if [ -n "$_nflal_root" ] && [ -n "$_nflal_dir" ]; then
    _nflal_payload=$(python3 -c 'import json, sys
root, case_ = sys.argv[1], sys.argv[2]
f = root + "/.claude/rules/copy.md"
if case_ == "protected-path":
    p = {"session_id": "smoke-sid-al", "agent_id": "smoke-agent-al", "tool_name": "Edit",
         "tool_input": {"file_path": f, "old_string": "a", "new_string": "b"}}
elif case_ == "fail-closed-unparseable":
    p = {"session_id": "smoke-sid-al", "agent_id": "smoke-agent-al", "tool_name": "Write",
         "tool_input": {"content": "rewriting .claude/rules/copy.md now"}}
elif case_ == "bash-write-redirect":
    p = {"session_id": "smoke-sid-al", "agent_id": "smoke-agent-al", "tool_name": "Bash",
         "tool_input": {"command": "echo x > " + f}}
else:
    p = {"session_id": "smoke-sid-al", "agent_id": "smoke-agent-al", "tool_name": "Bash",
         "tool_input": {"command": "perl -pi -e s/a/b/ " + f}}
print(json.dumps(p))' "$_nflal_root" "$_nflal_case")
    # The fail-closed arm is the only one needing jq gone: with jq present the payload parses, no
    # path is found, and the backstop is reached anyway — but via a different route, so the arm
    # would stop testing what it names.
    # ⛔ `env -i` MUST CARRY FF_ALWAYS_LOADED_ALLOW_MARKER — ADDED 2026-09-13 AFTER THIS ARM WAS
 # MEASURED RE-OPENING A FLEET-WIDE PUSH BLOCK.
    # The suite exports that variable at its prologue to a NON-EXISTENT mktemp path precisely so no
    # arm ever reads the live machine-global default. `env -i` erases the export, so the hook's
    # `marker_live()` fell back to /tmp/claude-always-loaded-allow — and `marker_live && exit 0` sits
    # directly on the fail-closed branch this arm exercises. Consequence: while ANY seat on this
    # machine holds the sanctioned 900-second bypass open, the hook exits 0, this arm goes RED, and
    # `.githooks/pre-push` runs this suite as a HARD GATE — so every seat's push fails, on an arm
    # whose message blames the fires log. The prologue's own self-check (grep
    # FF_ALWAYS_LOADED_ALLOW_MARKER above) exists for exactly this incident; this re-opened it
    # through a new door.
    # ⚠️ DELIBERATE DEVIATION FROM THE PRESCRIBED REMEDY, which was to delete this branch and let all
    # four cases take the `else`. That closes the hazard too, and the two routes were measured
    # producing a BYTE-IDENTICAL verdict — but byte-identical OUTCOME is not the same claim as the
    # same ROUTE, and this arm is NAMED for the no-jq route. Passing the marker keeps the route the
    # name promises and closes the hazard in one variable instead of removing coverage.
    # ⚠️ AND THE ROUTE DISTINCTION IS CURRENTLY UNASSERTED: nothing here can tell the two apart, so
    # the `env -i` buys fidelity no assertion checks. Keep it, or delete it with that measurement
    # quoted — do not delete it believing the arm proves anything about the route today.
    if [ "$_nflal_case" = fail-closed-unparseable ]; then
      _nflal_out=$(printf '%s' "$_nflal_payload" | env -i PATH="$_nfl_nojq" HOME="$HOME" \
        FF_ALWAYS_LOADED_ALLOW_MARKER="$FF_ALWAYS_LOADED_ALLOW_MARKER" \
        HOOK_FIRES_LOG_DIR="$_nflal_dir" CLAUDE_PROJECT_DIR="$_nflal_root" \
        /bin/bash .claude/hooks/block-subagent-always-loaded-write.sh 2>/dev/null)
    else
      _nflal_out=$(printf '%s' "$_nflal_payload" | env HOOK_FIRES_LOG_DIR="$_nflal_dir" \
        CLAUDE_PROJECT_DIR="$_nflal_root" bash .claude/hooks/block-subagent-always-loaded-write.sh 2>/dev/null)
    fi
    _nflal_got=$(_nfl_verdict "$_nflal_dir" subagent-always-loaded-block "$?" "$_nflal_out")
  fi
  rm -rf "$_nflal_root" "$_nflal_dir"
  assert_eq "subagent-always-loaded-write: the $_nflal_case DENY appends one record carrying that arm" \
    "rc=0 deny=1 records=1 arm=$_nflal_case sid=smoke-sid-al agent=smoke-agent-al" "$_nflal_got"
done
unset _nflal_case _nflal_root _nflal_dir _nflal_payload _nflal_out _nflal_got
# NEGATIVE CONTROLS, one per branch that can allow: an ordinary Write, and a Bash READ of a
# protected file. The read one is the arm that matters — this hook's whole Bash branch exists to
# grade the WRITE TARGET and never the mention, so a read entering the corpus would inflate every
# false-positive rate computed off it with traffic the guard is supposed to wave through.
for _nflals_case in ordinary-write bash-read; do
  _nflals_root=$(_nfl_alroot)
  _nflals_dir=$(_hfl_fresh_root)
  _nflals_got="fixture root refused (mktemp did not yield a fresh empty dir)"
  if [ -n "$_nflals_root" ] && [ -n "$_nflals_dir" ]; then
    if [ "$_nflals_case" = ordinary-write ]; then
      _nflals_payload='{"session_id":"smoke-sid-als","tool_name":"Write","tool_input":{"content":"hello world"}}'
    else
      _nflals_payload=$(python3 -c 'import json, sys
print(json.dumps({"session_id": "smoke-sid-als", "tool_name": "Bash",
                  "tool_input": {"command": "cat " + sys.argv[1] + "/.claude/rules/copy.md"}}))' "$_nflals_root")
    fi
    _nflals_out=$(printf '%s' "$_nflals_payload" | env HOOK_FIRES_LOG_DIR="$_nflals_dir" \
      CLAUDE_PROJECT_DIR="$_nflals_root" bash .claude/hooks/block-subagent-always-loaded-write.sh 2>/dev/null)
    _nflals_got=$(_nfl_none "$_nflals_dir" "$?" "$_nflals_out")
  fi
  rm -rf "$_nflals_root" "$_nflals_dir"
  assert_eq "subagent-always-loaded-write: an ALLOWED $_nflals_case writes no fires record (negative control)" \
    "rc=0 stdout-bytes=0 fires-logs=0" "$_nflals_got"
done
unset _nflals_case _nflals_root _nflals_dir _nflals_payload _nflals_out _nflals_got

# ── CONTAINMENT: a broken library must not turn any of these denies into an allow ────────────
# The same three shapes the block-dangerous/tracker rig above uses, against the three hooks wired
# here. `corrupt` fails to PARSE — and `.` is a POSIX special builtin, so under `set -e` that kills a
# hook sourcing it in its own shell with rc=2, which from a PreToolUse hook is itself a deny on every
# call it matches. `exit0` and `unbound` are the two shapes `bash -n` PASSES and that still END the
# sourcing shell: rc 0 or rc 1, nothing on either channel, which is ALLOW. All three must leave every
# decision and every stdout document exactly as they were, and write no record.
_nflc_build() {   # <shape> -> a fixture root with the three hooks and a shaped lib, or nothing
  local r
  r=$(_hfl_fresh_root)
  [ -n "$r" ] || return 0
  mkdir -p "$r/.claude/hooks/lib" "$r/.claude/rules" || return 0
  cp .claude/hooks/block-push-without-approval.sh .claude/hooks/block-subagent-memory-write.sh \
     .claude/hooks/block-subagent-always-loaded-write.sh "$r/.claude/hooks/" || return 0
  : > "$r/.claude/rules/copy.md"
  case "$1" in
    corrupt) printf 'echo CORRUPT-LIB-STDOUT\nfires_log() {\n  if then\n' > "$r/.claude/hooks/lib/fires-log.sh" ;;
    exit0)   { cat .claude/hooks/lib/fires-log.sh; printf '\nexit 0\n'; } > "$r/.claude/hooks/lib/fires-log.sh" ;;
    unbound) { cat .claude/hooks/lib/fires-log.sh; printf '\n: "$SMOKE_FIRES_LOG_UNBOUND_PROBE"\n'; } > "$r/.claude/hooks/lib/fires-log.sh" ;;
  esac
  printf '%s' "$r"
}
_nflc_run() {     # <root> <+e|-e> -> "<case>=rc<N>/<deny|empty|BROKEN> … records=<N>"
                  # `+e` is plain bash — how the harness runs a hook; `-e` is the stricter run.
  local got="" case_ payload out rc shape
  for case_ in pg-deny bsm-deny bsm-safe al-deny al-safe; do
    case "$case_" in
      pg-deny)  payload='{"session_id":"c","tool_name":"Bash","tool_input":{"command":"git push origin main"}}' ;;
      bsm-deny) payload='{"session_id":"c","tool_name":"Edit","tool_input":{"file_path":"/abs/.claude/skills/foo/MEMORY.md"}}' ;;
      bsm-safe) payload='{"session_id":"c","tool_name":"Edit","tool_input":{"file_path":"/abs/src/lib/foo.ts"}}' ;;
      al-deny)  payload=$(python3 -c 'import json, sys
print(json.dumps({"session_id": "c", "tool_name": "Edit", "tool_input": {
    "file_path": sys.argv[1] + "/.claude/rules/copy.md", "old_string": "a", "new_string": "b"}}))' "$1") ;;
      al-safe)  payload='{"session_id":"c","tool_name":"Write","tool_input":{"content":"hello world"}}' ;;
    esac
    case "$case_" in
      pg-deny)  shape=block-push-without-approval.sh ;;
      bsm-*)    shape=block-subagent-memory-write.sh ;;
      al-*)     shape=block-subagent-always-loaded-write.sh ;;
    esac
    # jq gone for pg-deny ONLY: that is the branch this fold wired, and it is the one that sources
    # the library. With jq present the push guard denies through its inline `reason` writer instead
    # and the arm would stop exercising the library at all.
    if [ "$case_" = pg-deny ]; then
      out=$(printf '%s' "$payload" | env -i PATH="$_nfl_nojq" HOME="$HOME" \
        CLAUDE_PROJECT_DIR="$1" /bin/bash "$2" "$1/.claude/hooks/$shape" 2>/dev/null)
    else
      out=$(printf '%s' "$payload" | env -u HOOK_FIRES_LOG_DIR -u SMOKE_FIRES_LOG_UNBOUND_PROBE \
        CLAUDE_PROJECT_DIR="$1" /bin/bash "$2" "$1/.claude/hooks/$shape" 2>/dev/null)
    fi
    rc=$?
    got="$got $case_=rc$rc/$(printf '%s' "$out" | python3 -c 'import json, sys
raw = sys.stdin.read()
if not raw.strip():
    print("empty"); sys.exit(0)
try:
    d = json.loads(raw)
    print("deny" if (d.get("hookSpecificOutput") or {}).get("permissionDecision") == "deny" else "BROKEN")
except ValueError:
    print("BROKEN")' 2>/dev/null)"
  done
  printf '%s records=%s' "${got# }" "$(cat "$1"/.claude/logs/*-fires.jsonl 2>/dev/null | grep -c .)"
}
for _nflc_shape in corrupt exit0 unbound; do
  _nflc_root=$(_nflc_build "$_nflc_shape")
  _nflc_got="fixture root refused (mktemp did not yield a fresh empty dir)"
  if [ -n "$_nflc_root" ]; then
    _nflc_got="plain: $(_nflc_run "$_nflc_root" +e) | bash -e: $(_nflc_run "$_nflc_root" -e)"
    rm -rf "$_nflc_root"
  fi
  assert_eq "fires-log containment: a broken lib ($_nflc_shape) turns no deny of the three newly-wired hooks into an allow, under plain bash or bash -e" \
    "plain: pg-deny=rc2/deny bsm-deny=rc0/deny bsm-safe=rc0/empty al-deny=rc0/deny al-safe=rc0/empty records=0 | bash -e: pg-deny=rc2/deny bsm-deny=rc0/deny bsm-safe=rc0/empty al-deny=rc0/deny al-safe=rc0/empty records=0" "$_nflc_got"
done
unset _nflc_shape _nflc_root _nflc_got
rm -rf "$_nfl_nojq"
unset _nfl_nojq _nfl_b _nfl_s

