echo ""
echo "=== validate-no-secrets.sh (staged-files secret scan) ==="
# ⚠️ EXISTENCE AND EXIT-CODE ASSERTIONS CANNOT GUARD A WARN-MODE SECRET SCANNER (the class
# `scripts/smoke-mutation-matrix.sh` measures: neuter the hook to `exit 0` and see what goes red).
#   · "exists + executable" — a mutation writes `exit 0` INTO the file, so it still exists and is
#     still executable. Passes over a corpse.
#   · "SAFE default → exit 0" — the hook is WARN-MODE and ALWAYS exits 0, so an exit-code assertion
#     cannot tell it apart from a dead hook. Passes over a corpse.
# Only the FIRE arms below make this block a guard.
#
# "Real FIRE needs git-stage manipulation" is NOT a reason to skip them: the hook reads
# `git diff --cached` from the **CWD** (:5, bare `git`, no -C, no CLAUDE_PROJECT_DIR), so a throwaway
# `git init` repo drives the real FIRE path with ZERO risk to the user's staging area (the same
# reasoning applies to `agent-diff-reporter` above). **Check how the SUT resolves its target before
# accepting "it would be destructive to test."**
VNS_T="$(mktemp -d)"
( cd "$VNS_T" && git init -q . && git config user.email t@t && git config user.name t ) >/dev/null 2>&1
vns() { ( cd "$VNS_T" && bash "$REPO_ROOT/.claude/hooks/validate-no-secrets.sh" 2>&1 ); }

if [[ ! -x .claude/hooks/validate-no-secrets.sh ]]; then
  fail "validate-no-secrets.sh missing or non-executable"
else
  pass "validate-no-secrets.sh exists + executable"
fi

# SAFE: nothing staged → silent. (Necessary, NOT sufficient — a dead hook passes this too.)
assert_empty "SAFE: nothing staged → silent" "$(vns)"

# SAFE: a staged file with NO secret → silent. (Proves it isn't just screaming at everything.)
( cd "$VNS_T" && echo "const x = 1;" > clean.ts && git add clean.ts ) >/dev/null 2>&1
assert_empty "SAFE: staged file, no secret → silent" "$(vns)"

# FIRE: each secret class the hook claims to catch. THESE are what make it a guard.
# The database service-role variable name is read out of the hook's own pattern, so this file does not restate it.
_vns_role_var="$(grep -oE '[A-Z]+_SERVICE_ROLE_KEY' .claude/hooks/validate-no-secrets.sh | head -1)"
( cd "$VNS_T" && printf '%s=%s\n' "$_vns_role_var" 'eyJ''hbGciOiJIUzI1NiJ9.fake' > leak.ts && git add leak.ts ) >/dev/null 2>&1   # fake value, assembled at run time
vns_out="$(vns)"
assert_contains "FIRE: staged database service-role key variable → warns" "$vns_out" "WARNING: Possible secret in staged file"
assert_contains "FIRE: names the offending file" "$vns_out" "leak.ts"
assert_contains "FIRE: emits the review directive" "$vns_out" "Review staged files for secrets"
# LEDGER WIRED (commit path) — same rationale as the write-path ledger arm above.
assert_contains "FIRE writes a ledger line (commit path)" "$(cat "$SECRET_SCAN_FIRES_LOG" 2>/dev/null)" '"hook":"validate-no-secrets"' 

( cd "$VNS_T" && git rm -q --cached leak.ts && rm -f leak.ts && printf 'const db = "postgres''ql://user:hunter2''@db.example.com:5432/x";\n' > url.ts && git add url.ts ) >/dev/null 2>&1
assert_contains "FIRE: staged postgres URL WITH a password → warns" "$(vns)" "WARNING: Possible secret in staged file"

( cd "$VNS_T" && git rm -q --cached url.ts && rm -f url.ts && printf -- '-----BEGIN %s PRIVATE KEY-----\n%s\n' 'RSA' 'fakeKeyBody==' > key.pem && git add key.pem ) >/dev/null 2>&1   # header assembled at run time
assert_contains "FIRE: staged private-key header → warns" "$(vns)" "WARNING: Possible secret in staged file"

# ONE FIRE FIXTURE PER PATTERN CLASS — a single FIRE proves ONE alternation, never the SET.
# A scanner's pattern set must match the keys the product actually holds: a pattern for a key the
# product cannot have guards nothing, and a missing pattern for one it does hold is a silent miss.
# Pattern set unified with scan-secrets-writes.sh (the WRITE path). Each class gets a fixture, so
# the next person to add a pattern cannot ship it untested.
( cd "$VNS_T" && git rm -q --cached key.pem && rm -f key.pem && printf 'const k = "sk-''proj-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";\n' > ai.ts && git add ai.ts ) >/dev/null 2>&1
assert_contains "FIRE: staged OpenAI key (sk-""proj-) → warns" "$(vns)" "WARNING: Possible secret in staged file"

( cd "$VNS_T" && git rm -q --cached ai.ts && rm -f ai.ts && printf 'const k = "sk-''ant-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";\n' > an.ts && git add an.ts ) >/dev/null 2>&1
assert_contains "FIRE: staged Anthropic key (sk-""ant-) → warns" "$(vns)" "WARNING: Possible secret in staged file"

( cd "$VNS_T" && git rm -q --cached an.ts && rm -f an.ts && printf 'const k = "ghp_''aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";\n' > gh.ts && git add gh.ts ) >/dev/null 2>&1
assert_contains "FIRE: staged GitHub PAT (ghp_) → warns" "$(vns)" "WARNING: Possible secret in staged file"

# ESCAPING ROUND-TRIP: a staged path carrying a BACKSLASH must land in
# the ledger as the SAME path. Pre-fix, printf logged VALID JSON whose file field was a
# DIFFERENT path (backslash-b parsed as a BACKSPACE) — silent field substitution in an
# attribution ledger. Parsed with a real JSON parser, not a grep; reverting the hook's
# backslash-first escape REDs this. gh.ts is left staged — the next block's chain expects it.
( cd "$VNS_T" && printf 'const k = "sk-''ant-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";\n' > 'esc\b.ts' && git add -- 'esc\b.ts' ) >/dev/null 2>&1
vns >/dev/null 2>&1
_esc_got=$(python3 -c "
import json, sys
ok = False
try:
    for l in open(sys.argv[1], encoding='utf-8', errors='replace'):
        l = l.strip()
        if not l: continue
        try: r = json.loads(l)
        except Exception: continue
        if r.get('file') == sys.argv[2] and r.get('hook') == 'validate-no-secrets': ok = True
except FileNotFoundError: pass
print('ROUNDTRIP-OK' if ok else 'ROUNDTRIP-FAIL')" "$SECRET_SCAN_FIRES_LOG" 'esc\b.ts')
assert_contains "escape arm (commit path): backslash path round-trips the ledger intact" "$_esc_got" "ROUNDTRIP-OK"
( cd "$VNS_T" && git rm -q --cached -- 'esc\b.ts' 2>/dev/null; rm -f 'esc\b.ts' ) >/dev/null 2>&1

# PGPASSWORD on the COMMIT path — same four states x two carriers. The two scanners are supposed to
# cover the SAME secret inventory, so a fixture here is what keeps the union honest rather than a
# comment asserting it.
( cd "$VNS_T" && git rm -q --cached gh.ts && rm -f gh.ts && printf 'PGPASSWORD=FixturePass1 psql -h h\n' > pg.sh && git add pg.sh ) >/dev/null 2>&1
assert_contains "FIRE: staged PGPASSWORD literal, SHELL carrier → warns" "$(vns)" "WARNING: Possible secret in staged file"
( cd "$VNS_T" && git rm -q --cached pg.sh && rm -f pg.sh && printf '          PGPASSWORD: FixturePass1\n' > pg.yml && git add pg.yml ) >/dev/null 2>&1
assert_contains "FIRE: staged PGPASSWORD literal, YAML carrier → warns" "$(vns)" "WARNING: Possible secret in staged file"
( cd "$VNS_T" && git rm -q --cached pg.yml && rm -f pg.yml && printf 'PGPASSWORD=${DB_PASS} psql -h h\n' > pgv.sh && git add pgv.sh ) >/dev/null 2>&1
assert_empty "SILENT: staged PGPASSWORD=\$VAR → no warning" "$(vns)"
( cd "$VNS_T" && git rm -q --cached pgv.sh && rm -f pgv.sh && printf 'PGPASSWORD=<password>\n' > pgp.sh && git add pgp.sh ) >/dev/null 2>&1
assert_empty "SILENT: staged PGPASSWORD=<password> → no warning" "$(vns)"
( cd "$VNS_T" && git rm -q --cached pgp.sh && rm -f pgp.sh && printf '          PGPASSWORD: test\n' > pgt.yml && git add pgt.yml ) >/dev/null 2>&1
assert_empty "SILENT: staged PGPASSWORD: test → no warning" "$(vns)"
( cd "$VNS_T" && git rm -q --cached pgt.yml && rm -f pgt.yml && printf 'const k = "ghp_''aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";\n' > gh.ts && git add gh.ts ) >/dev/null 2>&1

# STAGED-TRUTH: scan the STAGED BLOB, not the worktree. The discriminating case: stage a
# secret, then scrub it from the WORKTREE without re-staging. A worktree grep would read the clean
# worktree and stay SILENT while the secret is staged-and-committable. Mutation-valid: change it to
# `grep "$file"` (worktree) and this goes RED (the staged blob still holds the key).
( cd "$VNS_T" && git rm -q --cached gh.ts && rm -f gh.ts \
  && printf 'const k = "sk-''proj-bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb";\n' > scrub.ts && git add scrub.ts \
  && printf 'const k = "clean";\n' > scrub.ts ) >/dev/null 2>&1
assert_contains "FIRE: secret STAGED then scrubbed from worktree → still warns (scans the staged blob)" "$(vns)" "WARNING: Possible secret in staged file"
rm -rf "$VNS_T"

echo ""
# new-email-type-check.sh was DELETED: it could not fire
# at push time. Its replacement is a block-mode named vitest line in .githooks/pre-push running
# a test file that carries its own mutation-verified arms.

echo ""
echo "=== .githooks/pre-commit (skill-lint gate, retrospective coverage) ==="
# Existence + executable
if [[ ! -f .githooks/pre-commit ]]; then
  fail ".githooks/pre-commit missing"
elif [[ ! -x .githooks/pre-commit ]]; then
  fail ".githooks/pre-commit not executable"
else
  pass ".githooks/pre-commit exists + executable"
fi

# readonly-brief-compliance self-test (2026-09-04). WHY IT IS HERE: the guard shipped with a 6/6
# self-test and NO RUNNER — a zero-runner guard is a class this file names in its own comments, and
# it was caught the day it shipped. It is the only instrument that can answer whether a
# read-only BRIEF held, which matters precisely because the frontmatter demonstrably does not bind.
python3 scripts/readonly-brief-compliance.py --self-test >/dev/null 2>&1
assert_eq "readonly-brief-compliance --self-test → exit 0 (marker-beats-prose fixtures pass)" "0" "$?"

# Agent tool-frontmatter regression guard (2026-09-04). WHY: 53 generated bodies and 17 read-class
# frontmatters changed in one commit and NOTHING reddened on a wrong tool line — the arm below
# greps prose only. These read the FRONTMATTER, so a generator edit that drops the deny, widens a
# read-class tool line, or adds a `memory:` field (which the vendor docs say silently re-enables
# Read/Write/Edit) fails here instead of shipping.
# ⛔ FIXED STRINGS ONLY. The first draft used '^tools:.*\(Write\|Edit\)' and was
# BLOCKED for it — a variable-width quantifier before an alternation. grep -F cannot backtrack.
# ⛔ `assert_ne` DOES NOT EXIST in this suite — the first draft of this arm used it and was a
# SILENT NO-OP, which is precisely the class these arms exist to close. Computed boolean instead.
_ro_files=$(grep -lF 'disallowedTools: Write, Edit' .claude/agents/*.md 2>/dev/null | wc -l | tr -d ' ')
_ro_present=$([ "$_ro_files" -gt 0 ] && echo yes || echo no)
assert_eq "agent frontmatter: at least one read-class definition declares disallowedTools" "yes" "$_ro_present"
_ro_leak=0
for _f in $(grep -lF 'disallowedTools: Write, Edit' .claude/agents/*.md 2>/dev/null); do
  _tl=$(grep -m1 '^tools:' "$_f")
  case "$_tl" in *Write*|*Edit*) _ro_leak=$((_ro_leak+1));; esac
done
assert_eq "agent frontmatter: no read-class definition still lists Write/Edit in tools:" "0" "$_ro_leak"
# ⛔ ANCHOR THE FIELD TEST — this arm asserts a FRONTMATTER FIELD and the predicate was an
# UNANCHORED `grep -lF`, so it matched the token anywhere in the file INCLUDING INSIDE A
# `description:` STRING. It went RED on 2026-09-13 when an external catalog refresh put the
# upstream's own CLI invocation (`ecc memory: ecc.memory.v1 …`) into a generated agent
# description — a faithful description of the system being catalogued, not a field, and
# rewriting the description to dodge the predicate would have been fixing the wrong side.
# Measured at that moment: unanchored matched 1 file, anchored matched 0, and no agent
# definition carries the field at all. Frontmatter keys in these files are at column 0
# (`name:`/`description:`/`tools:`/`model:`), so `^memory:` is the field form exactly.
# The arm's safety intent is UNCHANGED and still worth having: a real `memory:` field
# re-enables Read/Write/Edit on a read-class definition. Use-vs-mention, which is the
# fourth instance of that class found in one sweep.
_memory_field=$(grep -lE '^memory:' .claude/agents/*.md 2>/dev/null | wc -l | tr -d ' ')
assert_eq "agent frontmatter: no definition carries a memory: field (it re-enables Read/Write/Edit)" "0" "$_memory_field"
_writer_lost=0
for _f in .claude/agents/*.md; do
  grep -qF 'disallowedTools:' "$_f" && continue
  _tl=$(grep -m1 '^tools:' "$_f")
  # A file with NO `tools:` line is not an agent definition — `_agent-primer.md` is shared prose.
  # Without this the arm counted it as a write-class seat that had lost Write, and RED'd on nothing.
  [ -z "$_tl" ] && continue
  case "$_tl" in *Write*) ;; *) _writer_lost=$((_writer_lost+1));; esac
done
assert_eq "agent frontmatter: every WRITE-class definition still grants Write (the /agent-work class is intact)" "0" "$_writer_lost"

# skill-lint MISSING_TRIGGER detector self-test (regression guard, 2026-06-18 — locks the +periodically|regularly change)
node scripts/skill-lint.mjs --self-test >/dev/null 2>&1
assert_eq "skill-lint --self-test → exit 0 (MISSING_TRIGGER fixtures pass)" "0" "$?"

# SAFE case: SKIP_SKILL_LINT=1 → silent exit 0 regardless of staged content
# Both escapes: the router-staleness arm sits ABOVE the skill-lint escape (its own escape var), so
# whole-hook silence needs both set.
out=$(SKIP_SKILL_LINT=1 SKIP_ROUTER_STALENESS_CHECK=1 bash .githooks/pre-commit 2>&1)
ec=$?
assert_eq "SAFE both escapes → exit 0" "0" "$ec"
assert_empty "SAFE both escapes → silent" "$out"

# SAFE case: no staged skill files → silent exit 0 (script greps git diff --cached)
# This relies on the actual git state. If no .claude/skills/*.md is staged at smoke-time, exits clean.
# If a skill file IS staged (e.g. during the actual commit that ships this hook), the script may
# print warnings — that's the warn-mode behavior we want, not a smoke-test failure.
out=$(bash .githooks/pre-commit 2>&1)
ec=$?
assert_eq "RUN default → exit 0 (warn-mode never blocks)" "0" "$ec"

# Spec invariant: warn-mode hardcoded in script (key string present)
if grep -q "WARN-MODE " .githooks/pre-commit; then
  pass "FIRE-mode block hardcoded as exit 0 (warn-mode marker present)"
else
  fail "pre-commit script missing warn-mode marker — may have been promoted to block-mode silently"
fi

# router-staleness arm: DETECT half wired here,
# REPAIR half is memory-tier-split --heal (/wrap Step 6b). Structural invariants + one live probe.
if grep -q "SKIP_ROUTER_STALENESS_CHECK" .githooks/pre-commit && grep -q -- "--heal" .githooks/pre-commit; then
  pass "pre-commit router-staleness arm present (escape var + --heal fix pointer)"
else
  fail "pre-commit router-staleness arm missing — the detect half was removed"
fi
if grep -qF '"--heal"' scripts/memory-tier-split.mjs; then
  pass "memory-tier-split --heal mode present (repair half)"
else
  fail "memory-tier-split --heal mode missing — /wrap Step 6b + the pre-commit warn both prescribe it"
fi
# Live probe: --heal --dry-run always emits a terminal HEAL VERDICT line and writes nothing.
# rc is state-dependent (clean corpus 0; manual-verdict rows 1) — assert the VERDICT TOKEN, not rc.
out=$(node scripts/memory-tier-split.mjs --heal --dry-run 2>&1)
if printf '%s' "$out" | grep -qE "HEAL VERDICT: (CLEAN|ATTENTION|DRY RUN)"; then
  pass "--heal --dry-run emits a positive HEAL VERDICT token"
else
  fail "--heal --dry-run emitted no HEAL VERDICT token"
fi
# RED CONTROL: a BROKEN router — manifest naming a shard not on disk —
# must yield ATTENTION + rc=1 and must NOT print CLEAN. Throwaway copy of a real sharded skill.
HB_TMP="$(mktemp -d "${TMPDIR:-/tmp}/heal-broken.XXXXXX")"
mkdir -p "$HB_TMP/skills" && cp -R .claude/skills/saas-engineer "$HB_TMP/skills/" \
  && rm -f "$HB_TMP"/skills/saas-engineer/MEMORY-ARCHIVE-2026-08-23-*.md
out=$(node scripts/memory-tier-split.mjs --heal "$HB_TMP/skills" 2>&1); ec=$?
assert_eq "--heal on a BROKEN router → rc 1" "1" "$ec"
if printf '%s' "$out" | grep -q "HEAL VERDICT: ATTENTION"; then
  pass "--heal on a BROKEN router → ATTENTION token"
else
  fail "--heal on a BROKEN router → no ATTENTION token (got: $(printf '%s' "$out" | tail -1))"
fi
if printf '%s' "$out" | grep -q "HEAL VERDICT: CLEAN"; then
  fail "--heal on a BROKEN router printed CLEAN — the false all-clear is back"
else
  pass "--heal on a BROKEN router does not print CLEAN"
fi
rm -rf "$HB_TMP"
# BEHAVIORAL arms for the pre-commit router arm, via a throwaway git repo (the arm reads the
# STAGED tree of whatever repo cwd is in). The presence gates anchor on .claude/hooks/*.sh,
# so this .githooks arm is invisible to both — these two arms are its only liveness coverage.
RS_REPO="$(pwd)"
RS_TMP="$(mktemp -d "${TMPDIR:-/tmp}/rs-smoke.XXXXXX")"
( cd "$RS_TMP" && git init -q . && git config user.email smoke@local && git config user.name smoke \
  && mkdir -p scripts/lib .claude/skills \
  && cp "$RS_REPO/scripts/memory-tier-split.mjs" "$RS_REPO/scripts/check-lesson-numbers.mjs" scripts/ \
  && cp "$RS_REPO/scripts/lib/is-main.mjs" scripts/lib/ \
  && cp -R "$RS_REPO/.claude/skills/saas-engineer" .claude/skills/ \
  && git add scripts .claude && git commit -m base >/dev/null ) 2>/dev/null
RS_SHARD="$(ls "$RS_TMP"/.claude/skills/saas-engineer/MEMORY-ARCHIVE-2026-08-23-*.md | head -1)"
printf '\n## 2026-08-26 — smoke synthetic entry\nsynthetic body for the FIRE arm.\n' >> "$RS_SHARD"
out=$(cd "$RS_TMP" && git add .claude/skills/saas-engineer && bash "$RS_REPO/.githooks/pre-commit" 2>&1); ec=$?
assert_eq "pre-commit router arm FIRE (staged shard, stale router) → exit 0 (warn-mode)" "0" "$ec"
if printf '%s' "$out" | grep -q "router-staleness warn-mode" && printf '%s' "$out" | grep -q "saas-engineer"; then
  pass "pre-commit router arm FIRE → warns, names the touched skill"
else
  fail "pre-commit router arm FIRE → no warn (got: $(printf '%s' "$out" | head -3))"
fi
out=$(cd "$RS_TMP" && git reset -q && git checkout -q -- .claude && printf 'x\n' > note.txt && git add note.txt && bash "$RS_REPO/.githooks/pre-commit" 2>&1); ec=$?
assert_eq "pre-commit router arm SAFE (no memory files staged) → exit 0" "0" "$ec"
if printf '%s' "$out" | grep -q "router-staleness"; then
  fail "pre-commit router arm SAFE → warned with no memory files staged"
else
  pass "pre-commit router arm SAFE → silent"
fi
rm -rf "$RS_TMP"

# --- the project-memory trigger ---
# ⛔ THE FIXTURE MUST CONTAIN A `.claude/skills` DIRECTORY, AND THAT IS NOT TIDINESS.
# ⚠️ **THE RATIONALE BELOW DESCRIBES BEHAVIOUR THAT NO LONGER EXISTS, AND BOTH HALVES CHANGED UNDER IT
# (corrected 2026-09-13).** It said skill-lint *dies* on an unguarded
# `readdirSync` and that a CRASH then falls through to the same print block as real findings.
# Neither is true now: skill-lint REFUSES with a named sentence at rc=2,
# and `.githooks/pre-commit` gives rc=2 its own branch that says INSTRUMENT FAILURE and withholds the
# promote-to-block line, rather than printing it as findings.
# **THE FIXTURE REQUIREMENT SURVIVES BOTH CHANGES, WHICH IS WHY THIS IS A REWRITE AND NOT A DELETION:**
# without the directory the arm exercises the REFUSAL path instead of the trigger it is testing, so it
# measures the wrong thing — quietly, since the arm still passes. The original measurement stands as
# the reason anyone noticed. Measured 2026-09-13: an arm built without that directory
# printed 28 lines of crash output and was reported as "the trigger fires"; the
# POSITIVE control read 0 lines and is what exposed it.
# The positive and BOTH negatives stage BYTE-IDENTICAL debris at three paths, so neither negative can
# be vacuous — the same content fires from the top level and is silent nested and dotted, which is
# what pins the `[^/.]` and `[^/]*` clauses of the hook's own pattern rather than the pattern's text.
_pcm_env() { env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY "$@"; }
_pcm_git() { _pcm_env git -C "$pcm_fx" -c init.defaultBranch=main -c user.email=smoke@local -c user.name=smoke "$@"; }
pcm_fx="$(cd "$(mktemp -d)" && pwd -P)"
pcm_real="$(cd "$REPO_ROOT" && pwd -P)"
pcm_own=0
pcm_pos="fixture refused (not a fresh empty dir outside REPO_ROOT)"
pcm_nest="$pcm_pos"
pcm_dot="$pcm_pos"
if [ -n "$pcm_fx" ] && [ -d "$pcm_fx" ] && [ -z "$(ls -A "$pcm_fx")" ] && [ "${pcm_fx#"$pcm_real"}" = "$pcm_fx" ]; then
  pcm_own=1
  pcm_pos="fixture refused (its git dir did not resolve inside the fixture)"
  pcm_nest="$pcm_pos"
  pcm_dot="$pcm_pos"
  mkdir -p "$pcm_fx/.claude/project-memory/sub" "$pcm_fx/.claude/skills" "$pcm_fx/.githooks" "$pcm_fx/scripts"
  cp "$REPO_ROOT/.githooks/pre-commit" "$pcm_fx/.githooks/"
  cp "$REPO_ROOT/scripts/skill-lint.mjs" "$pcm_fx/scripts/"
  if _pcm_git init -q && [ "$(_pcm_git rev-parse --absolute-git-dir)" = "$pcm_fx/.git" ]; then
    printf 'seed\n' > "$pcm_fx/seed.txt"
    _pcm_git add seed.txt && _pcm_git commit -q -m seed
    # One line ending in a harness closer at a line edge — what lintMemoryEnvelopes() flags.
    pcm_debris='A sentence the recovery pasted in.</result>'

    # POSITIVE — top-level, non-hidden .md. The trigger must REACH the lint, the echo must NAME the
    # file, the linter must report a finding, and nothing may have crashed to get there.
    printf '%s\n' "$pcm_debris" > "$pcm_fx/.claude/project-memory/probe.md"
    _pcm_git add .claude/project-memory/probe.md
    pcm_out="$(cd "$pcm_fx" && _pcm_env bash .githooks/pre-commit 2>&1)"
    pcm_rc=$?
    pcm_tot="$(printf '%s\n' "$pcm_out" | sed -n 's/^ *Total findings: *\([0-9][0-9]*\).*/\1/p' | tail -1)"
    # The fixture has no .claude/agents, no .claude/docs/architecture.md and no scripts/architecture-counts.mjs,
    # so three corpus-level units cannot look and say so (skill-lint.mjs header § THE UNSCANNED CONVENTION,
    # 2026-09-14): total = 1 debris finding + 3 markers, and the summary's `Unscanned units:` line carries the 3.
    # Pinning both numbers keeps the arm honest in both directions — a marker that stopped reaching the
    # hook's output, or a new unit marking on a bare tree, each move one of them.
    pcm_uns="$(printf '%s\n' "$pcm_out" | sed -n 's/^ *Unscanned units: *\([0-9][0-9]*\).*/\1/p' | tail -1)"
    pcm_pos="rc=$pcm_rc named=$(printf '%s\n' "$pcm_out" | grep -c -F 'Staged project-memory files: .claude/project-memory/probe.md') findings=${pcm_tot:-none} unscanned=${pcm_uns:-none} crash=$(printf '%s\n' "$pcm_out" | grep -c -F 'ENOENT')"

    # NEGATIVE 1 — the SAME bytes one directory down. `[^/]*` must exclude it.
    _pcm_git reset -q
    printf '%s\n' "$pcm_debris" > "$pcm_fx/.claude/project-memory/sub/probe.md"
    _pcm_git add .claude/project-memory/sub/probe.md
    pcm_out="$(cd "$pcm_fx" && _pcm_env bash .githooks/pre-commit 2>&1)"
    pcm_nest="rc=$? lines=$(printf '%s' "$pcm_out" | grep -c '')"

    # NEGATIVE 2 — the SAME bytes in a dotfile at the top level. `[^/.]` must exclude it.
    _pcm_git reset -q
    printf '%s\n' "$pcm_debris" > "$pcm_fx/.claude/project-memory/.probe.md"
    _pcm_git add -f .claude/project-memory/.probe.md
    pcm_out="$(cd "$pcm_fx" && _pcm_env bash .githooks/pre-commit 2>&1)"
    pcm_dot="rc=$? lines=$(printf '%s' "$pcm_out" | grep -c '')"
  fi
fi
assert_eq "pre-commit project-memory trigger: a top-level .md REACHES the lint — the echo names the staged file, the linter reports its one debris finding plus the three UNSCANNED markers a bare fixture earns (no agents roster, no architecture.md, no counts script), and nothing crashed on the way (a crash reaches the same print block, so crash=0 is what makes this arm mean anything)" \
  "rc=0 named=1 findings=4 unscanned=3 crash=0" "$pcm_pos"
assert_eq "pre-commit project-memory trigger: the SAME debris bytes one directory down are SILENT — pins the pattern's [^/]* clause, and cannot be vacuous because the arm above fires on this exact content" \
  "rc=0 lines=0" "$pcm_nest"
assert_eq "pre-commit project-memory trigger: the SAME debris bytes in a top-level DOTFILE are SILENT — pins the pattern's [^/.] clause" \
  "rc=0 lines=0" "$pcm_dot"
[ "$pcm_own" = 1 ] && rm -rf "$pcm_fx"

echo ""
echo "=== run ledger + gate-file observe (2026-10-09) ==="
# Every guard that states a promotion bar appends ONE row per in-scope run, CLEAN runs
# included, to <stem>-fires.jsonl through lib/fires-log.sh — the denominator a "5 clean pushes" bar is counted over.
# One arm per newly-logging guard: ONE run, ONE row, the outcome its fixture decides. Every run is pinned to a fresh
# HOOK_FIRES_LOG_DIR (or, for expand-before-code, its redirected log's dir), so no arm reaches the real ledger.
# And a SUB-AGENT write to a gate file is LOGGED by the always-loaded guard, never denied.
_rlg_rows() {  # <fires-dir> <stem> -> "rows=N outcome=X" off the LAST row; a missing log reads rows=0 outcome=none
  python3 -c 'import json, os, sys
p = os.path.join(sys.argv[1], sys.argv[2] + "-fires.jsonl")
rows = [json.loads(l) for l in open(p, encoding="utf-8") if l.strip()] if os.path.exists(p) else []
print("rows=%d outcome=%s" % (len(rows), rows[-1].get("outcome", "none") if rows else "none"))' "$1" "$2"
}
_rlg_cmd() {   # <stem> <command ...> -> the _rlg_rows verdict of ONE run of the command (stdin closed) into a fresh dir
  local stem="$1" d; shift
  d=$(_hfl_fresh_root); [ -n "$d" ] || { printf 'fixture refused'; return 0; }
  env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY HOOK_FIRES_LOG_DIR="$d" "$@" </dev/null >/dev/null 2>&1
  _rlg_rows "$d" "$stem"; rm -rf "$d"
}
_rlg_run() {   # <stem> <hook> <payload> [NAME=value ...] -> the _rlg_rows verdict of ONE payload run into a fresh dir
  local stem="$1" hook="$2" payload="$3" d; shift 3
  d=$(_hfl_fresh_root); [ -n "$d" ] || { printf 'fixture refused'; return 0; }
  printf '%s' "$payload" | env HOOK_FIRES_LOG_DIR="$d" "$@" bash "$hook" >/dev/null 2>&1
  _rlg_rows "$d" "$stem"; rm -rf "$d"
}
_rlg_git() { env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY git -C "$1" "${@:2}"; }
assert_eq "delegate-code-review-warn: a review dispatch with a live peer appends ONE found row" "rows=1 outcome=found" \
  "$(_rlg_run delegate-code-review-warn .claude/hooks/delegate-code-review-warn.sh '{"session_id":"rlg","tool_input":{"prompt":"code review of the diff","subagent_type":"x"}}' DELEGATE_REVIEW_FAKE_HUB=0 DELEGATE_REVIEW_FAKE_PEERS=1)"
assert_eq "pre-workflow-agenttype-warn: a lens-typed agent() script appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_run pre-workflow-agenttype-warn .claude/hooks/pre-workflow-agenttype-warn.sh '{"session_id":"rlg","tool_input":{"script":"agent(\"a\", {agentType: \"qa-expert\"})"}}')"
assert_eq "commit-pathspec-warn: a one-file commit appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_run commit-pathspec-warn .claude/hooks/commit-pathspec-warn.sh '{"session_id":"rlg","tool_input":{"command":"git commit -m x"}}' COMMIT_PATHSPEC_WARN_FAKE_STAGED_COUNT=1)"
assert_eq "commit-review-warn: a src commit with an unpushed set appends ONE found row" "rows=1 outcome=found" \
  "$(_rlg_run commit-review-warn .claude/hooks/commit-review-warn.sh '{"session_id":"rlg","tool_input":{"command":"git commit -m x"}}' COMMIT_REVIEW_WARN_TEST_SRC=1)"
assert_eq "grep-blowup-warn: a benign grep-family command appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_run grep-blowup-warn .claude/hooks/grep-blowup-warn.sh '{"session_id":"rlg","tool_input":{"command":"rg foo src/"}}' GREP_BLOWUP_NO_LOG=0)"
assert_eq "bash-safety-warn: a benign command appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_run bash-safety-warn .claude/hooks/bash-safety-warn.sh '{"session_id":"rlg","tool_input":{"command":"ls -la"}}' BASH_SAFETY_NO_LOG=0)"
# THE OTHER OUTCOME (a review lens found it): an arm that pins ONE outcome passes a hook that hard-wires it.
# Measured: `outcome clean` hard-wired in bash-safety-warn, grep-blowup-warn and scan-secrets-writes each
# left this section 139/0. One FOUND run per hook pins the predicate's other branch (scan-secrets' is beside its clean arm).
# A found run also writes each hook's OWN warn log (bash-safety-fires / grep-blowup-fires, under $CLAUDE_PROJECT_DIR, not
# HOOK_FIRES_LOG_DIR), so CLAUDE_PROJECT_DIR points at a throwaway root: those logs are calibration instruments.
_rlg_cpd=$(_hfl_fresh_root); _rlg_cpd=${_rlg_cpd:-/nonexistent/rlg}
assert_eq "bash-safety-warn: a warned command (git add -A) appends ONE found row" "rows=1 outcome=found" \
  "$(_rlg_run bash-safety-warn .claude/hooks/bash-safety-warn.sh '{"session_id":"rlg","tool_input":{"command":"git add -A"}}' BASH_SAFETY_NO_LOG=0 CLAUDE_PROJECT_DIR="$_rlg_cpd")"
_rlg_p=$(python3 -c 'import json,sys; print(json.dumps({"session_id":"rlg","tool_input":{"command":sys.argv[1]}}))' "grep -oE '.{0,120}(five|branch).{0,120}' f")
assert_eq "grep-blowup-warn: a blocked backtracking shape appends ONE found row" "rows=1 outcome=found" \
  "$(_rlg_run grep-blowup-warn .claude/hooks/grep-blowup-warn.sh "$_rlg_p" GREP_BLOWUP_NO_LOG=0 CLAUDE_PROJECT_DIR="$_rlg_cpd")"
rm -rf "$_rlg_cpd"; unset _rlg_cpd
# Fixture dirs fall back to a path that cannot exist rather than branching on the fixture variable (the assert lint reads a
# branch on a variable an assertion also reads as self-grading); a refused fixture then reads rows=0 and REDs. Payloads that
# interpolate a path are built OUTSIDE the $(...) — bash 3.2 brace-expands an escaped-quote JSON nested inside "$(...)".
_rlgfx=$(_hfl_fresh_root); _rlgfx=${_rlgfx:-/nonexistent/rlg}; printf '## 2026-06-10 heading one\nbody\n' > "$_rlgfx/rlg-MEMORY.md" 2>/dev/null
_rlg_p="{\"session_id\":\"rlg\",\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$_rlgfx/rlg-MEMORY.md\",\"old_string\":\"body\",\"new_string\":\"body2\"}}"
assert_eq "dup-durable-append-warn: an in-place Edit of a durable file appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_run dup-durable-append-warn .claude/hooks/dup-durable-append-warn.sh "$_rlg_p")"
printf 'export const a = 1;\n' > "$_rlgfx/rlg.ts" 2>/dev/null
_rlg_p="{\"session_id\":\"rlg\",\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$_rlgfx/rlg.ts\"}}"
assert_eq "scan-secrets-writes: one SCANNED clean write appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_run scan-secrets-writes .claude/hooks/scan-secrets-writes.sh "$_rlg_p")"
printf '%s\n' 'const k = "sk-''ant-api03-AbCdEfGhIjKlMnOpQrStUvWxYz0123456789abcdefgh";' > "$_rlgfx/rlgs.ts" 2>/dev/null
_rlg_p="{\"session_id\":\"rlg\",\"tool_name\":\"Write\",\"tool_input\":{\"file_path\":\"$_rlgfx/rlgs.ts\"}}"
assert_eq "scan-secrets-writes: one SCANNED write carrying a key appends ONE found row" "rows=1 outcome=found" \
  "$(_rlg_run scan-secrets-writes .claude/hooks/scan-secrets-writes.sh "$_rlg_p")"
rm -rf "$_rlgfx"
_rlgfx=$(_hfl_fresh_root); _rlgfx=${_rlgfx:-/nonexistent/rlg}
printf 'x = 1\n' > "$_rlgfx/a.txt" 2>/dev/null; _rlg_git "$_rlgfx" init -q >/dev/null 2>&1; _rlg_git "$_rlgfx" add a.txt >/dev/null 2>&1
assert_eq "validate-no-secrets: one run over a clean staged file appends ONE clean row" "rows=1 outcome=clean" \
  "$(cd "$_rlgfx" 2>/dev/null && _rlg_cmd validate-no-secrets bash "$REPO_ROOT/.claude/hooks/validate-no-secrets.sh")"
rm -rf "$_rlgfx"
assert_eq "migration-commit-msg-warn: one run over a migration-free range appends ONE clean row" "rows=1 outcome=clean" \
  "$(_rlg_cmd migration-commit-msg-warn bash .claude/hooks/migration-commit-msg-warn.sh HEAD)"
_rlgfx=$(_hfl_fresh_root); _rlgfx=${_rlgfx:-/nonexistent/rlg}
mkdir -p "$_rlgfx/src/actions" "$_rlgfx/.claude/hooks/lib" 2>/dev/null; cp .claude/hooks/lib/fires-log.sh "$_rlgfx/.claude/hooks/lib/" 2>/dev/null
printf '"use server";\nexport async function a() { await getAuthUserId(); }\n' > "$_rlgfx/src/actions/a.ts" 2>/dev/null; _rlg_git "$_rlgfx" init -q >/dev/null 2>&1
assert_eq "check-auth-actions: one run over an authed actions dir appends ONE clean row" "rows=1 outcome=clean" \
  "$(cd "$_rlgfx" 2>/dev/null && _rlg_cmd check-auth-actions bash "$REPO_ROOT/scripts/check-auth-actions.sh")"
rm -rf "$_rlgfx"
_rlgfx=$(_hfl_fresh_root); _rlgfx=${_rlgfx:-/nonexistent/rlg}
EXPAND_BEFORE_CODE_LOG="$_rlgfx/fires.jsonl" bash .claude/hooks/expand-before-code-warn.sh HEAD </dev/null >/dev/null 2>&1
assert_eq "expand-before-code-warn: one run appends ONE clean row BESIDE its redirected findings log" "rows=1 outcome=clean" \
  "$(_rlg_rows "$_rlgfx" expand-before-code-warn)"
rm -rf "$_rlgfx"
# The two in-hook pre-push gates, run as the hook's OWN text (its helper line + each block through its fire line).
_rlgfx=$(_hfl_fresh_root); _rlgfx=${_rlgfx:-/nonexistent/rlg}
mkdir -p "$_rlgfx/.claude/hooks/lib" "$_rlgfx/src" 2>/dev/null; cp .claude/hooks/lib/fires-log.sh "$_rlgfx/.claude/hooks/lib/" 2>/dev/null; _rlg_git "$_rlgfx" init -q >/dev/null 2>&1
{ echo 'set -euo pipefail'; echo 'BASE_REF=HEAD'; grep -E '^_pp_run_fire\(\) ' .githooks/pre-push; sed -n -e '/^STAGED_SOURCE_GREP_TEST=/,/^_pp_run_fire source-grep-test-warn/p' -e '/^TODO_COUNT=/,/^_pp_run_fire todo-inventory-warn/p' .githooks/pre-push; } > "$_rlgfx/pp.sh" 2>/dev/null
( cd "$_rlgfx" 2>/dev/null && env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE HOOK_FIRES_LOG_DIR="$_rlgfx/l" /bin/bash pp.sh </dev/null >/dev/null 2>&1 )
assert_eq "pre-push source-grep warn: one run appends ONE clean row" "rows=1 outcome=clean" "$(_rlg_rows "$_rlgfx/l" source-grep-test-warn)"
assert_eq "pre-push TODO-inventory warn: one run appends ONE clean row" "rows=1 outcome=clean" "$(_rlg_rows "$_rlgfx/l" todo-inventory-warn)"
rm -rf "$_rlgfx"
# block-subagent-always-loaded-write.sh — a SUB-AGENT Edit of a hook file is OBSERVED (one row, empty stdout); the
# same Edit from the orchestrator (no agent_id) writes nothing, so the arm cannot pass on a log-everything mutation.
_rlgfx=$(_hfl_fresh_root)
_rlg_out=$(printf '%s' '{"session_id":"rlg","agent_id":"rlg-agent","tool_name":"Edit","tool_input":{"file_path":".claude/hooks/x.sh","old_string":"a","new_string":"b"}}' \
  | env HOOK_FIRES_LOG_DIR="${_rlgfx:-/nonexistent}" bash .claude/hooks/block-subagent-always-loaded-write.sh 2>/dev/null); _rlg_rc=$?
assert_eq "subagent gate-file write: a SUB-AGENT Edit of .claude/hooks/x.sh is OBSERVED, never denied — empty stdout, ONE row in its own log" \
  "rc=0 stdout-bytes=0 rows=1" "rc=$_rlg_rc stdout-bytes=${#_rlg_out} $(_rlg_rows "${_rlgfx:-/nonexistent}" subagent-gate-file-write | cut -d' ' -f1)"
assert_eq "subagent gate-file write: the ORCHESTRATOR's same Edit (no agent_id) writes NO row (negative control)" "rows=0 outcome=none" \
  "$(_rlg_run subagent-gate-file-write .claude/hooks/block-subagent-always-loaded-write.sh '{"session_id":"rlg","tool_name":"Edit","tool_input":{"file_path":".claude/hooks/x.sh","old_string":"a","new_string":"b"}}')"
rm -rf "$_rlgfx"; unset _rlgfx _rlg_out _rlg_rc
# The gate keys on the agent_id KEY, like every refuse site in the hook: an EMPTY value is still a sub-agent.
_rlgfx=$(_hfl_fresh_root)
printf '%s' '{"session_id":"rlg","agent_id":"","tool_name":"Edit","tool_input":{"file_path":".claude/hooks/x.sh","old_string":"a","new_string":"b"}}' \
  | env HOOK_FIRES_LOG_DIR="${_rlgfx:-/nonexistent}" bash .claude/hooks/block-subagent-always-loaded-write.sh >/dev/null 2>&1
assert_eq "subagent gate-file write: an EMPTY agent_id is still OBSERVED (key presence, never the value) — ONE row" "rows=1" "$(_rlg_rows "${_rlgfx:-/nonexistent}" subagent-gate-file-write | cut -d' ' -f1)"
rm -rf "$_rlgfx"
# bash 3.2 (/bin/bash here): with set -e AND set -u live, an unbound-variable abort reaches an EXIT trap with $?=0 and
# the shell exits 0, so a crash would read as a CLEAN row and, in pre-commit, let the commit through. Each trap site
# classifies the abort by BASH_COMMAND and exits 1. Run as each file's OWN _w1_fire text; a bash 4+ box passes either way.
for _rlgf in .claude/hooks/commit-pathspec-warn.sh .claude/hooks/commit-review-warn.sh .claude/hooks/delegate-code-review-warn.sh .claude/hooks/pre-workflow-agenttype-warn.sh .githooks/pre-commit; do
  _rlgfx=$(_hfl_fresh_root); _rlgfx=${_rlgfx:-/nonexistent/rlg}
  for _rlge in 'exit 0' ': "$RLG_UNSET_PROBE"; exit 0'; do
    { echo 'set -euo pipefail'; echo "REPO_ROOT='$_rlgfx'"; sed -n '/_w1_fire() {/,/trap _w1_fire EXIT$/p' "$_rlgf"; echo "$_rlge"; } > "$_rlgfx/t.sh" 2>/dev/null
    ( cd "$_rlgfx" 2>/dev/null && HOOK_FIRES_LOG_DIR="$_rlgfx/l" /bin/bash t.sh </dev/null >/dev/null 2>&1 ); printf 'rc=%s ' "$?"
  done > "$_rlgfx/rc" 2>/dev/null
  assert_eq "$_rlgf: a clean exit stays 0; an unbound-variable abort after the trap exits 1, never 0" "rc=0 rc=1 " "$(cat "$_rlgfx/rc" 2>/dev/null)"
  rm -rf "$_rlgfx"
done; unset _rlgf _rlge _rlgfx

echo ""
echo "=== .githooks/pre-commit count-line branches (a count-parse fix + its review fold) ==="
# WHY this block exists: a fix closed two silent-clean paths in the hook's count parse, and its
# review found that NONE of the new states was in this gate — so a future edit that re-narrows the sed
# or un-guards the branch order would ship GREEN. The project-memory block above runs the REAL
# skill-lint, which can only ever produce whatever state the current tree happens to be in. This block
# swaps in a STUB linter that emits each state on demand, so every branch is driven through the REAL,
# unmodified hook end-to-end — the reviewer's technique, not an extracted region of the hook.
# ⛔ THE STUB SETS process.exitCode AND RETURNS; IT NEVER CALLS process.exit(). On macOS a pipe is an
# ASYNC stdout in Node, and exit() straight after console.log can drop the write — which would turn the
# reworded state into an EMPTY capture and make that arm exercise the CLEAN branch while still passing.
# ⛔ NEVER KEY A VERDICT ON AN UNANCHORED grep -F 'Total findings:'. The hook's UNPARSED diagnostic used
# to quote that string, so an unanchored needle matched text meaning the opposite.
# The needle= field pins that the diagnostic no longer does.
# States, and why each is here:
#   clean      rc=0  count 0           -> silent early exit                      unchanged path
#   findings   rc=0  count 14          -> findings block + promotion sentence    unchanged path
#   crash      rc=1  no count          -> INSTRUMENT FAILURE                     the fix
#   refusal    rc=2  no count          -> INSTRUMENT FAILURE                     the fix
#   reworded   rc=0  unparseable line  -> COUNT LINE UNPARSED                    the fix, repair 2
#   indented   rc=0  leading space     -> findings block                         the fix, repair 1
#   exitcount  rc=1  count 14          -> findings block, promotion WITHHELD,    the cell the review
#                                         and the exit named                      found unclaimed
# The crash/refusal pair is what catches a branch-ORDER regression: un-guard the UNPARSED check and both
# move onto it. Every SKIP_* the hook reads is unset, so an exported bypass cannot make this vacuous.
# ⛔ stub= PROVES THE STUB RAN. The hook echoes the linter's output on every branch except the clean
# early exit, so a path-resolution failure (node cannot find the stub) lands on INSTRUMENT FAILURE,
# which is exactly what crash and refusal expect. Measured before this field existed: a hook pointed at
# a linter path that does not exist PASSED both of those arms and failed the other five, so each arm
# alone could have been testing path resolution rather than a crash.
# clean carries stub=0 by design: its CLEAN verdict already requires the stub's zero count to parse.
# ⚠️ The fixture copies the WORKING-TREE hook, not the blob at HEAD, so a green from this block is a
# statement about the tree in front of you: a peer's uncommitted edit to the hook is silently under
# test. Never quote a local 7/0 as a claim about a commit.
_pcs_env() { env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY -u SKIP_SKILL_LINT -u SKIP_ROUTER_STALENESS_CHECK "$@"; }
_pcs_git() { _pcs_env git -C "$pcs_fx" -c init.defaultBranch=main -c user.email=smoke@local -c user.name=smoke "$@"; }
pcs_fx="$(cd "$(mktemp -d)" && pwd -P)"
pcs_real="$(cd "$REPO_ROOT" && pwd -P)"
pcs_own=0
pcs_ready=0
if [ -n "$pcs_fx" ] && [ -d "$pcs_fx" ] && [ -z "$(ls -A "$pcs_fx")" ] && [ "${pcs_fx#"$pcs_real"}" = "$pcs_fx" ]; then
  pcs_own=1
  mkdir -p "$pcs_fx/.claude/project-memory" "$pcs_fx/.githooks" "$pcs_fx/scripts"
  cp "$REPO_ROOT/.githooks/pre-commit" "$pcs_fx/.githooks/"
  cat > "$pcs_fx/scripts/skill-lint.mjs" <<'PCSSTUB'
const state = process.env.PCS_STATE ?? "";
let out = "";
let rc = 0;
switch (state) {
  case "clean":     out = "Total findings:   0"; rc = 0; break;
  case "findings":  out = "MEMORY_ENVELOPE_DEBRIS probe.md\nTotal findings:   14"; rc = 0; break;
  case "crash":     out = "TypeError: boom\n    at lint (skill-lint.mjs:1:1)"; rc = 1; break;
  case "refusal":   out = "skill-lint: cannot read skills root (ENOENT)"; rc = 2; break;
  case "reworded":  out = "Findings total: 14"; rc = 0; break;
  case "indented":  out = "  Total findings:   14"; rc = 0; break;
  case "exitcount": out = "MEMORY_ENVELOPE_DEBRIS probe.md\nTotal findings:   14"; rc = 1; break;
  default:          out = "PCS_STUB_UNKNOWN_STATE " + state; rc = 9;
}
console.log("pcs-stub-ran " + state + "\n" + out);
process.exitCode = rc;
PCSSTUB
  if _pcs_git init -q && [ "$(_pcs_git rev-parse --absolute-git-dir)" = "$pcs_fx/.git" ]; then
    printf 'seed\n' > "$pcs_fx/seed.txt"
    _pcs_git add seed.txt && _pcs_git commit -q -m seed
    printf 'probe\n' > "$pcs_fx/.claude/project-memory/probe.md"
    _pcs_git add .claude/project-memory/probe.md
    pcs_ready=1
  fi
fi
pcs_read() {
  # one stub state -> "rc=N VERDICT promo=N exited=N needle=N stub=N"
  local st out rc v
  st="$1"
  if [ "$pcs_ready" != 1 ]; then printf 'fixture not ready'; return; fi
  out="$(cd "$pcs_fx" && _pcs_env PCS_STATE="$st" bash .githooks/pre-commit 2>&1)"
  rc=$?
  if   printf '%s\n' "$out" | grep -qF 'PCS_STUB_UNKNOWN_STATE'; then v="STUB-UNKNOWN"
  elif printf '%s\n' "$out" | grep -qF 'INSTRUMENT FAILURE';     then v="INSTRUMENT"
  elif printf '%s\n' "$out" | grep -qF 'COUNT LINE UNPARSED';    then v="UNPARSED"
  elif printf '%s\n' "$out" | grep -qF 'findings on staged';     then v="FINDINGS"
  elif [ -z "$(printf '%s' "$out" | tr -d '[:space:]')" ];       then v="CLEAN"
  else v="UNCLASSIFIED"; fi
  printf 'rc=%s %s promo=%s exited=%s needle=%s stub=%s' "$rc" "$v" \
    "$(printf '%s\n' "$out" | grep -cF 'Promote to BLOCK-MODE')" \
    "$(printf '%s\n' "$out" | grep -cF 'EXITED ')" \
    "$(printf '%s\n' "$out" | grep -cF 'Total findings:')" \
    "$(printf '%s\n' "$out" | grep -cF "pcs-stub-ran $st")"
}
assert_eq "pre-commit count-line: CLEAN (rc=0, count 0) exits silently and banks nothing" \
  "rc=0 CLEAN promo=0 exited=0 needle=0 stub=0" "$(pcs_read clean)"
assert_eq "pre-commit count-line: FINDINGS (rc=0, count 14) prints the findings block and the promotion sentence" \
  "rc=0 FINDINGS promo=1 exited=0 needle=1 stub=1" "$(pcs_read findings)"
assert_eq "pre-commit count-line: CRASH (rc=1, no count) lands on INSTRUMENT FAILURE, not UNPARSED — catches an un-guarded branch order" \
  "rc=0 INSTRUMENT promo=0 exited=0 needle=0 stub=1" "$(pcs_read crash)"
assert_eq "pre-commit count-line: REFUSAL (rc=2, no count) lands on INSTRUMENT FAILURE, not UNPARSED" \
  "rc=0 INSTRUMENT promo=0 exited=0 needle=0 stub=1" "$(pcs_read refusal)"
assert_eq "pre-commit count-line: a REWORDED summary line is reported UNPARSED, never silent-clean, and the diagnostic does not quote the parse needle" \
  "rc=0 UNPARSED promo=0 exited=0 needle=0 stub=1" "$(pcs_read reworded)"
assert_eq "pre-commit count-line: an INDENTED summary line still parses and reaches the findings block" \
  "rc=0 FINDINGS promo=1 exited=0 needle=1 stub=1" "$(pcs_read indented)"
assert_eq "pre-commit count-line: a NON-ZERO exit WITH a count prints findings, names the exit, and withholds the promotion sentence" \
  "rc=0 FINDINGS promo=0 exited=1 needle=1 stub=1" "$(pcs_read exitcount)"
# Run ledger (2026-10-09): ONE clean skill-lint run appends ONE clean row. The lib is copied in only
# here, so every arm above ran with no lib and wrote nothing.
[ "$pcs_ready" = 1 ] && mkdir -p "$pcs_fx/.claude/hooks/lib" && cp "$REPO_ROOT/.claude/hooks/lib/fires-log.sh" "$pcs_fx/.claude/hooks/lib/"
_rlgpc=$(_hfl_fresh_root); HOOK_FIRES_LOG_DIR="${_rlgpc:-/nonexistent}" pcs_read clean >/dev/null
assert_eq "pre-commit skill-lint: one CLEAN run appends ONE clean row" "rows=1 outcome=clean" "$(_rlg_rows "${_rlgpc:-/nonexistent}" pre-commit-skill-lint)"
rm -rf "$_rlgpc"; unset _rlgpc
[ "$pcs_own" = 1 ] && rm -rf "$pcs_fx"

echo ""
echo "=== .githooks/pre-commit tsc gate (2026-09-18) ==="
# WHY this block exists: the gate is a .githooks arm, invisible to the hook-completeness gates (they anchor on
# .claude/hooks/*.sh), so these arms are its only liveness coverage. It runs the whole-project tsc, so every
# arm drives the REAL, unmodified hook inside a throwaway git repo whose tsconfig covers ONE planted file —
# the run costs well under a second and cannot touch the live tree. Two instruments make the arms
# non-vacuous: (1) `node_modules/.bin/tsc` in the fixture is a WRAPPER that records each invocation before
# exec'ing the real compiler, so "tsc did not run" (the tests/-only and skip arms) and "tsc ran and was
# clean" (the clean arm, which the hook keeps silent by house style) are both MEASURED rather than inferred
# from silence; (2) the FIRE arm's fixture is re-run under a MUTATED hook whose tsc call is replaced by `:`,
# and the banner must vanish — the reachability proof session-cadence.md § A NEW GUARD NO ARM CAN REACH
# demands, kept permanent so a later edit that makes the fire arm pass without running tsc reddens here.
# ⛔ The planted error is asserted by its OWN code (TS2322), never the bare `error TS` pair: a run that
# aborts on CONFIG prints `error TS5xxx` and would satisfy the pair with the planted error never typed
# (bash-environment.md, the TS5112 control trap).
# ⛔ Every hook call unsets HOOK_FIRES_LOG_DIR (the suite exports it globally, top of file) and pins
# CLAUDE_PROJECT_DIR to the fixture, so the ONE record the fire arm asserts lands in the fixture's own
# .claude/logs and never in the real calibration ledger — fires-log.sh § WHERE RECORDS GO.
# ⚠️ The fixture copies the WORKING-TREE hook, not the blob at HEAD (same caveat as the count-line block).
_tg_env() { env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY -u HOOK_FIRES_LOG_DIR -u SKIP_TSC_GATE -u SKIP_SKILL_LINT -u SKIP_ROUTER_STALENESS_CHECK CLAUDE_PROJECT_DIR="$tg_fx" "$@"; }
_tg_git() { _tg_env git -C "$tg_fx" -c init.defaultBranch=main -c user.email=smoke@local -c user.name=smoke "$@"; }
tg_fx="$(cd "$(mktemp -d)" && pwd -P)"
tg_real="$(cd "$REPO_ROOT" && pwd -P)"
tg_own=0
tg_ready=0
tg_refused="fixture refused (not a fresh empty dir outside REPO_ROOT, its git dir did not resolve inside it, or REPO_ROOT/node_modules/.bin/tsc is not executable)"
tg_fire="$tg_refused"; tg_rec="$tg_refused"; tg_clean="$tg_refused"; tg_tests="$tg_refused"; tg_skip="$tg_refused"
tg_disk="$tg_refused"; tg_missing="$tg_refused"; tg_mut="$tg_refused"
tg_bad='const n: number = "planted";
export {};'
tg_good='const n: number = 1;
export {};'
if [ -n "$tg_fx" ] && [ -d "$tg_fx" ] && [ -z "$(ls -A "$tg_fx")" ] && [ "${tg_fx#"$tg_real"}" = "$tg_fx" ] && [ -x "$tg_real/node_modules/.bin/tsc" ]; then
  tg_own=1
  mkdir -p "$tg_fx/.githooks" "$tg_fx/.claude/hooks/lib" "$tg_fx/node_modules/.bin" "$tg_fx/plans" "$tg_fx/tests"
  cp "$REPO_ROOT/.githooks/pre-commit" "$tg_fx/.githooks/"
  cp "$REPO_ROOT/.claude/hooks/lib/fires-log.sh" "$tg_fx/.claude/hooks/lib/"
  # Minimal project: strict, one include set, tests/ excluded exactly as the real tsconfig excludes it,
  # types:[] so nothing under the real node_modules/@types is pulled in.
  printf '%s\n' '{ "compilerOptions": { "target": "ES2020", "lib": ["es2020"], "strict": true, "noEmit": true, "module": "esnext", "moduleResolution": "bundler", "skipLibCheck": true, "incremental": true, "types": [] }, "include": ["**/*.ts", "**/*.mts"], "exclude": ["node_modules", "tests"] }' > "$tg_fx/tsconfig.json"
  # The invocation-counting wrapper. Absolute paths baked in: the hook cd's to its own toplevel.
  printf '#!/usr/bin/env bash\nprintf "ran\\n" >> "%s/tsc-invocations.txt"\nexec "%s/node_modules/.bin/tsc" "$@"\n' "$tg_fx" "$tg_real" > "$tg_fx/node_modules/.bin/tsc"
  chmod +x "$tg_fx/node_modules/.bin/tsc"
  if _tg_git init -q && [ "$(_tg_git rev-parse --absolute-git-dir)" = "$tg_fx/.git" ]; then
    printf 'seed\n' > "$tg_fx/seed.txt"
    _tg_git add seed.txt tsconfig.json && _tg_git commit -q -m seed
    tg_ready=1
  fi
fi
tg_read() {
  # run the hook (optionally under a different hook path / an env prefix) -> "rc=N banner=N ts2322=N skip=N missing=N inst=N tsc=N log=N"
  # $1 = hook path relative to the fixture; remaining args = env assignments for the call (NAME=value)
  local hook="$1" out rc; shift
  [ "$tg_ready" = 1 ] || { printf '%s' "$tg_refused"; return; }
  rm -f "$tg_fx/.claude/logs/tsc-gate-fires.jsonl"
  : > "$tg_fx/tsc-invocations.txt"
  out="$(cd "$tg_fx" && _tg_env "$@" bash "$hook" 2>&1)"
  rc=$?
  # The caller runs this in $(...), so a variable set here never reaches it — persist the output on disk.
  printf '%s\n' "$out" > "$tg_fx/last-out.txt"
  printf 'rc=%s banner=%s ts2322=%s skip=%s missing=%s inst=%s tsc=%s log=%s' "$rc" \
    "$(printf '%s\n' "$out" | grep -cF "reds any push gate that runs this check")" \
    "$(printf '%s\n' "$out" | grep -cF 'TS2322')" \
    "$(printf '%s\n' "$out" | grep -cF 'tsc gate SKIPPED')" \
    "$(printf '%s\n' "$out" | grep -cF 'NOTHING was typechecked')" \
    "$(printf '%s\n' "$out" | grep -cF 'INSTRUMENT FAILURE')" \
    "$(grep -c '' "$tg_fx/tsc-invocations.txt")" \
    "$( [ -f "$tg_fx/.claude/logs/tsc-gate-fires.jsonl" ] && grep -c '' "$tg_fx/.claude/logs/tsc-gate-fires.jsonl" || printf 0 )"
}
if [ "$tg_ready" = 1 ]; then
  # (a) FIRE — a planted TS2322 in plans/probe.mts, staged. Banner, the error's own code, one invocation,
  #     one record whose three keys carry the trigger file, the count and the first error line.
  _tg_git reset -q
  printf '%s\n' "$tg_bad" > "$tg_fx/plans/probe.mts"
  _tg_git add plans/probe.mts
  tg_fire="$(tg_read .githooks/pre-commit)"
  if [ -f "$tg_fx/.claude/logs/tsc-gate-fires.jsonl" ]; then
    tg_rec="staged=$(grep -cF '"staged":"plans/probe.mts"' "$tg_fx/.claude/logs/tsc-gate-fires.jsonl") errors=$(grep -cF '"errors":"1"' "$tg_fx/.claude/logs/tsc-gate-fires.jsonl") first=$(grep -cF '"first":"plans/probe.mts(1,7): error TS2322' "$tg_fx/.claude/logs/tsc-gate-fires.jsonl")"
  else
    tg_rec="no record written"
  fi
  # (b) CLEAN — the same path without the error. Silent by house style, so the wrapper's count is what
  #     proves the gate reached tsc (tsc=1) and the ledger's absence proves it banked nothing.
  _tg_git reset -q
  printf '%s\n' "$tg_good" > "$tg_fx/plans/probe.mts"
  _tg_git add plans/probe.mts
  tg_clean="$(tg_read .githooks/pre-commit)"
  # (c) tests/ ONLY — the SAME planted bytes under tests/, and nothing else staged. tsc must not run at
  #     all (tsc=0); cannot be vacuous because (a) fires on these exact bytes one directory over.
  _tg_git reset -q
  rm -f "$tg_fx/plans/probe.mts"
  printf '%s\n' "$tg_bad" > "$tg_fx/tests/probe.test.mts"
  _tg_git add tests/probe.test.mts
  tg_tests="$(tg_read .githooks/pre-commit)"
  # (d) ESCAPE — SKIP_TSC_GATE=1 with the erroring plans file staged: the skip line names the file, tsc
  #     does not run, nothing is recorded. (A script gate reads the inline env; not a harness hook.)
  _tg_git reset -q
  rm -f "$tg_fx/tests/probe.test.mts"
  printf '%s\n' "$tg_bad" > "$tg_fx/plans/probe.mts"
  _tg_git add plans/probe.mts
  tg_skip="$(tg_read .githooks/pre-commit SKIP_TSC_GATE=1) names=$(grep -F 'tsc gate SKIPPED' "$tg_fx/last-out.txt" | grep -cF 'plans/probe.mts')"
  # (e) WORKTREE READ — the error is STAGED but the disk copy is already clean. tsc runs (tsc=1) and is
  #     silent: the hook's header claims it types the worktree, not the index, and this is that claim's arm.
  _tg_git reset -q
  printf '%s\n' "$tg_bad" > "$tg_fx/plans/probe.mts"
  _tg_git add plans/probe.mts
  printf '%s\n' "$tg_good" > "$tg_fx/plans/probe.mts"
  tg_disk="$(tg_read .githooks/pre-commit)"
  # (f) MISSING TOOLCHAIN — the wrapper made non-executable with the erroring file staged and on disk:
  #     a LOUD skip line, no invocation, no record — never a silent pass.
  _tg_git reset -q
  printf '%s\n' "$tg_bad" > "$tg_fx/plans/probe.mts"
  _tg_git add plans/probe.mts
  chmod -x "$tg_fx/node_modules/.bin/tsc"
  tg_missing="$(tg_read .githooks/pre-commit)"
  chmod +x "$tg_fx/node_modules/.bin/tsc"
  # (g) MUTATION — the hook with its tsc invocation replaced by `:`, on the FIRE fixture. The banner must
  #     vanish and nothing may be recorded; landed=1 proves the sed reached the line it names.
  sed 's|^\([[:space:]]*\)env FORCE_COLOR=0 node_modules/\.bin/tsc .*$|\1: tsc-gate-mutated|' "$tg_fx/.githooks/pre-commit" > "$tg_fx/.githooks/pre-commit.mutated"
  tg_mut="$(tg_read .githooks/pre-commit.mutated) landed=$(grep -cF ': tsc-gate-mutated' "$tg_fx/.githooks/pre-commit.mutated")"
fi
assert_eq "pre-commit tsc gate FIRE: a staged plans/*.mts with a planted TS2322 prints the banner and the error's own code, runs tsc once, exits 0, and records ONE fire" \
  "rc=0 banner=1 ts2322=1 skip=0 missing=0 inst=0 tsc=1 log=1" "$tg_fire"
assert_eq "pre-commit tsc gate FIRE: the record carries the trigger file, the error count and the first error line" \
  "staged=1 errors=1 first=1" "$tg_rec"
assert_eq "pre-commit tsc gate CLEAN: the same file without the error runs tsc once (the wrapper count, since a clean run is silent) and records nothing" \
  "rc=0 banner=0 ts2322=0 skip=0 missing=0 inst=0 tsc=1 log=0" "$tg_clean"
assert_eq "pre-commit tsc gate tests/-ONLY: the same planted bytes under tests/ never reach tsc (tsc=0) — non-vacuous because the FIRE arm fires on these bytes one directory over" \
  "rc=0 banner=0 ts2322=0 skip=0 missing=0 inst=0 tsc=0 log=0" "$tg_tests"
assert_eq "pre-commit tsc gate ESCAPE: SKIP_TSC_GATE=1 prints the skip line naming the file, runs no tsc, records nothing" \
  "rc=0 banner=0 ts2322=0 skip=1 missing=0 inst=0 tsc=0 log=0 names=1" "$tg_skip"
assert_eq "pre-commit tsc gate WORKTREE READ: a staged error whose disk copy is clean runs tsc and is silent — the header's own limitation, measured rather than asserted" \
  "rc=0 banner=0 ts2322=0 skip=0 missing=0 inst=0 tsc=1 log=0" "$tg_disk"
assert_eq "pre-commit tsc gate MISSING TOOLCHAIN: a non-executable node_modules/.bin/tsc is a LOUD skip (never a silent pass), no invocation, no record" \
  "rc=0 banner=0 ts2322=0 skip=0 missing=1 inst=0 tsc=0 log=0" "$tg_missing"
assert_eq "pre-commit tsc gate MUTATION: with the tsc call replaced by ':' the FIRE fixture goes silent and records nothing — the fire arm's green depends on the call" \
  "rc=0 banner=0 ts2322=0 skip=0 missing=0 inst=0 tsc=0 log=0 landed=1" "$tg_mut"
[ "$tg_own" = 1 ] && rm -rf "$tg_fx"

echo ""
echo "=== additionalContext cap net (2026-08-26 — the harness caps one payload at 10,000 CHARS) ==="
# An over-cap additionalContext SPILLS to a session file and delivers only a ~2 KB preview — the
# failure that killed the commit-row keyed-reflex pilot (24 KB tier, ~5% delivered, reverted).
# Net for the surviving DYNAMIC emitters: band-o-inject chunks at EMIT_CLAMP_ABOVE and
# trigger-index-match clamps at 9,500. Presence/value asserts here; the runtime detector for the
# other emitters is the persisted spill file itself, which names the offending hook in its first line.
ACN_CLAMP=$(grep -oE '^EMIT_CLAMP_ABOVE *= *[0-9]+' .claude/hooks/band-o-inject.sh | head -1 | grep -oE '[0-9]+$')
ACN_TO=$(grep -oE '^EMIT_CLAMP_TO *= *[0-9]+' .claude/hooks/band-o-inject.sh | head -1 | grep -oE '[0-9]+$')
# Both scrapes anchored at column 0 AND counted (2026-09-07):
# the TO scrape was unanchored with `head -1`, so a COMMENT quoting `EMIT_CLAMP_TO = 1` above
# the assignment (the shape band-o-inject.sh already carries for ABOVE) would have passed a cap breach;
# and `head -1` over a doubled assignment reads whichever comes first. A count of exactly 1 per constant
# is what makes the value read below the real one.
# MIRROR BLINDNESS: the payload is PYTHON and column 0 is module
# scope, so exactly-once asserts "one MODULE-SCOPE binding, and it is the one read" — every conditional
# override is indented, so no legitimate shape is blocked, and the blindness is the inverse: an INDENTED
# rebinding reads N=1 and passes while the live clamp differs. The BEHAVIOUR arm below is the reading an
# indented rebinding would have to get past, since it runs the hook's own clamp stage parsed live.
ACN_N_ABOVE=$(grep -cE '^EMIT_CLAMP_ABOVE *= *[0-9]+' .claude/hooks/band-o-inject.sh); ACN_N_TO=$(grep -cE '^EMIT_CLAMP_TO *= *[0-9]+' .claude/hooks/band-o-inject.sh)
if [ "$ACN_N_ABOVE" = "1" ] && [ "$ACN_N_TO" = "1" ] && [ -n "$ACN_CLAMP" ] && [ "$ACN_CLAMP" -le 9800 ] && [ -n "$ACN_TO" ] && [ "$ACN_TO" -le 9700 ]; then
  pass "band-o-inject EMIT_CLAMP_ABOVE=$ACN_CLAMP <= 9800, EMIT_CLAMP_TO=$ACN_TO <= 9700, each assigned exactly once at column 0 (chunks clear the 10,000-char cap)"
else
  fail "band-o-inject clamp constants missing, over cap, or not assigned exactly once at column 0 (ABOVE=${ACN_CLAMP:-none} x${ACN_N_ABOVE} TO=${ACN_TO:-none} x${ACN_N_TO})"
fi
# BEHAVIOUR arm: a presence-grep passes with the clamp
# commented out or inverted while the notice string survives — the pilot's own failure shape.
# So run the hook's OWN clamp stage, parsed LIVE from the file (a gutted clamp changes the
# extracted code and REDs), against a 12,000-char payload.
TIMC_FIX="$(mktemp)"; python3 -c 'print("x" * 12000)' > "$TIMC_FIX"
TIMC_OUT="$(python3 - "$TIMC_FIX" <<'TIMCPY'
import io, re, subprocess, sys
hook = io.open(".claude/hooks/trigger-index-match.sh", encoding="utf8").read()
m = re.search(r"python3 -c '(import json,sys\n.*?)' \"\$_TIM_PAYLOAD\"", hook, re.S)
out = subprocess.run(["python3", "-c", m.group(1), sys.argv[1]], capture_output=True, text=True) if m else None
sys.stdout.write(out.stdout if out else "")
TIMCPY
)"
TIMC_LEN="$(printf '%s' "$TIMC_OUT" | python3 -c 'import json,sys; print(len(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"]))' 2>/dev/null)"
if [ -n "$TIMC_LEN" ] && [ "$TIMC_LEN" -le 9600 ] && printf '%s' "$TIMC_OUT" | grep -q 'payload clamped at 9,500 chars'; then
  pass "trigger-index-match clamp BEHAVES: 12,000-char payload -> $TIMC_LEN chars + notice (live-parsed stage)"
else
  fail "trigger-index-match clamp behaviour: len=${TIMC_LEN:-unparseable} or notice missing"
fi
rm -f "$TIMC_FIX"

echo ""
echo "=== agent-memory-brief-warn.sh (dispatch-plane memory-read nudge, 2026-08-26) ==="
# Inject-only PreToolUse(Agent): a brief lacking the read-first token for a MEMORY.md-owning
# subagent_type -> additionalContext nudge; per-thread TTL dampener; fires ledger (synthetic
# arms stamp themselves via AMBW_SMOKE=1 — the agent-dispatch-memory-guard fixture lesson).
AMBW_TP="/tmp/smoke-ambw-$$.jsonl"
AMBW_MARKER=".claude/state/agent-memory-brief-smoke-ambw-$$-qa-expert.mark"   # the hook keys its marker on <transcript stem>-<agent>; a stem-only name here matched no cleanup and left ONE orphan per run since 2026-08-26 (245 in .claude/state at the fix)
out=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"audit the flows"},"transcript_path":"%s"}' "$AMBW_TP" | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec=$?
assert_eq "agent-memory-brief FIRE (no line, owns MEMORY) → exit 0" "0" "$ec"
if printf '%s' "$out" | grep -q "AGENT-MEMORY BRIEF NUDGE"; then
  pass "agent-memory-brief FIRE → nudge emitted"
else
  fail "agent-memory-brief FIRE → no nudge emitted"
fi
# PARSE arm — its OWN thread key, because the FIRE above armed the TTL dampener for that
# thread+type and a re-run on the same transcript_path would capture SILENCE (EMPTY verdict),
# which reads as a broken emitter rather than a working dampener.
AMBW_PARSE_TP="/tmp/smoke-ambw-parse-$$.jsonl"
sout=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"audit the flows"},"transcript_path":"%s"}' "$AMBW_PARSE_TP" | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null)
assert_one_json_doc "PARSE: agent-memory-brief-warn.sh nudge arm → ONE parseable hookSpecificOutput doc, the agent's own MEMORY.md path survives" "$sout" '.claude/skills/qa-expert/MEMORY.md'
rm -f ".claude/state/agent-memory-brief-smoke-ambw-parse-$$-qa-expert.mark"
out2=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"second dispatch same wave"},"transcript_path":"%s"}' "$AMBW_TP" | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec2=$?
assert_eq "agent-memory-brief DAMPENER same-thread → exit 0" "0" "$ec2"
assert_empty "agent-memory-brief DAMPENER same-thread → suppressed" "$out2"
rm -f "$AMBW_MARKER"
out3=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"Read your .claude/skills/qa-expert/MEMORY.md first, then audit"},"transcript_path":"/tmp/smoke-ambw-safe-$$.jsonl"}' | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec3=$?
assert_eq "agent-memory-brief SAFE (line present) → exit 0" "0" "$ec3"
assert_empty "agent-memory-brief SAFE (line present) → silent" "$out3"
out4=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"general-purpose","prompt":"do a thing"},"transcript_path":"/tmp/smoke-ambw-nomem-$$.jsonl"}' | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec4=$?
assert_eq "agent-memory-brief SAFE (type owns no MEMORY.md) → exit 0" "0" "$ec4"
assert_empty "agent-memory-brief SAFE (no MEMORY.md) → silent" "$out4"
out5=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"audit"},"transcript_path":"/tmp/smoke-ambw-skip-$$.jsonl"}' | SKIP_AGENT_MEMORY_BRIEF_WARN=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec5=$?
assert_eq "agent-memory-brief SKIP escape → exit 0" "0" "$ec5"
assert_empty "agent-memory-brief SKIP escape → silent" "$out5"
# RED CONTROLS for the PATH predicate (the phrase key once nudged a compliant
# backtick-form brief). The key is the agent's OWN family path in any spelling.
out6=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"Read `.claude/skills/qa-expert/MEMORY.md` first, then audit"},"transcript_path":"/tmp/smoke-ambw-bt-$$.jsonl"}' | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec6=$?
assert_eq "agent-memory-brief SAFE (backtick-quoted path) → exit 0" "0" "$ec6"
assert_empty "agent-memory-brief SAFE (backtick-quoted path) → silent — the live false-fire class" "$out6"
AMBW_WRONG_TP="/tmp/smoke-ambw-wrong-$$.jsonl"   # expanded — a literal $$ here left a marker no cleanup matched, TTL-damping the NEXT run (caught 2026-08-26, consecutive-run red)
out7=$(printf '{"tool_name":"Agent","tool_input":{"subagent_type":"qa-expert","prompt":"Read .claude/skills/uncle-bob/MEMORY.md first"},"transcript_path":"%s"}' "$AMBW_WRONG_TP" | AMBW_SMOKE=1 bash .claude/hooks/agent-memory-brief-warn.sh 2>/dev/null); ec7=$?
assert_eq "agent-memory-brief FIRE (names ANOTHER type's path) → exit 0" "0" "$ec7"
if printf '%s' "$out7" | grep -q "AGENT-MEMORY BRIEF NUDGE"; then
  pass "agent-memory-brief FIRE (another type's path) → nudges — key is type-specific"
else
  fail "agent-memory-brief FIRE (another type's path) → silent — predicate is not type-specific"
fi
rm -f "$AMBW_MARKER" ".claude/state/agent-memory-brief-smoke-ambw-wrong-$$-qa-expert.mark"
# LEDGER: every memory-owning dispatch logs haspath + fired (the paired keep/kill key needs both).
if tail -3 .claude/logs/agent-memory-brief-fires.jsonl 2>/dev/null | grep -q '"haspath":1,"fired":0' && tail -3 .claude/logs/agent-memory-brief-fires.jsonl | grep -q '"haspath":0,"fired":1'; then
  pass "agent-memory-brief ledger carries haspath+fired for both arms"
else
  fail "agent-memory-brief ledger missing haspath/fired fields (got: $(tail -2 .claude/logs/agent-memory-brief-fires.jsonl 2>/dev/null | tr '\n' ' '))"
fi

echo ""
echo "=== .claude/rules/active-recall.md structural ==="
if [[ ! -f .claude/rules/active-recall.md ]]; then
  fail ".claude/rules/active-recall.md missing — always-loaded enforcement layer gone"
else
  pass "active-recall.md exists"
  if grep -q "^## Hot Tier" .claude/rules/active-recall.md; then
    pass "active-recall.md has Hot Tier section"
  else
    fail "active-recall.md missing Hot Tier section — file structure changed"
  fi
  # Sanity check row density (Hot Tier should have ≥10 data rows — table rows after the separator)
  hot_tier_rows=$(awk '/^## Hot Tier/{f=1; next} /^## /{f=0} f && /^\|/{n++; if ($0 ~ /^\|[-| :]+\|$/) sep=n} END{print n-sep+0}' .claude/rules/active-recall.md)
  if [[ "$hot_tier_rows" -ge 10 ]]; then
    pass "active-recall.md Hot Tier has $hot_tier_rows rows (≥10 threshold)"
  else
    fail "active-recall.md Hot Tier only $hot_tier_rows rows — may have been silently trimmed"
  fi
fi

echo ""
echo "=== .claude/skills/sniff-test/SKILL.md structural ==="
if [[ ! -f .claude/skills/sniff-test/SKILL.md ]]; then
  fail ".claude/skills/sniff-test/SKILL.md missing — auto-fired audit layer gone"
else
  pass "sniff-test SKILL.md exists"
  if grep -q "^## Trigger conditions" .claude/skills/sniff-test/SKILL.md; then
    pass "sniff-test has Trigger conditions section"
  else
    fail "sniff-test missing Trigger conditions section — auto-fire logic at risk"
  fi
  if grep -q "^## The 15-check rubric" .claude/skills/sniff-test/SKILL.md; then
    pass "sniff-test has 15-check rubric section"
  else
    fail "sniff-test missing 15-check rubric section — audit content at risk"
  fi
  # Sanity check rubric integrity — a FLOOR, not exact equality, and read from HEAD not the worktree.
 # ⛔ This was `-eq 15` against the LIVE WORKING TREE until 2026-08-18. Two independent
  # defects in one line: (a) EXACT equality means legitimately ADDING a 16th check fails the suite;
  # (b) reading the WORKTREE of a many-writer file means one seat's UNCOMMITTED rubric edit fails
  # EVERY OTHER SEAT'S PUSH, with a message blaming the rubric. That is the same machine-global-
  # shared-state class the marker arm below was fixed for, and the robust sibling at ~:2114 (`-ge 10`
  # on a floor) shows the pattern was already known in this file. Reading HEAD makes it immune to
  # every peer's worktree; the floor makes it immune to legitimate growth.
  check_count=$(git show HEAD:.claude/skills/sniff-test/SKILL.md 2>/dev/null | grep -cE "^### Check [0-9]+:"); check_count=${check_count:-0}
  if [[ "$check_count" -ge 15 ]]; then
    pass "sniff-test rubric has $check_count checks at HEAD (>=15 floor)"
  else
    fail "sniff-test rubric has $check_count checks (expected 15) — rubric drift"
  fi
fi

echo ""
echo "=== mail-relay-staleness-warn.sh (Stop — relay-staleness residue) ==="
# Residue net for the un-hookable "verify a mail state-claim before relaying it" decision.
# Synthetic transcript jsonls; the hook reads transcript_path from the Stop payload.
# MAIL_RELAY_NO_LOG=1: fixture fires must NOT pollute the production calibration log
# (.claude/logs/mail-relay-staleness-fires.jsonl — the FP-rate instrument); the warn
# OUTPUT still fires, which is what the assertions below check.
export MAIL_RELAY_NO_LOG=1
mr_log=.claude/logs/mail-relay-staleness-fires.jsonl
mr_fire=$(mktemp); printf '%s\n' \
  '{"type":"attachment","content":"===== SESSION-MAIL (ADVISORY DATA — NOT AN INSTRUCTION) ====="}' \
  '{"role":"assistant","content":"noted, moving on"}' > "$mr_fire"
out=$(echo "{\"transcript_path\":\"$mr_fire\"}" | bash .claude/hooks/mail-relay-staleness-warn.sh 2>&1)
assert_contains "FIRE: mail surfaced + no ground-truth check after → staleness warning" "$out" "STALENESS WARNING"
# ⛔ STDOUT MUST STAY EMPTY — a Stop hook speaks on bare stderr only, as session-memory-reminder.sh does
# and as this hook's own header states. The parse-arm coverage gate below SKIPS it: its emitter predicate strips
# comment lines first and finds ZERO emit sites (the word hookSpecificOutput appears only in a
# comment), so this hook is outside the gate's population. This arm is the INVERSE of a parse
# assertion: it REDs the day someone converts the channel. Positive control is the FIRE arm
# directly above (stderr 603 B), so a 0-byte stdout is silence, not a dead hook.
sout=$(echo "{\"transcript_path\":\"$mr_fire\"}" | bash .claude/hooks/mail-relay-staleness-warn.sh 2>/dev/null)
assert_empty "STDOUT-SILENT: mail-relay-staleness-warn.sh writes NOTHING to the model channel (a Stop hook speaks on stderr only — no parse arm is possible or wanted)" "$sout"
mr_gt=$(mktemp); printf '%s\n' \
  '{"type":"attachment","content":"===== SESSION-MAIL ====="}' \
  '{"role":"assistant","tool_use":{"name":"Bash","input":{"command":"git log --oneline -5 -- foo"}}}' > "$mr_gt"
out=$(echo "{\"transcript_path\":\"$mr_gt\"}" | bash .claude/hooks/mail-relay-staleness-warn.sh 2>&1)
mrg=$(printf '%s' "$out" | grep -c "STALENESS WARNING" || true)
assert_eq "SAFE: ground-truth check (git log) after surface → silent" "0" "$mrg"
mr_none=$(mktemp); printf '%s\n' '{"role":"assistant","content":"no mail this session"}' > "$mr_none"
out=$(echo "{\"transcript_path\":\"$mr_none\"}" | bash .claude/hooks/mail-relay-staleness-warn.sh 2>&1)
mrn=$(printf '%s' "$out" | grep -c "STALENESS WARNING" || true)
assert_eq "SAFE: no mail surfaced → silent" "0" "$mrn"
out=$(SKIP_MAIL_RELAY_CHECK=1 bash -c "echo '{\"transcript_path\":\"$mr_fire\"}' | bash .claude/hooks/mail-relay-staleness-warn.sh" 2>&1)
mre=$(printf '%s' "$out" | grep -c "STALENESS WARNING" || true)
assert_eq "SAFE: SKIP_MAIL_RELAY_CHECK=1 escape-hatch → silent" "0" "$mre"
# per-surface reset: surface → git-log → ANOTHER surface (no GT after the 2nd) must FIRE (gt_after resets per surface; verification of the 1st surface must not leak to the 2nd)
mr_reset=$(mktemp); printf '%s\n' \
  '{"type":"attachment","content":"===== SESSION-MAIL ====="}' \
  '{"role":"assistant","tool_use":{"name":"Bash","input":{"command":"git log --oneline -3"}}}' \
  '{"type":"attachment","content":"===== SESSION-MAIL ====="}' \
  '{"role":"assistant","content":"relayed without re-checking"}' > "$mr_reset"
out=$(echo "{\"transcript_path\":\"$mr_reset\"}" | bash .claude/hooks/mail-relay-staleness-warn.sh 2>&1)
assert_contains "FIRE: 2nd surface with no GT after it → warns (gt_after resets per surface, no leak across the 1st verify)" "$out" "STALENESS WARNING"
# Count only rows naming THIS run's fixture transcripts (each row records its transcript path, and every
# fixture is a fresh mktemp path), never the file's whole line count: the log is fleet-shared, so a
# before/after delta also counted any peer's live fire during the gate and refused a dev push on
# 2026-10-06 (expected 4822, actual 4823). A fixture row is the leak; a peer row cannot match.
mr_own=$(grep -c -F -e "$mr_fire" -e "$mr_gt" -e "$mr_none" -e "$mr_reset" "$mr_log" 2>/dev/null || true); mr_own=${mr_own:-0}
assert_eq "MAIL_RELAY_NO_LOG=1: fixture fires did NOT append to the production calibration log" "0" "$mr_own"
# SEAM COVERAGE — every fixture above is 54-270 B against a 1 MB read chunk, so NONE of them can
# reach the second iteration of the backward-scan loop. Measured: a seam-only mutant (carry
# discarded instead of prepended) PASSED 4/4 of the arms above while going quiet on a transcript
# whose lines straddle a chunk boundary — a silent detection failure. Re-running the SAME fixtures
# at a 7-byte chunk forces every line across a seam and kills that mutant 6/10, at zero repo weight.
# The path is live: 60 transcript lines on this box exceed 1 MB, longest 1,887,330 B.
for mr_f in "$mr_fire" "$mr_reset"; do
  out=$(echo "{\"transcript_path\":\"$mr_f\"}" | MAIL_RELAY_CHUNK=7 bash .claude/hooks/mail-relay-staleness-warn.sh 2>&1)
  # Label carries the fixture's ROLE, never its mktemp name: a random name in a label reads as a VANISHED
  # label to the mutation matrix's un-mutated re-run control and falsely flagged the suite FLAKY (2026-08-26).
  _mr_role=$([ "$mr_f" = "$mr_fire" ] && echo fire || echo reset)
  assert_contains "FIRE at MAIL_RELAY_CHUNK=7 (lines straddle chunk seams): the ${_mr_role} fixture still warns" "$out" "STALENESS WARNING"
done
out=$(echo "{\"transcript_path\":\"$mr_gt\"}" | MAIL_RELAY_CHUNK=7 bash .claude/hooks/mail-relay-staleness-warn.sh 2>&1)
mrc=$(printf '%s' "$out" | grep -c "STALENESS WARNING" || true)
assert_eq "SAFE at MAIL_RELAY_CHUNK=7: ground-truth check after surface → still silent" "0" "$mrc"
unset MAIL_RELAY_NO_LOG
rm -f "$mr_fire" "$mr_gt" "$mr_none" "$mr_reset"

# FIRE-ONCE-PER-**SURFACE** — the dedupe key, which no static fixture can pin. `surface_offset` was
# `surface_line` until 2026-08-24; a mutant pinning the key to a constant degrades the contract to
# fire-once-per-TRANSCRIPT and is killed by NOTHING above (verified: 4/4 arms pass under it). It
# dies only to this 4-turn sequence, where turn 4 is a SECOND surface at a NEW offset. Needs the
# calibration log live (that IS the dedupe store), so it runs in an isolated git repo — the log path
# is derived from `git rev-parse --show-toplevel`, so the production log is untouched by construction.
mr_hook="$PWD/.claude/hooks/mail-relay-staleness-warn.sh"
mr_d=$(mktemp -d); ( cd "$mr_d" && git init -q . && mkdir -p .claude/logs )
mr_t="$mr_d/tr.jsonl"
printf '%s\n' '{"type":"attachment","content":"===== SESSION-MAIL ====="}' \
              '{"role":"assistant","content":"noted"}' > "$mr_t"
mr_v() { local e; e=$(cd "$mr_d" && echo "{\"transcript_path\":\"$mr_t\"}" | bash "$mr_hook" 2>&1 >/dev/null)
         printf '%s' "$e" | grep -q 'STALENESS WARNING' && printf WARN || printf QUIET; }
assert_eq "FIRE-ONCE 1/4: surface A, no ground truth after → warns" "WARN" "$(mr_v)"
assert_eq "FIRE-ONCE 2/4: same surface, unchanged → deduped silent" "QUIET" "$(mr_v)"
printf '%s\n' '{"role":"assistant","tool_use":{"name":"Bash","input":{"command":"git log --oneline -3"}}}' >> "$mr_t"
assert_eq "FIRE-ONCE 3/4: ground-truth check lands after surface A → silent" "QUIET" "$(mr_v)"
printf '%s\n' '{"type":"attachment","content":"===== SESSION-MAIL ====="}' \
              '{"role":"assistant","content":"relayed"}' >> "$mr_t"
assert_eq "FIRE-ONCE 4/4: surface B at a NEW offset, no GT after → MUST warn (per-SURFACE, not per-transcript)" "WARN" "$(mr_v)"
rm -rf "$mr_d"

echo ""
echo "=== settings.json integrity ==="
# Valid JSON
if jq empty .claude/settings.json 2>/dev/null; then
  pass "settings.json parses as JSON"
else
  fail "settings.json is malformed JSON"
fi

# Every referenced hook script exists + executable
missing_hooks=0
while IFS= read -r cmd; do
  [[ -z "$cmd" ]] && continue
  # Extract script path — 'bash "${CLAUDE_PROJECT_DIR:-.}/path/x.sh"' → path/x.sh
  # strip quotes + expand the project-dir placeholder; suite runs from repo root.
  # .py too: keep-warm-gate.py is wired as `python3 ".../x.py"`, and a .sh-only pattern read it
  # as an empty path and failed "hook script missing: " on every run.
  script=$(echo "$cmd" | grep -oE '\.claude/hooks/[A-Za-z0-9._-]+\.(sh|py)' | head -1)
  if [[ -z "$script" ]]; then
    fail "hook command names no .claude/hooks/*.sh or *.py script: $cmd"
    missing_hooks=$((missing_hooks+1))
  elif [[ ! -f "$script" ]]; then
    fail "hook script missing: $script"
    missing_hooks=$((missing_hooks+1))
  elif [[ ! -x "$script" ]]; then
    fail "hook script not executable: $script"
    missing_hooks=$((missing_hooks+1))
  fi
done < <(jq -r '.hooks | to_entries[].value[] | .hooks[]? | select(.type == "command") | .command' .claude/settings.json 2>/dev/null)
[[ $missing_hooks -eq 0 ]] && pass "all referenced hook scripts exist + executable"

# Cwd-independence. A bare `cd` in any Bash tool call moves the session cwd, and hooks
# INHERIT it; a relative hook command then dies exit 127, SILENTLY disabling the enforce layer,
# security guards included.
cwd_dep=0
while IFS= read -r cmd; do
  [[ -z "$cmd" ]] && continue
  # anchored := references the project-dir placeholder, or passes an absolute path
  if [[ "$cmd" == *'${CLAUDE_PROJECT_DIR'* || "$cmd" == *' /'* ]]; then
    :
  else
    fail "hook command is cwd-dependent (dies after any 'cd'): $cmd"; cwd_dep=$((cwd_dep+1))
  fi
done < <(jq -r '.hooks | to_entries[].value[] | .hooks[]? | select(.type == "command") | .command' .claude/settings.json 2>/dev/null)
[[ $cwd_dep -eq 0 ]] && pass "all hook commands are cwd-independent"

# Second order — a hook whose COMMAND is anchored can still write/read a SHADOW tree if its
# INTERNAL paths are cwd-relative. Fossil found 2026-07-10: .claude/hooks/.claude/logs/... , and
# post-compact-pending-check.sh silently found no marker when the session cwd was a subdirectory.
unanchored_paths=0
for hf in .claude/hooks/*.sh; do
  if grep -qE '(=|:-)"?(\.claude/(logs|state)|plans/)' "$hf"; then
    fail "hook uses an unanchored .claude/{logs,state} or plans/ path (shadow tree when cwd is a subdir): $(basename "$hf")"
    unanchored_paths=$((unanchored_paths+1))
  fi
done
[[ $unanchored_paths -eq 0 ]] && pass "no hook uses an unanchored .claude/{logs,state} or plans/ path"

# Third order (2026-08-26). An ANCHORED-looking
# `${CLAUDE_PROJECT_DIR:-$(pwd)}` is the same shadow tree one rung down: CLAUDE_PROJECT_DIR is UNSET in
# live sessions, so the fallback IS the live path and a bare $(pwd) resolves to whatever
# cwd the session launched from — the guard above was green over exactly that recurrence in plans/.
# Every hook takes session-start.sh:9's ladder (`git rev-parse --show-toplevel 2>/dev/null || pwd`).
# The 7-hook population was fixed in the same commit, so this ships FAIL-mode on a passing baseline.
bare_pwd=0
for hf in .claude/hooks/*.sh; do
  if grep -qF ':-$(pwd)}' "$hf"; then
    fail "hook resolves the project root with a bare \$(pwd) fallback (third order — take session-start.sh:9's ladder): $(basename "$hf")"
    bare_pwd=$((bare_pwd+1))
  fi
done
[[ $bare_pwd -eq 0 ]] && pass "no hook uses the bare \${CLAUDE_PROJECT_DIR:-\$(pwd)} fallback (third order)"

# ─────────────────────────────────────────────────────────────────────────────
# SECURITY-CONTROL WIRING PIN (disk → settings).
#
# The integrity checks ABOVE go settings → disk ("every referenced script exists + is executable +
# cwd-independent"); this block goes disk → settings. Without it, delete a security control's
# settings.json entry, or typo its matcher ("Bsh"), and the file still exists, its behavioral
# assertions still pass (they invoke it BY PATH), the coverage gate drops it from the wired-set
# (`wired=0 → continue`) — and the suite reads all-green while the control never fires.
# A hook is fail-OPEN: unwired ⇒ no deny emitted ⇒ the tool proceeds. For a SECURITY control that is a
# secret committed, or a production deploy shipped, with no signal.
#
# THE PIN: each control is pinned to its EXACT (event, matcher). A security control's wiring is a
# load-bearing invariant — changing it must be a DELIBERATE, reviewed act (update this table in the
# same commit), never a silent one. Reads settings.json LIVE (stale-proof); fails CLOSED (a missing
# or mis-matched entry ⇒ RED). Its own mutation: delete any pinned entry from settings.json → RED.
echo ""
echo "=== security-control wiring pin (disk→settings — unwiring must not stay green) ==="
# hook<TAB>event<TAB>matcher   — the matcher is a regex string in settings.json; "" = matcher-less.
SEC_WIRING="block-dangerous	PreToolUse	Bash
block-push-without-approval	PreToolUse	Bash
block-subagent-memory-write	PreToolUse	Edit|Write
block-subagent-always-loaded-write	PreToolUse	Edit|Write
block-subagent-always-loaded-write	PreToolUse	MultiEdit
validate-no-secrets	PostToolUse	Bash
scan-secrets-writes	PostToolUse	Edit|Write
hooks-integrity-check	SessionStart	"
wiring_fail=0
while IFS=$'\t' read -r whook wevent wmatcher; do
  [[ -z "$whook" ]] && continue
  # Does settings.json wire THIS hook under THIS event with THIS matcher? Ask jq — exact triple.
  present=$(jq -r --arg e "$wevent" --arg m "$wmatcher" --arg h "$whook" '
    (.hooks[$e] // [])
    | map(select((.matcher // "") == $m))
    | map(.hooks[]? | select(.type=="command") | .command)
    | map(select(test("hooks/" + $h + "\\.sh")))
    | length' .claude/settings.json 2>/dev/null)
  if [[ "$present" == "1" ]]; then
    pass "wiring pinned: $whook → $wevent/${wmatcher:-（matcher-less）}"
  else
    fail "SECURITY CONTROL UNWIRED or mis-matched: $whook expected at $wevent/${wmatcher:-（matcher-less）} — found $present (settings.json edited without updating the pin, OR the control was silently disabled)"
    wiring_fail=$((wiring_fail+1))
  fi
done <<< "$SEC_WIRING"
[[ $wiring_fail -eq 0 ]] && pass "all $(printf '%s\n' "$SEC_WIRING" | grep -c .) security controls wired to their exact event+matcher"

echo "=== pre-push SKIP_E2E_HOOK disclosure (DERIVED, not hand-maintained) ==="
# The skip message must name every SKIP_-gated check, and must do so by DERIVING
# the list from the hook's own source. A hand-written list is accurate the day it
# is written and becomes a false assurance the moment a gate is added: BAND_BUDGET
# went unnamed for weeks after shipping, and once hand-patched, EXPAND_BEFORE_CODE
# replaced it as the newest unnamed gate — 7 omissions in both states, different sets.
#
# MUTATION-VALID BY CONSTRUCTION: this arm injects a SKIP_ var that exists nowhere
# in the repo and asserts it is disclosed. A hand-written message cannot pass — it
# has no way to know a gate invented inside this test.
_ppd_out="$(SKIP_E2E_HOOK=1 bash .githooks/pre-push origin https://example.invalid </dev/null 2>&1 || true)"
for _g in $(grep -oE 'SKIP_[A-Z0-9_]+' .githooks/pre-push | sort -u | grep -vx 'SKIP_E2E_HOOK'); do
  assert_contains "skip-disclosure names $_g" "$_ppd_out" "$_g"
done
# This trap REPLACES the suite-wide EXIT trap set near the top, so it calls that cleanup too.
_ppd_tmp="$(mktemp)"; trap 'rm -f "$_ppd_tmp"; _smoke_exit_cleanup' EXIT
sed 's/^set -euo pipefail$/set -euo pipefail\n: "${SKIP_SMOKE_SYNTHETIC_GATE:=0}"/' .githooks/pre-push > "$_ppd_tmp"
_ppd_mut="$(SKIP_E2E_HOOK=1 bash "$_ppd_tmp" origin https://example.invalid </dev/null 2>&1 || true)"
assert_contains "skip-disclosure DERIVES the list (a gate invented in this test is disclosed with no message edit)" \
  "$_ppd_mut" "SKIP_SMOKE_SYNTHETIC_GATE"
# A disclosure failure must never become a push failure: unreadable source => warn, exit 0.
_ppd_bad="$(mktemp)"
sed 's|_pp_src="${BASH_SOURCE\[0\]:-$0}"|_pp_src="/nonexistent/prepush/source"|' .githooks/pre-push > "$_ppd_bad"
_ppd_badout="$(SKIP_E2E_HOOK=1 bash "$_ppd_bad" origin https://example.invalid </dev/null 2>&1; echo "rc=$?")"
rm -f "$_ppd_bad"
assert_contains "skip-disclosure degrades LOUDLY when it cannot derive" "$_ppd_badout" "assume EVERY gate is skipped"
assert_contains "skip-disclosure failure never fails the push" "$_ppd_badout" "rc=0"

echo "=== pre-push cert-freshness warn (2026-09-07) ==="
# The gate reports whether the prompt certification is stale on a push that touches the cert
# closure. prompts.md § THE CERT RUNS THE PRODUCTION ARM SET said "The cert gates the deploy"
# until 2026-09-07 (it now reads that a push touching the closure OWES a certified cert, the
# owner discharging it) and nothing on the way out read the cert: a prompt version shipped to
# production uncertified and nobody was told.
#
# ⛔ THE `certified` ARM IS THE REASON THIS SUITE ENTRY EXISTS, NOT A COMPLETENESS GESTURE.
# The first version of the gate captured its UNCERTIFIED grep unguarded under the hook's
# `set -euo pipefail`. grep returns 1 on NO MATCH — the HEALTHY reading — so the gate aborted
# the push with rc=1 exactly when the cert was clean: a warn-mode gate that blocked, on the one
# input class it was supposed to stay quiet for. It passed every other arm. The live cert is
# stale today, so that branch "cannot be produced" without a stub, which is precisely what made
# skipping it feel free (bash-environment.md § vacuous controls, TWELFTH way).
#
# The block is EXTRACTED FROM THE HOOK AT TEST TIME rather than copied, so these arms track the
# shipped source; `node` is stubbed so each verdict branch is driven directly.
_cfw_s="$(grep -n '^# ── cert freshness warn' .githooks/pre-push | cut -d: -f1)"
_cfw_e="$(awk -v s="${_cfw_s:-0}" 'NR>s && /^# memory-config-drift warn/ {print NR-2; exit}' .githooks/pre-push)"
if [[ -z "$_cfw_s" || -z "$_cfw_e" ]]; then
  fail "cert-freshness: block not found in .githooks/pre-push (WIRED arm — the gate is gone or renamed)"
else
  pass "cert-freshness: block present in .githooks/pre-push"
  # WIRED, anchored past the comment marker — a #-commented copy must not satisfy this.
  if grep -qE '^[[:space:]]*if \[\[ "\$\{SKIP_CERT_FRESHNESS_CHECK' .githooks/pre-push; then
    pass "cert-freshness: gate is live code, not a commented copy"
  else
    fail "cert-freshness: no uncommented SKIP_CERT_FRESHNESS_CHECK guard — gate is inert"
  fi
  _cfw_h="$(mktemp)"; _cfw_d="$(mktemp -d)"
  # CHANGED_FILE feeds a large payload by FILE: Linux caps ONE argv string at 131,072 B and CI
  # is ubuntu, so arm (10)'s 148,923 B argument was E2BIG there and the arm read its own RED as
 # the defect it guards. macOS has no such cap, which
  # is why it was green here.
  { echo '#!/usr/bin/env bash'; echo 'set -euo pipefail'
    echo 'if [[ -n "${CHANGED_FILE:-}" ]]; then CHANGED="$(cat "$CHANGED_FILE")"; else CHANGED="${1:-}"; fi'
    sed -n "${_cfw_s},${_cfw_e}p" .githooks/pre-push; echo 'echo "SMOKE-RC=0"'; } > "$_cfw_h"
  if bash -n "$_cfw_h" 2>/dev/null; then pass "cert-freshness: extracted block parses"; else fail "cert-freshness: extracted block does not parse"; fi

  _cfw_stub() {  # $1 = body of the --check-fresh branch
    printf '#!/bin/bash\ncase "$*" in\n  *--manifest*) printf %s ;;\n  *--check-fresh*) %s ;;\nesac\n' \
      "'combined manifest sha: d\nfiles: 1\n\ncombined closure:\n  aaaa  src/lib/ai/prompts/versions.ts\n'" "$1" > "$_cfw_d/node"
    chmod +x "$_cfw_d/node"
  }

  # (1) STALE — a closure file in the push and a leg with no PASS row.
  _cfw_stub "printf 'x ceiling: UNCERTIFIED: leg sha abc has no PASS row\n'; exit 1"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  assert_contains "cert-freshness: STALE cert warns" "$_cfw_o" "CERT FRESHNESS"
  assert_contains "cert-freshness: STALE names the offending closure file" "$_cfw_o" "src/lib/ai/prompts/versions.ts"
  assert_contains "cert-freshness: STALE never blocks the push" "$_cfw_o" "SMOKE-RC=0"

  # (2) CERTIFIED — the regression arm. Must print the clean line AND still exit 0.
  _cfw_stub "printf 'ok ceiling: CERTIFIED-CURRENT\n'; exit 0"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  assert_contains "cert-freshness: CERTIFIED prints the clean verdict" "$_cfw_o" "all GATING legs CERTIFIED-CURRENT"
  assert_contains "cert-freshness: CERTIFIED does not abort the push (the shipped-once regression)" "$_cfw_o" "SMOKE-RC=0"

  # (3) check-fresh CRASHES — non-zero with no UNCERTIFIED line is UNCHECKED, never clean.
  _cfw_stub "printf 'TypeError: boom\n' >&2; exit 7"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  assert_contains "cert-freshness: crash reads as unrecognised, not as clean" "$_cfw_o" "unrecognised output"
  assert_contains "cert-freshness: crash never blocks" "$_cfw_o" "SMOKE-RC=0"

  # (4) EMPTY CLOSURE — the manifest parser going stale must be LOUD, not a silent pass.
  printf '#!/bin/bash\nprintf "files: 0\\n"\n' > "$_cfw_d/node"; chmod +x "$_cfw_d/node"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  assert_contains "cert-freshness: empty closure says NOT RUN" "$_cfw_o" "EMPTY closure"
  assert_contains "cert-freshness: an EMPTY closure never blocks the push" "$_cfw_o" "SMOKE-RC=0"

  # (4b) STALL: a pre-push hook that HANGS is worse than one that
  # warns, and nothing bounded the two node calls. Both are wrapped in perl's alarm (there is no
  # `timeout` on this box). The harness copy sheds the bound to 1s so the arm exercises the REAL
  # branch without a 20s test; the shipped constant is asserted separately, below.
  _cfw_fast="$(mktemp)"; sed "s/alarm 20;/alarm 1;/g" "$_cfw_h" > "$_cfw_fast"
  printf '#!/bin/bash\nsleep 5\n' > "$_cfw_d/node"; chmod +x "$_cfw_d/node"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_fast" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  assert_contains "cert-freshness: a STALLED cert probe says NOT RUN" "$_cfw_o" "NOT RUN"
  assert_contains "cert-freshness: a STALLED probe names the alarm rather than reading as clean" "$_cfw_o" "142"
  assert_contains "cert-freshness: a STALLED probe never blocks the push" "$_cfw_o" "SMOKE-RC=0"
  rm -f "$_cfw_fast"
  # The bound itself is a constant, so assert it at source rather than by waiting 20s for it.
  # ⛔ COUNT, never `grep -q`. A `-q` on this literal PASSES with only ONE of the two
  # subprocesses wrapped, so it could never have detected the half-bounded state it exists
 # to catch. The literal also carries `or die`: perl's exec
  # returns rc=0 with NO output on failure, which the check-fresh site read as CLEAN.
  _cfw_bound="$(grep -cF "perl -we 'alarm 20; exec @ARGV or die" .githooks/pre-push)"
  if [[ "$_cfw_bound" -eq 2 ]]; then
    pass "cert-freshness: BOTH cert subprocesses are bounded AND fail loud in the shipped hook"
  else
    fail "cert-freshness: expected 2 bounded+loud cert subprocesses in the shipped hook, found $_cfw_bound"
  fi

  # (5) NEGATIVE — a src/ file outside the closure must produce no verdict at all.
  _cfw_stub "printf 'x ceiling: UNCERTIFIED: leg sha abc has no PASS row\n'; exit 1"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/components/ui/button.tsx' 2>&1)"
  if printf '%s' "$_cfw_o" | grep -qF 'CERT FRESHNESS'; then
    fail "cert-freshness: fired on a file outside the cert closure (over-broad trigger)"
  else
    pass "cert-freshness: silent on a src/ file outside the closure"
  fi
  assert_contains "cert-freshness: a file outside the closure never blocks the push" "$_cfw_o" "SMOKE-RC=0"

  # (6) ESCAPE — the documented bypass must actually bypass.
  _cfw_o="$(SKIP_CERT_FRESHNESS_CHECK=1 PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  if printf '%s' "$_cfw_o" | grep -qF 'CERT FRESHNESS'; then
    fail "cert-freshness: SKIP_CERT_FRESHNESS_CHECK=1 did not bypass"
  else
    pass "cert-freshness: SKIP_CERT_FRESHNESS_CHECK=1 bypasses"
  fi
  assert_contains "cert-freshness: the escape never blocks the push either" "$_cfw_o" "SMOKE-RC=0"

  # (7) ⛔ VACUOUS GREEN — a SILENT rc-0 producer must NOT read as certified. The clean
  # branch used to be the bare `else` of an emptiness test, so anything that printed
  # nothing and exited 0 produced "all legs CERTIFIED-CURRENT" — a clean verdict asserted
  # from an ABSENCE. Arms 1-6 all drive a stub that PRINTS something, so the whole suite
 # was structurally incapable of exhibiting it.
  _cfw_stub "exit 0"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  # ⛔ KEY ON THE CLEAN-VERDICT PHRASE, NOT THE BARE TOKEN. The fix's own unrecognised
  # message reads "printed no CERTIFIED-CURRENT line", so a bare `grep -F CERTIFIED-CURRENT`
  # matches the very output that PROVES the gate works — use-vs-mention, planted in the
  # corpus by the fix itself. It was caught when an arm went RED on a healthy gate.
  if printf '%s' "$_cfw_o" | grep -qF 'legs CERTIFIED-CURRENT'; then
    fail "cert-freshness: a SILENT rc-0 check-fresh read as CERTIFIED (clean verdict from an absence)"
  else
    pass "cert-freshness: a SILENT rc-0 check-fresh does NOT read as certified"
  fi
  assert_contains "cert-freshness: a silent rc-0 probe is reported as unrecognised" "$_cfw_o" "unrecognised output"
  assert_contains "cert-freshness: a silent rc-0 probe never blocks the push" "$_cfw_o" "SMOKE-RC=0"

  # (8) REPORT-ONLY — checkFresh() prints "UNCERTIFIED ... [report-only]" for a NON-GATING
  # leg and deliberately leaves rc at 0 (spatial is gating:false). Keying STALE on the
  # UNCERTIFIED grep announced a stale cert on the instrument's own clean reading.
  _cfw_stub "printf 'ok ceiling: CERTIFIED-CURRENT\n'; printf 'x spatial: UNCERTIFIED: leg sha abc has no PASS row [report-only]\n'; exit 0"
  _cfw_o="$(PATH="$_cfw_d:$PATH" bash "$_cfw_h" 'src/lib/ai/prompts/versions.ts' 2>&1)"
  if printf '%s' "$_cfw_o" | grep -qF 'CERT FRESHNESS'; then
    fail "cert-freshness: a REPORT-ONLY uncertified leg (rc 0) was announced as a STALE cert"
  else
    pass "cert-freshness: a REPORT-ONLY uncertified leg does not read as STALE"
  fi
  assert_contains "cert-freshness: report-only still reports the clean GATING verdict" "$_cfw_o" "all GATING legs CERTIFIED-CURRENT"
  assert_contains "cert-freshness: report-only leg is disclosed rather than swallowed" "$_cfw_o" "REPORT-ONLY"

  # (10) ⛔ LARGE $CHANGED — the pre-filter must still FIRE. `echo "$CHANGED" | grep -q` under
  # this hook's `set -euo pipefail` returns 141 once the path bytes AFTER the first match pass
  # ~48.9 KB (certain past ~66.4 KB — the quantity is bytes after the match, never payload size;
  # measured 2026-09-07, replacing a "~64 KB" that had a reader sizing the wrong thing),
  # because grep -q exits at the first match and echo takes SIGPIPE; the `&&` then reads FALSE
  # and the whole cert check SILENTLY SKIPS. It fails toward "no check ran", which looks exactly
  # like "nothing to check" — so every arm above, which drives a ONE-LINE $CHANGED, is blind to
  # it. Measured: 30,893 B rc=0 · 94,893 B rc=141 · 192,894 B rc=141; here-string rc=0 at all
  # three. The payload travels by FILE (CHANGED_FILE, header above) — at 148,923 B it is over
  # Linux's 131,072 B single-argument cap, and it must stay over ~66.4 KB to discriminate.
  _cfw_stub "printf 'ok ceiling: CERTIFIED-CURRENT\n'; exit 0"
  _cfw_big="src/lib/ai/prompts/versions.ts"
  for _i in $(seq 1 6000); do _cfw_big="${_cfw_big}
src/generated/pad${_i}.ts"; done
  _cfw_bigf="$(mktemp)"; printf '%s' "$_cfw_big" > "$_cfw_bigf"
  _cfw_o="$(PATH="$_cfw_d:$PATH" CHANGED_FILE="$_cfw_bigf" bash "$_cfw_h" 2>&1)"
  if printf '%s' "$_cfw_o" | grep -qF 'cert freshness'; then
    pass "cert-freshness: the pre-filter still FIRES on a ${#_cfw_big}-byte \$CHANGED fed by file (SIGPIPE from ~48.9 KB after the match)"
  else
    fail "cert-freshness: a ${#_cfw_big}-byte \$CHANGED SILENTLY SKIPPED the whole check (SIGPIPE pre-filter)"
  fi
  assert_contains "cert-freshness: a large push never blocks either" "$_cfw_o" "SMOKE-RC=0"
  rm -f "$_cfw_bigf"

  rm -rf "$_cfw_d"; rm -f "$_cfw_h"

  # (9) CONTRACT — every arm above drives a STUB whose output is hard-coded to the shape
  # the hook's awk assumes, so parser and fixture drift together: a hand-authored fixture
  # re-encoding the code's own assumption. This arm runs the REAL instrument
  # through the REAL shipped parser, extracted from the hook rather than copied, and
  # asserts the parsed count equals the instrument's own `files: N`. Costs 0.15s.
  _cfw_awk="$(grep -F '_cert_closure=' .githooks/pre-push | sed "s/.*awk '//; s/')\".*//")"
  _cfw_mf="$(node scripts/cert.mjs --manifest --verbose 2>&1)"
  _cfw_declared="$(printf '%s\n' "$_cfw_mf" | grep -m1 '^files:' | awk '{print $2}')"
  _cfw_parsed="$(printf '%s\n' "$_cfw_mf" | awk "$_cfw_awk" | grep -c '')"
  if [[ -n "$_cfw_declared" && "$_cfw_declared" -gt 0 && "$_cfw_declared" == "$_cfw_parsed" ]]; then
    pass "cert-freshness: the shipped awk parses the REAL manifest — declared $_cfw_declared == parsed $_cfw_parsed"
  else
    fail "cert-freshness: shipped awk vs REAL manifest MISMATCH — declared '$_cfw_declared', parsed '$_cfw_parsed'"
  fi
fi

echo "=== pre-deploy eslint ERROR gate disposition (scripts/lib/predeploy-lint-verdict.sh) ==="
# pre-deploy-check lints the CHANGED files and refuses on an eslint ERROR (rc 1) through this lib,
# so the deploying push reads eslint's exit code; every branch is driven here with a
# fixture log, the same shape as the l3-verdict arms below. The WIRED arm is the one that matters:
# a lib nothing sources is a guard that cannot fire (session-cadence.md § A HALTING GUARD WITH AN
# INERT TRIGGER IS WORSE THAN NO GUARD).
_pl="scripts/lib/predeploy-lint-verdict.sh"
if bash -n "$_pl" 2>/dev/null; then pass "lint-verdict: lib parses"; else fail "lint-verdict: lib does not parse (pre-deploy-check would abort at source)"; fi
if bash -n scripts/pre-deploy-check.sh 2>/dev/null; then pass "lint-verdict: pre-deploy-check.sh parses"; else fail "lint-verdict: pre-deploy-check.sh does not parse"; fi
# ⛔ THE TWO WIRING GREPS ARE ANCHORED PAST THE COMMENT MARKER, AND THAT IS THE WHOLE ARM
# (2026-09-05). They were `grep -q -F` on the literal source lines, so a `#`-commented copy of
# either line satisfied them — the use-vs-mention shape bash-environment.md codifies, on the arm the
# commit message called "the one that matters". `^[[:space:]]*` (leading whitespace only, then the
# token) is the anchor: the lines are indented inside the else-branch, so a bare `^` cannot be used.
# Proven by mutation both directions: commenting out the `source` line REDs this arm; restoring GREENs
# it. ⚠️ RESIDUAL, stated rather than claimed away: this proves the line is UNCOMMENTED, not that it is
# REACHED — wrapping step 1b in `if false; then … fi` still leaves both green. Closing that needs an
# execution arm, which cannot run here (pre-deploy-check runs tsc + the full unit suite).
# The source line moved to the guarded, script-dir form on 2026-10-05 (a design review finding).
if grep -qE '^[[:space:]]*\. "\$\(dirname "\$\{BASH_SOURCE\[0\]\}"\)/lib/predeploy-lint-verdict\.sh"' scripts/pre-deploy-check.sh; then pass "lint-verdict: pre-deploy-check sources the lib on a LIVE (uncommented) line — the gate is WIRED"; else fail "lint-verdict: pre-deploy-check does not source the lib on a live line — the gate is INERT"; fi
if grep -qE '^[[:space:]]*(el)?if lint_error_disposition "\$lint_rc"' scripts/pre-deploy-check.sh; then pass "lint-verdict: pre-deploy-check feeds eslint's OWN rc to the disposition, on a LIVE line"; else fail "lint-verdict: the disposition is not fed eslint's rc on a live line"; fi
if grep -qE "^[[:space:]]*npx eslint --no-warn-ignored \"\\\$\{lint_files\[@\]\+" scripts/pre-deploy-check.sh; then pass "lint-verdict: pre-deploy-check invokes eslint WITHOUT xargs — rc 2 reaches the disposition"; else fail "lint-verdict: eslint is invoked through xargs (BSD xargs collapses rc 2 -> 1, so the rc>=2 branch is unreachable)"; fi
if grep -qE "^[[:space:]]*lint_candidates=\"\\\$\(git ls-tree -r --name-only HEAD" scripts/pre-deploy-check.sh; then pass "lint-verdict: the no-merge-base branch FALLS BACK to every tracked file (fail-safe), it does not skip"; else fail "lint-verdict: the no-merge-base branch does not fall back — the gate is OPEN on a degenerate baseline"; fi
_pllog="$(mktemp)"
printf '%s\n' "/x/src/lib/a.ts" "  12:5  error  bare lookup  local/no-bare-object-key-lookup" > "$_pllog"
_plrun() {  # <rc> [VAR=val ...] -> output + "rc=<n>"
  local _rc="$1"; shift
  local _out; _out="$(env "$@" bash -c 'set -euo pipefail; source "$1"; lint_error_disposition "$2" "$3" 3' _ "$_pl" "$_rc" "$_pllog" 2>&1)"; local _r=$?
  printf '%s\nrc=%s\n' "$_out" "$_r"
}
_o="$(_plrun 0)"
assert_contains "lint-verdict: rc=0 → clean line names the file count" "$_o" "no errors in the 3 changed"
assert_contains "lint-verdict: rc=0 → returns 0" "$_o" "rc=0"
_o="$(_plrun 1)"
assert_contains "lint-verdict: rc=1 → prints the offending rule row" "$_o" "local/no-bare-object-key-lookup"
assert_contains "lint-verdict: rc=1 → prints the file header" "$_o" "/x/src/lib/a.ts"
assert_contains "lint-verdict: rc=1 → REFUSES (returns 1)" "$_o" "rc=1"
_o="$(_plrun 1 SKIP_LINT_ERROR_GATE=1)"
assert_contains "lint-verdict: rc=1 + SKIP_LINT_ERROR_GATE=1 → disclosed, not silent" "$_o" "NOT refusing"
assert_contains "lint-verdict: rc=1 + escape → returns 0" "$_o" "rc=0"
_o="$(_plrun 1 SKIP_LINT_RATCHET=1)"
assert_contains "lint-verdict: the pre-push RATCHET's escape does NOT reach this gate (different concern)" "$_o" "rc=1"
_o="$(_plrun 2)"
assert_contains "lint-verdict: rc=2 (eslint did not run) → REFUSES — instrument failure lands on the failing side" "$_o" "rc=1"
assert_contains "lint-verdict: rc=2 → says eslint did not run, never 'clean'" "$_o" "failed to RUN"
rm -f "$_pllog"

echo "=== pre-push Layer-3 verdict disposition (scripts/lib/prepush-l3-verdict.sh) ==="
# Extracted 2026-08-26 from the inline if/elif/else in .githooks/pre-push so every branch can be driven
# with a FIXTURE LOG; until then the secret-scanner BLOCK had no arm at all. Each arm runs the function
# under the hook's own `set -euo pipefail` in a child bash and reads the child's rc — the shape pre-push
# actually executes, so a `set -e` abort inside the function reads as a real failure here too.
_l3lib="scripts/lib/prepush-l3-verdict.sh"
if bash -n "$_l3lib" 2>/dev/null; then pass "l3-verdict: lib parses"; else fail "l3-verdict: lib does not parse (pre-push would abort at source)"; fi
_l3log="$(mktemp)"
_l3run() {  # <rc> <log content> <changed-hook basenames, newline-separated> [VAR=val ...] -> output + "rc=<n>"
  local _rc="$1" _content="$2" _hooks="$3"; shift 3
  printf '%s\n' "$_content" > "$_l3log"
  local _out; _out="$(env "$@" bash -c 'set -euo pipefail; source "$1"; l3_disposition "$2" "$3" "$4"' _ "$_l3lib" "$_rc" "$_l3log" "$_hooks" 2>&1)"; local _r=$?
  printf '%s\nrc=%s\n' "$_out" "$_r"
}
_o="$(_l3run 0 "" "agent-diff-reporter.sh")"
assert_contains "l3-verdict: rc=0 → LIVE line, push proceeds" "$_o" "every changed hook is mutation-LIVE"
assert_contains "l3-verdict: rc=0 → returns 0" "$_o" "rc=0"
# rc=3 is CAUSE-AWARE by rule: BASELINE-RED + a scanner changed BLOCKS; every other
# cause, and a log with no cause line, stays the documented fail-open.
_o="$(_l3run 3 "   ⛔ BASELINE IS NOT GREEN. Every delta below would be measured against a broken suite.
L3-CAUSE=BASELINE-RED" "validate-no-secrets.sh")"
assert_contains "l3-verdict: rc=3 (infra) → names the errored gate" "$_o" "Layer 3 gate ERRORED"
assert_contains "l3-verdict: rc=3 BASELINE-RED + a SCANNER changed → BLOCK text" "$_o" "OWN BASELINE IS RED"
assert_contains "l3-verdict: rc=3 BASELINE-RED + a SCANNER changed → returns 1 (push refused)" "$_o" "rc=1"
_o="$(_l3run 3 "⛔ scripts/smoke-mutation-matrix.sh or smoke-test-hooks.sh has UNCOMMITTED/STAGED changes.
L3-CAUSE=DIRTY-TREE" "validate-no-secrets.sh")"
assert_not_contains "l3-verdict: rc=3 DIRTY-TREE + a SCANNER changed → no BLOCK (transient cause stays fail-open)" "$_o" "OWN BASELINE IS RED"
assert_contains "l3-verdict: rc=3 DIRTY-TREE → names the cause in the WARN line" "$_o" "cause: L3-CAUSE=DIRTY-TREE"
assert_contains "l3-verdict: rc=3 DIRTY-TREE + a SCANNER changed → returns 0" "$_o" "rc=0"
_o="$(_l3run 3 "   ⛔ BASELINE IS NOT GREEN.
L3-CAUSE=BASELINE-RED" "agent-diff-reporter.sh")"
assert_not_contains "l3-verdict: rc=3 BASELINE-RED + only a GENERAL hook changed → no BLOCK (scanner subset only)" "$_o" "OWN BASELINE IS RED"
assert_contains "l3-verdict: rc=3 BASELINE-RED + general hook → returns 0" "$_o" "rc=0"
_o="$(_l3run 3 "   ⛔ BASELINE IS NOT GREEN.
L3-CAUSE=BASELINE-RED" "validate-no-secrets.sh" SKIP_HOOK_LIVENESS_GATE=1)"
assert_contains "l3-verdict: rc=3 BASELINE-RED + scanner + SKIP_HOOK_LIVENESS_GATE=1 → returns 0 (escape honoured)" "$_o" "rc=0"
_o="$(_l3run 3 "   ⛔ BASELINE IS NOT GREEN. (an older matrix: no cause line)" "validate-no-secrets.sh")"
assert_contains "l3-verdict: rc=3 with NO cause line + scanner → fail-open, and says the cause was not named" "$_o" "not named by the matrix"
assert_contains "l3-verdict: rc=3 with NO cause line → returns 0" "$_o" "rc=0"
# A FLAKY / STATE-DEPENDENT refusal names the labels that dropped, and the operator must see them: the lib
# prints only matching lines, so a `dropped: ` line it does not match
# would reach nobody.
_o="$(_l3run 3 "   ⛔ SUITE FLAKY — an un-mutated re-run dropped baseline-✓ labels; the gate verdict is untrustworthy.
      dropped: SMOKE-FIXTURE dropped label
L3-CAUSE=SUITE-FLAKY" "agent-diff-reporter.sh")"
assert_contains "l3-verdict: rc=3 SUITE-FLAKY → the dropped label reaches the operator" "$_o" "dropped: SMOKE-FIXTURE dropped label"
_m_dropped="$(grep -v '^[[:space:]]*#' scripts/smoke-mutation-matrix.sh | grep -cE '^[[:space:]]+name_dropped "\$BASE" "\$(ctrl|post)"$')"
assert_eq "l3-verdict: the matrix names dropped labels at both of its unstable-suite refusals (what it prints: --self-test-gate)" "2" "$_m_dropped"
# TOKEN COUPLING — the lib greps a token the matrix must emit; each side alone is a silent no-op.
_m_src="scripts/smoke-mutation-matrix.sh"
# command-position only: a prose "(exit 3)" inside an echo is not a site (it is there, line ~410). The
# connectives cover shapes a FUTURE author may write (`&& exit 3`, `|| exit 3`), not just today's two —
# the arm's value is the case that has not happened yet.
_m_exit3="$(grep -v '^[[:space:]]*#' "$_m_src" | grep -cE '(^|;|&&|\|\|)[[:space:]]*exit 3')"; _m_cause="$(grep -v '^[[:space:]]*#' "$_m_src" | grep -c 'L3-CAUSE=')"
if [ "${_m_exit3:-0}" -ge 1 ] && [ "$_m_exit3" = "$_m_cause" ]; then pass "l3-verdict: every matrix exit-3 site names a cause ($_m_exit3 = $_m_cause)"; else fail "l3-verdict: matrix exit-3 sites ($_m_exit3) != cause lines ($_m_cause) — an unnamed refusal reads as transient (fail-open)"; fi
if grep -A8 -F 'BASELINE IS NOT GREEN' "$_m_src" | grep -qF 'L3-CAUSE=BASELINE-RED'; then pass "l3-verdict: the matrix emits L3-CAUSE=BASELINE-RED at its red-baseline exit"; else fail "l3-verdict: the red-baseline exit does not emit L3-CAUSE=BASELINE-RED — the lib's block can never fire"; fi
if grep -v '^[[:space:]]*#' "$_l3lib" | grep -qF 'L3-CAUSE=BASELINE-RED'; then pass "l3-verdict: the lib keys on the exact token the matrix emits"; else fail "l3-verdict: lib does not reference L3-CAUSE=BASELINE-RED"; fi
# NO /tmp/ PATH IN THE MATRIX'S CODE — its scratch files are read back into verdicts, and a fixed path let two
# concurrent runs clobber each other (measured 2026-08-26: the first full census read two false UNGUARDED while
# this seat's hand run had the baseline file empty mid-rewrite, then inflated every LIVE count by 29 phantom
# labels). NOW= had been converted to mktemp for this reason and four siblings had not — guard the CLASS.
_m_tmp="$(grep -v '^[[:space:]]*#' "$_m_src" | grep -c -F '/tmp/')"
if [ "${_m_tmp:-0}" = "0" ]; then pass "matrix: no /tmp/ path in code (every scratch file is per-process)"; else fail "matrix: $_m_tmp /tmp/ path(s) in code — concurrent runs (a peer's pre-push gate, a census) clobber each other's scratch files"; fi
# the two pre-push Layer-3 logs (the ones a BLOCK decision reads) are per-process too
# WIDENED 2026-08-26: the arm used to guard only the two
# Layer-3 logs. Every operator-facing gate log moved under one per-process $_pp_logs dir in the same
# change, so the guard is now the WHOLE FAMILY — any fixed /tmp/<name>-prepush path coming back means
# two seats pushing at once can overwrite each other's log between the write and the tail that reads it.
# ⚠️ READABILITY IS ASSERTED FIRST: the path is RELATIVE and the arm had `|| true`
# plus `${_pp_fixed:-0}`, which together turn "could not read the file" into "the file is clean" —
# measured, running it from another cwd PASSED against a file it never opened. An unreadable target
# is an INSTRUMENT failure and must red, never certify.
# ⚠️ AND THIS PREDICATE IS DELIBERATELY USE-BLIND, unlike the matrix arm a few lines up which STRIPS
# comments before counting (two adjacent arms once carried opposite conventions, neither saying
# why). The difference is intended: there the literal legitimately appears in prose, here the literal
# must not appear AT ALL — a comment documenting the old fixed path is exactly how it creeps back.
if [ ! -r .githooks/pre-push ]; then
  fail "pre-push: .githooks/pre-push is not readable from here — the per-process-log arm cannot certify a file it never opened"
else
  _pp_fixed="$(grep -c -E '/tmp/[a-z0-9-]+-prepush' .githooks/pre-push || true)"
  if [ "${_pp_fixed:-0}" = "0" ]; then pass "pre-push: every gate log is per-process (no fixed /tmp/<name>-prepush path)"; else fail "pre-push: $_pp_fixed fixed /tmp/<name>-prepush path(s) are back — concurrent pushes clobber each other's gate logs"; fi
fi
if grep -q -F '_pp_logs="$(mktemp -d)"' .githooks/pre-push; then pass "pre-push: the per-process log dir is created once, up front"; else fail "pre-push: _pp_logs is not created with mktemp -d — the gate logs have no private home"; fi
# A BARE ${_pp_logs} INSIDE A $( ) SUBSTITUTION IS UNPROTECTED even when the whole thing sits inside
# double quotes: `$( … )` opens a FRESH quoting context, so the enclosing quotes stop at the boundary
# and bash word-splits the path (zsh does NOT, which is how a zsh-run probe reads it as fine and why
# two independent enumerations agreed on a wrong zero).
# `mktemp -d` returns a space-free path TODAY, so nothing fails now — and these two sites sat on the
# SUCCESS path, printing `✓ green ()` with an empty value. Latent, silent, and green.
# ⛔ BOTH SPELLINGS. The first version of this arm keyed on the BRACED form only (`grep -F '${_pp_logs}'`)
# and read 0 on a planted `$_pp_logs` needle — reproduced here before the fix.
# No live bug at that sha (both non-braced uses were a comment and a plain echo string), but the arm's
# whole job is stopping the class returning, and a future author writing the unbraced form got nothing.
# Same defect one domain over as bash-environment.md's two-spellings clause: a key that exists in two
# spellings, where each spelling's grep is blind to the other's corpus.
# The needle control below is what stops this arm going vacuously green if the predicate ever breaks —
# it plants BOTH spellings and requires 2, so a regression to a one-spelling predicate reads 1 and FAILS.
_pp_needle="$(mktemp)"; printf 'echo "x ($(tail -1 ${_pp_logs}/planted.log))"\necho "y ($(tail -1 $_pp_logs/planted.log))"\n' > "$_pp_needle"
_pp_ctl="$(grep '\$(' "$_pp_needle" | grep -E '\$\{?_pp_logs' | grep -vcE '"\$\{?_pp_logs' || true)"
rm -f "$_pp_needle"
if [ "${_pp_ctl:-0}" -ge 2 ]; then pass "pre-push: the unquoted-in-substitution predicate matches BOTH spellings of a planted needle (control)"; else fail "pre-push: the predicate matched $_pp_ctl of 2 planted needles — it is spelling-blind, so the arm below is partly vacuous"; fi
_pp_bare="$(grep '\$(' .githooks/pre-push | grep -E '\$\{?_pp_logs' | grep -vcE '"\$\{?_pp_logs' || true)"
if [ "${_pp_bare:-0}" = "0" ]; then pass "pre-push: no bare \${_pp_logs} inside a \$( ) substitution (fresh quoting context — the enclosing quotes do not reach)"; else fail "pre-push: $_pp_bare bare \${_pp_logs} inside \$( ) — word-splits under bash on any path with a space; the gate prints a green tick with an EMPTY value"; fi
# ISOLATION FAILED after a CLEAN inner run must not read as a clean pass: the branch
# converts rc 0 → 3 with its own cause; the lib names it and stays fail-open (usually a peer's concurrent edit).
# BOTH-OUTCOMES CONTROLS — a control that prints only when it FAILS makes its own silence ambiguous
# (passed vs never-ran are the same bytes). The post-run state-dependence control now prints on PASS too.
# ⚠️ -A16, not -A6: the first cut used a 6-line window and went RED on the live file because the COMMENT
# explaining the fix pushed the payload past it — the fixed-width-window trap bash-environment.md
# documents, committed live one minute after writing it. Anchor at BOTH ends where you can; where a
# window is unavoidable, size it for the comment a future author will add above the line.
# BOTH-ENDS RANGE, not a fixed window. The first cut was -A6 and went RED on
# correct code because my own explanatory comment pushed the payload past it; widening to -A16 only
# DELAYED that — the next author adding four lines of rationale re-reds it, and the RED reads as the
# control breaking rather than the window. Both anchors are unique in the target (measured: 1 and 1),
# so a range read is available and is immune to any comment length. Verified before folding: the range
# reads 12 lines, opens on the mktemp line, closes on `exit $gate_rc`, and a RED control (the target
# line stripped) reads 0.
if awk '/post="\$\(mktemp\)"; suite_labels/,/exit \$gate_rc/' "$_m_src" | grep -qF 'post-run control:'; then pass "matrix: the post-run state-dependence control prints on PASS as well as FAIL (its silence is no longer ambiguous)"; else fail "matrix: the post-run control is silent-on-pass — passed and never-ran are indistinguishable from the log"; fi
if awk '/ISOLATION FAILED — the LIVE/,/elif \[ -n "\$ISO_PRE_DIRT" \]; then/' "$_m_src" | grep -qF 'L3-CAUSE=ISOLATION-FAIL'; then pass "l3-verdict: the ISOLATION FAILED branch emits L3-CAUSE=ISOLATION-FAIL (a clean inner rc no longer passes silently)"; else fail "l3-verdict: ISOLATION FAILED emits no cause — a clean inner run reads as a green Layer-3 tick"; fi
_o="$(_l3run 3 "🚨 ISOLATION FAILED — the LIVE tree's hooks are dirty. This must NEVER happen:
L3-CAUSE=ISOLATION-FAIL" "validate-no-secrets.sh")"
assert_not_contains "l3-verdict: rc=3 ISOLATION-FAIL + a SCANNER changed → no BLOCK (not the blocking cause)" "$_o" "OWN BASELINE IS RED"
assert_contains "l3-verdict: rc=3 ISOLATION-FAIL → the cause is named in the WARN line" "$_o" "cause: L3-CAUSE=ISOLATION-FAIL"
assert_contains "l3-verdict: rc=3 ISOLATION-FAIL → returns 0" "$_o" "rc=0"
# hooks-fingerprint (scripts/lib/hooks-dirt-fingerprint.sh): the matrix's isolation proof compares the live
# .claude/hooks/ BEFORE and AFTER its run. It used to fail on ANY dirt there, so another session's
# uncommitted hook edit turned every clean gate run into ISOLATION-FAIL (2026-10-05). These arms drive the
# real function on a scratch repo: a fresh EMPTY dir outside REPO_ROOT with GIT_* stripped, refused
# otherwise, because a failed mktemp would leave `cd ""` in the shared repo.
_hf_lib="$REPO_ROOT/scripts/lib/hooks-dirt-fingerprint.sh"
if bash -n "$_hf_lib" 2>/dev/null; then pass "hooks-fingerprint: lib parses"; else fail "hooks-fingerprint: lib does not parse"; fi
_hf_env() { env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY \
  -u GIT_ALTERNATE_OBJECT_DIRECTORIES -u GIT_PREFIX "$@"; }
_hf_fx="$(cd "$(mktemp -d)" && pwd -P)"; _hf_real="$(cd "$REPO_ROOT" && pwd -P)"
_hf_git() { _hf_env git -C "$_hf_fx" -c init.defaultBranch=main -c user.email=smoke@local -c user.name=smoke -c commit.gpgsign=false "$@"; }
_hf() { _hf_env bash -c 'source "$1"; hooks_fingerprint "$2" "$3"' _ "$_hf_lib" "$_hf_fx" "$1" 2>/dev/null; }
if [ -n "$_hf_fx" ] && [ -d "$_hf_fx" ] && [ -z "$(ls -A "$_hf_fx")" ] && [ "${_hf_fx#"$_hf_real"}" = "$_hf_fx" ] \
   && _hf_git init -q && [ "$(_hf_git rev-parse --absolute-git-dir)" = "$_hf_fx/.git" ]; then
  mkdir -p "$_hf_fx/.claude/hooks" && echo 'echo a' > "$_hf_fx/.claude/hooks/a.sh"
  _hf_git add -A && _hf_git commit -qm base
  _hf_base="$(_hf_git rev-parse HEAD)"
  _hf0="$(_hf "$_hf_base")"
  echo 'echo peer' >> "$_hf_fx/.claude/hooks/a.sh"
  _hf1="$(_hf "$_hf_base")"
  assert_eq "hooks-fingerprint: a clean hooks dir still yields a hash, never empty" "1" "$([ -n "$_hf0" ] && echo 1 || echo 0)"
  assert_eq "hooks-fingerprint: an uncommitted hook edit changes it" "1" "$([ -n "$_hf1" ] && [ "$_hf1" != "$_hf0" ] && echo 1 || echo 0)"
  assert_eq "hooks-fingerprint: the same pre-existing edit read twice is equal (a peer's dirt passes)" "$_hf1" "$(_hf "$_hf_base")"
  _hf_git commit -qam peer
  assert_eq "hooks-fingerprint: a peer COMMIT mid-run (HEAD moves, files do not) leaves it unchanged" "$_hf1" "$(_hf "$_hf_base")"
  echo 'echo new' > "$_hf_fx/.claude/hooks/new.sh"; _hf2="$(_hf "$_hf_base")"
  assert_eq "hooks-fingerprint: a new untracked hook file changes it" "1" "$([ -n "$_hf2" ] && [ "$_hf2" != "$_hf1" ] && echo 1 || echo 0)"
  echo 'echo edited' > "$_hf_fx/.claude/hooks/new.sh"
  assert_eq "hooks-fingerprint: editing that untracked file changes it again" "1" "$([ "$(_hf "$_hf_base")" != "$_hf2" ] && echo 1 || echo 0)"
  assert_eq "hooks-fingerprint: an unusable base prints nothing, so two failures never compare equal" "" "$(_hf 0000000000000000000000000000000000000000)"
else
  fail "hooks-fingerprint: scratch repo refused (not a fresh empty dir outside REPO_ROOT, or its git dir resolved elsewhere)"
fi
[ -n "$_hf_fx" ] && [ "${_hf_fx#"$_hf_real"}" = "$_hf_fx" ] && rm -rf "$_hf_fx"
# Matrix wiring: both reads go through the lib, an empty before-read refuses, and the absolute test is gone.
assert_eq "hooks-fingerprint: the matrix fingerprints before AND after its run" "2" "$(grep -v '^[[:space:]]*#' "$_m_src" | grep -cF 'hooks_fingerprint "$REPO" "$ISO_BASE"')"
assert_eq "hooks-fingerprint: an empty before-read refuses with L3-CAUSE=ISOLATION-PRECHECK" "1" "$(grep -v '^[[:space:]]*#' "$_m_src" | grep -cF 'L3-CAUSE=ISOLATION-PRECHECK')"
assert_eq "hooks-fingerprint: the old 'any dirt under .claude/hooks/ = failed' test is gone" "0" "$(grep -v '^[[:space:]]*#' "$_m_src" | grep -cF 'if [ -n "$(git -C "$REPO" status --porcelain .claude/hooks/)" ]')"
# hooks-fingerprint SCOPE + failure contract: the arms above edit only INSIDE .claude/hooks/,
# so a lib that diffs the whole repo (every peer edit anywhere = ISOLATION FAILED, the founding defect one directory
# wider) passed all of them, and only the diff call's failure was armed. Sourced under the matrix's own options.
_hs_fx="$(cd "$(mktemp -d)" && pwd -P)"
_hs_git() { _hf_env git -C "$_hs_fx" -c init.defaultBranch=main -c user.email=smoke@local -c user.name=smoke -c commit.gpgsign=false "$@"; }
_hs() { _hf_env bash -c 'set -uo pipefail; source "$1"; hooks_fingerprint "$2" "$3"' _ "$_hf_lib" "$_hs_fx" "$1" 2>/dev/null; }
if [ -n "$_hs_fx" ] && [ -d "$_hs_fx" ] && [ -z "$(ls -A "$_hs_fx")" ] && [ "${_hs_fx#"$_hf_real"}" = "$_hs_fx" ] \
   && _hs_git init -q && [ "$(_hs_git rev-parse --absolute-git-dir)" = "$_hs_fx/.git" ]; then
  mkdir -p "$_hs_fx/.claude/hooks" && echo 'echo a' > "$_hs_fx/.claude/hooks/a.sh" && echo 'x' > "$_hs_fx/README"
  echo '*.cache' >> "$_hs_fx/.git/info/exclude"; echo 'c1' > "$_hs_fx/.claude/hooks/x.cache"
  _hs_git add -A && _hs_git commit -qm base
  _hs_base="$(_hs_git rev-parse HEAD)"; _hs0="$(_hs "$_hs_base")"
  echo 'y' >> "$_hs_fx/README"; echo 'n' > "$_hs_fx/notes.txt"; echo 'c2' > "$_hs_fx/.claude/hooks/x.cache"
  assert_eq "hooks-fingerprint: edits OUTSIDE .claude/hooks/, and to an ignored file inside it, leave it unchanged" "1" "$([ -n "$_hs0" ] && [ "$_hs0" = "$(_hs "$_hs_base")" ] && echo 1 || echo 0)"
  printf '#!/bin/sh\necho CONSTANT\n' > "$_hs_fx/.git/constdiff"; chmod +x "$_hs_fx/.git/constdiff"
  _hs_git config diff.external "$_hs_fx/.git/constdiff"
  echo 'echo b' > "$_hs_fx/.claude/hooks/a.sh"; _hs1="$(_hs "$_hs_base")"; echo 'echo c' > "$_hs_fx/.claude/hooks/a.sh"
  assert_eq "hooks-fingerprint: a diff.external in the repo config cannot make two different hook edits hash equal" "1" "$([ -n "$_hs1" ] && [ "$_hs1" != "$(_hs "$_hs_base")" ] && echo 1 || echo 0)"
  _hs_git config --unset diff.external; echo 'echo a' > "$_hs_fx/.claude/hooks/a.sh"
  ln -s nowhere "$_hs_fx/.claude/hooks/dangling.sh"
  assert_eq "hooks-fingerprint: a failed hash of an untracked hook (dangling symlink) prints nothing" "" "$(_hs "$_hs_base")"
else
  fail "hooks-fingerprint: scope scratch repo refused (not a fresh empty dir outside REPO_ROOT, or its git dir resolved elsewhere)"
fi
[ -n "$_hs_fx" ] && [ "${_hs_fx#"$_hf_real"}" = "$_hs_fx" ] && rm -rf "$_hs_fx"
# Matrix isolation block, DRIVEN: the three wiring arms above are spelling greps, and they
# stayed green on a vacuous comparison ("$ISO_POST" != "$ISO_POST"), on the founding any-dirt test respelled with
# `--`, and on an unreachable PRECHECK. These run THIS tree's matrix + lib, copied into a scratch repo, over a stub
# suite that fires one stub hook (about a second per arm). FF_MUTATION_ISOLATED is stripped: the real matrix runs
# this suite with it set, and inherited it would make the copy skip the very block these arms drive.
_hi_git() { _hf_env git -C "$_hi_fx" -c init.defaultBranch=main -c user.email=smoke@local -c user.name=smoke -c commit.gpgsign=false "$@"; }
_hi_run() {  # $1 = clean | predirt | breach | loaddeath | precheck | bypass -> "rc=<n> wt=<worktrees left>", then the output
  _hi_fx="$(cd "$(mktemp -d)" && pwd -P)"
  if [ -z "$_hi_fx" ] || [ ! -d "$_hi_fx" ] || [ -n "$(ls -A "$_hi_fx")" ] || [ "${_hi_fx#"$_hf_real"}" != "$_hi_fx" ] \
     || ! _hi_git init -q || [ "$(_hi_git rev-parse --absolute-git-dir)" != "$_hi_fx/.git" ]; then echo "rc=REFUSED"; return 0; fi
  mkdir -p "$_hi_fx/scripts/lib" "$_hi_fx/.claude/hooks"
  cp "$REPO_ROOT/scripts/smoke-mutation-matrix.sh" "$_hi_fx/scripts/"; cp "$_hf_lib" "$_hi_fx/scripts/lib/"
  printf '%s\n' '#!/usr/bin/env bash' '[ "$(bash .claude/hooks/h.sh 2>/dev/null)" = FIRE ] && echo "  ✓ h fires"' \
    'echo "  ✓ always"' '[ -n "${_HI_BREACH:-}" ] && ! grep -q BREACH "$_HI_BREACH" && echo "echo BREACH" >> "$_HI_BREACH"' \
    'exit 0' > "$_hi_fx/scripts/smoke-test-hooks.sh"
  echo 'echo FIRE' > "$_hi_fx/.claude/hooks/h.sh"; echo 'echo P' > "$_hi_fx/.claude/hooks/p.sh"
  chmod +x "$_hi_fx/.claude/hooks/"*.sh "$_hi_fx/scripts/"*.sh
  _hi_git add -A && _hi_git commit -qm base
  local brk="" iso=0 o r
  case "$1" in
    predirt)   echo '# a peer edit' >> "$_hi_fx/.claude/hooks/p.sh" ;;
    breach)    echo '# a peer edit' >> "$_hi_fx/.claude/hooks/p.sh"; brk="$_hi_fx/.claude/hooks/h.sh" ;;
    loaddeath) echo ': "${_HI_NEVER_SET}"' >> "$_hi_fx/scripts/lib/hooks-dirt-fingerprint.sh" ;;
    precheck)  printf 'hooks_fingerprint() {\n' > "$_hi_fx/scripts/lib/hooks-dirt-fingerprint.sh" ;;
    bypass)    iso=1 ;;
  esac
  o="$(_hf_env -u FF_MUTATION_ISOLATED FF_MUTATION_ISOLATED="$iso" _HI_BREACH="$brk" bash "$_hi_fx/scripts/smoke-mutation-matrix.sh" --gate h.sh 2>&1)"; r=$?
  echo "rc=$r wt=$(_hi_git worktree list | grep -c .)"; printf '%s\n' "$o"
  [ "${_hi_fx#"$_hf_real"}" = "$_hi_fx" ] && rm -rf "$_hi_fx"
}
_hi_o="$(_hi_run clean)"
assert_contains "matrix isolation: a clean run exits 0 and reads untouched" "$_hi_o" "rc=0 wt=1"
assert_contains "matrix isolation: a clean run prints the untouched line" "$_hi_o" "ISOLATION VERIFIED — live .claude/hooks/ untouched"
_hi_o="$(_hi_run predirt)"
assert_contains "matrix isolation: a hook already dirty BEFORE the run passes (exit 0)" "$_hi_o" "rc=0 wt=1"
assert_contains "matrix isolation: ...and is reported as not this run's" "$_hi_o" "already uncommitted before it started; not this run's"
_hi_o="$(_hi_run breach)"
assert_contains "matrix isolation: a live hook changed DURING a clean run exits 3" "$_hi_o" "rc=3 wt=1"
assert_contains "matrix isolation: ...with L3-CAUSE=ISOLATION-FAIL" "$_hi_o" "L3-CAUSE=ISOLATION-FAIL"
assert_contains "matrix isolation: ...and names the path that changed during the run" "$_hi_o" "     .claude/hooks/h.sh"
assert_not_contains "matrix isolation: ...and not the path that was already dirty before it" "$(printf '%s\n' "$_hi_o" | sed -n '/changed DURING the run:/,/Diff it BEFORE/p')" "p.sh"
_hi_o="$(_hi_run loaddeath)"
assert_contains "matrix isolation: a lib that dies while loading refuses with ISOLATION-PRECHECK (exit 3), never its own rc" "$_hi_o" "rc=3 wt=1"
assert_contains "matrix isolation: ...and names the cause" "$_hi_o" "L3-CAUSE=ISOLATION-PRECHECK"
_hi_o="$(_hi_run precheck)"
assert_contains "matrix isolation: an unparseable lib refuses with ISOLATION-PRECHECK" "$_hi_o" "L3-CAUSE=ISOLATION-PRECHECK"
assert_not_contains "matrix isolation: ...before any worktree is made" "$_hi_o" "ISOLATING"
_hi_o="$(_hi_run bypass)"
assert_contains "matrix isolation: an inherited FF_MUTATION_ISOLATED=1 in the live tree refuses with NOT-ISOLATED" "$_hi_o" "L3-CAUSE=NOT-ISOLATED"
assert_not_contains "matrix isolation: ...and never runs a kill there (no LIVE/UNGUARDED verdict)" "$_hi_o" "LIVE —"
_o="$(_l3run 1 "  ❌ validate-no-secrets.sh    UNGUARDED — killing it fails NOTHING" "validate-no-secrets.sh")"
assert_contains "l3-verdict: scanner UNGUARDED → BLOCK text" "$_o" "SECRET SCANNER is UNGUARDED"
assert_contains "l3-verdict: scanner UNGUARDED → returns 1 (push refused)" "$_o" "rc=1"
_o="$(_l3run 1 "  ❌ agent-diff-reporter.sh    UNGUARDED — killing it fails NOTHING" "agent-diff-reporter.sh")"
assert_contains "l3-verdict: non-scanner UNGUARDED → WARN-mode line" "$_o" "WARN-mode for non-scanner hooks"
assert_contains "l3-verdict: non-scanner UNGUARDED → returns 0 (warn)" "$_o" "rc=0"
_o="$(_l3run 1 "  ❌ validate-no-secrets.sh    UNGUARDED — killing it fails NOTHING" "validate-no-secrets.sh" SKIP_HOOK_LIVENESS_GATE=1)"
assert_not_contains "l3-verdict: SKIP_HOOK_LIVENESS_GATE=1 → no BLOCK even for a scanner" "$_o" "SECRET SCANNER is UNGUARDED"
assert_contains "l3-verdict: SKIP_HOOK_LIVENESS_GATE=1 → returns 0" "$_o" "rc=0"
_o="$(_l3run 1 "  ✅ validate-no-secrets.sh    LIVE — 3 assertion(s) die
  ❌ agent-diff-reporter.sh    UNGUARDED — killing it fails NOTHING" "validate-no-secrets.sh
agent-diff-reporter.sh")"
assert_not_contains "l3-verdict: a LIVE scanner beside an UNGUARDED general hook does not BLOCK (predicate keys on the scanner's OWN line)" "$_o" "SECRET SCANNER is UNGUARDED"
assert_contains "l3-verdict: … and returns 0" "$_o" "rc=0"
rm -f "$_l3log"

# --- pre-push EMPTY STDIN is DISTINGUISHABLE from a pass -----------------------------
# The hook read stdin, found it empty, and `exit 0`d printing ZERO BYTES. So the shape of
# every hand-verification that forgets a ref range — `printf "" | bash .githooks/pre-push
# origin .` — was byte-identical to a clean push gate, in the one hook whose entire question
# is "is my push blocked?". Codified false-green shape (active-recall.md: a runner's helpful
# exit-0 path makes every gate above it FALSE-GREEN).
#
# BOTH STATES ARE ASSERTED, which is the point — an arm that only checked the empty case
# would pass just as well if the marker printed unconditionally, including on real pushes.
# The real-range arm feeds a SELF-REFERENTIAL ref line (remote_sha == HEAD), so CHANGED is
# empty and every path-gated gate short-circuits: the hook runs end-to-end in ~0s without
# invoking tsc, the suites or a build.
#
# NOT exit-non-zero: whether git ever invokes pre-push with zero ref lines is UNMEASURED
# (githooks(5) gives the line format and is silent on the zero-line case; settling it needs
# a real `git push`, which is owner-gated here). A marker is correct under both hypotheses.
_ppe_empty="$(printf '' | bash .githooks/pre-push origin . 2>&1; echo "rc=$?")"
assert_contains "pre-push empty stdin ANNOUNCES that nothing was checked" \
  "$_ppe_empty" "NOTHING WAS CHECKED"
assert_contains "pre-push empty stdin still exits 0 (a valid no-op push must not break)" \
  "$_ppe_empty" "rc=0"
_ppe_head="$(git rev-parse HEAD)"
_ppe_real="$(printf 'refs/heads/smoke-probe %s refs/heads/smoke-probe %s\n' "$_ppe_head" "$_ppe_head" \
  | SKIP_PREPUSH_LOCK=1 SKIP_PREPUSH_SNAPSHOT=1 bash .githooks/pre-push origin . 2>&1; echo "rc=$?")"
assert_not_contains "pre-push with a REAL ref range does NOT claim nothing was checked" \
  "$_ppe_real" "NOTHING WAS CHECKED"
assert_contains "pre-push with a REAL ref range reaches its own gates (positive control)" \
  "$_ppe_real" "skipping e2e gate"

# --- pre-push PRINTS THE RANGE IT CHECKED, AND ITS COUNT IS rev-list's -----------------------
# The empty-stdin marker above cannot see a WRONG range:
# `HEAD~1` fed as the remote sha is well-formed and non-empty, and on 2026-08-25 it certified this
# gate rc=0 while the real push range (472 commits) returned rc=1. The hook now prints
# `→ push range checked: <base>..<head-sha> — N commit(s), …` before any gate runs. These arms red
# if N disagrees with `git rev-list --count` over the PRINTED range, or if the printed base is not
# the remote sha the ref line fed.
#   (1) WIRED — the real hook end to end, on the self-referential line above (a 0-commit range).
#   (2) NON-TRIVIAL — a 0-commit range cannot tell a right count from a constant 0, and running the
#       whole hook over a real range fires tsc, the suites and the build. So the range block is
#       EXTRACTED FROM THE HOOK AT TEST TIME (the cert-freshness shape: it tracks the shipped source,
#       never a copy) and fed HEAD~5 as the remote sha, which is at least 5 commits by construction.
_ppr_parse() {  # stdin: hook output -> "<range> <count>" off the disclosure line, or nothing
  awk '/push range checked: /{for(i=1;i<=NF;i++) if($i=="checked:"){print $(i+1), $(i+3); exit}}'
}
read -r _ppr_rng _ppr_n <<< "$(_ppr_parse <<< "$_ppe_real")"
if [[ -z "${_ppr_rng:-}" ]]; then
  fail "pre-push range (wired): the real hook printed no 'push range checked:' line — the disclosure is gone or reworded"
else
  assert_eq "pre-push range (wired): the printed base is the remote sha the ref line fed" \
    "$_ppe_head" "${_ppr_rng%%..*}"
  assert_eq "pre-push range (wired): printed count == git rev-list --count over the printed range" \
    "$(git rev-list --count "$_ppr_rng" 2>/dev/null || echo rev-list-failed)" "${_ppr_n:-<none>}"
fi
_ppr_s="$(grep -n '^# Determine the base to diff against' .githooks/pre-push | head -1 | cut -d: -f1)"
_ppr_e="$(grep -n '^# ── end push-range disclosure' .githooks/pre-push | head -1 | cut -d: -f1)"
_ppr_base="$(git rev-parse --verify -q 'HEAD~5^{commit}' 2>/dev/null || true)"
if [[ -z "$_ppr_s" || -z "$_ppr_e" ]]; then
  fail "pre-push range (non-trivial): the range block's markers are not in .githooks/pre-push — the arm cannot run"
elif [[ -z "$_ppr_base" ]]; then
  fail "pre-push range (non-trivial): HEAD~5 does not resolve (shallow clone?) — no multi-commit range to feed"
else
  _ppr_h="$(mktemp)"
  { echo '#!/usr/bin/env bash'; echo 'set -euo pipefail'; echo 'STDIN_CONTENT="$1"'
    sed -n "${_ppr_s},${_ppr_e}p" .githooks/pre-push; echo 'echo "SMOKE-RC=0"'; } > "$_ppr_h"
  _ppr_o="$(bash "$_ppr_h" "refs/heads/smoke-probe $(git rev-parse HEAD) refs/heads/smoke-probe $_ppr_base" 2>&1)"
  read -r _ppr_rng2 _ppr_n2 <<< "$(_ppr_parse <<< "$_ppr_o")"
  assert_contains "pre-push range (non-trivial): the extracted block runs clean under set -euo pipefail" \
    "$_ppr_o" "SMOKE-RC=0"
  assert_eq "pre-push range (non-trivial): the printed base is the remote sha the ref line fed" \
    "$_ppr_base" "${_ppr_rng2%%..*}"
  assert_eq "pre-push range (non-trivial): printed count == git rev-list --count over the printed range" \
    "$(git rev-list --count "${_ppr_rng2:-<none>}" 2>/dev/null || echo rev-list-failed)" "${_ppr_n2:-<none>}"
  if [[ "${_ppr_n2:-}" =~ ^[0-9]+$ ]] && (( _ppr_n2 >= 5 )); then
    pass "pre-push range (non-trivial): the fed range is multi-commit (${_ppr_n2}), so the count arm can discriminate"
  else
    fail "pre-push range (non-trivial): printed count '${_ppr_n2:-<none>}' from a HEAD~5 base — need >= 5, or the count arm proves nothing"
  fi
  rm -f "$_ppr_h"
fi

# The L#-ledger guard must exist, self-test clean, and be WIRED at the push boundary.
# A guard that is present but unwired is the wired-!=-fired class it was written to prevent.
if [[ -f scripts/check-lesson-numbers.mjs ]]; then
  if node scripts/check-lesson-numbers.mjs --self-test >/dev/null 2>&1; then
    pass "check-lesson-numbers.mjs self-test passes (mutation-valid)"
  else
    fail "check-lesson-numbers.mjs self-test FAILS"
  fi
  if grep -q "check-lesson-numbers.mjs" .githooks/pre-push; then
    pass "L#-ledger guard is wired into .githooks/pre-push"
  else
    fail "L#-ledger guard exists but is NOT wired into pre-push — present != firing"
  fi

  # A hard-block gate must BLOCK regardless of how it was invoked. The entrypoint guard's naive form
  # (`import.meta.url === pathToFileURL(argv[1]).href`) FAILS OPEN through a symlink — node resolves
  # symlinks for `import.meta.url`, argv[1] keeps what the caller typed — so `main` silently never
  # ran and the guard exited 0 on a dirty ledger. Mutation-valid: drop `realpathSync` and the
  # symlink row goes rc=0 → FAIL.
  # ⛔ FIXTURE-PREMISE ROT, repaired 2026-08-06 (the meta archive split). This built the
  # dirty ledger by copying the ledger's main file and injecting a SECOND declaration of an existing number —
  # sound while that file held the declarations. Post-split that file is a ROUTER with ZERO declaration
  # headings, so the injected line was the ONLY declaration of that number in the fixture, there was no
  # duplicate to find, and the guard
  # correctly exited 0 — which this arm then reported as "entrypoint guard fails open". A GREEN
  # guard accused of failing open by its own stale fixture: the arm had stopped discriminating and
  # said so in the loudest possible way. Build from the TIER UNION, which is what the ledger now is.
  # This copy ships no ledger, so its fixture is self-contained instead: two declarations of one
  # invented number, and an empty retired list in place of the retired file.
  _lnk="$(mktemp -d)/repo-link"; ln -sfn "$PWD" "$_lnk" 2>/dev/null
  _dirty="$(mktemp -d)/dirty.md"
  printf '## 2026-07-09 — L9990: smoke fixture declaration\n\nbody\n\n## 2026-07-10 — L9990: smoke-injected duplicate\n\nbody\n' > "$_dirty"
  # PRECONDITION — the arm must PROVE its fixture is discriminating before reading any verdict from
  # it. Without this, the next reshaping of the ledger makes the arm vacuous again and the failure
  # once more accuses the guard instead of the fixture. Two declarations = a real duplicate.
  _dupn=$(grep -c '^## .*\bL9990\b' "$_dirty" 2>/dev/null || true)
  if [[ "${_dupn:-0}" -lt 2 ]]; then
    fail "L#-guard arm is VACUOUS: the dirty fixture holds ${_dupn:-0} declarations, needs >=2 — fixture rot, not a guard defect"
  fi
  _shapes_ok=1
  for _inv in "$PWD/scripts/check-lesson-numbers.mjs" "$_lnk/scripts/check-lesson-numbers.mjs" "./scripts/check-lesson-numbers.mjs"; do
    node "$_inv" "$_dirty" /dev/null >/dev/null 2>&1 || continue
    _shapes_ok=0  # exit 0 on a DIRTY ledger = the gate did not run
  done
  if [[ $_shapes_ok -eq 1 ]]; then
    pass "L#-guard hard-blocks a duplicate via abs / symlinked / relative invocation (no entrypoint fail-open)"
  else
    fail "L#-guard EXITS 0 on a dirty ledger for at least one invocation shape — entrypoint guard fails open"
  fi
  rm -rf "$(dirname "$_lnk")" "$(dirname "$_dirty")" 2>/dev/null

  # --- TRIGGER COVERAGE over the MEMORY TIER FAMILY (2026-08-06, PHASE 1 of the archive split) ---
  # The stanza's own CHANGED-matching regex is the gate BEFORE the gate: it decides whether
  # check-lesson-numbers.mjs runs at all. It was an EXACT alternation `(MEMORY|RETIRED)`, so an
  # ARCHIVE-ONLY commit — moving a lesson between shards, repairing an archived number, a distill
  # roll — matched nothing and skipped the hard gate ENTIRELY. Not a degraded check: no check.
  # The regex is EXTRACTED FROM THE LIVE HOOK, never restated here, so narrowing the hook REDs
  # these rows instead of leaving a copy that agrees with itself.
  _lnre="$(awk '/SKIP_LESSON_NUMBER_CHECK/ && /grep -qE/ { if (match($0, /'"'"'[^'"'"']+'"'"'/)) { print substr($0, RSTART+1, RLENGTH-2); exit } }' .githooks/pre-push)"
  if [[ -n "$_lnre" ]]; then
    _trig_ok=1; _trig_bad=""
    # MUST fire: every L#-bearing tier in meta/.
    for _p in ".claude/skills/meta/MEMORY.md" \
              ".claude/skills/meta/MEMORY-ARCHIVE-2026-04-14-2026-05-23.md" \
              ".claude/skills/meta/MEMORY-ARCHIVE-legacy-list.md" \
              ".claude/skills/meta/RETIRED.md"; do
      echo "$_p" | grep -qE "$_lnre" || { _trig_ok=0; _trig_bad="$_trig_bad missing:$_p"; }
    done
    # MUST NOT fire: same dir but not the L# ledger, another skill, and a deeper path (the
    # anchors + `[^/]*` must refuse to cross a path segment).
    for _p in ".claude/skills/meta/RULES.md" \
              ".claude/skills/meta/CHANGELOG.md" \
              ".claude/skills/meta/WATCH-TIER.md" \
              ".claude/skills/qa-expert/MEMORY.md" \
              ".claude/skills/meta/sub/MEMORY.md"; do
      echo "$_p" | grep -qE "$_lnre" && { _trig_ok=0; _trig_bad="$_trig_bad overmatch:$_p"; }
    done
    if [[ $_trig_ok -eq 1 ]]; then
      pass "pre-push L#-stanza triggers on the whole meta MEMORY tier family, and on nothing else"
    else
      fail "pre-push L#-stanza trigger regex is wrong —$_trig_bad"
    fi
  else
    fail "could not extract the L#-stanza trigger regex from .githooks/pre-push (shape changed)"
  fi
else
  fail "scripts/check-lesson-numbers.mjs is missing (the L#-ledger guard)"
fi

echo ""
echo "=== /wrap Step-0 post-compact marker gate (meta) ==="
# WHY: the SessionStart:compact directive fires ONCE, and post-compact-pending-check.sh re-surfaces
# the marker on every PROMPT — but a /wrap is ONE prompt and dozens of turns, so neither net can
# interrupt a wrap already in flight. On 2026-07-10 an auto-compaction fired INSIDE a /wrap and went
# unnamed for 11 tool calls, after the identical skip had been corrected earlier the same
# session. The gate must therefore be COMPUTED by wrap-reconcile, not asserted by the spec.
#
# DISCRIMINATING, both directions: marker present -> must report; marker absent -> must NOT report.
# A one-sided assertion would pass on a script that prints the warning unconditionally.
# ⛔ The `zzsmoke-` prefix is LOAD-BEARING: wrap-reconcile honours WRAP_RECONCILE_SMOKE_SKIP only for a sid
# that starts with it (scripts/lib/wrap-reconcile-smoke-skip.mjs). A new fixture sid without the prefix
# silently runs every probe again, including the trigger scan this arm skips below.
_pc_sid="zzsmoke-postcompact-0000-0000-000000000000"
_pc_marker=".claude/state/post-compact-pending-${_pc_sid}"
mkdir -p .claude/state
printf 'compacted=2026-01-01 00:00:00 UTC trigger=auto focus=no\n' > "$_pc_marker"
_pc_with=$(CLAUDE_CODE_SESSION_ID="$_pc_sid" node scripts/wrap-reconcile.mjs 2>&1 || true)
rm -f "$_pc_marker"
_pc_without=$(CLAUDE_CODE_SESSION_ID="$_pc_sid" node scripts/wrap-reconcile.mjs 2>&1 || true)

if echo "$_pc_with" | grep -q " PENDING"; then
  pass "wrap-reconcile REPORTS an uncleared post-compact marker"
else
  fail "wrap-reconcile is BLIND to an uncleared post-compact marker — /wrap can print ✅ with the gate unrun"
fi
if echo "$_pc_without" | grep -q " PENDING"; then
  fail "wrap-reconcile reports PENDING with NO marker present — the check is unconditional, not a check"
else
  pass "wrap-reconcile is silent when no marker exists (the assertion discriminates)"
fi
# The probe must survive the no-transcript early-exit: a marker is a fact on disk and does not
# depend on a readable transcript. The synthetic sid above has no jsonl, which is exactly that path.
#
# ...but the two assertions above only prove the WARNING PRINTS. A regression that keeps the print
# and drops the `findings.push()` would leave the ✅ reachable with the gate unrun — the exact
# wired-but-inert class. So assert the BLOCK, not the banner: drive the real script past its
# transcript gate via `--transcript` + `--json`, and require the finding to be IN `findings[]`
# (verdict is computed from `findings` alone). Mutation-valid: delete the `findings.push` and this
# goes RED while the two banner assertions above stay green.
_pc_tx="$(mktemp -d)/fake.jsonl"; printf '{"type":"user"}\n' > "$_pc_tx"
printf 'compacted=2026-01-01 00:00:00 UTC trigger=auto focus=no\n' > "$_pc_marker"
# WRAP_RECONCILE_SMOKE_SKIP=step-7h: these two passes assert the post-compact marker, and the step-7h
# trigger scan runs a `git blame` — ~25 s on a full clone, but in CI's blobless partial clone
# (`filter: blob:none`) one on-demand fetch per historical version: this section went from 23-25 s to
# 35-103 minutes of CI time while asserting nothing about triggers. Honoured only for this `zzsmoke-`
# id. The second pass also names a skip id that exists nowhere (`step-zz-stale`), so the last two
# arms below prove, in the production path, that a skip is REPORTED by id and a stale id is LOUD.
_pc_json=$(CLAUDE_CODE_SESSION_ID="$_pc_sid" WRAP_RECONCILE_SMOKE_SKIP=step-7h node scripts/wrap-reconcile.mjs --json --transcript "$_pc_tx" 2>&1 || true)
rm -f "$_pc_marker"
_pc_json_clear=$(CLAUDE_CODE_SESSION_ID="$_pc_sid" WRAP_RECONCILE_SMOKE_SKIP=step-7h,step-zz-stale node scripts/wrap-reconcile.mjs --json --transcript "$_pc_tx" 2>&1 || true)
rm -rf "$(dirname "$_pc_tx")" 2>/dev/null

if echo "$_pc_json" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const j=JSON.parse(s);process.exit((j.findings||[]).some(f=>/ PENDING/.test(f))?0:1)}catch{process.exit(1)}})'; then
  pass "an uncleared marker enters findings[] — it BLOCKS the ✅, not merely prints"
else
  fail "the marker warning prints but never enters findings[] — /wrap can still reach ✅ with the gate unrun (wired-but-inert)"
fi
if echo "$_pc_json_clear" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const j=JSON.parse(s);process.exit((j.findings||[]).some(f=>/ PENDING/.test(f))?1:0)}catch{process.exit(1)}})'; then
  pass "no marker → no post-compact finding (the block discriminates)"
else
  fail "post-compact finding is pushed with NO marker present — unconditional, not a gate"
fi
# Keyed on skipped[], not on the verdict: this fixture is BLIND for unrelated reasons (no tasks dir, no
# session-start anchor), so a verdict check here could not fail. That a skip forces BLIND is proven
# sub-second by wrap-reconcile's --self-test, on the same makeProbe factory production now uses.
if echo "$_pc_json" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const j=JSON.parse(s);process.exit(JSON.stringify(j.skipped)===JSON.stringify(["step-7h"])?0:1)}catch{process.exit(1)}})'; then
  pass "the smoke-only step-7h skip is REPORTED by id in skipped[] — production builds its probe from the self-tested factory"
else
  fail "WRAP_RECONCILE_SMOKE_SKIP=step-7h is not reported as skipped[]==[step-7h] — either the skip is not wired (the arm pays the full trigger scan again) or it went silent"
fi
if echo "$_pc_json_clear" | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const j=JSON.parse(s);process.exit(JSON.stringify(j.skipped)===JSON.stringify(["step-7h"])&&(j.blind||[]).some(b=>b.includes("\"step-zz-stale\""))?0:1)}catch{process.exit(1)}})'; then
  pass "a skip id that matches no probe is LOUD in blind[] (production path), and does not skip anything"
else
  fail "WRAP_RECONCILE_SMOKE_SKIP=step-7h,step-zz-stale: the stale id left no blind[] entry, or skipped[] is not exactly [step-7h] — a typo or a renamed probe would go silent"
fi

if grep -q "post-compact-pending" .claude/skills/wrap/SKILL.md; then
  pass "/wrap Step 0 spec names the post-compact marker check"
else
  fail "/wrap Step 0 does not read .claude/state/post-compact-pending-<sid> (procedural layer missing)"
fi

# ⛔ THE GREP ABOVE IS A PRESENCE CHECK STANDING WHERE A BRANCH CHECK IS NEEDED, AND IT CANNOT
# SEE THE THING THE THREE-BRANCH GATE EXISTS FOR. `post-compact-pending` appears 4 times in that
# spec, so deleting the whole `elif [ -f "$C" ]` branch leaves it PASSING. Measured:
# with the branch removed, the CLEARED and NONE states collapse to one
# verdict — which is the original vacuity (a clear that this session performed reads identically
# to no compaction ever having happened).
#
# So EXECUTE the spec's own gate under all three states instead of grepping for it. The gate is a
# self-contained block in the fenced bash, extracted by its own first and last lines, so this
# cannot drift from what the spec tells a human to run — if someone rewrites the gate, this runs
# the rewrite.
#
# DISCRIMINATING: three states must yield THREE DISTINCT verdicts. Two-of-three is the failure,
# not zero-of-three, and only a state-by-state compare can see it.
_pcgate_run() {                      # $1 = pending|cleared|none · $2 = spec file
  local sid="pcgateprobe$$" out
  rm -f ".claude/state/post-compact-pending-$sid" ".claude/state/post-compact-cleared-$sid"
  case "$1" in
    pending) printf 'compacted=probe trigger=auto focus=no\n' > ".claude/state/post-compact-pending-$sid" ;;
    cleared) printf '2026-01-01T00:00:00Z\n' > ".claude/state/post-compact-cleared-$sid" ;;
  esac
  # Synthetic sid: never collides with a live session's markers, and the two rm's bracket the run
  # so a failing assertion cannot leave state behind for the next arm (or for a real /wrap).
  out=$(CLAUDE_CODE_SESSION_ID="$sid" bash -c "$(awk '/^M="\.claude\/state\/post-compact-pending-/,/^else echo .* GATE CLEAR/' "$2")" 2>&1)
  rm -f ".claude/state/post-compact-pending-$sid" ".claude/state/post-compact-cleared-$sid"
  printf '%s' "$out"
}
_pcgate_spec=".claude/skills/wrap/SKILL.md"
_pcgate_p=$(_pcgate_run pending "$_pcgate_spec")
_pcgate_c=$(_pcgate_run cleared "$_pcgate_spec")
_pcgate_n=$(_pcgate_run none    "$_pcgate_spec")

if [ -n "$_pcgate_p" ] && [ -n "$_pcgate_c" ] && [ -n "$_pcgate_n" ]; then
  pass "Step-0 gate is extractable and runs in all three marker states"
else
  fail "Step-0 gate produced EMPTY output for at least one state — the awk extraction anchors no longer match the spec's gate block (silence is not a pass)"
fi

if [ "$_pcgate_c" != "$_pcgate_n" ]; then
  pass "Step-0 gate DISTINGUISHES a cleared-by-this-session marker from no-marker-ever (the elif is live)"
else
  fail "Step-0 gate reads a cleared marker IDENTICALLY to no marker — the three-branch gate is vacuous on the path that actually fires, so /wrap prints ✅ over an unrun recovery"
fi

if [ "$_pcgate_p" != "$_pcgate_c" ] && [ "$_pcgate_p" != "$_pcgate_n" ]; then
  pass "Step-0 gate reports a PRESENT marker distinctly from both cleared and absent"
else
  fail "Step-0 gate cannot distinguish a live pending marker from a cleared/absent one — the primary branch is dead"
fi
unset _pcgate_p _pcgate_c _pcgate_n _pcgate_spec

# ── The five shapes the first suite never drove — every one of them was a live bug (root cause:
# "every shape the suite never drives is a shape that broke").
# EMPTY MARKER: v1 gated on `readFileSync(...).trim()` truthiness, so a 0-byte file — reachable from
# our own `compact-save.sh` (`> "$marker"` truncates first, `|| true` swallows a mid-write kill during
# a compaction) — silently disarmed the gate while the marker sat on disk.
: > "$_pc_marker"
if CLAUDE_CODE_SESSION_ID="$_pc_sid" node scripts/wrap-reconcile.mjs 2>&1 | grep -q " PENDING"; then
  pass "an EMPTY (0-byte) marker still fires the gate — presence, not content-truthiness"
else
  fail "a 0-byte marker DISARMS the gate — ✅ reachable with the marker on disk"
fi
# FOCUS=YES arm: a sanctioned named-skip must still be reported (the marker tracks the DECISION).
printf 'compacted=x trigger=manual focus=yes\n' > "$_pc_marker"
if CLAUDE_CODE_SESSION_ID="$_pc_sid" node scripts/wrap-reconcile.mjs 2>&1 | grep -q "focus=yes"; then
  pass "focus=yes reports the sanctioned NAMED SKIP (marker still must be cleared)"
else
  fail "focus=yes arm never exercised / does not report"
fi
# NON-ROOT CWD: the path must anchor to the repo, not the caller's cwd. A hook's cwd is not
# guaranteed, and this suite runs from root — so only an explicit `cd` can catch it.
printf 'trigger=auto focus=no\n' > "$_pc_marker"
if ( cd scripts && CLAUDE_CODE_SESSION_ID="$_pc_sid" node wrap-reconcile.mjs 2>&1 | grep -q " PENDING" ); then
  pass "gate fires from a NON-ROOT cwd (marker path anchored to the repo, not \$PWD)"
else
  fail "gate is BLIND from a non-root cwd — cwd-relative marker path"
fi
# FAIL-PATH JSON: the verdict is computed from findings[]; a Stop-hook consumer parses it.
if CLAUDE_CODE_SESSION_ID="$_pc_sid" node scripts/wrap-reconcile.mjs --json 2>/dev/null \
   | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{try{const j=JSON.parse(s);process.exit(Array.isArray(j.findings)&&j.findings.length?0:1)}catch{process.exit(1)}})'; then
  pass "the no-transcript --json path still carries findings[] (Stop-hook consumable)"
else
  fail "fail()'s --json branch omits findings[] — the marker vanishes on the path a Stop hook parses"
fi
rm -f "$_pc_marker"
# EISDIR: an unguarded readFileSync throws uncaught, violating "a broken reconciler must not wedge /wrap".
mkdir -p "$_pc_marker"
CLAUDE_CODE_SESSION_ID="$_pc_sid" node scripts/wrap-reconcile.mjs >/dev/null 2>&1
if [[ $? -eq 0 ]]; then
  pass "a DIRECTORY at the marker path does not wedge the reconciler (exit 0, warn-mode honored)"
else
  fail "reconciler exits NONZERO on an unreadable marker — it wedges the /wrap it guards"
fi
rmdir "$_pc_marker" 2>/dev/null

echo ""
echo "=== agent-definition clause coverage ==="
# Every expert agent (non-template, non-external) should have the no-self-persist clause
missing_clause=0
missing_list=()
for f in .claude/agents/*.md; do
  basename=$(basename "$f")
  case "$basename" in
    _*) continue ;;          # skip template/shared files like _agent-primer.md
    external-*) continue ;;  # skip external-system experts (different MEMORY pattern)
  esac
  if ! grep -q "DO NOT call Edit" "$f" 2>/dev/null; then
    missing_clause=$((missing_clause+1))
    [[ ${#missing_list[@]} -lt 5 ]] && missing_list+=("$basename")
  fi
done
if [[ $missing_clause -eq 0 ]]; then
  pass "all expert agent definitions have no-self-persist clause"
else
  fail "no-self-persist clause missing from $missing_clause agent(s): ${missing_list[*]}"
fi

echo ""
echo "=== session-manifest.py self-test (WIRING an until-now zero-runner guard) ==="
# `session-manifest.py self-test` guards the identity invariant, the manifest evidence-tag
# storage format, the Bash write-harvest, the mail-receipt turn-outcome field and fleet-claim
# mutual exclusion — and until 2026-08-02 it was invoked by NOTHING: not this suite, not
# .githooks/pre-push, not CI. A guard in a location no runner executes advertises enforcement
# it does not have (the zero-runner convention in .claude/rules/tests-unit.md), so its checks
# could rot silently while every surface reported green. Wiring it here costs ~1s.
#
# Read the COUNTS, not just the exit code: the banner self-counts (`N/N pass`, never a typed
# literal), so a suite that silently stopped running cases would still exit 0 while the number
# fell. The floor below is deliberately a FLOOR, not an equality — adding a case must not RED
# this arm, but deleting the whole block must.
sm_st_out=$(python3 scripts/session-manifest.py self-test 2>&1); sm_st_rc=$?
assert_eq "session-manifest self-test exits 0" "0" "$sm_st_rc"
assert_not_contains "session-manifest self-test reports no failing case" "$sm_st_out" "✗"
sm_st_n=$(printf '%s' "$sm_st_out" | sed -n 's/^self-test: \([0-9]*\)\/[0-9]* pass.*/\1/p')
sm_st_n=${sm_st_n:-0}
if [[ "$sm_st_n" -ge 55 ]]; then
  pass "session-manifest self-test ran $sm_st_n cases (floor 55 — a silently-shrinking suite REDs)"
else
  fail "session-manifest self-test ran only '$sm_st_n' cases (floor 55) — the banner prints only on a pass, so 0 beside a red exit is that red; 0 on exit 0 means the banner changed; 1-54 means cases vanished"
fi
# On a red, print the self-test's own tail: the one failure seen (2026-10-21 promote gate, 0 cases,
# never reproduced) left only the three lines above, so its cause could not be read afterwards.
if [[ "$sm_st_rc" -ne 0 || "$sm_st_n" -lt 55 ]]; then
  printf '%s\n' "$sm_st_out" | tail -20 | sed 's/^/    | /'
fi

echo ""
echo "=== session-manifest.py check-overlap (Phase 3 TIERED BLOCK gate) ==="
# Verify the BLOCK/WARN tiering shipped 2026-05-30. This is a
# blocking enforce mechanism (exit 2 halts /expert-review Step 2a) with no other
# regression coverage — exactly the enforce-layer-drift class this suite exists
# to catch. FF_MANIFEST_DIR/FF_LOGS_DIR isolate to temp so the live
# active-sessions/ dir is never polluted (a residual synthetic manifest would
# trigger false overlaps in real audits).
sm_tmp="$(mktemp -d)"
sm_logs="$(mktemp -d)"
sm_sessions="$(mktemp -d)"
mkdir -p "$sm_tmp"
cat > "$sm_tmp/zz999999.md" <<'SMEOF'
# Session manifest: zz999999

- **Last activity:** 2026-05-30T00:00:00Z
- **Work subject:** SMOKE SYNTHETIC PEER
- **Files touched (2):**
  - `src/lib/zz-smoke-synthetic.ts`
  - `.claude/skills/zz-smoke/MEMORY.md`
SMEOF
# 2026-06-10: the overlap gate now requires a LIVE jsonl (mtime < OVERLAP_LIVE_HOURS)
# for a peer to count as active — a manifest alone no longer blocks. Give the
# synthetic PEER a FRESH jsonl (mtime=now) so Cases 1/3/5-control still BLOCK, AND
# an OWN jsonl + pinned CLAUDE_CODE_SESSION_ID so own_session_path() resolves to a
# non-peer sid — else it'd pick the peer's jsonl as "own" and exclude the peer
# manifest, hiding the overlap.
: > "$sm_sessions/zz999999-smoke.jsonl"
: > "$sm_sessions/abcdef12-self.jsonl"   # HEX prefix: current_sid() hex-validates the [:8]
_saved_ccsid="${CLAUDE_CODE_SESSION_ID:-}"
export CLAUDE_CODE_SESSION_ID="abcdef12-self"

# Case 1: code-file overlap → BLOCK + exit 2
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions" python3 scripts/session-manifest.py check-overlap src/lib/zz-smoke-synthetic.ts 2>&1); ec=$?
assert_eq "code/migration overlap → exit 2 (BLOCK)" "2" "$ec"
assert_contains "BLOCK banner emitted" "$out" "BLOCK MODE"

# Case 2: coordination-file overlap → WARN + exit 0
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions" python3 scripts/session-manifest.py check-overlap .claude/skills/zz-smoke/MEMORY.md 2>&1); ec=$?
assert_eq "coordination-file overlap → exit 0 (WARN)" "0" "$ec"
assert_contains "WARN banner emitted (not BLOCK)" "$out" "WARN MODE"

# Case 3: code-file overlap + --allow-overlap → downgrade to exit 0
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions" python3 scripts/session-manifest.py check-overlap src/lib/zz-smoke-synthetic.ts --allow-overlap 2>&1); ec=$?
assert_eq "--allow-overlap downgrades BLOCK → exit 0" "0" "$ec"
assert_contains "override banner emitted" "$out" "Override active"

# Case 4: no overlap → exit 0 + clean message
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions" python3 scripts/session-manifest.py check-overlap "src/lib/zz-unrelated-$$.ts" 2>&1); ec=$?
assert_eq "no overlap → exit 0" "0" "$ec"
assert_contains "clean no-overlap message" "$out" "no overlap"

# Fire log written to the ISOLATED dir, not the live one
if [[ -f "$sm_logs/scope-overlap-fires.jsonl" ]]; then
  pass "fires logged to isolated FF_LOGS_DIR (not live .claude/logs)"
else
  fail "fires logged to isolated FF_LOGS_DIR (not live .claude/logs)"
fi
# Confirm no synthetic residue leaked into the live active-sessions dir
if [[ ! -f ".claude/state/active-sessions/zz999999.md" ]]; then
  pass "no synthetic manifest leaked into live active-sessions/"
else
  fail "no synthetic manifest leaked into live active-sessions/"
  rm -f .claude/state/active-sessions/zz999999.md
fi

# Case 5 (2026-06-09): peer has EXITED (terminal SessionEnd marker in STATE_DIR) →
# dropped from the manifest channel → the same code-file that BLOCKed in Case 1 now
# returns no overlap. Closes the "defends against already-wrapped-and-closed peers"
# gap — the manifest layer now reads the lifecycle marker it was previously blind to.
# (Channel 2 git-working-tree still backstops real uncommitted danger separately.)
sm_state="$(mktemp -d)"
: > "$sm_state/session-finished-zz999999"
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions" FF_STATE_DIR="$sm_state" python3 scripts/session-manifest.py check-overlap src/lib/zz-smoke-synthetic.ts 2>&1); ec=$?
assert_eq "EXITED peer skipped → code overlap no longer BLOCKs (exit 0)" "0" "$ec"
assert_contains "no-overlap message when sole peer has EXITED" "$out" "no overlap"
# Control: WITHOUT the finished marker the same file still BLOCKs (proves the skip
# is marker-driven, not a test artifact — and that WRAPPED/ACTIVE peers still defend).
sm_state2="$(mktemp -d)"
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions" FF_STATE_DIR="$sm_state2" python3 scripts/session-manifest.py check-overlap src/lib/zz-smoke-synthetic.ts 2>&1); ec=$?
assert_eq "non-exited peer still BLOCKs (exit 2) — skip is marker-driven" "2" "$ec"
rm -rf "$sm_state" "$sm_state2"

# Case 6 (2026-06-10, staleness gate): peer manifest exists + NOT exited, but its
# jsonl is absent/stale (idle > OVERLAP_LIVE_HOURS) → dropped from the manifest
# channel → the same code-file that BLOCKed in Case 1 returns no overlap. This is
# the load-bearing dead-peer drop: a crash/kill leaves no `session-finished` marker,
# so the jsonl mtime (not the marker) is the always-observable liveness signal.
# Empty FF_SESSIONS_DIR = no jsonl for zz999999 = treated as dead.
sm_sessions_empty="$(mktemp -d)"
out=$(FF_MANIFEST_DIR="$sm_tmp" FF_LOGS_DIR="$sm_logs" FF_SESSIONS_DIR="$sm_sessions_empty" python3 scripts/session-manifest.py check-overlap src/lib/zz-smoke-synthetic.ts 2>&1); ec=$?
assert_eq "stale/absent-jsonl peer dropped → code overlap no longer BLOCKs (exit 0)" "0" "$ec"
assert_contains "no-overlap message when peer jsonl is stale/absent" "$out" "no overlap"
rm -rf "$sm_sessions_empty" "$sm_sessions"
# Restore CLAUDE_CODE_SESSION_ID (pinned above so own_session_path didn't pick the peer)
if [[ -n "$_saved_ccsid" ]]; then export CLAUDE_CODE_SESSION_ID="$_saved_ccsid"; else unset CLAUDE_CODE_SESSION_ID; fi
rm -rf "$sm_tmp" "$sm_logs"

echo ""
echo "=== parallel-session-scan (finished-marker EXITED badge) ==="
# parallel-session-scan.py previously could only DISCLAIM "recency != liveness" — it had
# no positive terminated-peer signal. It now reads the SAME session-finished-<sid> marker
# the manifest layer reads (lifecycle_status replica). A peer with the marker is badged
# "✓ EXITED" (shown-but-badged, not dropped — matches the manifest read convention);
# WRAPPED → "⏸ wrapped"; ACTIVE → un-badged. FF_STATE_DIR/FF_SESSIONS_DIR isolate the
# synthetics from live state. '(terminal' is unique to the EXITED header badge in output
# (the NOTE/directive say "terminal" without the paren), so it's the marker-driven discriminator.
pss_state="$(mktemp -d)"; pss_sessions="$(mktemp -d)"
pss_ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
printf '%s\n' "{\"type\":\"user\",\"timestamp\":\"$pss_ts\",\"message\":{\"role\":\"user\",\"content\":\"smoke peer editing zz-scan-synthetic for the badge test, recent enough to surface in the lookback window\"}}" > "$pss_sessions/zzscan01-smoke.jsonl"
: > "$pss_sessions/5e1f5e1f-self.jsonl"   # pin own session (HEX prefix for current_sid) so the scan doesn't claim the peer as self
_saved_ccsid2="${CLAUDE_CODE_SESSION_ID:-}"; export CLAUDE_CODE_SESSION_ID="5e1f5e1f-self"

# FIRE: finished marker present → peer badged "✓ EXITED", still listed
: > "$pss_state/session-finished-zzscan01"
out=$(FF_STATE_DIR="$pss_state" FF_SESSIONS_DIR="$pss_sessions" python3 scripts/parallel-session-scan.py --hours 24 2>&1)
assert_contains "scan: finished marker → peer badged EXITED" "$out" "(terminal"
assert_contains "scan: EXITED peer still LISTED (shown-but-badged, not dropped)" "$out" "zzscan01"

# TOUCH-ONLY (the RED CONTROL that earns the RESUMED arm below — added at the 3-site
# unification). Bump ONLY the jsonl's MTIME past the finished marker, appending NO record.
# The unified derivation (scripts/session_status.py) keys resumption on transcript RECORDS
# precisely because an mtime moves for write-class ops that are NOT a session turn — `touch`,
# os.utime, a copy-back/restore, a sync tool re-materializing the file, a harness flush. So
# this must STAY badged EXITED. Without this control the RESUMED arm below is satisfiable by
# a pure mtime bump, which is what it used to do — it asserted the intent ("a session that
# came back is not EXITED") through a fixture that never simulated a session coming back.
python3 - "$pss_state/session-finished-zzscan01" "$pss_sessions/zzscan01-smoke.jsonl" <<'PY'
import os, sys
m = os.path.getmtime(sys.argv[1])
os.utime(sys.argv[2], (m + 2, m + 2))   # mtime only — no new record
PY
out=$(FF_STATE_DIR="$pss_state" FF_SESSIONS_DIR="$pss_sessions" python3 scripts/parallel-session-scan.py --hours 24 2>&1)
assert_contains "scan (touch-only): newer jsonl MTIME with NO new record → still EXITED (an mtime is not a turn)" "$out" "(terminal"

# lifecycle `status` drives the SAME seam (delegation) — CONTROL arm: marker +
# mtime-only bump ⇒ derive_status says EXITED. NB session-lifecycle resolves transcripts
# via FF_JSONL_DIR (deliberately distinct from FF_SESSIONS_DIR — see _jsonl_dir docstring).
out=$(FF_STATE_DIR="$pss_state" FF_JSONL_DIR="$pss_sessions" python3 scripts/session-lifecycle.py status --session zzscan01 2>&1)
assert_contains "lifecycle status (touch-only control): marker + mtime-only ⇒ EXITED" "$out" "EXITED"

# RESUMED (stale-marker guard, post-mortem fold 2026-07-30): the session took a REAL turn
# after its exit marker → the marker is a stale one-way latch → ACTIVE, no EXITED badge.
# Mirrors session-manifest.py lifecycle_status and session-lifecycle.py derive_status — all
# three now import the same derivation. Pre-fix (bare existence check) this arm REDs —
# mutation re-proven on THIS arm's own synthetic fixture (re-run 2026-08-02: fixture B,
# a real record 2s past the marker — SSOT ACTIVE vs pre-fix EXITED; the live observation below
# was a DIFFERENT instrument and could not discharge the proof on its own, per the
# same-instrument rule). The live motivating case: two sessions writing 0 min ago
# were badged "✓ EXITED" into /expert-review briefs. The record is appended with a UTC timestamp
# 2s past the marker; nobody can forge a record, which is why it is the predicate.
python3 - "$pss_state/session-finished-zzscan01" "$pss_sessions/zzscan01-smoke.jsonl" <<'PY'
import datetime, json, os, sys
m = os.path.getmtime(sys.argv[1])
ts = datetime.datetime.fromtimestamp(m + 2, datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
with open(sys.argv[2], 'a') as f:
    f.write(json.dumps({'type': 'assistant', 'timestamp': ts}) + '\n')
os.utime(sys.argv[2], (m + 2, m + 2))
PY
out=$(FF_STATE_DIR="$pss_state" FF_SESSIONS_DIR="$pss_sessions" python3 scripts/parallel-session-scan.py --hours 24 2>&1)
assert_not_contains "scan (resumed): a RECORD newer than the finished marker → NO EXITED badge (stale-latch guard)" "$out" "(terminal"
assert_contains "scan (resumed): resumed peer still listed" "$out" "zzscan01"

# RESUMED through the lifecycle CLI itself: a real record past the marker ⇒ NOT EXITED.
# This is the un-mutation-armed delegation seam the 2026-08-02 triage flagged:
# cmd_status → session_status.derive_status
# → exit_marker_superseded had NO arm — the resumed path was exercised only via the SCAN
# replica above. Mutation: force exit_marker_superseded to return False ⇒ this arm REDs
# (EXITED) while every scan arm above stays green (mutation-run at authoring, 2026-08-02).
out=$(FF_STATE_DIR="$pss_state" FF_JSONL_DIR="$pss_sessions" python3 scripts/session-lifecycle.py status --session zzscan01 2>&1)
assert_contains "lifecycle status (resumed): real record past marker ⇒ ACTIVE via the SSOT seam" "$out" "ACTIVE"
assert_not_contains "lifecycle status (resumed): no EXITED through the delegation seam" "$out" "EXITED"

# CONTROL: remove the marker → ACTIVE → no EXITED badge (proves the badge is marker-driven)
rm -f "$pss_state/session-finished-zzscan01"
out=$(FF_STATE_DIR="$pss_state" FF_SESSIONS_DIR="$pss_sessions" python3 scripts/parallel-session-scan.py --hours 24 2>&1)
assert_not_contains "scan: no marker → ACTIVE peer carries no EXITED badge" "$out" "(terminal"
assert_contains "scan: ACTIVE peer still listed" "$out" "zzscan01"

# WRAPPED: wrapped marker → "⏸ wrapped" badge, NOT EXITED (repeatable, still a coordination risk)
: > "$pss_state/session-wrapped-zzscan01"
out=$(FF_STATE_DIR="$pss_state" FF_SESSIONS_DIR="$pss_sessions" python3 scripts/parallel-session-scan.py --hours 24 2>&1)
assert_contains "scan: wrapped marker → wrapped badge" "$out" "⏸ wrapped"
assert_not_contains "scan: WRAPPED peer not mislabeled EXITED" "$out" "(terminal"

# Sibling lock: env-set-but-NO-match must NOT exclude the most-recent peer as phantom-self.
# Pre-fix `excluded = [jsonls[0]]` dropped the newest peer; post-fix the env-set branch excludes
# only a real startswith-match (here none → []), so the peer survives. RED on the pre-fix sibling.
touch "$pss_sessions/zzscan01-smoke.jsonl"   # force the PEER to be the most-recent jsonl
out=$(FF_STATE_DIR="$pss_state" FF_SESSIONS_DIR="$pss_sessions" CLAUDE_CODE_SESSION_ID="feedface-no-jsonl-here" python3 scripts/parallel-session-scan.py --hours 24 2>&1)
assert_contains "scan: no-match own-sid does NOT exclude the most-recent peer as phantom-self" "$out" "zzscan01"

if [[ -n "$_saved_ccsid2" ]]; then export CLAUDE_CODE_SESSION_ID="$_saved_ccsid2"; else unset CLAUDE_CODE_SESSION_ID; fi
rm -rf "$pss_state" "$pss_sessions"

echo ""
echo "=== session-manifest.py hub-discover + mail-listen --rebroadcast-hours (review-hub push+pull) ==="
# Committed regression coverage for the review-hub push+pull discoverability mechanism, which
# shipped with NO committed RED-control. PULL =
# hub-discover surfaces a live peer hub / skips self / GCs a dead one / KEEPS a live-but-stalled
# one (the liveness gate). PUSH = mail-listen --rebroadcast-hours surfaces the nudge.
# FF_STATE_DIR isolates the review-hub-active-<sid> markers; FF_MANIFEST_DIR is the liveness
# gate (GC only when the session manifest is ALSO absent). CCSID[:8]=5e1f5e1f = own hub sid.
hub_state="$(mktemp -d)"; hub_manifests="$(mktemp -d)"; hub_sessions="$(mktemp -d)"
: > "$hub_sessions/5e1f5e1f-hub.jsonl"   # HEX prefix — current_sid() hex-validates [:8]
_saved_ccsid3="${CLAUDE_CODE_SESSION_ID:-}"; export CLAUDE_CODE_SESSION_ID="5e1f5e1f-hub"
_hbd() { python3 -c "import os,time,sys;os.utime(sys.argv[1],(time.time()-float(sys.argv[2])*3600,)*2)" "$1" "$2"; }

# PULL 1: no markers → silent
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py hub-discover 2>&1); ec=$?
assert_eq "hub-discover: no markers → exit 0" "0" "$ec"
assert_not_contains "hub-discover: no markers → silent" "$out" " live"

# PULL 2: fresh PEER marker + manifest → surfaced
echo x > "$hub_manifests/face0001.md"; date -u +%FT%TZ > "$hub_state/review-hub-active-face0001"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py hub-discover 2>&1)
assert_contains "hub-discover: fresh peer hub → surfaced" "$out" "face0001"

# PULL 3: OWN-sid marker → skipped (a hub isn't told it's the hub)
echo x > "$hub_manifests/5e1f5e1f.md"; date -u +%FT%TZ > "$hub_state/review-hub-active-5e1f5e1f"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py hub-discover 2>&1)
assert_not_contains "hub-discover: own-sid marker → skipped" "$out" "review-hub-active-5e1f5e1f"

# PULL 4: LIVE hub — stale 80h marker + manifest PRESENT → marker KEPT (not GC'd)
date -u +%FT%TZ > "$hub_state/review-hub-active-face0001"; _hbd "$hub_state/review-hub-active-face0001" 80
FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py hub-discover >/dev/null 2>&1
if [[ -f "$hub_state/review-hub-active-face0001" ]]; then _r=0; else _r=1; fi
assert_eq "hub-discover: live-hub stale marker KEPT (session-liveness gate)" "0" "$_r"

# PULL 5: DEAD hub — stale 80h marker + manifest ABSENT → GC'd
date -u +%FT%TZ > "$hub_state/review-hub-active-face0002"; _hbd "$hub_state/review-hub-active-face0002" 80
FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py hub-discover >/dev/null 2>&1
if [[ ! -f "$hub_state/review-hub-active-face0002" ]]; then _r=0; else _r=1; fi
assert_eq "hub-discover: dead-hub stale marker GC'd (session gone)" "0" "$_r"

# PUSH 1: stale OWN marker + --rebroadcast-hours 48 → nudge fires
date -u +%FT%TZ > "$hub_state/review-hub-active-5e1f5e1f"; _hbd "$hub_state/review-hub-active-5e1f5e1f" 50
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py mail-listen --once --rebroadcast-hours 48 2>&1)
assert_contains "mail-listen: stale marker + rebroadcast-hours 48 → nudge fires" "$out" "RE-BROADCAST DUE"

# PUSH 2: --rebroadcast-hours 0 (default/off) + stale marker → silent
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py mail-listen --once 2>&1)
assert_not_contains "mail-listen: rebroadcast OFF (default) → no nudge" "$out" "RE-BROADCAST DUE"

# PUSH 3: fresh marker + --rebroadcast-hours 48 → silent
date -u +%FT%TZ > "$hub_state/review-hub-active-5e1f5e1f"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py mail-listen --once --rebroadcast-hours 48 2>&1)
assert_not_contains "mail-listen: fresh marker → no nudge" "$out" "RE-BROADCAST DUE"

# PUSH 4: stale marker + `.retiring` companion → SILENT. A retiring hub must never be told to
# announce itself: obeying the nudge broadcasts availability against a live successor, which
# hub-discover's own docstring calls a CONFLICT. Measured live 2026-09-04 before the guard.
date -u +%FT%TZ > "$hub_state/review-hub-active-5e1f5e1f"; _hbd "$hub_state/review-hub-active-5e1f5e1f" 50
touch "$hub_state/review-hub-active-5e1f5e1f.retiring"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py mail-listen --once --rebroadcast-hours 48 2>&1)
assert_not_contains "mail-listen: stale marker + .retiring → no nudge (a retiring hub is silent)" "$out" "RE-BROADCAST DUE"

# PUSH 5 — THE CONTROL that makes PUSH 4 mean something. Same stale marker, companion REMOVED:
# the nudge must come BACK.
# ⛔ THIS COMMENT FIRST SAID PUSH 5 GUARDS AGAINST "a guard that suppressed the nudge
# unconditionally", AND THAT REASON IS WRONG — measured, three mutants in a
# detached worktree. Under a blanket `if False:` mute, PUSH 1 reds too, three lines above; PUSH 1
# already covers that mutant, so the stated justification named a job another arm was doing. The
# danger of a wrong reason here is specific: a reader who checks it against PUSH 1, finds it
# already covered, and deletes PUSH 5 as redundant.
# ⭐ WHAT PUSH 5 ACTUALLY CATCHES: a mutant with MEMORY ACROSS INVOCATIONS. The probe was a sticky
# latch — once `.retiring` is seen, drop a sentinel and stay silent forever after — and PUSH 1
# PASSES, PUSH 4 PASSES, PUSH 5 is the ONLY arm that reds.
# WHY IT CANNOT BE FOLDED INTO PUSH 1: the two have IDENTICAL filesystem state at run time (stale
# marker, no companion). They are the same test at two points in the SEQUENCE, and the only thing
# separating them is history — a companion existed and was removed. So PUSH 5's whole discriminating
# power is temporal, and it is unreachable by any arm that does not run after PUSH 4.
# ⚠️ ORDER IS LOAD-BEARING: PUSH 5 must run AFTER PUSH 4. Reordering them silently voids it.
rm -f "$hub_state/review-hub-active-5e1f5e1f.retiring"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" python3 scripts/session-manifest.py mail-listen --once --rebroadcast-hours 48 2>&1)
assert_contains "mail-listen CONTROL: .retiring removed → nudge returns (guard is the retiring file, not a mute)" "$out" "RE-BROADCAST DUE"

# ── SELF-BRANCH: a RETIRING hub must not be prompted to RE-STAMP ──────────────────────────
# `hub-discover`'s own-seat branch (live_count == 0) printed "You ARE the review-hub … ⚠️ re-stamp
# due" and handed over the re-stamp command, keyed on the BASE marker with no companion check.
# Obeying it RESURRECTS the base marker and un-retires the seat in every peer's discovery — a
# STATE CHANGE, not a nag. Found twice independently (a sibling grep; a mutation probe).
#
# ⚠️ THE THIRD ARM IS THE POINT: the fix suppresses the PROMPT, never the BRANCH. A seat that has
# stamped `.retiring` is still the hub and still SERVING — the retirement procedure has it derive
# its queue, preserve the ledger, broadcast and forward BEFORE teardown — so the unconditional
# RE-READ-THE-SPEC block must survive. A blanket guard would pass arms 1 and 2 and silently strip
# the spec reminder from the seat that needs it most.
_hb_self() { FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" \
             CLAUDE_CODE_SESSION_ID="face0001" \
             python3 scripts/session-manifest.py hub-discover 2>&1; }
rm -f "$hub_state"/review-hub-active-*
date -u +%FT%TZ > "$hub_state/review-hub-active-face0001"; _hbd "$hub_state/review-hub-active-face0001" 60

# SELF 1 — CONTROL: stale own marker, no companion → the re-stamp command MUST appear.
out=$(_hb_self)
assert_contains "hub-discover SELF CONTROL: stale own marker → re-stamp command offered" "$out" "date -u +%FT%TZ >"

# SELF 2 — companion present → the prompt and its command are GONE, and the state is named.
touch "$hub_state/review-hub-active-face0001.retiring"
out=$(_hb_self)
assert_not_contains "hub-discover: retiring seat is NOT prompted to re-stamp (would resurrect the marker)" "$out" "date -u +%FT%TZ >"
assert_not_contains "hub-discover: retiring seat gets no 're-stamp due' warning" "$out" "re-stamp due"
assert_contains "hub-discover: retiring seat is told so, positively" "$out" "RETIRING"

# SELF 3 — OVER-SUPPRESSION GUARD. The spec reminder is what a retiring-but-serving hub still
# needs; if a future edit blanket-guards the branch, arms 1-2 stay green and only this reds.
assert_contains "hub-discover: a RETIRING hub still gets the RE-READ-THE-SPEC block (prompt suppressed, branch not)" "$out" "RE-READ THE SPEC"
# SELF 4 — a PARKED (/standby) hub, same shape: no re-stamp prompt or command, the state named, spec kept.
rm -f "$hub_state/review-hub-active-face0001.retiring"; echo "$(date +%s) x" > "$hub_state/session-standby-face0001"
out=$(_hb_self)
assert_not_contains "hub-discover: a PARKED hub is NOT prompted to re-stamp (a fresh mtime advertises a deaf seat)" "$out" "date -u +%FT%TZ >"
assert_contains "hub-discover: a parked hub is told STANDBY, positively" "$out" "STANDBY — owner-parked"
assert_contains "hub-discover: a PARKED hub still gets the RE-READ-THE-SPEC block" "$out" "RE-READ THE SPEC"
rm -f "$hub_state/session-standby-face0001"
# SELF 5 — a PAUSED hub (`/review-hub --pause`): the hold is named and nothing is suppressed, because a
# paused hub still serves (it finishes what runs and sends those verdicts). Control first: no marker, no suffix.
out=$(_hb_self)
assert_not_contains "hub-discover CONTROL: no pause marker → no PAUSED suffix" "$out" "PAUSED by the owner"
echo "$(date +%s) inflight=0 until=owner" > "$hub_state/review-hub-paused-face0001"
out=$(_hb_self)
assert_contains "hub-discover: a PAUSED hub is told so, positively" "$out" "PAUSED by the owner"
assert_contains "hub-discover: a PAUSED hub still gets the RE-READ-THE-SPEC block" "$out" "RE-READ THE SPEC"
# A paused hub still serves, so its marker must keep its re-stamp prompt: the RETIRING and STANDBY
# suffixes above suppress it, and copying their `(not …)` guard into stale_soon would let a serving
# hub age past the 72h floor into STALE-BROADCAST. The own marker here is 60h old, so the prompt is due.
assert_contains "hub-discover: a PAUSED hub is still prompted to re-stamp (paused is not parked)" "$out" "re-stamp due"
# The pause the owner armed on the limit (`/review-hub --pause --when usage>=N`) lifts at the reset by a watch: a recovering
# hub told to wait for the owner's word would never re-arm it (review-hub/SKILL.md § ⏸ step 9).
echo "$(date +%s) inflight=0 until=reset:2026-10-19T03:30:00Z cause=usage>=80" > "$hub_state/review-hub-paused-face0001"
out=$(_hb_self)
assert_contains "hub-discover: a USAGE-paused hub is told the reset's watch lifts it" "$out" "PAUSED at the usage limit"
assert_not_contains "hub-discover: a USAGE-paused hub is NOT told to wait for the owner's word" "$out" "until the owner’s word"
rm -f "$hub_state/review-hub-paused-face0001"
# SELF 6 — a RESTARTED hub. SessionStart's lifecycle gate writes session-exit-resumed-<sid>
# just before hub-discover, so a fresh one is THIS start's restart and the Monitors died with the process. The SELF arms
# above carry no such file and never print it; an hour-old record is a past restart; a parked seat is not re-armed.
echo "$(date +%s) logout" > "$hub_state/session-exit-resumed-face0001"
out=$(_hb_self)
assert_contains "hub-discover: a hub resumed after an exit is told it RESTARTED and to re-arm its Monitors" "$out" "↻ RESTARTED"
echo "$(date +%s) x" > "$hub_state/session-standby-face0001"
out=$(_hb_self)
assert_not_contains "hub-discover: a PARKED restarted hub is not told to re-arm its Monitors" "$out" "RESTARTED"
rm -f "$hub_state/session-standby-face0001"; _hbd "$hub_state/session-exit-resumed-face0001" 1
out=$(_hb_self)
assert_not_contains "hub-discover CONTROL: a resumed record an hour old is a past restart, not this start's" "$out" "RESTARTED"
rm -f "$hub_state/session-exit-resumed-face0001"
# PEER side — a hub parked past the 72h floor keeps its manifest (prune skips STANDBY), so it must tier
# STANDBY, never STALE-BROADCAST, whose "elect ONLY on no-ack" elects over a seat that cannot ack.
echo "$(date +%s) x" > "$hub_state/session-standby-face0003"; printf '# Session manifest: face0003\n' > "$hub_manifests/face0003.md"
date -u +%FT%TZ > "$hub_state/review-hub-active-face0003"; _hbd "$hub_state/review-hub-active-face0003" 73
out=$(_hb_self)
assert_contains "hub-discover: a hub PARKED past the 72h floor tiers STANDBY" "$out" "\`face0003\` STANDBY"
assert_not_contains "hub-discover: a parked hub never reads STALE-BROADCAST (no claim-or-disclaim to a deaf seat)" "$out" "\`face0003\` STALE-BROADCAST"
rm -f "$hub_state/session-standby-face0003" "$hub_state/review-hub-active-face0003" "$hub_manifests/face0003.md"
rm -f "$hub_state"/review-hub-active-*

# The evidence gate: the has_block fp-filter has to be guarded
# at the EXIT CODE, not just the storage boundary — a refactor dropping the assigned_only filter
# (silent re-block) or reading it fleet-wide would stay green under the read_manifest self-test.
# Peer face0004: fresh jsonl (passes the OVERLAP_LIVE_HOURS gate) + a manifest claiming a
# BLOCK-tier code path. [assigned] → WARN exit 0; [observed] → BLOCK exit 2. The proposed path
# is synthetic (never dirty in the real tree) so Channel 2 cannot contaminate the assertion.
: > "$hub_sessions/face0004-peer.jsonl"
printf '# Session manifest: face0004\n\n- **Last activity:** %s\n- **Work subject:** smoke fixture\n- **Files touched (1):**\n  - `src/zz-smoke-evidence-gate.ts` [assigned]\n' "$(date -u +%FT%TZ)" > "$hub_manifests/face0004.md"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" FF_LOGS_DIR="$hub_state" python3 scripts/session-manifest.py check-overlap src/zz-smoke-evidence-gate.ts 2>&1); ec=$?
assert_eq "check-overlap: [assigned]-only code overlap → WARN exit 0 (non-load-bearing for BLOCK)" "0" "$ec"
assert_contains "check-overlap: [assigned] overlap badged, not blocking" "$out" "declared wave scope"
printf '# Session manifest: face0004\n\n- **Last activity:** %s\n- **Work subject:** smoke fixture\n- **Files touched (1):**\n  - `src/zz-smoke-evidence-gate.ts` [observed]\n' "$(date -u +%FT%TZ)" > "$hub_manifests/face0004.md"
out=$(FF_STATE_DIR="$hub_state" FF_MANIFEST_DIR="$hub_manifests" FF_SESSIONS_DIR="$hub_sessions" FF_LOGS_DIR="$hub_state" python3 scripts/session-manifest.py check-overlap src/zz-smoke-evidence-gate.ts 2>&1); ec=$?
assert_eq "check-overlap: [observed] code overlap → BLOCK exit 2 (gate still alive)" "2" "$ec"

if [[ -n "$_saved_ccsid3" ]]; then export CLAUDE_CODE_SESSION_ID="$_saved_ccsid3"; else unset CLAUDE_CODE_SESSION_ID; fi
rm -rf "$hub_state" "$hub_manifests" "$hub_sessions"

echo ""
echo "=== pre-workflow-agenttype-warn (Workflow agentType warn) ==="
# Warn-mode PreToolUse Workflow hook (2026-05-31). Scans tool_input.script for
# agent() calls lacking a lens-matched agentType. Same-commit obligation per
# meta/SKILL.md Check 9 "Expand trigger". JS string literals use ' so the
# shell single-quoted JSON payload stays clean; the hook's jq/python decodes it.
WAHK=".claude/hooks/pre-workflow-agenttype-warn.sh"

# JS string literals use \" (escaped double-quotes) so the shell single-quoted
# JSON payload stays intact; jq/python decodes them and the hook greps the result.
# FIRE 1: 2 agent() calls, neither with agentType → warn + exit 0
p='{"tool_input": {"script": "const a = await agent(\"x\", { schema: S }); const b = await agent(\"y\", { schema: T });"}}'
out=$(printf '%s' "$p" | bash "$WAHK" 2>&1); ec=$?
assert_contains "FIRE: agent() without agentType → warn" "$out" "pre-workflow-agenttype-warn"
sout=$(printf '%s' "$p" | bash "$WAHK" 2>/dev/null)
assert_one_json_doc "PARSE: pre-workflow-agenttype-warn.sh FIRE arm → ONE parseable hookSpecificOutput doc, the escape line survives" "$sout" 'SKIP_WORKFLOW_AGENTTYPE_WARN=1'
assert_eq "SAFE: pre-workflow-agenttype-warn is warn-mode (exit 0 — never blocks a Workflow)" "0" "$ec"

# FIRE 2: agentType:"general-purpose" → warn (even though agentType present)
p='{"tool_input": {"script": "const a = await agent(\"x\", { agentType: \"general-purpose\", schema: S });"}}'
out=$(printf '%s' "$p" | bash "$WAHK" 2>&1)
assert_contains "FIRE: general-purpose agentType → warn" "$out" "general-purpose"

# SAFE 1: every agent() lens-matched (non-generic) → silent
p='{"tool_input": {"script": "const a = await agent(\"x\", { agentType: \"saas-engineer\", schema: S }); const b = await agent(\"y\", { agentType: \"qa-expert\", schema: T });"}}'
out=$(printf '%s' "$p" | bash "$WAHK" 2>&1)
assert_empty "SAFE: all agent() lens-matched → silent" "$out"

# SAFE 2: no agent() calls → silent (early exit)
p='{"tool_input": {"script": "const x = 5; log(\"hi\");"}}'
out=$(printf '%s' "$p" | bash "$WAHK" 2>&1)
assert_empty "SAFE: no agent() calls → silent" "$out"

echo ""
echo "=== delegate-code-review-warn (delegate --code to a peer hub) ==="
# Warn-mode PreToolUse Agent hook. Fires on a code-review-style dispatch when a peer
# is live. The peer-probe is gated behind DELEGATE_REVIEW_FAKE_PEERS for deterministic
# FIRE (the real probe scans this project's session jsonls — not CI-synthesizable).
DCRW=".claude/hooks/delegate-code-review-warn.sh"

# FIRE: code-review dispatch + (faked) peer live → warn + exit 0
out=$(printf '%s' '{"tool_input":{"prompt":"Builder!=breaker code review — find what is WRONG with this diff","subagent_type":"security-expert"}}' | DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>&1); ec=$?
assert_contains "FIRE: --code dispatch + peers → warn" "$out" "delegate-code-review-warn"
sout=$(printf '%s' '{"tool_input":{"prompt":"Builder!=breaker code review — find what is WRONG with this diff","subagent_type":"security-expert"}}' | DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>/dev/null)
assert_one_json_doc "PARSE: delegate-code-review-warn.sh FIRE arm → ONE parseable hookSpecificOutput doc, the mail-send delegate command survives" "$sout" 'scripts/session-manifest.py mail-send'
assert_eq "SAFE: delegate-code-review-warn is warn-mode (exit 0 — never blocks an Agent)" "0" "$ec"

# ── HUB SELF-SKIP — REBUILT 2026-09-02 AFTER A DEFECT IN THE FIRST VERSION ──────────
# ⛔ THE ARMS THIS REPLACES COULD NOT FAIL, AND A MUTATION RUN PROVED IT.
# They drove DELEGATE_REVIEW_FAKE_HUB, and the fixture carried NO session_id — so `$SID`
# was empty, the `elif [[ -n "$SID" ]]` holding the real marker check was never reached,
# and every arm exercised the test-override instead of the code. A probe mutated the hook
# three ways (filename typo, inverted `! -f`, gutting the real `exit 0`) and all three arms
# stayed green through every one. A test-override branch is a shortcut AROUND the code
# under test; an arm that takes it certifies the shortcut.
# So these drive the REAL predicate: a session_id in the fixture, NO override, and a marker
# in a scratch CLAUDE_PROJECT_DIR — the shape :4862 already uses for band-o-inject.
dcrw_dir="$(mktemp -d)"; mkdir -p "$dcrw_dir/.claude/state"
DCRW_P='{"session_id":"smkhub00-0000-0000-0000-000000000000","tool_input":{"prompt":"Builder!=breaker code review — find what is WRONG with this diff","subagent_type":"security-expert"}}'
# SAFE: an armed hub is silent. The marker must be found by the REAL check.
: > "$dcrw_dir/.claude/state/review-hub-active-smkhub00"
out=$(printf '%s' "$DCRW_P" | CLAUDE_PROJECT_DIR="$dcrw_dir" DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>&1); ec=$?
assert_not_contains "SAFE: an ARMED review-hub does not get told to delegate to itself (REAL marker, no override)" "$out" "delegate-code-review-warn"
assert_eq "SAFE: the hub self-skip is a clean exit 0" "0" "$ec"
# SAFE: a RETIRING hub is silent TOO, and that is
# right: `.retiring` is stamped at step 1 of 7, BEFORE a successor exists (step 4, which may
# end in VACANCY-DECLARED), and the advisory says "delegate to the peer hub via mail-send" in
# those words. Nudging into that window is what the spec calls "One review, N panels".
: > "$dcrw_dir/.claude/state/review-hub-active-smkhub00.retiring"
out=$(printf '%s' "$DCRW_P" | CLAUDE_PROJECT_DIR="$dcrw_dir" DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>&1)
assert_not_contains "SAFE: a RETIRING hub is silent too — .retiring is stamped before a successor exists" "$out" "delegate-code-review-warn"
# FIRE: no marker at all -> an ordinary seat still gets the advisory. This is the arm that
# fails if the skip is widened to everyone, and it is what makes the two SAFE arms mean
# something rather than certifying a hook that never fires.
rm -f "$dcrw_dir/.claude/state/review-hub-active-smkhub00" "$dcrw_dir/.claude/state/review-hub-active-smkhub00.retiring"
out=$(printf '%s' "$DCRW_P" | CLAUDE_PROJECT_DIR="$dcrw_dir" DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>&1)
assert_contains "FIRE: a seat with NO hub marker still gets the delegate advisory (the discriminating control)" "$out" "delegate-code-review-warn"
rm -rf "$dcrw_dir"

# SAFE 1: code-review dispatch but NO peers (faked 0) → silent
out=$(printf '%s' '{"tool_input":{"prompt":"code review this commit","subagent_type":"security-expert"}}' | DELEGATE_REVIEW_FAKE_PEERS=0 bash "$DCRW" 2>&1)
assert_empty "SAFE: --code dispatch but solo → silent" "$out"

# SAFE 2: non-review dispatch (even with peers) → silent (no marker match)
out=$(printf '%s' '{"tool_input":{"prompt":"implement the upload feature in image-uploader.tsx","subagent_type":"saas-engineer"}}' | DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>&1)
assert_empty "SAFE: non-review dispatch → silent" "$out"

# SAFE 3: fork re-uses my context → silent despite the review marker
out=$(printf '%s' '{"tool_input":{"prompt":"code review this","subagent_type":"fork"}}' | DELEGATE_REVIEW_FAKE_PEERS=2 bash "$DCRW" 2>&1)
assert_empty "SAFE: fork subagent → silent" "$out"

echo ""
echo "=== session-lifecycle (done-for-now vs exited signal) ==="
# Non-blocking SessionEnd/SessionStart hooks + session-lifecycle.py. FF_STATE_DIR
# isolates synthetic markers from live .claude/state. Same-commit obligation per
# meta/SKILL.md Check 9 "Expand trigger".
sl_state=$(mktemp -d)
export FF_STATE_DIR="$sl_state"

# WRAPPED: /wrap stamp → derived status WRAPPED. There is no finer verdict to assert.
# ⚠️ DO NOT "STRENGTHEN" THIS TO "WRAPPED (on-hold)" OR ADD A "(reopened …)" ARM.
# Both existed earlier on 2026-08-07 and were REMOVED with the refinement they tested
# (session-lifecycle.py derive_status). The refinement's predicate was repo-GLOBAL, so it
# read reopened for 16/16 live wrap markers, and the session-scoped replacement measured
# identically degenerate — every wrapped session has records after its own stamp, because
# /wrap stamps at Step 0 and keeps writing. A reader asking "parked or still going?" is
# NOT answered by this script at all any more: this line named JSONL_STALE_HOURS until that
# constant and its sweep were removed under the no-hour-based-inference rule below, and a dead constant cited
# in a smoke test is the pointer a maintainer trusts. The honest answer is that only a real
# SessionEnd distinguishes parked from finished, and /exit fires none.
# Re-adding an arm here requires a predicate that DISCRIMINATES on the live population.
CLAUDE_CODE_SESSION_ID="smkwrap1cc" python3 scripts/session-lifecycle.py wrapped >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkwrap1cc" 2>&1)
assert_contains "WRAPPED: /wrap stamp → WRAPPED" "$out" "WRAPPED"
assert_not_contains "WRAPPED: no on-hold/reopened refinement (removed 2026-08-07)" "$out" "reopened"

# SOFT reason (other) must NOT promote to EXITED (only logout/prompt_input_exit are terminal)
python3 scripts/session-lifecycle.py finished --session "smkwrap1cc" --reason other >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkwrap1cc" 2>&1)
assert_contains "SAFE: soft reason (other) stays WRAPPED" "$out" "WRAPPED"

# TRUE exit via SessionEnd hook (stdin JSON, reason=logout — the REAL terminal value the
# harness sends; the old test fed source=exit, a triple-fiction that masked the dead feature)
echo '{"session_id":"smkexit2ff","reason":"logout"}' | bash .claude/hooks/session-end.sh >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkexit2ff" 2>&1)
assert_contains "FIRE: SessionEnd hook (reason=logout) → EXITED" "$out" "EXITED"

# SessionEnd hook with soft reason (clear) → no terminal marker (ACTIVE)
echo '{"session_id":"smkclear03","reason":"clear"}' | bash .claude/hooks/session-end.sh >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkclear03" 2>&1)
assert_contains "SAFE: SessionEnd soft reason (clear) → not EXITED" "$out" "ACTIVE"

# ⛔ NO HOUR-BASED INFERENCE — by rule, an exit mark comes only from a proper session close,
# never from elapsed hours. The jsonl-staleness backstop that
# used to sit here (path 2b, the only signal that caught /exit, which fires NO SessionEnd at
# all per #17885) was REMOVED from session-lifecycle.py, and this arm is INVERTED rather than
# deleted so the removal is defended: a silent transcript must NOT produce an exit verdict.
# The consequence is accepted — an /exit-closed session now reads WRAPPED or ACTIVE forever,
# because an honest "no evidence" beats a plausible guess that lands in the same file, with
# the same shape, as a measured SessionEnd. FF_JSONL_DIR isolates synthetic transcripts.
sl_jsonl=$(mktemp -d)
export FF_JSONL_DIR="$sl_jsonl"
stale_ts=$(date -v-4H '+%Y%m%d%H%M' 2>/dev/null || date -d '4 hours ago' '+%Y%m%d%H%M')
CLAUDE_CODE_SESSION_ID="smkstal4" python3 scripts/session-lifecycle.py wrapped >/dev/null 2>&1
: > "$sl_jsonl/smkstal4-fixture-transcript.jsonl"
touch -t "$stale_ts" "$sl_jsonl/smkstal4-fixture-transcript.jsonl"
python3 scripts/session-lifecycle.py gate --source startup >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkstal4" 2>&1)
assert_contains "SAFE: wrapped + jsonl silent >3h → stays WRAPPED (no hour-based inference)" "$out" "WRAPPED"

# ⛔ THE REMOVED SWEEP HAD **TWO** TRIGGERS AND THE ARM ABOVE DEFENDS ONLY ONE.
# Path 2b was transcript-silence (3h). Path 2a was HEAD-UNMOVED: 18h since the wrap stamp
# AND current HEAD still equal to the sha the marker recorded. The arm above stamps its
# marker at `now`, so 2a can never fire on that fixture — measured on a
# scratch copy: a 19h-old wrap marker at an unmoved HEAD writes `inferred-stale` → EXITED
# under the pre-fix script, and NOTHING in this suite went red if only that half came back.
# The record of the change claimed that re-adding the inference goes red; that was true for
# one path of two until this arm existed.
# The marker format is `<head-sha> <unix-ts> <mode>`, so backdating the TIMESTAMP field
# while leaving the sha equal to live HEAD reproduces 2a exactly.
sl_head=$(git rev-parse HEAD 2>/dev/null || echo 0000000000000000000000000000000000000000)
CLAUDE_CODE_SESSION_ID="smkhead5" python3 scripts/session-lifecycle.py wrapped >/dev/null 2>&1
printf '%s %s wrap\n' "$sl_head" "$(( $(date +%s) - 19 * 3600 ))" > "$sl_state/session-wrapped-smkhead5"
python3 scripts/session-lifecycle.py gate --source startup >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkhead5" 2>&1)
assert_contains "SAFE: wrapped 19h ago + HEAD UNMOVED → stays WRAPPED (the sweep's OTHER trigger)" "$out" "WRAPPED"
assert_not_contains "SAFE: 19h + HEAD unmoved writes no inferred marker" "$out" "inferred"
CLAUDE_CODE_SESSION_ID="smkfrsh6" python3 scripts/session-lifecycle.py wrapped >/dev/null 2>&1
: > "$sl_jsonl/smkfrsh6-fixture-transcript.jsonl"
python3 scripts/session-lifecycle.py gate --source startup >/dev/null 2>&1
out=$(python3 scripts/session-lifecycle.py status --session "smkfrsh6" 2>&1)
assert_contains "SAFE: wrapped + fresh transcript → stays WRAPPED (no false exit)" "$out" "WRAPPED"
unset FF_JSONL_DIR

# SessionStart resume advisory fires for a wrapped, not-finished session.
# Critically: env id (smkreop07) and stdin id (smkreop07cc) must normalize to
# the SAME 8-char key, else writer/reader disagree and the advisory misses.
CLAUDE_CODE_SESSION_ID="smkreop07" python3 scripts/session-lifecycle.py wrapped >/dev/null 2>&1
out=$(echo '{"session_id":"smkreop07cc","source":"resume"}' | bash .claude/hooks/session-start.sh 2>&1)
assert_contains "FIRE: SessionStart resume advisory (env/stdin id normalize-match)" "$out" "REOPENING"

# SessionStart on a fresh (never-wrapped) session → no REOPENING advisory, but the
# blindspot prime block IS now emitted (auto-fire wired into session-start.sh
# 2026-06-09; this was assert_empty before the prime wiring).
out=$(echo '{"session_id":"smkfresh08","source":"startup"}' | bash .claude/hooks/session-start.sh 2>&1)
reopen=$(printf '%s' "$out" | grep -c "REOPENING" || true)
assert_eq "SAFE: SessionStart fresh session → no REOPENING advisory" "0" "$reopen"
assert_contains "FIRE: SessionStart auto-emits the blindspot prime block (2026-06-09)" "$out" "Recurring-blindspot prime"

# RESUMED AFTER AN EXIT (2026-10-20): a review hub
# was restarted; SessionEnd wrote its session-finished marker and the resume brought the
# SAME sid back. The gate now supersedes that sid's own marker (moved to session-exit-resumed-<sid>
# with the resume appended), leaves a PEER's marker alone, and runs AFTER the resume advisory, so a
# wrapped-then-exited session still gets no REOPENING line on that start (the inputs it had before).
echo '{"session_id":"7e57ab1e00","reason":"logout"}' | bash .claude/hooks/session-end.sh >/dev/null 2>&1
echo '{"session_id":"9a8b7c6d00","reason":"prompt_input_exit"}' | bash .claude/hooks/session-end.sh >/dev/null 2>&1
CLAUDE_CODE_SESSION_ID=9a8b7c6d00 python3 scripts/session-lifecycle.py wrapped >/dev/null 2>&1
assert_eq "PRECONDITION: SessionEnd wrote the exit marker the resume must supersede" "1" "$([ -f "$sl_state/session-finished-9a8b7c6d" ] && echo 1 || echo 0)"
# Back-date the exit so this wrap strictly post-dates it: step 4 moves a wrap stamped AT OR BEFORE the exit along
# with the marker, and both stamps land in the same second here, so without this the wrap went too and the ORDER
# arm below passed with step 4 moved above step 3 (245/0). A wrap the move keeps is the only input on
# which the order still changes the advisory; the wrap-then-exit arms after this one pin the real-order input.
printf '%s prompt_input_exit\n' "$(( $(date +%s) - 60 ))" > "$sl_state/session-finished-9a8b7c6d"
out=$(echo '{"session_id":"9a8b7c6d00","source":"resume"}' | bash .claude/hooks/session-start.sh 2>&1)
assert_eq "FIRE: a resumed session's OWN session-finished marker is gone after its SessionStart" "0" "$([ -f "$sl_state/session-finished-9a8b7c6d" ] && echo 1 || echo 0)"
rs_body=$(cat "$sl_state/session-exit-resumed-9a8b7c6d" 2>/dev/null)
assert_contains "FIRE: the superseded exit is kept, with its reason" "$rs_body" "prompt_input_exit"
assert_contains "FIRE: the superseded exit records the resume" "$rs_body" "resumed source=resume"
reopen=$(printf '%s' "$out" | grep -c "REOPENING" || true)
assert_eq "ORDER: the resume advisory still reads the pre-supersede state (wrapped + exited → no REOPENING)" "0" "$reopen"
out=$(python3 scripts/session-lifecycle.py status --session 9a8b7c6d00 2>&1)
assert_not_contains "FIRE: the resumed session no longer reads EXITED" "$out" "EXITED"
assert_eq "SAFE: a PEER's exit marker is untouched by another session's start" "1" "$([ -f "$sl_state/session-finished-7e57ab1e" ] && echo 1 || echo 0)"
# The REAL order is wrap THEN exit (no turn runs after SessionEnd). lifecycle_status silences a wrap
# that predates the exit only while the exit marker exists, so moving the marker alone made the
# resumed seat read WRAPPED to every peer (hub-discover: not LIVE; mail-await --peer-done: GO).
printf 'deadbeef %s wrap\n' "$(( $(date +%s) - 120 ))" > "$sl_state/session-wrapped-5a5a5a5a"
echo '{"session_id":"5a5a5a5a00","reason":"logout"}' | bash .claude/hooks/session-end.sh >/dev/null 2>&1
out=$(echo '{"session_id":"5a5a5a5a00","source":"resume"}' | bash .claude/hooks/session-start.sh 2>&1)
assert_eq "ORDER: wrap-then-exit, resumed → still no REOPENING on that start" "0" "$(printf '%s' "$out" | grep -c "REOPENING" || true)"
out=$(python3 scripts/session-lifecycle.py status --session 5a5a5a5a00 2>&1)
assert_contains "FIRE: a wrap stamped BEFORE the exit does not speak after the resume (ACTIVE, not WRAPPED)" "$out" "ACTIVE"
assert_contains "FIRE: the superseded wrap is kept on record" "$(cat "$sl_state/session-exit-resumed-5a5a5a5a" 2>/dev/null)" "superseded-wrap deadbeef"

# Drift sentinels in session-start.sh (2026-07-16; patterns anchored to each
# script's FINDING VOCABULARY after a review — a blind-state net-hole + 4 FP
# breadth). Assert WIRED + emit-parse mutation-validity: audit-tier fires on a real finding AND the
# BLIND/vacuous state, silent on clean (incl. a 40-row scan + the benign un-backfilled ops line);
# surface-register fires on a finding/✗ DRIFT, silent on its own name-bearing clean line.
# i18n-prose (3.5s) deliberately stays /orient-only. Patterns MIRROR the hook (keep in sync).
sstart_src=$(cat .claude/hooks/session-start.sh)
assert_contains "WIRED: session-start drift-sentinel block (audit-tier)" "$sstart_src" "audit-tier-drift-check.mjs"
assert_contains "WIRED: session-start drift-sentinel block (surface-register)" "$sstart_src" "surface-register-drift.mjs"
assert_not_contains "SAFE: i18n-prose (3.5s) NOT wired into session-start" "$sstart_src" "i18n-prose-drift.mjs 2>/dev/null"
AT_PAT='TOTAL flows\+features drift findings: [1-9]|[1-9][0-9]* drift finding|vacuous pass'
dr_fire=$(printf 'features — 2 drift finding(s)\n' | grep -iE "$AT_PAT" || true)
assert_contains "FIRE: audit-tier catches a real finding" "$dr_fire" "2 drift finding"
dr_blind=$(printf '  ⚠️ 0 rows scanned — probable format drift (vacuous pass, not clean)\n' | grep -iE "$AT_PAT" || true)
assert_contains "FIRE: audit-tier catches the BLIND/vacuous state (blind-state net-hole)" "$dr_blind" "vacuous pass"
dr_fp2=$(printf '  ⓘ Audit Tiers column un-backfilled → a BACKFILL task, not a drift-fix.\n' | grep -iE "$AT_PAT" || true)
assert_eq "SAFE: audit-tier silent on the benign un-backfilled ops line" "" "$dr_fp2"
dr_clean=$(printf 'flows — 0 drift finding(s)\n' | grep -iE "$AT_PAT" || true)
assert_eq "SAFE: audit-tier silent on a 0-drift line" "" "$dr_clean"
dr_clean40=$(printf '  ✓ clean — every audit marker has its token key (40 rows scanned)\n' | grep -iE "$AT_PAT" || true)
assert_eq "SAFE: audit-tier silent on a clean 40-row scan (vacuous-pass anchor, not 0-rows-scanned)" "" "$dr_clean40"
SR_PAT='finding\(s\)|✗ DRIFT|NO-SSOT|NOT-IN-MATRIX'
sr_fire=$(printf 'surface-register-drift — 2 finding(s) · 19 row vectors / 19 matrix surfaces\n' | grep -E "$SR_PAT" || true)
assert_contains "FIRE: surface-register catches a finding-summary" "$sr_fire" "finding(s)"
sr_drift=$(printf '  ✗ DRIFT         S2   security  row=x matrix=y\n' | grep -E "$SR_PAT" || true)
assert_contains "FIRE: surface-register catches a ✗ DRIFT detail" "$sr_drift" "DRIFT"
sr_clean=$(printf '✓ surface-register-drift: rows ↔ matrix agree (19 row vectors / 19 matrix surfaces)\n' | grep -E "$SR_PAT" || true)
assert_eq "SAFE: surface-register silent on the clean agree line (name-drift no longer leaks)" "" "$sr_clean"

# ---------------------------------------------------------------------------
# mail-listen reconnect-leak fix (2026-07-16): session-keyed pid file + kill-0/ps guard
# + SessionEnd teardown. Guards the primary leak (source=resume re-arming a DUPLICATE),
# the ① lowercased-key convention (a re-introduced ${SID:0:8} REDs the mixed-case rows),
# and the ② armed-marker GC (teardown must remove it or a resumed session under-arms).
# ---------------------------------------------------------------------------
ML_S8="smkmail9"                                    # SMKMAIL999 -> .lower()[:8]
ML_PF=".claude/state/mail-listen-$ML_S8.pid"
ML_MK=".claude/state/mail-listen-armed-$ML_S8"
# (b-dead + ①) mixed-CASE sid + DEAD pid at the LOWERCASED key → re-arms + cleans the stale file.
rm -f "$ML_PF" "$ML_MK"; echo 999999 > "$ML_PF"
out=$(echo '{"session_id":"SMKMAIL999","source":"resume"}' | bash .claude/hooks/session-start.sh 2>&1)
assert_eq "mail-listen guard: mixed-case sid + DEAD pid at lowercased key → re-arms (①+dead-path)" "1" "$(printf '%s' "$out" | grep -c 'MAIL-LISTEN' || true)"
assert_eq "mail-listen guard: stale dead-pid file cleaned" "0" "$([ -f "$ML_PF" ] && echo 1 || echo 0)"
# (a-teardown + ①②) SessionEnd removes BOTH the pid file AND the armed-marker at the lowercased key.
echo 999999 > "$ML_PF"; touch "$ML_MK"
echo '{"session_id":"SMKMAIL999","reason":"logout"}' | bash .claude/hooks/session-end.sh >/dev/null 2>&1
assert_eq "mail-listen teardown: pid file removed at lowercased key (①)" "0" "$([ -f "$ML_PF" ] && echo 1 || echo 0)"
assert_eq "mail-listen teardown: armed-marker removed at lowercased key (②)" "0" "$([ -f "$ML_MK" ] && echo 1 || echo 0)"
# (b-live) a LIVE process at the lowercased key whose command IS a mail-listen → guard SKIPS re-arm.
# Deterministic fake: `exec -a` sets the ps command; writing the pid file directly avoids the
# real-listener pid-write timing race (a spawned python's write is non-deterministic in a loaded suite).
rm -f "$ML_PF" "$ML_MK"
( exec -a "python3 scripts/session-manifest.py mail-listen --poll 30" sleep 30 ) &
ML_LIVE=$!; echo "$ML_LIVE" > "$ML_PF"
out=$(echo '{"session_id":"SMKMAIL999","source":"resume"}' | bash .claude/hooks/session-start.sh 2>&1)
assert_eq "mail-listen guard: LIVE listener at lowercased key → does NOT re-arm (reconnect leak fixed)" "0" "$(printf '%s' "$out" | grep -c 'MAIL-LISTEN' || true)"
kill "$ML_LIVE" 2>/dev/null; wait "$ML_LIVE" 2>/dev/null || true
rm -f "$ML_PF" "$ML_MK"

# Consume terminus (signal-gated-Stop chain close): a PEER that FINISHED w/o a
# session-memory-done-<day> marker + committed work → one-line backstop advisory.
# FF_FAKE_COMMITS makes the commit-count gate deterministic (else FIRE depends on
# the live repo having >=2 commits "today").
ct_state=$(mktemp -d); export FF_STATE_DIR="$ct_state"
: > "$ct_state/session-finished-smkpeera"   # fresh peer exit, no done-marker
ctf=$(FF_FAKE_COMMITS=3 CLAUDE_CODE_SESSION_ID="smkmail999" python3 scripts/session-lifecycle.py gate --source startup 2>&1 >/dev/null)
assert_contains "FIRE: peer EXITED w/o /session-memory + commits → consume-terminus advisory" "$ctf" "no /session-memory"
touch "$ct_state/session-memory-done-$(date +%Y-%m-%d)"
cts=$(FF_FAKE_COMMITS=3 CLAUDE_CODE_SESSION_ID="smkmail999" python3 scripts/session-lifecycle.py gate --source startup 2>&1 >/dev/null)
sup=$(printf '%s' "$cts" | grep -c "smkpeera" || true)
assert_eq "SAFE: session-memory-done marker suppresses the advisory" "0" "$sup"
rm -f "$ct_state/session-memory-done-$(date +%Y-%m-%d)"
ctl=$(FF_FAKE_COMMITS=1 CLAUDE_CODE_SESSION_ID="smkmail999" python3 scripts/session-lifecycle.py gate --source startup 2>&1 >/dev/null)
low=$(printf '%s' "$ctl" | grep -c "smkpeera" || true)
assert_eq "SAFE: <2 commits that day → no advisory (not worth surfacing)" "0" "$low"
# own-session-skip: clear peers, seed ONLY the current sid's finished marker → no self-advisory (session-lifecycle.py own-sid guard)
rm -f "$ct_state"/session-finished-*
: > "$ct_state/session-finished-smkmail9"   # CLAUDE_CODE_SESSION_ID=smkmail999 normalizes to sid "smkmail9"
cto=$(FF_FAKE_COMMITS=3 CLAUDE_CODE_SESSION_ID="smkmail999" python3 scripts/session-lifecycle.py gate --source startup 2>&1 >/dev/null)
ownc=$(printf '%s' "$cto" | grep -c "no /session-memory" || true)
assert_eq "SAFE: own-session finished marker is skipped (no self-advisory)" "0" "$ownc"
# >24h-staleness cutoff: a peer finished outside the fresh-exit window → no advisory
touch -t "$(date -v-25H '+%Y%m%d%H%M' 2>/dev/null || date -d '25 hours ago' '+%Y%m%d%H%M')" "$ct_state/session-finished-smkoldpr"
cta=$(FF_FAKE_COMMITS=3 CLAUDE_CODE_SESSION_ID="smkmail999" python3 scripts/session-lifecycle.py gate --source startup 2>&1 >/dev/null)
stalec=$(printf '%s' "$cta" | grep -c "smkoldpr" || true)
assert_eq "SAFE: peer finished >24h ago → outside fresh-exit window, no advisory" "0" "$stalec"
export FF_STATE_DIR="$sl_state"; rm -rf "$ct_state"

unset FF_STATE_DIR
# Leak guard: synthetic markers must NOT land in the live .claude/state
if [[ ! -f ".claude/state/session-wrapped-smkwrap1" && ! -f ".claude/state/session-finished-smkexit2" ]]; then
  pass "no synthetic lifecycle marker leaked into live .claude/state"
else
  fail "no synthetic lifecycle marker leaked into live .claude/state"
  rm -f .claude/state/session-wrapped-"smkwrap1" .claude/state/session-finished-"smkexit2"
fi
rm -rf "$sl_state"

# ---------------------------------------------------------------------------
# Blindspot prime --render (the session-start spotlight; single render source
# shared by session-start.sh + /orient Step 9). Added 2026-06-09.
# ---------------------------------------------------------------------------
out=$(python3 scripts/meta-corrections-scan.py --prime --render 2>/dev/null)
assert_contains "FIRE: --prime --render emits the spotlight header" "$out" "Recurring-blindspot prime"
assert_contains "FIRE: --prime --render labels the #1 pattern" "$out" "#1 "
assert_contains "FIRE: --prime --render attaches a counter-action to #1" "$out" "events) —"
raw=$(python3 scripts/meta-corrections-scan.py --prime 2>/dev/null)
assert_contains "FIRE: --prime (raw TSV) still works (backward-compat)" "$raw" "corrections-prime:"

echo ""
echo "=== band-governor-framing-warn (warn — count-as-justification) ==="
# Git-state-driven pre-push hook (reads BASE_REF..HEAD via cwd git), so it needs a throwaway
# repo fixture, not an stdin payload. Same-commit obligation per meta/SKILL.md Check 9
# "Expand trigger" — this hook shipped 2026-08-07 WITHOUT an arm and a later check caught
# it in the same wrap that shipped it.
bgf_tmp=$(mktemp -d)
git -C "$bgf_tmp" init -q
git -C "$bgf_tmp" config user.email "smoke@""test.local"
git -C "$bgf_tmp" config user.name smoke
git -C "$bgf_tmp" commit -q --allow-empty -m "base"
bgf_base=$(git -C "$bgf_tmp" rev-parse HEAD)
mkdir -p "$bgf_tmp/.claude/rules"
printf 'row\n' > "$bgf_tmp/.claude/rules/active-recall.md"
git -C "$bgf_tmp" add .claude/rules/active-recall.md
git -C "$bgf_tmp" commit -q -m "rules: extend a row — cap-neutral, hot tier stays 36"
# FIRE: a GOVERNED file + count-framing in the message -> warn, exit 0
cd "$bgf_tmp"
out=$(bash "$REPO_ROOT/.claude/hooks/band-governor-framing-warn.sh" "$bgf_base" 2>&1); ec=$?
cd "$REPO_ROOT"
assert_contains "FIRE: governed file + count-framing -> warn" "$out" "BAND-GOVERNOR FRAMING"
assert_eq "SAFE: band-governor-framing-warn is warn-mode (exit 0 — never blocks)" "0" "$ec"
# SAFE 1: same governed file, message justified by CONTENT rather than the count -> silent
git -C "$bgf_tmp" commit -q --amend -m "rules: extend the row because the trigger family already overlaps"
cd "$bgf_tmp"
out=$(bash "$REPO_ROOT/.claude/hooks/band-governor-framing-warn.sh" "$bgf_base" 2>&1)
cd "$REPO_ROOT"
assert_empty "SAFE: content-justified message on a governed file -> silent" "$out"
# SAFE 2: count-framing but the file is NOT governed -> silent (the file-gate, not the regex)
printf 'x\n' > "$bgf_tmp/README.md"
git -C "$bgf_tmp" add README.md
git -C "$bgf_tmp" commit -q -m "docs: cap-neutral, hot tier stays 36"
cd "$bgf_tmp"
out=$(bash "$REPO_ROOT/.claude/hooks/band-governor-framing-warn.sh" "$bgf_base" 2>&1)
cd "$REPO_ROOT"
assert_empty "SAFE: ungoverned file with count-framing -> file-gate holds (silent)" "$out"
rm -rf "$bgf_tmp"

echo "=== migration-commit-msg-warn (warn — migration audit-trail) ==="
# Git-state-driven pre-push hook (reads commits in BASE_REF..HEAD via cwd git), so it
# needs a throwaway repo fixture, not an stdin payload — which is why it had ZERO
# coverage until 2026-06-06. Same-commit obligation per meta/SKILL.md
# Check 9 "Expand trigger".
mch_tmp=$(mktemp -d)
git -C "$mch_tmp" init -q
git -C "$mch_tmp" config user.email "smoke@""test.local"
git -C "$mch_tmp" config user.name smoke
git -C "$mch_tmp" commit -q --allow-empty -m "base"
mch_base=$(git -C "$mch_tmp" rev-parse HEAD)
mkdir -p "$mch_tmp/supabase/migrations"
printf 'select 1;\n' > "$mch_tmp/supabase/migrations/9001_smoke.sql"
git -C "$mch_tmp" add supabase/migrations/9001_smoke.sql
git -C "$mch_tmp" commit -q -m "feat: add smoke table"
# FIRE: migration commit with NO environment-application status note → warn, exit 0
cd "$mch_tmp"
out=$(bash "$REPO_ROOT/.claude/hooks/migration-commit-msg-warn.sh" "$mch_base" 2>&1); ec=$?
cd "$REPO_ROOT"
assert_contains "FIRE: migration commit w/o status note → warn" "$out" "lacks environment-application status"
assert_eq "SAFE: migration-commit-msg-warn is warn-mode (exit 0 — never blocks a commit)" "0" "$ec"
# SAFE 1: amend message to include a status phrase → silent
git -C "$mch_tmp" commit -q --amend -m "feat: add smoke table — migrations 9001 staging+prod applied"
cd "$mch_tmp"
out=$(bash "$REPO_ROOT/.claude/hooks/migration-commit-msg-warn.sh" "$mch_base" 2>&1)
cd "$REPO_ROOT"
assert_empty "SAFE: migration commit WITH status note → silent" "$out"
# SAFE 2: range with no migration files → silent
mch_head=$(git -C "$mch_tmp" rev-parse HEAD)
git -C "$mch_tmp" commit -q --allow-empty -m "chore: docs only"
cd "$mch_tmp"
out=$(bash "$REPO_ROOT/.claude/hooks/migration-commit-msg-warn.sh" "$mch_head" 2>&1)
