echo ""
echo "=== expand-before-code-warn (warn — unapplied migration + a live src read) ==="
# NEW class (second occurrence, 2026-07-26):
# code reading a column whose migration is unapplied 42703s the ENTIRE shared query.
# Same fixture shape as migration-commit-msg-warn above (git-state-driven, needs a
# throwaway repo, not an stdin payload). EXPAND_BEFORE_CODE_LOG is redirected so a
# suite run never appends to the live calibration log (the FF_MEM_ALLOW_MARKER rule).
ebc_tmp=$(mktemp -d)
git -C "$ebc_tmp" init -q
git -C "$ebc_tmp" config user.email "smoke@""test.local"
git -C "$ebc_tmp" config user.name smoke
git -C "$ebc_tmp" commit -q --allow-empty -m "base"
ebc_base=$(git -C "$ebc_tmp" rev-parse HEAD)
mkdir -p "$ebc_tmp/supabase/migrations" "$ebc_tmp/src/services"
printf 'ALTER TABLE widgets\n  ADD COLUMN IF NOT EXISTS smoke_flag_id uuid;\n' > "$ebc_tmp/supabase/migrations/9101_smoke.sql"
printf 'export const q = { smokeFlagId: widgets.smokeFlagId };\n' > "$ebc_tmp/src/services/smoke.ts"
git -C "$ebc_tmp" add supabase/migrations/9101_smoke.sql src/services/smoke.ts
git -C "$ebc_tmp" commit -q -m "feat(smoke): smoke-flag mechanism — migration 9101"
# FIRE: unapplied migration + a src read of its new column (snake OR camel) → warn, exit 0
cd "$ebc_tmp"
out=$(EXPAND_BEFORE_CODE_LOG="$ebc_tmp/fires.jsonl" bash "$REPO_ROOT/.claude/hooks/expand-before-code-warn.sh" "$ebc_base" 2>&1); ec=$?
cd "$REPO_ROOT"
assert_contains "FIRE: unapplied migration + live src read → warn" "$out" "expand-before-code"
assert_contains "FIRE: names the offending column" "$out" "smoke_flag_id"
assert_eq "SAFE: expand-before-code is warn-mode (exit 0 — never blocks a push)" "0" "$ec"
# ESCAPE: the documented bypass silences the SAME fixture
cd "$ebc_tmp"
out=$(SKIP_EXPAND_BEFORE_CODE=1 EXPAND_BEFORE_CODE_LOG="$ebc_tmp/fires.jsonl" bash "$REPO_ROOT/.claude/hooks/expand-before-code-warn.sh" "$ebc_base" 2>&1)
cd "$REPO_ROOT"
assert_empty "ESCAPE: SKIP_EXPAND_BEFORE_CODE=1 silences it" "$out"
# SAFE: an applied-notation commit for the same number → silent
git -C "$ebc_tmp" commit -q --allow-empty -m "chore(migration): 9101 staging+prod applied"
cd "$ebc_tmp"
out=$(EXPAND_BEFORE_CODE_LOG="$ebc_tmp/fires.jsonl" bash "$REPO_ROOT/.claude/hooks/expand-before-code-warn.sh" "$ebc_base" 2>&1)
cd "$REPO_ROOT"
assert_empty "SAFE: 'NNNN staging+prod applied' notation → silent" "$out"
rm -rf "$ebc_tmp"
# Behavioral self-test (arm list and mutation matrix: the hook's own header).
# Asserts the PASS LINE, not just rc — a killed hook exits 0 with no output, which an
# rc-only assertion would read as green (the liveness bound).
# ⚠ ", 0 failed" ALONE IS ALSO SATISFIED BY "0 passed, 0 failed", so an EMPTIED arm list read
# green. The passed count is pinned to a FLOOR — the hook's ASSERTION
# count (its "N passed"), NOT its arm count: 83 assertions over 55 arms since 2026-09-29 (72
# over 47 on 2026-09-23; 51 over 32 on 2026-09-21; the HEAD-read fold added 16 over 10, the
# index-plane fold 3 over 3, the population/colour fold 2 over 2, the insert-site fold 5 over 4,
# its review fold 5 over 3, its fold-verify 1 over 1), so reconciling this against the arm count
# would lower it to 55 and silently permit deleting 28
# assertions. Adding assertions stays green; deleting one
# reddens until the floor is lowered on purpose in the same diff. The observed count goes in the FAILURE text only,
# never the label (a per-run value in a label reads as a vanished assertion to a comparator).
EBC_SELFTEST_FLOOR=83
# Run with the git location variables cleared: a pre-push hook fired from a LINKED worktree inherits
# GIT_DIR=<repo>/.git/worktrees/<n>, and this self-test runs `git init` + `git config` + commits in its own temp
# dirs, which would then write the SHARED .git/config (core.bare=true) and commit fixtures onto the pushing branch.
ebc_st="$(env -u GIT_DIR -u GIT_WORK_TREE -u GIT_INDEX_FILE -u GIT_COMMON_DIR -u GIT_OBJECT_DIRECTORY -u GIT_ALTERNATE_OBJECT_DIRECTORIES -u GIT_NAMESPACE -u GIT_PREFIX bash "$REPO_ROOT/.claude/hooks/expand-before-code-warn.sh" --self-test 2>&1)"
assert_contains "self-test: expand-before-code-warn --self-test all-green" "$ebc_st" ", 0 failed"
ebc_passed="$(printf '%s\n' "$ebc_st" | sed -n 's/^[[:space:]]*\([0-9][0-9]*\) passed, 0 failed[[:space:]]*$/\1/p' | tail -1)"
if [ -n "$ebc_passed" ] && [ "$ebc_passed" -ge "$EBC_SELFTEST_FLOOR" ]; then
  pass "self-test: expand-before-code-warn ran at least its pinned assertion count (an emptied list is not green)"
else
  fail "self-test: expand-before-code-warn ran at least its pinned assertion count (an emptied list is not green) (floor=$EBC_SELFTEST_FLOOR passed='${ebc_passed:-no counts line}')"
fi

echo ""
echo "=== log-user-slash-commands.sh (telemetry capture-gap closure 2026-06-16) ==="
# UserPromptSubmit logger for user-typed slash commands (the half the Skill-tool
# logger can't see). Unlike log-skill-invocations (PreToolUse Skill — synthetic
# payloads unreliable, existence-only skip), UserPromptSubmit IS easy to
# synthesize: feed {"prompt":"/cmd"} and assert the log delta. The fires land in a sandbox
# project (below), never the analyzed log (skill-invocations.jsonl); the sentinel session is the counting key.
# SANDBOXED (2026-10-06):
# the hook resolves BOTH its log dir (:35) and its skill lookup (:74) from
# CLAUDE_PROJECT_DIR, so the fires go to a mktemp project holding only the names the arms need. Until then
# they wrote into the fleet-shared skill-invocations.jsonl and a read-filter-`mv` cleanup rewrote that
# whole ledger, losing any peer row appended between the grep and the mv on every smoke run, and every
# push gate runs this suite against the shared .claude/logs. Nothing here writes to the
# shared ledger now; the leak check at the end still reads it, keyed on this run's sentinel.
# The sandbox holds exactly what each arm needs, so each arm is decided by the predicate its label names:
# `orient` for the skill FIRE; `meta`, so the mid-sentence '/meta' arm is held by the leading-slash rule
# alone (without it, the missing skill dir backstops that arm and a hook logging any `/word` passes); and a
# commands file the real repo lacks, which both exercises the commands branch and fails if the skill lookup
# stops reading CLAUDE_PROJECT_DIR (`orient` exists in both places, so its arm cannot tell).
USLC_ROOT="$(mktemp -d)"
mkdir -p "$USLC_ROOT/.claude/logs" "$USLC_ROOT/.claude/skills/orient" "$USLC_ROOT/.claude/skills/meta" "$USLC_ROOT/.claude/commands"
: > "$USLC_ROOT/.claude/commands/uslc-sandbox-cmd.md"
USLC_LOG="$USLC_ROOT/.claude/logs/skill-invocations.jsonl"
USLC_REAL_LOG="$REPO_ROOT/.claude/logs/skill-invocations.jsonl"
USLC_SENTINEL="smoke-uslc-$$"
# ⛔ COUNT ONLY THIS RUN'S SENTINEL LINES, never the whole file. `wc -l` over a SHARED log
# makes the delta assertion below read 2 whenever a peer invokes any skill inside the
# before/after window — a RED that is not the suite's, costing the next seat a diagnosis
# round on somebody else's activity. Measured 2026-08-12: failed once, passed on re-run.
# The sentinel already exists (USLC_SENTINEL, unique per run via $$) and lands in the
# logged line as "session" — it was created for isolation and then not used for counting.
# `grep -c` PRINTS 0 and EXITS 1 on no-match, so `$(... || echo 0)` yields the two-line
# string "0\n0" (codified trap). Capture, then default the empty case instead.
uslc_count() { local n; n=$(grep -cF "$USLC_SENTINEL" "$USLC_LOG" 2>/dev/null); echo "${n:-0}"; }
# ⛔ THE SENTINEL GOES IN THE PAYLOAD, NOT THE ENVIRONMENT — corrected 2026-09-02, and the old
# form is why a 100%-broken field was green for the life of this arm. It set
# `CLAUDE_SESSION_ID="$USLC_SENTINEL"` on the hook's env; the harness sets
# `CLAUDE_CODE_SESSION_ID` and never that, so the arm supplied the one variable production does
# not, proved the code path works when it IS set, and was structurally incapable of noticing
# that every real record read `session:"unknown"` (4,341 of 4,341, both writers, measured).
# The fixture-supplies-the-variable vacuous control, in its purest form: the fixture was the
# only thing in the system providing the input under test.
# Passing it in the payload preserves BOTH jobs the sentinel already had — per-run isolation and
# the counting key — and converts the arm into a discriminating one: revert the hook to reading
# the env var and the sentinel never lands, so `uslc_count` reads 0 and every FIRE assertion
# below goes RED. Verified both ways at authoring (payload-only → recorded; nothing anywhere →
# `unknown`).
uslc_fire() { printf '{"session_id":"%s","prompt":%s}' "$USLC_SENTINEL" "$1" | CLAUDE_PROJECT_DIR="$USLC_ROOT" bash .claude/hooks/log-user-slash-commands.sh; }

# FIRE: real command skill /orient → 1 line
b=$(uslc_count); uslc_fire '"/orient"'; a=$(uslc_count)
assert_eq "FIRE on '/orient' (real skill) → 1 log line" "1" "$((a-b))"

# FIRE: plugin-namespaced /vercel:deploy prod → 1 line, args captured
b=$(uslc_count); uslc_fire '"/vercel:deploy prod"'; a=$(uslc_count)
assert_eq "FIRE on '/vercel:deploy prod' (plugin :) → 1 log line" "1" "$((a-b))"
assert_contains "FIRE captures args + source" "$(tail -1 "$USLC_LOG")" '"source":"user-prompt"'
assert_contains "FIRE captures the args text itself" "$(tail -1 "$USLC_LOG")" '"args":"prod"'

# FIRE: a .claude/commands/*.md command that exists only in the sandbox → 1 line
b=$(uslc_count); uslc_fire '"/uslc-sandbox-cmd"'; a=$(uslc_count)
assert_eq "FIRE on a sandbox-only .claude/commands/*.md command → 1 log line" "1" "$((a-b))"

# SAFE: mid-sentence mention (not a leading slash) → 0 lines
b=$(uslc_count); uslc_fire '"lets run /meta telemetry now"'; a=$(uslc_count)
assert_eq "SAFE mid-sentence '/meta' mention → no log line" "0" "$((a-b))"

# SAFE: prose whose first line holds a colon → 0 lines. Only the leading-slash rule keeps this out: without
# it, the whole line becomes the "command" and its `:` matches the plugin branch of the lookup.
b=$(uslc_count); uslc_fire '"note: run /meta later"'; a=$(uslc_count)
assert_eq "SAFE prose with a colon (no leading slash) → no log line" "0" "$((a-b))"

# SAFE: built-in harness command (no skill dir / command file) → 0 lines
b=$(uslc_count); uslc_fire '"/clear"'; a=$(uslc_count)
assert_eq "SAFE built-in '/clear' (not a skill) → no log line" "0" "$((a-b))"

# SAFE: empty prompt → 0 lines
b=$(uslc_count); uslc_fire '""'; a=$(uslc_count)
assert_eq "SAFE empty prompt → no log line" "0" "$((a-b))"

# No cleanup of the shared ledger: nothing above wrote to it. The sandbox goes, and the leak check reads
# the REAL ledger for this run's sentinel (a hook that ignored CLAUDE_PROJECT_DIR would land rows there).
rm -rf "$USLC_ROOT"
# Match the quoted JSON value, not a substring: with no cleanup any more, a leftover row from another run
# whose pid starts with this one's (smoke-uslc-1234 vs smoke-uslc-12345) would otherwise read as a leak.
uslc_key="\"$USLC_SENTINEL\""
uslc_leak=$(grep -cF "$uslc_key" "$USLC_REAL_LOG" 2>/dev/null); uslc_leak="${uslc_leak:-0}"
assert_eq "cleanup: no sentinel lines leak into analyzed log" "0" "$uslc_leak"

echo ""
echo "=== defer-loc-check.sh (defer-residue net) ==="
# A newly-written vague-defer line to todo.txt WITHOUT an LOC estimate → warn.
# Scans only the Edit's new_string (the changed region), never the whole tracker.
dlc() { echo "$1" | DEFER_LOC_NO_LOG=1 bash .claude/hooks/defer-loc-check.sh 2>&1; }
# STDOUT-ONLY sibling of dlc(): warn_emit writes stderr FIRST, so the merged stream dlc() returns
# can never parse as one JSON document.
dlc_stdout() { echo "$1" | DEFER_LOC_NO_LOG=1 bash .claude/hooks/defer-loc-check.sh 2>/dev/null; }
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"foo","new_string":"- [ ] Refactor the usage ledger — monitor post-launch, revisit later"}}')
assert_contains "FIRE: vague-defer to todo.txt, no LOC → warn" "$out" "DEFER-LOC WARNING"
sout=$(dlc_stdout '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"foo","new_string":"- [ ] Refactor the usage ledger — monitor post-launch, revisit later"}}')
assert_one_json_doc "PARSE: defer-loc-check.sh vague-defer arm → ONE parseable hookSpecificOutput doc, the directive survives" "$sout" ': no defer without an LOC estimate'
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"foo","new_string":"- [ ] Refactor — post-launch; ~12 LOC; trigger: when 1K MAU"}}')
assert_empty "SAFE: defer carries an LOC estimate → silent" "$out"
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/notes.md","old_string":"a","new_string":"- [ ] thing post-launch revisit later"}}')
assert_empty "SAFE: non-todo.txt file → silent" "$out"
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [x] Refactor — SHIPPED post-launch (revisit later)"}}')
assert_empty "SAFE: defer being CLOSED (SHIPPED) → silent" "$out"
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Add dark-mode toggle to settings"}}')
assert_empty "SAFE: neutral open todo (no vague-defer vocab) → silent" "$out"
out=$(echo '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"foo","new_string":"- [ ] thing post-launch revisit later"}}' | SKIP_DEFER_LOC_CHECK=1 bash .claude/hooks/defer-loc-check.sh 2>&1)
assert_empty "SAFE: SKIP_DEFER_LOC_CHECK=1 escape → silent" "$out"

# --- OVERSIZE-PAYLOAD arm: the gate must survive a payload past the ~1 MB execve cap ---
# The payload used to ride an ENV VAR. macOS caps env+args at ~1 MB (bisected on the dev box:
# 1,019 KB ok / 1,024 KB E2BIG); past it `execve` fails, python never starts, and bash's non-zero
# is swallowed by the script's trailing `exit 0` — the harness logged `exitCode: 0` and the gate
# was SILENTLY OPEN, 21x in one session, every one on todo.txt. Now the payload goes via a temp
# FILE and the env var carries only a path. This arm is the regression guard: it FIREs on a 1.6 MB
# payload, so reverting to the env-var form REDs here instead of failing open in production.
# Mutation-checked at fix time: the pre-fix hook emitted "Argument list too long" + rc=0 on this
# exact input while the same small-payload arms above stayed green — i.e. size-selective, which is
# why the fire-log looked healthy throughout.
big_defer_payload=$(python3 -c '
import json
print(json.dumps({"tool_name":"Edit",
  "tool_input":{"file_path":"/x/todo.txt","old_string":"foo",
                "new_string":"- [ ] Refactor the ledger — monitor post-launch, revisit later"},
  "_bulk":"z"*1600000}))')
out=$(dlc "$big_defer_payload")
assert_contains "FIRE: 1.6 MB payload still reaches the gate (execve-cap)" "$out" "DEFER-LOC WARNING"
assert_not_contains "SAFE: 1.6 MB payload does NOT E2BIG" "$out" "Argument list too long"

# --- BLOCKER / VERIFIED residue branch (`:unverified-blocker`, 2026-07-12) ---
# The rot-net. The branch originally shipped with ZERO smoke coverage, so the suite's green proved only
# the OLD (LOC-only) behavior while the new regexes could degrade silently — the exact enforce-drift class
# this suite exists to prevent. Each assertion below LOCKS one
# fixed defect; delete a fix and its fixture goes RED.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the tag sweep (~5 LOC) — blocked on the Paddle sandbox"}}')
assert_contains "FIRE: blocker cited, no verified: residue — fires EVEN WITH an LOC (residues independent)" "$out" "blocker-unverified"
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the tag sweep (~5 LOC) — blocked on Paddle. verified: `git log --grep=paddle` -> none"}}')
assert_empty "SAFE: blocker carries a verified: residue + LOC → silent" "$out"
# Negation-escape — the INVERSE-of-intent bug: an EXPLICITLY-unverified blocker must NOT be silenced.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the tag sweep (~5 LOC) — blocked on Paddle. un-verified: no idea yet"}}')
assert_contains "FIRE: 'un-verified:' must NOT satisfy the residue (negation-guard)" "$out" "blocker-unverified"
# Incidental-backtick escape — a stray command elsewhere on the line is not a verification CUE.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the ledger fix (~5 LOC) — blocked on the migration; see `git blame` for auth history"}}')
assert_contains "FIRE: incidental backticked cmd is NOT a residue (VERIFIED cue-scope)" "$out" "blocker-unverified"
# Reachability — a line whose ONLY defer signal is an UNAMBIGUOUS blocker phrase must reach the check.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Refactor the empty-state copy — needs a design decision"}}')
assert_contains "FIRE: blocker-only defer signal reaches the check (DEFER-lexicon reachability)" "$out" "blocker-unverified"
# DONE position-anchor — blocker PROSE containing 'done' must not be read as a CLOSED item.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the ledger fix (~5 LOC) — blocked on the 0227 migration being done"}}')
assert_contains "FIRE: 'being done' in blocker prose is not a CLOSED item (DONE anchored to item-start)" "$out" "blocker-unverified"
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [x] DONE — was blocked on the 0227 migration, now shipped"}}')
assert_empty "SAFE: genuinely CLOSED item (marker at item-start) → silent" "$out"
# The 'entangled with' anchor — kills the feature-name FP, keeps the documented TP.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Ship the entangled-particles hero animation (~30 LOC) — punt the polish"}}')
assert_empty "SAFE: 'entangled-particles' feature name is not a blocker (entangled-WITH anchor)" "$out"
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the refund fix (~5 LOC) — entangled with the renewal race"}}')
assert_contains "FIRE: 'entangled with X' is still a real blocker (TP kept, zero loss)" "$out" "blocker-unverified"
# --- ITEM-GRAMMAR + TIME-ESTIMATE (2026-07-12 — scripts/defer-loc-fire-triage.mjs measured 47/87=54% of real fires) ---
# FP class: residue (a loc-estimate: field) on a SIBLING line of the same multi-line item → no longer fires.
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] compound-genre coverage\n    trigger: post-launch when genre-link CTR data exists\n    loc-estimate: 1 DB query + decision"}}')
assert_empty "SAFE (item-grammar): defer continuation whose item carries a loc-estimate: field (prose value) → silent" "$out"
# TP: a multi-line item with NO estimate anywhere still fires (item-grammar does not over-suppress).
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Tighten the empty state\n    revisit post-launch, monitor and see"}}')
assert_contains "FIRE (item-grammar): item with a defer continuation + NO estimate anywhere → warn" "$out" "DEFER-LOC WARNING"
# A human-TIME estimate ("~1-2h") must NOT satisfy the LOC requirement (was wrongly accepted by ~\s*[0-9]+).
out=$(dlc '{"tool_name":"Edit","tool_input":{"file_path":"/x/todo.txt","old_string":"a","new_string":"- [ ] Defer the ledger tidy post-launch, ~1-2h of work"}}')
assert_contains "FIRE (time-estimate): a bare '~1-2h' time-estimate is NOT an LOC → warn (unit-anchor fix)" "$out" "DEFER-LOC WARNING"
# --- defer-loc-check-bash.sh (2026-07-12 — closes the Bash-write bypass; extractor → delegates to the same check) ---
dlcb() { printf '%s' "$1" | DEFER_LOC_NO_LOG=1 bash .claude/hooks/defer-loc-check-bash.sh 2>&1; }
out=$(dlcb '{"tool_name":"Bash","tool_input":{"command":"cat >> todo.txt <<EOF\n- [ ] vague thing, revisit post-launch, monitor and see\nEOF"}}')
assert_contains "FIRE (bash): heredoc writes a vague defer with no LOC → warn (Edit|Write bypass closed)" "$out" "DEFER-LOC WARNING"
out=$(dlcb '{"tool_name":"Bash","tool_input":{"command":"cat >> todo.txt <<EOF\n- [ ] thing post-launch — ~10 LOC fix\nEOF"}}')
assert_empty "SAFE (bash): heredoc defer carries an LOC → silent (delegates to the same check)" "$out"
out=$(dlcb '{"tool_name":"Bash","tool_input":{"command":"grep post-launch todo.txt | head"}}')
assert_empty "SAFE (bash): a READ of todo.txt (grep) is not a write → silent" "$out"
out=$(dlcb '{"tool_name":"Bash","tool_input":{"command":"echo hi > /tmp/x.txt"}}')
assert_empty "SAFE (bash): command not writing todo.txt → silent" "$out"
out=$(printf '%s' '{"tool_name":"Bash","tool_input":{"command":"cat >> todo.txt <<EOF\n- [ ] defer post-launch\nEOF"}}' | SKIP_DEFER_LOC_BASH=1 bash .claude/hooks/defer-loc-check-bash.sh 2>&1)
assert_empty "SAFE (bash): SKIP_DEFER_LOC_BASH=1 escape → silent" "$out"
# Mutation-valid extractor tests. (1) — a defer word in the SURROUNDING cmd but the
# heredoc BODY is well-formed (defer + LOC) → silent ONLY if the extractor isolates the body; a
# whole-command fallback would fire on the surrounding bare defer (mutation: break the heredoc regex → RED).
out=$(dlcb '{"tool_name":"Bash","tool_input":{"command":"echo post-launch-note && cat >> todo.txt <<EOF\n- [ ] revisit this post-launch ~8 LOC\nEOF"}}')
assert_empty "SAFE (bash body-isolation): defer word in surrounding cmd, well-formed BODY → silent (extractor isolates the body, not whole-cmd)" "$out"
# (2) — a non-heredoc write path (tee) with a vague no-LOC defer → warn (covers tee-detect + whole-cmd fallback).
out=$(dlcb '{"tool_name":"Bash","tool_input":{"command":"echo \"- [ ] vague thing post-launch\" | tee -a todo.txt"}}')
assert_contains "FIRE (bash tee): a tee-write of a vague no-LOC defer → warn (non-heredoc write path)" "$out" "DEFER-LOC WARNING"

echo ""
echo "=== check-copy-test-orphans.py (copy↔test-orphan — pre-push WARN, synthetic-diff seam) ==="
# Drives the --diff-file injection seam (the script's testability hook, mirroring
# migration-column-acl-check.py --files). FIRE: a synthetic messages/en.json
# value-change that strands a literal a REAL test still references (the exact
# 2026-06-28 flow19 e2e orphan) → must WARN on a stable ORPHAN: line. SAFE: a
# value-change that KEEPS the locator phrase → must stay silent (the FP control).
# Locks the n-gram matcher + the removed-phrase FP filter against silent regex
# degradation. Needle "ORPHAN:" is the verbatim per-finding line prefix.
CTO_DIFF_FIRE="/tmp/cto-smoke-fire-$$.diff"
CTO_DIFF_SAFE="/tmp/cto-smoke-safe-$$.diff"
# FIRE fixture: confirmSpamHint drops "spam, junk, or promotions" — the phrase
# tests/e2e/flow19-password-reset.spec.ts:42 holds in its getByText locator.
cat > "$CTO_DIFF_FIRE" <<'CTOEOF'
diff --git a/messages/en.json b/messages/en.json
--- a/messages/en.json
+++ b/messages/en.json
@@ -361,7 +361,7 @@
       "confirmCommitmentAnchor": "anchor",
-      "confirmSpamHint": "Don't see it? Check your <b>spam, junk, or promotions</b> folder.",
+      "confirmSpamHint": "Don't see it? Check your <b>junk or promotions</b> folder.",
       "confirmResend": "Resend email",
CTOEOF
out=$(python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_FIRE" 2>&1)
ec=$?
assert_contains "FIRE: en.json value drops a phrase a real test holds → ORPHAN warn" "$out" "ORPHAN:"
# ⛔ VALUE PIN + PROPERTY PIN, and the property pin is the one that survives an edit.
# This arm pinned `:42` and the spec grew to
# 85 lines, so the phrase moved to :54 and the arm went red while the DETECTOR WAS FINE —
# its sibling "ORPHAN:" assertion stayed green and it was emitting one MORE orphan than
# the arm knew about. A line NUMBER legitimately moves every time anyone edits that spec,
# so pinning it trains the next reader to bump the digit without reading it (the
# tests-unit.md documentation-half shape, coverage-removing direction). The value pin is
# KEPT — it catches a detector that stops emitting coordinates at all — and the property
# pin below is what makes a spec edit stop being a false red.
assert_contains "FIRE: names the orphaned e2e test:file" "$out" "tests/e2e/flow19-password-reset.spec.ts:"
assert_orphan_line_holds_phrase "FIRE: the emitted line RESOLVES to the phrase (property, drift-proof)" "$out" \
  "tests/e2e/flow19-password-reset.spec.ts" "spam, junk, or promotions"
assert_eq "SAFE: check-copy-test-orphans is warn-mode (exit 0 — never blocks a push)" "0" "$ec"
# A phrase another LIVE key still renders is ANNOTATED, never suppressed: this fixture's phrase is
# also rendered by Auth.forgotPassword.sentSpamHint, and hiding shared phrases would hide the very
# kind of orphan this checker was built for.
assert_contains "FIRE: a phrase another live key still renders is ANNOTATED, not suppressed" "$out" 'e.g. "Auth.forgotPassword.sentSpamHint"'

# SAFE fixture: value changes around the phrase but KEEPS "spam, junk, or promotions"
# → the locator survives → no orphan.
cat > "$CTO_DIFF_SAFE" <<'CTOEOF'
diff --git a/messages/en.json b/messages/en.json
--- a/messages/en.json
+++ b/messages/en.json
@@ -361,7 +361,7 @@
       "confirmCommitmentAnchor": "anchor",
-      "confirmSpamHint": "Don't see it? Check your <b>spam, junk, or promotions</b> folder.",
+      "confirmSpamHint": "Can't find it? Check your <b>spam, junk, or promotions</b> folder right away.",
       "confirmResend": "Resend email",
CTOEOF
out=$(python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_SAFE" 2>&1)
assert_empty "SAFE: value change KEEPS the locator phrase → silent (FP control)" "$out"

# SAFE: a purely-ADDED key (no old VALUE to strand a test on) → silent.
cat > "$CTO_DIFF_SAFE" <<'CTOEOF'
diff --git a/messages/en.json b/messages/en.json
--- a/messages/en.json
+++ b/messages/en.json
@@ -361,6 +361,7 @@
       "confirmResend": "Resend email",
+      "brandNewKey": "Don't see it? Check your spam, junk, or promotions folder.",
       "confirmResent": "Email resent",
CTOEOF
out=$(python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_SAFE" 2>&1)
assert_empty "SAFE: purely-added key (no stranded old value) → silent" "$out"

# SAFE: the old text survives only as MENTIONS — a comment line and a line marked
# "copy-orphan: mention" — so there is no ORPHAN line, and the skip is REPORTED, never hidden.
# The real old -> new of the rating subheading (changed 2026-09-23); its two hits are
# tests/critique-rating-subheading-gate-copy.test.ts :11 (comment) and :53 (marked). The
# "skipped" assertion is also what stops this arm passing vacuously if those lines ever go.
cat > "$CTO_DIFF_SAFE" <<'CTOEOF'
diff --git a/messages/en.json b/messages/en.json
--- a/messages/en.json
+++ b/messages/en.json
@@ -1675,7 +1675,7 @@
       "heading": "Rate this critique",
-      "subheading": "Only the team sees this. It won't change this critique, but low ratings are what we review to fix the scoring.",
+      "subheading": "Only the team sees this. It won't change this critique, but it's what we review to fix the scoring.",
       "submit": "Send",
CTOEOF
out=$(python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_SAFE" 2>&1)
assert_not_contains "SAFE: old copy quoted only by a comment and a marked line → no ORPHAN" "$out" "ORPHAN:"
assert_contains "SAFE: the skipped mentions are REPORTED, never hidden" "$out" "skipped as MENTIONS"

# _is_mention, one row per leg, hermetic: every comment leg and the marker SKIP, and nothing else
# does. The corpus arms above reach only the `*` leg and the marker; the `//` leg (most of the real
# skips) and an unanchored `p in line` both passed them green.
cto_tbl=$(python3 - <<'CTOPY'
import importlib.util
s = importlib.util.spec_from_file_location("cto", "scripts/check-copy-test-orphans.py")
m = importlib.util.module_from_spec(s); s.loader.exec_module(m)
P = "Old copy here"
rows = [("  // Old copy here", True), ("   * Old copy here", True), ("  /* Old copy here", True),
        ("  {/* Old copy here */}", True), ('x = "Old copy here"; // copy-orphan: mention', True),
        ('expect(getByText("Old copy here")).toBeVisible(); // note', False),
        ('{/* moved */}<p>Old copy here</p>', False), ('/* arg */ "Old copy here",', False),
        ('#label = "Old copy here";', False), ('getByText("Old copy here copy-orphan: mention")', False)]
bad = [r for r in rows if m._is_mention(r[0], P) != r[1]]
print("CTO_TABLE_OK" if not bad else f"CTO_TABLE_BAD {bad}")
CTOPY
)
assert_eq "SAFE/FIRE: _is_mention skips each comment leg and the marker, never a locator" "CTO_TABLE_OK" "$cto_tbl"

# The skip note on the FINDINGS path (a real push has both): the tooltip's old text is quoted by
# `//` comments AND located by live tests.
cat > "$CTO_DIFF_SAFE" <<'CTOEOF'
diff --git a/messages/en.json b/messages/en.json
--- a/messages/en.json
+++ b/messages/en.json
@@ -1,3 +1,3 @@
-      "retryDisabledTooltip": "Usage is being returned. Try again in a moment",
+      "retryDisabledTooltip": "Your usage is being settled. Check back later.",
CTOEOF
cto_out=$(python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_SAFE" 2>&1)
assert_contains "FIRE: findings and mentions together → ORPHAN lines" "$cto_out" "ORPHAN:"
assert_contains "FIRE: findings and mentions together → the skip is still REPORTED" "$cto_out" "skipped as MENTIONS"

# Two changes to one LEAF name in two hunks (many objects hold a `title` or `body`): the first
# strands the flow19 locator. A leaf-keyed dict kept only the second, and this arm went silent.
cat > "$CTO_DIFF_SAFE" <<'CTOEOF'
diff --git a/messages/en.json b/messages/en.json
--- a/messages/en.json
+++ b/messages/en.json
@@ -361,7 +361,7 @@
-      "confirmSpamHint": "Don't see it? Check your <b>spam, junk, or promotions</b> folder.",
+      "confirmSpamHint": "Don't see it? Check your <b>junk or promotions</b> folder.",
@@ -900,7 +900,7 @@
-      "confirmSpamHint": "A different object's hint, reworded here.",
+      "confirmSpamHint": "A different object's hint, reworded again.",
CTOEOF
cto_out=$(python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_SAFE" 2>&1)
assert_contains "FIRE: a same-leaf change in a LATER hunk does not hide the earlier one's orphan" "$cto_out" "tests/e2e/flow19-password-reset.spec.ts:"

# SAFE: per-invocation escape via SKIP_COPY_TEST_ORPHAN_CHECK=1 on the FIRE fixture.
out=$(SKIP_COPY_TEST_ORPHAN_CHECK=1 python3 scripts/check-copy-test-orphans.py --diff-file "$CTO_DIFF_FIRE" 2>&1)
assert_not_contains "SAFE: SKIP_COPY_TEST_ORPHAN_CHECK=1 escape → no ORPHAN warn" "$out" "ORPHAN:"
rm -f "$CTO_DIFF_FIRE" "$CTO_DIFF_SAFE"

echo ""
echo "=== pre-push / self-audit enforce scripts (syntax + self-test) ==="
# Closure (2026-06-18): the hook-completeness gate below covers .claude/hooks/*.sh but is
# BLIND to the enforce SCRIPTS the routines invoke (architecture-counts, memory-config-drift,
# migration-column-acl-check, ...). A silently-broken enforce script (syntax error, a regex that
# stops matching, a no-op after a src refactor) degrades the gate with nothing to catch it -- the
# same enforce-layer drift this suite was built to prevent, one layer over. The list is DERIVED
# from the routines (pre-push + pre-commit + meta self-audit SKILL.md) so a NEW enforce script is
# auto-covered. (a) syntax-check every one (load-breaking); (b) run --self-test for the ones that
# ship one (behavioral regression). Closes the recurrence: memory-config-drift shipped
# 2026-06-18 with a --self-test that ran in ZERO routine.
ENFORCE_SCRIPTS=$(grep -ohE 'scripts/[a-zA-Z0-9_-]+\.(mjs|py|sh)' \
  "$REPO_ROOT/.githooks/pre-push" "$REPO_ROOT/.githooks/pre-commit" \
  "$REPO_ROOT/.claude/skills/meta/SKILL.md" 2>/dev/null | sort -u)
# `architecture-counts` added 2026-09-08 with its first --self-test. Its arms cover ONE thing:
# the Appendix C range-span EXEMPTION, the only subtractive branch in that script — everything
# else there over-reports on failure, while a range regex that matches too much silently exempts
# an L# that genuinely owes a row. Reachability is not assumed: the stem only fires if the
# ENFORCE_SCRIPTS derivation above finds `scripts/architecture-counts.mjs`, which it does via
# `.claude/skills/meta/SKILL.md` (the meta self-audit routine), NOT via either githook.
SELFTEST_STEMS=" memory-config-drift meta-corrections-scan skill-lint focus-visible-staged-check architecture-counts "
n_enforce=$(printf '%s\n' "$ENFORCE_SCRIPTS" | grep -c . || true)
if [ "${n_enforce:-0}" -ge 5 ]; then
  pass "enforce-script discovery: $n_enforce scripts derived from routines"
else
  fail "enforce-script discovery: expected >=5, found ${n_enforce:-0} -- derivation broke (false-green risk)"
fi
# ── EDIT-TIME SYNTAX GATE OVER .claude/hooks/*.sh (2026-08-19) ──────────────────────────────
# The ENFORCE_SCRIPTS loop below derives its set from a `scripts/`-anchored pattern, so it
# STRUCTURALLY CANNOT reach `.claude/hooks/` — 45 files, several of them block-mode PreToolUse.
# `.githooks/pre-push` mutation-gates CHANGED hooks, so this was never zero coverage; it was
# PUSH-TIME and BEHAVIORAL, never EDIT-TIME and STATIC. The difference is the whole point:
# a wired block-mode hook that will not parse is DENYING EVERY CALL from the moment it is
# saved, and push is far too late to learn that. Measured the day this shipped: one apostrophe
# inside a comment inside a single-quoted python payload left `block-subagent-always-loaded-write.sh`
# unparseable WHILE WIRED, and the only thing that caught it was the author running `bash -n`
# by hand — four times, because nothing made it permanent.
# ⚠️ A syntax gate is NOT a liveness gate: parsing proves the file loads, never that it still
# guards. The pre-push mutation matrix remains the arm that proves a hook can still fail.
_hooks_bad=0
for _h in "$REPO_ROOT"/.claude/hooks/*.sh; do
  [ -f "$_h" ] || continue
  bash -n "$_h" 2>/dev/null || { _hooks_bad=$((_hooks_bad+1)); echo "    UNPARSEABLE: $(basename "$_h")"; }
done
# ⛔ NON-EMPTY ASSERTION FIRST — without it this arm PASSES over zero files and prints
# "every .claude/hooks/*.sh parses", which is the false-green the arm three lines up already
# guards against with its own >=5 floor. The precedent was in the author's viewport and the
# gate shipped without it (2026-08-19).
_hooks_seen=$(ls "$REPO_ROOT"/.claude/hooks/*.sh 2>/dev/null | wc -l | tr -d ' ')
if [[ "${_hooks_seen:-0}" -lt 20 ]]; then
  fail "syntax: hook corpus derivation broke — saw ${_hooks_seen:-0} files, expected >=20 (false-green risk)"
elif [[ "$_hooks_bad" -eq 0 ]]; then
  pass "syntax: every .claude/hooks/*.sh parses (bash -n) — a wired hook that will not parse denies every call"
else
  fail "syntax: $_hooks_bad hook(s) FAIL bash -n — if any is wired block-mode it is denying every call right now"
fi

for sp in $ENFORCE_SCRIPTS; do
  [ -f "$REPO_ROOT/$sp" ] || continue   # prose-mentioned-but-renamed -> not a real gate
  base=$(basename "$sp"); stem="${base%.*}"
  # (a) syntax/load check -- the scripts/ analog of `bash -n` on the pre-push itself
  if [[ "$sp" == *.mjs ]]; then
    if node --check "$REPO_ROOT/$sp" 2>/dev/null; then pass "syntax: $base loads (node --check)"
    else fail "syntax: $base FAILS node --check -- won't load, its gate is silently dead"; fi
  elif [[ "$sp" == *.sh ]]; then
    if bash -n "$REPO_ROOT/$sp" 2>/dev/null; then pass "syntax: $base parses (bash -n)"
    else fail "syntax: $base FAILS bash -n -- won't load, its gate is silently dead"; fi
  else
    if python3 -c "import ast,sys; ast.parse(open(sys.argv[1]).read())" "$REPO_ROOT/$sp" 2>/dev/null; then pass "syntax: $base parses (ast)"
    else fail "syntax: $base FAILS ast.parse -- won't load, its gate is silently dead"; fi
  fi
  # (b) behavioral self-test for the ones that ship one
  if [[ "$SELFTEST_STEMS" == *" $stem "* ]]; then
    case "$sp" in
      *.mjs) st_out=$(node "$REPO_ROOT/$sp" --self-test 2>&1); st_rc=$? ;;
      *.sh)  st_out=$(bash "$REPO_ROOT/$sp" --self-test 2>&1); st_rc=$? ;;
      *)     st_out=$(python3 "$REPO_ROOT/$sp" --self-test 2>&1); st_rc=$? ;;
    esac
    if [ "$st_rc" -eq 0 ]; then pass "self-test: $base --self-test PASS"
    else fail "self-test: $base --self-test FAIL -> $(printf '%s' "$st_out" | tail -1)"; fi
  fi
done

echo ""
echo "=== mail-listen-armed-marker.sh (PostToolUse Monitor — per-session arm marker) ==="
# FIRE: a Monitor call whose command arms the mail listener writes the per-session
# marker (key = session_id.lower()[:8], matching scripts/session-manifest.py).
rm -f .claude/state/mail-listen-armed-smk0test 2>/dev/null
echo '{"session_id":"SMK0TEST-aaaa","tool_name":"Monitor","tool_input":{"command":"python3 scripts/session-manifest.py mail-listen --poll 30"}}' | bash .claude/hooks/mail-listen-armed-marker.sh >/dev/null 2>&1
if [ -f .claude/state/mail-listen-armed-smk0test ]; then pass "FIRE: mail-listen Monitor → marker written (lowercased [:8] key)"; else fail "FIRE: mail-listen Monitor should write per-session marker"; fi
rm -f .claude/state/mail-listen-armed-smk0test 2>/dev/null
# SAFE: an unrelated Monitor command (log tail) writes no marker.
rm -f .claude/state/mail-listen-armed-smk1test 2>/dev/null
echo '{"session_id":"smk1test","tool_name":"Monitor","tool_input":{"command":"tail -f deploy.log | grep ERROR"}}' | bash .claude/hooks/mail-listen-armed-marker.sh >/dev/null 2>&1
if [ -f .claude/state/mail-listen-armed-smk1test ]; then fail "SAFE: unrelated Monitor should NOT write marker"; rm -f .claude/state/mail-listen-armed-smk1test; else pass "SAFE: unrelated Monitor → no marker"; fi

echo ""
echo "=== mail-listen-arm-reminder.sh (UserPromptSubmit — arm directive injected into AGENT CONTEXT until armed) ==="
# FIRE: marker absent → directive injected. The LOAD-BEARING path is stdout JSON
# additionalContext (model-VISIBLE). The prior stderr-only version reached the USER only —
# a UserPromptSubmit exit-0 hook's stderr is NOT injected into the model's context — so the
# arm-miss recurred 2026-06-25 despite this hook existing. Assert the model-visible STDOUT
# JSON shape explicitly (not just that the text appears somewhere on a 2>&1 merge).
rm -f .claude/state/mail-listen-armed-smk2test 2>/dev/null
sout=$(echo '{"prompt":"do a thing","session_id":"smk2test"}' | bash .claude/hooks/mail-listen-arm-reminder.sh 2>/dev/null)
if printf '%s' "$sout" | grep -q '"hookEventName": "UserPromptSubmit"' \
   && printf '%s' "$sout" | grep -q '"additionalContext"' \
   && printf '%s' "$sout" | grep -q 'mail-listen --poll 30'; then
  pass "FIRE: unarmed → STDOUT carries UserPromptSubmit additionalContext w/ the arm command (model-visible path)"
else
  fail "FIRE: unarmed → STDOUT must be hookSpecificOutput.additionalContext JSON w/ the arm command (the model-visible path the stderr-only version lacked)"
fi
assert_one_json_doc "PARSE: mail-listen-arm-reminder.sh unarmed arm → ONE parseable hookSpecificOutput doc, the arm command survives (the multi-doc class — the three greps above are substring checks, green on a two-doc stdout that delivers nothing)" "$sout" 'mail-listen --poll 30'
# The idle exception must stay SCOPED: a seat that is owed mail (the review hub, an unanswered
# review request or deploy-hold) keeps re-arming. Unscoped, the exception switched the hub off.
ctx=$(printf '%s' "$sout" | python3 -c 'import json,sys; print(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"])' 2>/dev/null)
if printf '%s' "$ctx" | grep -qF 'review-hub-active' && printf '%s' "$ctx" | grep -qF 'deploy-hold'; then
  pass "SCOPE: mail-listen-arm-reminder.sh idle exception names the review-hub marker and an unanswered deploy-hold as owed-mail cases"
else
  fail "SCOPE: mail-listen-arm-reminder.sh idle exception must name review-hub-active and deploy-hold, or it switches off seats that are waiting for mail"
fi
# SAFE: marker present (session armed) → fully silent (no stdout, no stderr). SMK2TEST-bbbb → same [:8] key.
touch .claude/state/mail-listen-armed-smk2test
out=$(echo '{"prompt":"do a thing","session_id":"SMK2TEST-bbbb"}' | bash .claude/hooks/mail-listen-arm-reminder.sh 2>&1)
assert_empty "SAFE: armed session (marker present) → silent" "$out"
rm -f .claude/state/mail-listen-armed-smk2test 2>/dev/null
# The Monitor tool KILLS every watch at timeout_ms (<=30 min) and the armed marker outlives it, so the
# marker alone cannot say "armed". FIRE: marker + a DEAD listener pid -> the directive re-injects. CONTROL: marker +
# a LIVE mail-listen-shaped pid -> silent (without this arm a hook that ignored the marker would pass the FIRE).
touch .claude/state/mail-listen-armed-smk2test
( exit 0 ) & _ml_dead=$!; wait "$_ml_dead" 2>/dev/null
printf '%s' "$_ml_dead" > .claude/state/mail-listen-smk2test.pid
sout=$(echo '{"prompt":"do a thing","session_id":"smk2test"}' | bash .claude/hooks/mail-listen-arm-reminder.sh 2>/dev/null)
assert_one_json_doc "FIRE: armed marker + DEAD listener pid (Monitor expiry) → the arm directive re-injects" "$sout" 'mail-listen --poll 30'
bash -c 'sleep 30; : mail-listen' & _ml_live=$!
printf '%s' "$_ml_live" > .claude/state/mail-listen-smk2test.pid
out=$(echo '{"prompt":"do a thing","session_id":"smk2test"}' | bash .claude/hooks/mail-listen-arm-reminder.sh 2>&1)
assert_empty "CONTROL: armed marker + LIVE mail-listen pid → silent" "$out"
kill "$_ml_live" 2>/dev/null; wait "$_ml_live" 2>/dev/null
rm -f .claude/state/mail-listen-armed-smk2test .claude/state/mail-listen-smk2test.pid 2>/dev/null
# SAFE: no session_id → silent (no un-clearable every-turn nag).
out=$(echo '{"prompt":"do a thing"}' | bash .claude/hooks/mail-listen-arm-reminder.sh 2>&1)
assert_empty "SAFE: no session_id → silent" "$out"

echo ""
echo "=== keep-warm-armed-marker.sh (PostToolUse CronCreate — per-session keep-warm arm marker; 2026-10-18) ==="
# The mirror of mail-listen-armed-marker.sh. FIRE: a CronCreate whose prompt opens with the
# keep-warm gate's sentinel writes keep-warm-armed-<sid8> (lowercased [:8]) under FF_STATE_DIR.
KW_M=$(cd "$(mktemp -d)" && pwd -P)
echo '{"session_id":"SMK3TEST-aaaa","tool_name":"CronCreate","tool_input":{"cron":"7,22,37,52 * * * *","prompt":"[keep-warm] automated cache keep-alive, scheduled by this session.","recurring":true}}' | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_contains "FIRE: keep-warm CronCreate → keep-warm-armed marker written (lowercased [:8] key)" "$(ls "$KW_M")" "keep-warm-armed-smk3test"
# FIRE: the same timer with its prompt built from keep-warm-gate.py's own SENTINEL, so a reword of the gate that
# leaves this hook's case pattern behind reds here (the arm above pins the hook against a literal, not the gate).
_kw_sent=$(python3 -c 'import ast,sys; t=ast.parse(open(sys.argv[1]).read()); print(next(n.value.value for n in t.body if isinstance(n,ast.Assign) and getattr(n.targets[0],"id","")=="SENTINEL"))' .claude/hooks/keep-warm-gate.py 2>/dev/null)
assert_contains "keep-warm-gate.py SENTINEL read for the marker fixture" "$_kw_sent" "[keep-warm]"
printf '{"session_id":"SMK3SENT-aaaa","tool_name":"CronCreate","tool_input":{"cron":"7,22,37,52 * * * *","prompt":"%s, scheduled by this session.","recurring":true}}' "$_kw_sent" | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_eq "FIRE: CronCreate prompt opening with the gate's SENTINEL → marker written" "1" "$(ls "$KW_M" | grep -cx 'keep-warm-armed-smk3sent' || true)"
# SAFE: an unrelated CronCreate (any other prompt) writes no marker.
echo '{"session_id":"smk4test","tool_name":"CronCreate","tool_input":{"cron":"*/5 * * * *","prompt":"check the deploy"}}' | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_eq "SAFE: unrelated CronCreate → no keep-warm marker" "0" "$(ls "$KW_M" | grep -c 'keep-warm-armed-smk4test' || true)"
# SAFE: a [keep-warm]-prefixed prompt that is NOT the gate's full sentinel is not a timer the gate recognises.
echo '{"session_id":"smk4btst","tool_name":"CronCreate","tool_input":{"cron":"7 * * * *","prompt":"[keep-warm] status check","recurring":true}}' | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_eq "SAFE: [keep-warm] prefix without the full sentinel → no marker" "0" "$(ls "$KW_M" | grep -c 'keep-warm-armed-smk4btst' || true)"
# SAFE: a one-shot (recurring:false) fires once and deletes itself — not a timer.
echo '{"session_id":"smk4ctst","tool_name":"CronCreate","tool_input":{"cron":"7 9 * * *","prompt":"[keep-warm] automated cache keep-alive, x","recurring":false}}' | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_eq "SAFE: one-shot keep-warm CronCreate → no marker" "0" "$(ls "$KW_M" | grep -c 'keep-warm-armed-smk4ctst' || true)"
# FIRE: the gate lstrips before matching, so a leading newline is still the timer.
echo '{"session_id":"smk4dtst","tool_name":"CronCreate","tool_input":{"cron":"7,22,37,52 * * * *","prompt":"\n[keep-warm] automated cache keep-alive, x","recurring":true}}' | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_eq "FIRE: leading-whitespace keep-warm prompt → marker (matches the gate's lstrip)" "1" "$(ls "$KW_M" | grep -c 'keep-warm-armed-smk4dtst' || true)"
# SAFE: no session id → no sid-less marker file.
echo '{"tool_name":"CronCreate","tool_input":{"cron":"7,22,37,52 * * * *","prompt":"[keep-warm] automated cache keep-alive, x","recurring":true}}' | FF_STATE_DIR="$KW_M" bash .claude/hooks/keep-warm-armed-marker.sh >/dev/null 2>&1
assert_eq "SAFE: no session_id → no keep-warm-armed- file" "0" "$(ls "$KW_M" | grep -cx 'keep-warm-armed-' || true)"
rm -rf "$KW_M"

echo ""
echo "=== keep-warm-arm-reminder.sh (UserPromptSubmit — /keep-warm on directive injected into AGENT CONTEXT until armed; 2026-10-18) ==="
# FIRE needs the fleet switch (or a pilot marker) and the gate + tool-deny wired in the REAL settings.json.
