assert_empty "SAFE: SKIP_KEEP_WARM_ARM_REMINDER=1 → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | SKIP_KEEP_WARM_ARM_REMINDER=1 FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
