touch -t "$(date -v-8d +%Y%m%d%H%M 2>/dev/null || date -d '8 days ago' +%Y%m%d%H%M)" "$KW_T/keep-warm-armed-smk5test"
assert_contains "FIRE: marker older than 7 days → reminder fires (job auto-expired)" "$(echo '{"prompt":"x","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>/dev/null)" "/keep-warm on"
