assert_empty "SAFE: keep-warm ping turn → silent" "$(echo '{"prompt":"[keep-warm] automated cache keep-alive","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
assert_empty "SAFE: ping turn with a JSON-escaped leading newline → silent" "$(echo '{"prompt":"\n[keep-warm] automated cache keep-alive","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
touch "$KW_T/keep-warm-off-smk5test"
assert_empty "SAFE: /keep-warm off → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
rm -f "$KW_T/keep-warm-off-smk5test"; touch "$KW_T/session-standby-smk5test"
assert_empty "SAFE: /standby → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
rm -f "$KW_T/session-standby-smk5test" "$KW_T/keep-warm-enabled"
assert_empty "SAFE: no fleet switch and no pilot marker → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
touch "$KW_T/keep-warm-pilot-smk5test"
assert_contains "FIRE: pilot marker alone (no fleet switch) → fires" "$(echo '{"prompt":"x","session_id":"smk5test"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>/dev/null)" "/keep-warm on"
# The wired predicate and the SKILL.md check read CLAUDE_PROJECT_DIR: drive them with a fixture project.
KW_P=$(cd "$(mktemp -d)" && pwd -P); mkdir -p "$KW_P/.claude/skills/keep-warm"; touch "$KW_P/.claude/skills/keep-warm/SKILL.md"
printf '%s' '{"hooks":{"UserPromptSubmit":[{"hooks":[{"command":"x/keep-warm-gate.py"}]}],"PreToolUse":[{"matcher":"","hooks":[{"command":"x/keep-warm-tool-deny.sh"}]}]}}' > "$KW_P/.claude/settings.json"
