printf '%s' '{"hooks":{"UserPromptSubmit":[{"hooks":[{"command":"x/keep-warm-gate.py"}]}],"PreToolUse":[{"matcher":"Bash","hooks":[{"command":"x/keep-warm-tool-deny.sh"}]}]}}' > "$KW_P/.claude/settings.json"
assert_empty "SAFE: tool-deny under a Bash-only matcher (not all tools) → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | CLAUDE_PROJECT_DIR="$KW_P" FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
printf '%s' '{"hooks":{"PreToolUse":[{"matcher":"","hooks":[{"command":"x/keep-warm-tool-deny.sh"}]}]}}' > "$KW_P/.claude/settings.json"
assert_empty "SAFE: gate not wired → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | CLAUDE_PROJECT_DIR="$KW_P" FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
printf '%s' '{"hooks":{"UserPromptSubmit":[{"hooks":[{"command":"x/keep-warm-gate.py"}]}],"PreToolUse":[{"matcher":"","hooks":[{"command":"x/keep-warm-tool-deny.sh"}]}]}}' > "$KW_P/.claude/settings.json"
rm -f "$KW_P/.claude/skills/keep-warm/SKILL.md"
assert_empty "SAFE: keep-warm SKILL.md missing → silent" "$(echo '{"prompt":"x","session_id":"smk5test"}' | CLAUDE_PROJECT_DIR="$KW_P" FF_STATE_DIR="$KW_T" bash .claude/hooks/keep-warm-arm-reminder.sh 2>&1)"
rm -f "$KW_T/keep-warm-pilot-smk5test"
# The marker's lifecycle: a startup has no timer and a resume may restore an EXPIRED-or-not job → session-start
# drops it (the skill's step 3 re-touches a restored job); a compact keeps the session id and its jobs, and a
# clear opens a new session id → the marker stays. The sid is reused so no new session-start anchor is written.
touch "$KW_T/keep-warm-armed-smk6test"
# Another session's armed marker past the 7-day expiry is GC'd by any SessionStart; the fresh one above is the control.
touch -t "$(date -v-8d +%Y%m%d%H%M 2>/dev/null || date -d '8 days ago' +%Y%m%d%H%M)" "$KW_T/keep-warm-armed-smk8test"
echo '{"session_id":"SMK6TEST-aaaa","source":"compact"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/session-start.sh >/dev/null 2>&1
assert_eq "SAFE: SessionStart compact keeps the keep-warm marker" "1" "$(ls "$KW_T" | grep -c 'keep-warm-armed-smk6test' || true)"
assert_eq "FIRE: SessionStart GCs another session's armed marker older than 7 days" "0" "$(ls "$KW_T" | grep -c 'keep-warm-armed-smk8test' || true)"
echo '{"session_id":"SMK6TEST-aaaa","source":"clear"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/session-start.sh >/dev/null 2>&1
assert_eq "SAFE: SessionStart clear keeps the keep-warm marker" "1" "$(ls "$KW_T" | grep -c 'keep-warm-armed-smk6test' || true)"
echo '{"session_id":"SMK6TEST-aaaa","source":"resume"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/session-start.sh >/dev/null 2>&1
assert_eq "FIRE: SessionStart resume drops the keep-warm marker" "0" "$(ls "$KW_T" | grep -c 'keep-warm-armed-smk6test' || true)"
touch "$KW_T/keep-warm-armed-smk6test"
echo '{"session_id":"SMK6TEST-aaaa","source":"startup"}' | FF_STATE_DIR="$KW_T" bash .claude/hooks/session-start.sh >/dev/null 2>&1
assert_eq "FIRE: SessionStart startup drops the keep-warm marker" "0" "$(ls "$KW_T" | grep -c 'keep-warm-armed-smk6test' || true)"
# session-end reads $DIR/.claude/state, so it runs against the fixture project (no shared state touched).
mkdir -p "$KW_P/.claude/state"; touch "$KW_P/.claude/state/keep-warm-armed-smk7test"
echo '{"session_id":"SMK7TEST-aaaa","reason":"other"}' | CLAUDE_PROJECT_DIR="$KW_P" bash .claude/hooks/session-end.sh >/dev/null 2>&1
assert_eq "FIRE: SessionEnd drops the keep-warm marker" "0" "$(ls "$KW_P/.claude/state" | grep -c 'keep-warm-armed-smk7test' || true)"
rm -rf "$KW_T" "$KW_P"

echo ""
echo "=== session-start.sh working-plan pointer (two plan files for one sid → the LAST in byte order, as summary-plan-sync's findPlan resolves it; 2026-10-12) ==="
# Until 2026-10-12 the hook took `head -1`, which on both multi-plan sessions named the stale fragment
# (`…-blocks-<date>.md` sorts before `….md`: hyphen before dot), so the post-compaction re-read path
# pointed at the wrong file. The hook
# honours CLAUDE_PROJECT_DIR, so the arm points it at a scratch root and never touches the real plans/.
# Both arms read the ONE line the hook prints for the plan; the stale name is asserted ABSENT from it,
# the live name PRESENT, so a `head -1` regression REDs the pair and a dead hook REDs the first.
_wpp_dir="$(cd "$(mktemp -d)" && pwd -P)"; mkdir -p "$_wpp_dir/plans" "$_wpp_dir/.claude/state"
touch "$_wpp_dir/plans/session-smk5wpp1-2000-01-01-blocks-2000-01-03.md" "$_wpp_dir/plans/session-smk5wpp1-2000-01-01.md"
out=$(echo '{"session_id":"SMK5WPP1-aaaa","source":"resume"}' | CLAUDE_PROJECT_DIR="$_wpp_dir" bash .claude/hooks/session-start.sh 2>/dev/null | grep -F 'WORKING PLAN (exists)')
assert_contains "FIRE: two plan files for one sid → the hook announces the LAST in byte order (the live plan)" "$out" "plans/session-smk5wpp1-2000-01-01.md —"
assert_not_contains "FIRE: the stale -blocks- fragment is NOT the announced plan" "$out" "-blocks-2000-01-03.md"
rm -rf "$_wpp_dir"

echo ""
echo "=== working-plan-reminder.sh (UserPromptSubmit — plan directive injected into AGENT CONTEXT until plans/session-<sid8>-*.md exists) ==="
# Sibling of mail-listen-arm-reminder.sh (by rule: first message, same mechanism as
# the listener). Self-clear key = the plan file's own existence under the RESOLVED project root, so
# the arms point the hook at scratch roots and never touch the real plans/. FIRE arms assert the
# PARSE (assert_one_json_doc, whole-stdout json.loads), never a substring: a
# substring arm stayed green while a `"` broke the JSON and a backtick silently deleted the spec
# filename. Co-location makes the SAFE arms non-vacuous (a dead hook REDs the FIRE arms in
# the same section), so the 0-byte SAFE shape is kept on purpose.
_wpr_dir="$(mktemp -d)"; mkdir -p "$_wpr_dir/plans"
# FIRE: no plan file for this sid → exactly ONE parseable doc; hookEventName right; the inline spec (its REVIEW LEDGER clause),
# the exact path and the directory searched all survive INSIDE the parsed additionalContext.
sout=$(echo '{"prompt":"do a thing","session_id":"SMK4WPX1-aaaa"}' | CLAUDE_PROJECT_DIR="$_wpr_dir" bash .claude/hooks/working-plan-reminder.sh 2>/dev/null)
assert_contains "FIRE: no plan file → hookEventName is UserPromptSubmit" "$sout" '"hookEventName": "UserPromptSubmit"'
assert_one_json_doc "FIRE: no plan file → ONE parseable doc, inline spec survives in additionalContext" "$sout" "REVIEW LEDGER"
assert_one_json_doc "FIRE: no plan file → exact plans/session-<sid8>-<today>.md path survives in the PARSED context" "$sout" "plans/session-smk4wpx1-$(date +%Y-%m-%d).md"
assert_one_json_doc "FIRE: the directory searched is named in the PARSED context (self-diagnosis)" "$sout" "$_wpr_dir/plans/"
# SAFE: plan file exists (any date suffix) → fully silent (no stdout, no stderr).
touch "$_wpr_dir/plans/session-smk4wpx2-2000-01-01.md"
out=$(echo '{"prompt":"do a thing","session_id":"SMK4WPX2-bbbb"}' | CLAUDE_PROJECT_DIR="$_wpr_dir" bash .claude/hooks/working-plan-reminder.sh 2>&1)
assert_empty "SAFE: plan file exists → silent" "$out"
# SAFE: no session_id → silent (no un-clearable every-turn nag).
out=$(echo '{"prompt":"do a thing"}' | CLAUDE_PROJECT_DIR="$_wpr_dir" bash .claude/hooks/working-plan-reminder.sh 2>&1)
assert_empty "SAFE: no session_id → silent" "$out"
# SAFE: one-shot escape (=1 only) → silent; a stray =0 must NOT bypass (and still parses).
out=$(echo '{"prompt":"do a thing","session_id":"smk4wpx3"}' | SKIP_WORKING_PLAN_REMINDER=1 CLAUDE_PROJECT_DIR="$_wpr_dir" bash .claude/hooks/working-plan-reminder.sh 2>&1)
assert_empty "SAFE: SKIP_WORKING_PLAN_REMINDER=1 → silent" "$out"
sout=$(echo '{"prompt":"do a thing","session_id":"smk4wpx3"}' | SKIP_WORKING_PLAN_REMINDER=0 CLAUDE_PROJECT_DIR="$_wpr_dir" bash .claude/hooks/working-plan-reminder.sh 2>/dev/null)
assert_one_json_doc "FIRE: SKIP_WORKING_PLAN_REMINDER=0 does NOT bypass (and parses)" "$sout" "REVIEW LEDGER"
rm -rf "$_wpr_dir"
# FALLBACK RUNG: CLAUDE_PROJECT_DIR is UNSET in live sessions, so the
# fallback IS the live path. From a SUBDIRECTORY of a scratch git repo, with CLAUDE_PROJECT_DIR unset,
# the hook must resolve the repo ROOT — silent when the root holds the plan, and naming the ROOT (not
# the cwd) on stderr when it does not. A bare $(pwd) fallback fails both.
_wpr_git="$(mktemp -d)"; git -C "$_wpr_git" init -q; mkdir -p "$_wpr_git/plans" "$_wpr_git/sub"
_wpr_root="$(cd "$_wpr_git" && git rev-parse --show-toplevel)"
touch "$_wpr_git/plans/session-smk4wpx4-2000-01-01.md"
out=$(cd "$_wpr_git/sub" && echo '{"prompt":"x","session_id":"smk4wpx4"}' | env -u CLAUDE_PROJECT_DIR bash "$REPO_ROOT/.claude/hooks/working-plan-reminder.sh" 2>&1)
assert_empty "SAFE (fallback rung): cwd = subdir, CLAUDE_PROJECT_DIR unset, plan at repo root → silent" "$out"
serr=$(cd "$_wpr_git/sub" && echo '{"prompt":"x","session_id":"smk4wpx5"}' | env -u CLAUDE_PROJECT_DIR bash "$REPO_ROOT/.claude/hooks/working-plan-reminder.sh" 2>&1 >/dev/null)
assert_contains "FIRE (fallback rung): cwd = subdir, no plan → stderr names the repo ROOT it searched, not the cwd" "$serr" "$_wpr_root/plans/"
rm -rf "$_wpr_git"

echo ""
echo "=== standby-resume-check.sh (UserPromptSubmit — /standby resume directive until the marker clears) + the standby branches of session-start.sh / mail-listen-arm-reminder.sh / session-lifecycle.py (2026-09-23) ==="
# /standby parks a seat: listener stopped, `session-standby-<sid8>` stamped. The marker is
# the STATE; this hook is the wake-up net (one JSON doc per prompt until `resume` clears it), and the two
# arm directives must go quiet on it — the silent re-arm was the measured defect. FF_STATE_DIR isolates the
# lifecycle marker exactly as session-lifecycle.py does; the arm-reminder resolves its state dir off
# CLAUDE_PROJECT_DIR, so it gets a scratch root. Every FIRE arm asserts the PARSE, never a substring.
_sb_state="$(mktemp -d)"
echo "1700000000 deadbeef" > "$_sb_state/session-standby-smk9stby"
_sb_live0=$(grep -cF '"session":"smk9stby"' .claude/logs/standby-resume-fires.jsonl 2>/dev/null)
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"hi"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_contains "FIRE: standby marker → hookEventName is UserPromptSubmit" "$sout" '"hookEventName":"UserPromptSubmit"'
assert_one_json_doc "FIRE: standby marker → ONE parseable doc, the lifecycle resume command survives in additionalContext" "$sout" "session-lifecycle.py resume"
assert_one_json_doc "FIRE: the arm command survives in the PARSED context (resume step 2)" "$sout" "mail-listen --poll 30"
assert_one_json_doc "FIRE: the not-the-owner guard survives (a notification turn must stay parked)" "$sout" "NOT AN OWNER MESSAGE"
serr=$(printf '{"session_id":"SMK9STBY-1234","prompt":"hi"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>&1 >/dev/null)
assert_empty "FIRE: standby marker → stderr silent (a verdict probe reads stdout only)" "$serr"
out=$(printf '{"session_id":"other111","prompt":"hi"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>&1)
assert_empty "SAFE: no standby marker for this sid → silent" "$out"
out=$(printf '{"prompt":"hi"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>&1)
assert_empty "SAFE: no session_id → silent" "$out"
out=$(printf '{"session_id":"SMK9STBY-1234","prompt":"hi"}' | SKIP_STANDBY_RESUME_CHECK=1 FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>&1)
assert_empty "SAFE: SKIP_STANDBY_RESUME_CHECK=1 → silent" "$out"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"hi"}' | SKIP_STANDBY_RESUME_CHECK=0 FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: SKIP_STANDBY_RESUME_CHECK=0 does NOT bypass (and parses)" "$sout" "session-lifecycle.py resume"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"hi"}' | SKIP_MAIL_LISTEN_ARM_REMINDER=1 FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: SKIP_MAIL_LISTEN_ARM_REMINDER=1 → the resume directive still parses and says to skip the listener re-arm" "$sout" "skip the listener re-arm"
assert_not_contains "SAFE: SKIP_MAIL_LISTEN_ARM_REMINDER=1 → the resume directive orders no listener arm (/standby resume step 2 skips it)" "$sout" "mail-listen --poll 30"
# WHO IS SPEAKING: a harness-prefixed prompt must NOT be told "THIS PROMPT ENDS IT"; the owner prompt above is the control.
for _sb_p in '<task-notification>\n<task-id>b1</task-id>' '<cross-session-message from=\"uds:/tmp/x.sock\">hi' '# Autonomous loop check\n\nx' '# Autonomous loop tick (dynamic pacing)\n\nx' '<agent-message from=\"ab12cd\">done' '[keep-warm] automated cache keep-alive'; do
  sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"%s"}' "$_sb_p" | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
  assert_one_json_doc "FIRE: harness prompt (${_sb_p:0:14}) → stay-parked line parses" "$sout" "NOT the owner"
  assert_not_contains "SAFE: harness prompt (${_sb_p:0:14}) → NOT told this prompt ends standby" "$sout" "THIS PROMPT ENDS IT"
done
# The /autorun one-shot is NOT a harness prompt any more: the owner armed that timer, so the hook classes
# '[Owner-authorized' as autorun and its prompt ENDS the park like the owner's own message. It sat in the loop above
# until then; this arm is the one that moved out.
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"[Owner-authorized autonomous run — cron fired]"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: /autorun one-shot prompt → the autorun resume directive parses (it ENDS the park)" "$sout" "ONE-SHOT ENDS IT"
assert_not_contains "SAFE: /autorun one-shot prompt → NOT the stay-parked harness line" "$sout" "NOT the owner"
assert_one_json_doc "FIRE: the autorun directive names the keep-warm re-arm (step 2b)" "$sout" "/keep-warm on"
# The rest of what that directive ships — each step is a one-line deletion the three arms above
# survive (measured): clear the marker, re-arm the listener, read the mail, guardrails.
assert_one_json_doc "FIRE: the autorun directive clears the marker (resume step 1)" "$sout" "session-lifecycle.py resume"
assert_one_json_doc "FIRE: the autorun directive re-arms the listener (resume step 2)" "$sout" "mail-listen --poll 30"
assert_one_json_doc "FIRE: the autorun directive reads the queued mail (resume step 3)" "$sout" "/mail check"
assert_one_json_doc "FIRE: the autorun directive keeps the one-shot's guardrails (step 4)" "$sout" "never push, commit local"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"[Owner-authorized WO-N RETRY — one-shot cron fired ~12:01 CET] resume the work order"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: the second /autorun spelling (a RETRY one-shot) → the autorun directive too" "$sout" "ONE-SHOT ENDS IT"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"Your claude.ai usage limit has reset. Continue the task"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: usage-limit reset → the continuation line (resume iff the cut turn was the owner's)" "$sout" "RESUMING a turn a usage limit cut"
touch "$_sb_state/review-hub-active-smk9stby"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"hi"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: a parked REVIEW HUB re-arms with --rebroadcast-hours 48 (review-hub Phase 2)" "$sout" "mail-listen --poll 30 --rebroadcast-hours 48"
assert_one_json_doc "FIRE: a parked REVIEW HUB re-arms the staleness poller (the hub_extra clause)" "$sout" "hub-stale-request-poll.sh"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"[Owner-authorized autonomous run — cron fired]"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: an /autorun one-shot waking a parked HUB → --rebroadcast-hours 48" "$sout" "mail-listen --poll 30 --rebroadcast-hours 48"
assert_one_json_doc "FIRE: an /autorun one-shot waking a parked HUB → the staleness poller" "$sout" "hub-stale-request-poll.sh"
rm -f "$_sb_state/review-hub-active-smk9stby"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"wake up"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "CONTROL: an owner-typed prompt → the resume directive" "$sout" "THIS PROMPT ENDS IT"
# Resume step 2b: /standby step 1b deletes the keep-warm timer, so both resume
# directives must name its re-arm, and the harness line must not (a notification turn stays parked).
assert_one_json_doc "FIRE: owner resume directive names the keep-warm re-arm (step 2b)" "$sout" "/keep-warm on"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"Your claude.ai usage limit has reset. Continue the task"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "FIRE: continuation directive names the keep-warm re-arm (step 2b)" "$sout" "/keep-warm on"
sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"<task-notification>\\n<task-id>b1</task-id>"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
assert_one_json_doc "CONTROL: harness line still parses (step-2b arm below reads a real doc)" "$sout" "NOT the owner"
assert_not_contains "SAFE: harness line → no keep-warm re-arm (stays parked)" "$sout" "/keep-warm on"
# The harness arm's BREADTH: an owner prompt opening with '[' or '#' (an image paste, a backlog ref — both
# measured owner openings on the hook plane) must still end standby; a '['* or '#'* arm reads green without these.
for _sb_o in '[Image #1] this crop looks tight' '#5 a) do that next'; do
  sout=$(printf '{"session_id":"SMK9STBY-1234","prompt":"%s"}' "$_sb_o" | FF_STATE_DIR="$_sb_state" bash .claude/hooks/standby-resume-check.sh 2>/dev/null)
  assert_one_json_doc "CONTROL: owner prompt (${_sb_o:0:10}) → the resume directive, not the harness line" "$sout" "THIS PROMPT ENDS IT"
done
# Fire-log isolation: every FIRE above ran under FF_STATE_DIR, so the LIVE log must not carry this sid and the
# smoke log must (positive control) — keyed on the fixture sid, never a before/after line count of a shared log.
_sb_live=$(grep -cF '"session":"smk9stby"' .claude/logs/standby-resume-fires.jsonl 2>/dev/null)
assert_eq "fire-log: smoke fires never reach the live standby-resume-fires.jsonl (fixture-sid delta)" "${_sb_live0:-0}" "${_sb_live:-0}"
_sb_fires=$(grep -cF '"session":"smk9stby"' .claude/logs/standby-resume-fires.smoke.jsonl 2>/dev/null); [ "${_sb_fires:-0}" -gt 0 ] && pass "fire-log: smoke fires land in the .smoke log (positive control)" || fail "fire-log: smoke fires land in the .smoke log (positive control) — read ${_sb_fires:-0}"
# session-start.sh: the STANDBY branch prints the parked line and SUPPRESSES the arm directive; the same
# sid with no marker is the control and must invert both.
out=$(echo '{"session_id":"SMK9STBY-1234","source":"resume"}' | FF_STATE_DIR="$_sb_state" bash .claude/hooks/session-start.sh 2>&1)
assert_contains "FIRE: session-start under a standby marker → STANDBY line" "$out" "STANDBY: this session was parked by the owner"
assert_not_contains "FIRE: session-start under a standby marker → the ARM directive is SUPPRESSED" "$out" "MAIL-LISTEN (standing directive)"
_sb_ctl="$(mktemp -d)"
out=$(echo '{"session_id":"SMK9STBY-1234","source":"resume"}' | FF_STATE_DIR="$_sb_ctl" bash .claude/hooks/session-start.sh 2>&1)
assert_not_contains "CONTROL: same sid, no marker → no STANDBY line" "$out" "STANDBY: this session was parked by the owner"
assert_contains "CONTROL: same sid, no marker → the ARM directive is emitted" "$out" "MAIL-LISTEN (standing directive)"
out=$(echo '{"session_id":"SMK9STBY-1234","source":"resume"}' | FF_STATE_DIR="$_sb_ctl" SKIP_MAIL_LISTEN_ARM_REMINDER=1 bash .claude/hooks/session-start.sh 2>&1)
assert_not_contains "ESCAPE: session-start with SKIP_MAIL_LISTEN_ARM_REMINDER=1 → the ARM directive is SUPPRESSED (a setup that never runs two sessions at once)" "$out" "MAIL-LISTEN (standing directive)"
assert_contains "ESCAPE: the switch drops only the ARM directive → the start still runs past it (the working-plan line is emitted)" "$out" "WORKING PLAN"
out=$(echo '{"session_id":"SMK9STBY-1234","source":"resume"}' | FF_STATE_DIR="$_sb_ctl" SKIP_MAIL_LISTEN_ARM_REMINDER=0 bash .claude/hooks/session-start.sh 2>&1)
assert_contains "ESCAPE: SKIP_MAIL_LISTEN_ARM_REMINDER=0 does NOT bypass → the ARM directive is emitted (=1 only, as mail-listen-arm-reminder.sh reads it)" "$out" "MAIL-LISTEN (standing directive)"
# mail-listen-arm-reminder.sh: silent under standby even with NO armed marker; nags again once the marker is gone.
_sb_root="$(mktemp -d)"; mkdir -p "$_sb_root/.claude/state"; echo "1700000000 x" > "$_sb_root/.claude/state/session-standby-smk9stby"
out=$(echo '{"prompt":"x","session_id":"SMK9STBY-1234"}' | CLAUDE_PROJECT_DIR="$_sb_root" bash .claude/hooks/mail-listen-arm-reminder.sh 2>&1)
assert_empty "SAFE: arm-reminder under a standby marker (no armed marker) → silent" "$out"
rm -f "$_sb_root/.claude/state/session-standby-smk9stby"
sout=$(echo '{"prompt":"x","session_id":"SMK9STBY-1234"}' | CLAUDE_PROJECT_DIR="$_sb_root" bash .claude/hooks/mail-listen-arm-reminder.sh 2>/dev/null)
assert_one_json_doc "CONTROL: arm-reminder once the standby marker is gone → nags again" "$sout" "mail-listen --poll 30"
# COMPLEMENT: the arm-reminder and the resume net are two halves of ONE per-prompt listener decision, coupled only
# by an inverse test on one marker. Drive BOTH on the PRODUCTION path (CLAUDE_PROJECT_DIR, no FF_STATE_DIR).
_sb_x="$(mktemp -d)"; mkdir -p "$_sb_x/.claude/state" "$_sb_x/.claude/logs"
_sb_emits() { local n=0 o h; for h in mail-listen-arm-reminder.sh standby-resume-check.sh; do
  o=$(echo '{"prompt":"x","session_id":"SMK9STBY-1234"}' | CLAUDE_PROJECT_DIR="$_sb_x" bash ".claude/hooks/$h" 2>/dev/null)
  [ -n "$o" ] && n=$((n+1)); done; echo "$n"; }
assert_eq "COMPLEMENT: unarmed, not parked → exactly ONE of arm-reminder / resume-net speaks" "1" "$(_sb_emits)"
echo "1700000000 x" > "$_sb_x/.claude/state/session-standby-smk9stby"
assert_eq "COMPLEMENT: parked, unarmed → exactly ONE speaks (zero = a deaf seat nobody tells to resume)" "1" "$(_sb_emits)"
: > "$_sb_x/.claude/state/mail-listen-armed-smk9stby"; rm -f "$_sb_x/.claude/state/session-standby-smk9stby"
assert_eq "COMPLEMENT: armed, not parked → neither speaks" "0" "$(_sb_emits)"
rm -rf "$_sb_x"
# session-lifecycle.py round trip — the SSOT derivation, isolated state dir, NO transcripts (so a finished
# marker cannot be superseded and EXITED must win).
_sb_lc="$(mktemp -d)"
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/none" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: fresh seat → ACTIVE" "$st" "ACTIVE"
FF_STATE_DIR="$_sb_lc" python3 scripts/session-lifecycle.py standby --session smk9stby >/dev/null 2>&1
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/none" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: after standby → STANDBY" "$st" "STANDBY"
printf '%s %s wrap\n' "deadbeef" "$(( $(date +%s) - 5 ))" > "$_sb_lc/session-wrapped-smk9stby"
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/none" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: an OLDER wrap marker does not unpark → STANDBY" "$st" "STANDBY"
printf '%s %s wrap\n' "deadbeef" "$(( $(date +%s) + 5 ))" > "$_sb_lc/session-wrapped-smk9stby"
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/none" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: a NEWER wrap marker does not unpark either (the listener is still disarmed) → STANDBY" "$st" "STANDBY"
rm -f "$_sb_lc/session-wrapped-smk9stby"
res=$(FF_STATE_DIR="$_sb_lc" python3 scripts/session-lifecycle.py resume --session smk9stby 2>&1)
assert_contains "lifecycle: resume clears the marker and prints the parked duration" "$res" "STANDBY cleared"
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/none" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: after resume → ACTIVE" "$st" "ACTIVE"
res=$(FF_STATE_DIR="$_sb_lc" python3 scripts/session-lifecycle.py resume --session smk9stby 2>&1)
assert_contains "lifecycle: a second resume is a no-op that says so" "$res" "nothing to clear"
FF_STATE_DIR="$_sb_lc" python3 scripts/session-lifecycle.py standby --session smk9stby >/dev/null 2>&1
FF_STATE_DIR="$_sb_lc" python3 scripts/session-lifecycle.py finished --session smk9stby --reason logout >/dev/null 2>&1
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/none" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: EXITED outranks STANDBY (a parked seat can still die)" "$st" "EXITED"
# The seat is RESUMED after that exit (a transcript record after the finished marker supersedes it): the marker
# still stands, so STANDBY speaks again — the "survives a terminal close" boundary in standby/SKILL.md.
mkdir -p "$_sb_lc/jsonl"; _sb_rec=$(( $(date +%s) + 60 ))
printf '{"type":"user","timestamp":"%s"}\n' "$(python3 -c 'import datetime,sys; print(datetime.datetime.fromtimestamp(int(sys.argv[1]), datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z"))' "$_sb_rec")" > "$_sb_lc/jsonl/smk9stby-0000.jsonl"
st=$(FF_STATE_DIR="$_sb_lc" FF_JSONL_DIR="$_sb_lc/jsonl" python3 scripts/session-lifecycle.py status --session smk9stby 2>/dev/null)
assert_contains "lifecycle: exited then RESUMED (record after the exit) with the marker still standing → STANDBY" "$st" "STANDBY"
# 30-day GC: pinned by BOTH sides of the horizon, driven by a PEER's gate (the parked seat takes no turns).
_sb_gc="$(mktemp -d)"
echo "1 x" > "$_sb_gc/session-standby-old31dd"; echo "1 x" > "$_sb_gc/session-standby-new29dd"
python3 -c 'import os,sys,time; [os.utime(p,(time.time()-d*86400,)*2) for p,d in ((sys.argv[1],31),(sys.argv[2],29))]' "$_sb_gc/session-standby-old31dd" "$_sb_gc/session-standby-new29dd"
FF_STATE_DIR="$_sb_gc" FF_JSONL_DIR="$_sb_gc/none" python3 scripts/session-lifecycle.py gate --session peer0000 --source startup >/dev/null 2>&1
assert_eq "lifecycle GC: a standby marker older than STANDBY_GC_DAYS (31d) is removed by a peer's gate" "0" "$(ls "$_sb_gc" | grep -c 'old31dd')"
assert_eq "lifecycle GC: a 29-day park survives (the horizon is 30 days, not the 7-day wrap/exit GC)" "1" "$(ls "$_sb_gc" | grep -c 'new29dd')"
# mail-await --peer-done: a wrapped-then-parked peer is quiescent — GO, never a 2h timeout that reads as a stall.
_sb_mw="$(mktemp -d)"; mkdir -p "$_sb_mw/st" "$_sb_mw/sess" "$_sb_mw/man" "$_sb_mw/mail" "$_sb_mw/logs"
printf 'deadbeef %s wrap\n' "$(( $(date +%s) - 600 ))" > "$_sb_mw/st/session-wrapped-bead0001"
echo "$(( $(date +%s) - 300 )) deadbeef" > "$_sb_mw/st/session-standby-bead0001"
mw=$(FF_STATE_DIR="$_sb_mw/st" FF_SESSIONS_DIR="$_sb_mw/sess" FF_MANIFEST_DIR="$_sb_mw/man" FF_MAIL_DIR="$_sb_mw/mail" FF_LOGS_DIR="$_sb_mw/logs" CLAUDE_CODE_SESSION_ID="abcdef12" python3 scripts/session-manifest.py mail-await --peer-done "bead0001" --timeout 3 --poll 2 2>&1)
assert_contains "mail-await --peer-done: a WRAPPED-then-parked peer is a GO (not a timeout)" "$mw" "WRAPPED and is now in STANDBY"
rm -rf "$_sb_gc" "$_sb_mw" "$_sb_ctl"; rm -f ".claude/state/session-start-sha-SMK9STBY-1234"
# mail-prune HOLDS a parked recipient's direct mail past the 72h unread TTL — the queue /standby promises
# and resume step 3 reads; an unparked recipient's equally old mail is the control and must still prune.
_sb_mp="$(mktemp -d)"; mkdir -p "$_sb_mp/session-mail"; echo "1700000000 x" > "$_sb_mp/session-standby-smk9stby"
for _f in smk9stby__1__peer0001.md smk9othr__1__peer0001.md; do echo x > "$_sb_mp/session-mail/$_f"; touch -t 202001010000 "$_sb_mp/session-mail/$_f"; done
FF_STATE_DIR="$_sb_mp" FF_MAIL_DIR="$_sb_mp/session-mail" FF_LOGS_DIR="$_sb_mp" FF_MANIFEST_DIR="$_sb_mp" python3 scripts/session-manifest.py mail-prune >/dev/null 2>&1
assert_eq "mail-prune: a PARKED recipient's 72h+ unread mail is held" "1" "$(ls "$_sb_mp/session-mail" | grep -c '^smk9stby__')"
assert_eq "CONTROL: an unparked recipient's 72h+ unread mail is pruned" "0" "$(ls "$_sb_mp/session-mail" | grep -c '^smk9othr__')"
rm -rf "$_sb_mp"
# manifest prune SKIPS a parked seat (its jsonl idles BY DESIGN); an unparked 48h-idle peer is the control.
_sb_pr="$(mktemp -d)"; mkdir -p "$_sb_pr/m" "$_sb_pr/s"; echo "$(date +%s) x" > "$_sb_pr/session-standby-smk9prkd"
for _s in smk9prkd smk9idle; do printf '# Session manifest: %s\n' "$_s" > "$_sb_pr/m/$_s.md"; echo '{}' > "$_sb_pr/s/$_s-0.jsonl"; touch -t 202001010000 "$_sb_pr/s/$_s-0.jsonl"; done
FF_STATE_DIR="$_sb_pr" FF_MANIFEST_DIR="$_sb_pr/m" FF_SESSIONS_DIR="$_sb_pr/s" python3 scripts/session-manifest.py prune >/dev/null 2>&1
assert_eq "prune: a PARKED seat's manifest survives a 24h-idle jsonl" "1" "$(ls "$_sb_pr/m" | grep -c '^smk9prkd')"
assert_eq "CONTROL: an unparked 24h-idle manifest is pruned" "0" "$(ls "$_sb_pr/m" | grep -c '^smk9idle')"
rm -rf "$_sb_pr"
rm -rf "$_sb_state" "$_sb_root" "$_sb_lc"; rm -f .claude/logs/standby-resume-fires.smoke.jsonl

echo ""
echo "=== band-o-inject.sh (UserPromptSubmit — the Band-O orchestrator band, 2-band split 2026-07-12) ==="
# The split's delivery rail: Band-O rows reach the ORCHESTRATOR via UserPromptSubmit
# additionalContext and NEVER reach sub-agents (which don't fire UserPromptSubmit). It ships in
# TWO chunks because additionalContext is capped at 10K chars per VALUE — probe-measured
# 2026-07-12: a 9.4K value lands whole, a 15K value degrades to a ~2K preview. A chunk that
# crosses that ceiling truncates SILENTLY: the orchestrator would lose Band-O rules with no
# error anywhere. Hence the hard size assertions below.
# ⛔ ISOLATED (2026-08-14). These arms used to run the hook with NO
# CLAUDE_PROJECT_DIR, so every smoke run appended synthetic rows to the PRODUCTION instrument
# log and left a real `.claude/state/band-o-state-smkbando.json` behind — 140 records, 10.5% of
# the log, landing in the very digest_rate denominator this feature is watched by. The later
# arms in this section already isolated; these did not. The band file is COPIED so the emitted
# bytes are identical to the real ones.
bo_iso="$(mktemp -d)"; mkdir -p "$bo_iso/.claude/orchestrator" "$bo_iso/.claude/logs" "$bo_iso/.claude/state"
cp .claude/orchestrator/active-recall-orchestrator.md "$bo_iso/.claude/orchestrator/" 2>/dev/null
bo1=$(printf '{"prompt":"x","session_id":"smkbando"}' | CLAUDE_PROJECT_DIR="$bo_iso" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
bo2=$(printf '{"prompt":"x","session_id":"smkbando"}' | CLAUDE_PROJECT_DIR="$bo_iso" bash .claude/hooks/band-o-inject.sh 2 2>/dev/null)
# Explicit parse arms: the bare json.loads probes below DO red on a second
# document, but their failure text names a BUDGET cause; the highest-dose emitter in the fleet
# deserves a failure that says "stdout stopped parsing as one document" in so many words.
assert_one_json_doc "PARSE: band-o-inject.sh chunk 1 → ONE parseable hookSpecificOutput doc (a second doc here drops Band-O from every orchestrator turn)" "$bo1" "BAND-O"
assert_one_json_doc "PARSE: band-o-inject.sh chunk 2 → ONE parseable hookSpecificOutput doc" "$bo2" "BAND-O"
# FIRE: chunk 1 → model-visible UserPromptSubmit additionalContext carrying the Band-O table
if printf '%s' "$bo1" | grep -q '"hookEventName": "UserPromptSubmit"' \
   && printf '%s' "$bo1" | grep -q '"additionalContext"' \
   && printf '%s' "$bo1" | grep -q 'Orchestrator Hot Tier'; then
  pass "FIRE: chunk 1 → STDOUT UserPromptSubmit additionalContext carrying the Orchestrator Hot Tier"
else
  fail "FIRE: chunk 1 must emit hookSpecificOutput.additionalContext with the Band-O table (the model-visible path)"
fi
# FIRE: chunk 2 must be a DIFFERENT slice — this is what proves the settings.json `bash "..." N`
# form actually passes the chunk arg through. If both chunks came back identical, $1 is not reaching
# the hook and half of Band-O would never be delivered.
# ⛔ WAS PINNED TO 'User pushback handling' LIVING IN CHUNK 2 — a CONTENT anchor for a
# STRUCTURAL property (2026-08-18, 3-chunk split). That section moved to chunk 3 the moment a
# second boundary marker landed, so the arm RED-ed on a correct emission. The property it exists
# to prove is "$1 reaches the hook", i.e. the chunks are DISTINCT — assert that directly and the
# arm stops depending on where any particular section happens to sit.
# ⛔ HASH INSIDE PYTHON — md5(1) is BSD-ONLY and does not exist on the Linux runner
# (GNU ships md5sum, with different output shape). Piping to it there produced EMPTY
# hashes, so the `[ -n "$_bo2c" ]` guard below went false and the arm failed on a
# correct emission. Red on CI. python3 is already in this pipe, so
# hashlib costs nothing and removes the portability question entirely.
_bo1c=$(printf '%s' "$bo1" | python3 -c 'import json,sys,hashlib; print(hashlib.md5(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"].encode("utf-8")).hexdigest())' 2>/dev/null)
_bo2c=$(printf '%s' "$bo2" | python3 -c 'import json,sys,hashlib; print(hashlib.md5(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"].encode("utf-8")).hexdigest())' 2>/dev/null)
if printf '%s' "$bo2" | grep -q '"additionalContext"' \
   && [ -n "$_bo2c" ] && [ "$_bo1c" != "$_bo2c" ]; then
  pass "FIRE: chunk 2 → a DISTINCT slice from chunk 1 (content md5 differs) — the chunk arg passes through"
else
  fail "FIRE: chunk 2 must be a distinct slice from chunk 1 (identical ⇒ the \$1 chunk arg is not reaching the hook)"
fi

# --- trigger instrumentation (added 2026-08-10) ---
# WHY THESE ARMS EXIST: Band-O is injected ~325x per session against ~95 typed prompts (measured),
# because UserPromptSubmit also fires on background/notification wakes. Before any dedup can be
# designed, the hook must be able to SAY which trigger it saw — so it logs the payload shape.
# The logger shipped BROKEN for one minute: it piped the payload into `python3 - <<HEREDOC`, which
# takes the PROGRAM from stdin, so the payload was unreachable and every row read has_prompt=false.
# A logger stuck at "false" does not look broken — it looks like the measurement "the hook cannot
# discriminate its trigger", which is the exact false finding the log exists to prevent. A
# positive/negative control pair caught it; in these two arms the POSITIVE one is load-bearing.
bo_log="$(mktemp -d)/band-o-inject.jsonl"
bo_dir="$(mktemp -d)"; mkdir -p "$bo_dir/.claude/logs" "$bo_dir/.claude/orchestrator"
cp .claude/orchestrator/active-recall-orchestrator.md "$bo_dir/.claude/orchestrator/" 2>/dev/null
printf '{"prompt":"a typed prompt","session_id":"smkbando"}' \
  | CLAUDE_PROJECT_DIR="$bo_dir" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
bo_pos="$(tail -1 "$bo_dir/.claude/logs/band-o-inject.jsonl" 2>/dev/null)"
if printf '%s' "$bo_pos" | grep -q '"has_prompt": true' \
   && printf '%s' "$bo_pos" | grep -q '"prompt_head": "a typed prompt"'; then
  pass "FIRE: a payload WITH a prompt logs has_prompt=true + the head (the positive control — a logger stuck at false reads as a real measurement)"
else
  fail "FIRE: trigger log must record has_prompt=true for a payload carrying a prompt (got: $bo_pos)"
fi
printf '{"session_id":"smkbando"}' \
  | CLAUDE_PROJECT_DIR="$bo_dir" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
bo_neg="$(tail -1 "$bo_dir/.claude/logs/band-o-inject.jsonl" 2>/dev/null)"
if printf '%s' "$bo_neg" | grep -q '"has_prompt": false'; then
  pass "SAFE: a payload WITHOUT a prompt logs has_prompt=false — meaningful only because the arm above proves true is reachable"
else
  fail "SAFE: trigger log must record has_prompt=false when no prompt field is present (got: $bo_neg)"
fi
# OVERSIZE ARM (added 2026-08-10 after the payload channel broke SILENTLY for the SECOND time).
# History: v1 piped the payload into `python3 - <<HEREDOC`, which takes the PROGRAM from stdin, so
# the payload was unreachable -> every row false. v2 moved it to an ENV VAR, which is the shape
# a written rule bans: macOS caps env+args at ~1 MB, past it execve fails, the interpreter never starts, and
# the `|| true` swallows it. Both bugs are INVISIBLE to the two arms above, because both arms use a
# SMALL payload. The failure is SIZE-SELECTIVE in the one direction that ruins this log: an
# oversized payload IS a typed-prompt-with-a-large-paste, so dropped rows skew the corpus toward
# has_prompt=false -- "background wake" -- which is the reading that argues FOR the dedup this log
# exists to decide. Measured old-vs-new on the same 1.2 MB fixture: env-var rows=0, temp-file rows=1.
# Keep this arm on a payload > 1 MB; shrinking it below the execve cap makes it decorative.
bo_big="$(mktemp)"; python3 -c 'import json,sys;sys.stdout.write(json.dumps({"prompt":"P"*1200000,"session_id":"smkbando"}))' > "$bo_big"
: > "$bo_dir/.claude/logs/band-o-inject.jsonl"
CLAUDE_PROJECT_DIR="$bo_dir" bash .claude/hooks/band-o-inject.sh 1 < "$bo_big" >/dev/null 2>&1
bo_bigrow="$(tail -1 "$bo_dir/.claude/logs/band-o-inject.jsonl" 2>/dev/null)"
if printf '%s' "$bo_bigrow" | grep -q '"has_prompt": true'; then
  pass "FIRE: a >1MB payload still logs has_prompt=true — the payload channel is not env/args, so execve's ~1MB cap cannot silently drop the biggest typed prompts"
else
  fail "FIRE: a >1MB payload logged NOTHING — the payload is going through env/args again. Dropped rows are exactly the large TYPED prompts, so the log now under-counts has_prompt=true and biases the dedup decision. Use a temp file. (got: $bo_bigrow)"
fi
rm -f "$bo_big"
# The emit must be UNCHANGED by the instrumentation: log-only means log-only.
bo1b=$(printf '{"prompt":"x","session_id":"smkbando"}' | CLAUDE_PROJECT_DIR="$bo_iso" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if [ "$bo1b" = "$bo1" ]; then
  pass "SAFE: instrumentation does not alter chunk 1's emitted bytes (log-only)"
else
  fail "SAFE: chunk 1 emit changed — the trigger log must be side-effect-free on the injected band"
fi
rm -rf "$bo_dir" "$(dirname "$bo_log")" 2>/dev/null
# FIRE (load-bearing): each SOURCE chunk under the 9.5K guard.
#
# ⚠️ 2026-07-31 — THIS ASSERTION PREVIOUSLY READ THE HOOK'S *OUTPUT* AND WAS THEREFORE
# STRUCTURALLY UNFAILABLE. `band-o-inject.sh:28-29` CLAMPS an over-budget chunk to
# `part[:9400] + <~79-char marker>` = 9479 chars — permanently BELOW the 9500 this asserts.
# Measured failure domain of the old form: exactly {source == 9500} ∪ {hook dead}. That is,
# the ONLY input it rejected was the last SAFE value, and every genuinely over-budget source
# PASSED (probed: 9501 → pass, 12000 → pass, 30000 → pass with 68% of the band discarded).
# Not blind — ANTI-CORRELATED. It was green while a commit shipped chunk 1 at 9589 chars,
# truncating the row mid-word on every orchestrator turn until a fix landed 7 min later;
# a human caught that by reading, not a gate. `smoke-mutation-matrix.sh` scored it "guarded"
# off the hook-DEAD mutation (the weak arm) while the strong arm — grow the band — stays green.
# GENERAL RULE: when a guard NORMALISES its output, a test measuring that output cannot fail
# by construction — assert on the guard's INPUT, and separately on the guard's own marker.
#
# Unit note: the guard compares CHARACTERS, so this asserts characters — a pre-flight must
# read the way the thing it gates reads. Bytes are REPORTED (never asserted) so a future unit
# change is visible rather than silent.
#
# The harness ceiling is CHARACTERS — MEASURED 2026-07-31, not inferred. Two live UserPromptSubmit
# probes carrying multi-byte CJK, where chars and bytes DIVERGE ~3x, both landed with their tail
# sentinel intact: 5,013 chars / 14,813 bytes, and 9,516 chars / 28,322 bytes. So no BYTE cap
# exists below 28,322, and a value at this guard's own 9,500 limit survives — the guard is sized
# against the right quantity AND positioned correctly.
#
# ⚠️ WHY THE EARLIER "probe-confirmed" TAG WAS NOT A MEASUREMENT, since the lesson outlives it:
# the 2026-07-12 run bracketed [9.4K lands, 15K degrades] on ASCII, where chars and bytes are
# EQUAL — so it fixed the MAGNITUDE and could not touch the UNIT, yet shipped tagged as settling
# both. It carried that inference into a fleet-wide guard for 19 days. A measurement taken where
# the two candidate quantities coincide cannot distinguish them, and its correct-looking result
# is exactly what stops anyone re-running it. Only a divergent-unit fixture can discriminate.
# The probe below runs the REAL hook, so it needs json/subprocess and cannot live in a
# `python3 -c "..."` double-quoted string (the shell would eat `$`, backticks and backslashes).
# Temp file + QUOTED heredoc, per .claude/rules/bash-environment.md.
_bo_budget_py="$(mktemp "${TMPDIR:-/tmp}/bobudget.XXXXXX")"
_bo_budget_err="$(mktemp "${TMPDIR:-/tmp}/bobuderr.XXXXXX")"
cat > "$_bo_budget_py" <<'PY'
import json, os, re, shutil, subprocess, sys, tempfile

BAND = '.claude/orchestrator/active-recall-orchestrator.md'
HOOK = '.claude/hooks/band-o-inject.sh'
MARK = '<!-- BAND-O-CHUNK-BOUNDARY -->'
CUSHION = 5
# Part count DERIVED from the real band, so every bound/prefix assertion below scales with it
# instead of pinning the 2-chunk era. Default 2 only if the band is unreadable — the `t` read
# further down fails loud on that path anyway.
try:
    NCHUNKS = len(open(BAND, encoding='utf-8').read().split(MARK))
except Exception:
    NCHUNKS = 2
CHUNKS = tuple(range(1, NCHUNKS + 1))
# ⛔ TRIPWIRE ONLY — BOUND below does NOT read this. See the loop comment: these exist so a
# FULL-chunk notice edit REDs with both numbers named, not so the bound can be computed from a
# literal. Chunk 1 = FULL_TAG (34) + "\n" + FULL_SPLIT (225) + "\n"; chunk 2 = FULL_CONT (57) + "\n".
# 2026-08-18: FULL_SPLIT grew 225 -> 233 chars when its part count became DERIVED (it names N
# twice now instead of saying "2 of 2"), so chunk 1's prefix went 261 -> 268; chunk 3 joined.
# Tail prefixes are equal-length because "2/3" and "3/3" are the same width.
PREFIX_EXPECTED = {1: 268, 2: 58, 3: 58}

try:
    cap = int(re.search(r'^EMIT_CLAMP_ABOVE = (\d+)',
                        open(HOOK, encoding='utf-8').read(), re.M).group(1))
except Exception:
    cap = 0                # symbol unreadable/renamed => bound 0 => the loop fails loud

BOX = tempfile.mkdtemp()


def emitted_len(chunk, n):
    """Chars the REAL hook emits for `chunk` when THAT chunk's own source is exactly n.

    A typed prompt forces the FULL path on both chunks (decide() -> full_typed), and a fresh
    temp root has no state file, so chunk 2 re-derives the same decision. -1 on any doubt,
    including a clamp — a clamped emission measures EMIT_CLAMP_TO, not the prefix.
    """
    d = tempfile.mkdtemp(dir=BOX)
    for sub in ('.claude/orchestrator', '.claude/logs', '.claude/state'):
        os.makedirs(os.path.join(d, sub))
    # ⛔ THE SYNTHETIC BAND MUST HAVE THE SAME NUMBER OF PARTS AS THE REAL ONE (2026-08-18).
    # It used to hardcode one marker, i.e. a 2-chunk band — so probing chunk 3 wrote a band that
    # HAS no chunk 3, the hook correctly emitted nothing, and the probe read -1 and reported the
    # HOOK as broken. The prefix under test is N-dependent (FULL_SPLIT names the part count), so
    # a 2-part fixture cannot measure a 3-part prefix even in principle.
    sizes = [40] * NCHUNKS
    sizes[chunk - 1] = n
    with open(os.path.join(d, BAND), 'w', encoding='utf-8') as f:
        f.write(("\n" + MARK + "\n").join(chr(120 + i % 2) * s for i, s in enumerate(sizes)) + "\n")
    env = dict(os.environ, CLAUDE_PROJECT_DIR=d)
    env.pop('SKIP_BAND_O_INJECT', None)
    p = subprocess.run(['bash', HOOK, str(chunk)], capture_output=True, text=True, env=env,
                       input=json.dumps({'prompt': 'typed', 'session_id': 'smkbndpfx'}))
    try:
        ctx = json.loads(p.stdout)['hookSpecificOutput']['additionalContext']
    except Exception:
        return -1
    return -1 if 'SPLIT FURTHER' in ctx else len(ctx)


PREFIX = {i: -1 for i in CHUNKS}
try:
    for _i in CHUNKS:
        # TWO sizes, because a prefix is a CONSTANT: one probe cannot tell a constant prepend
        # from a size-dependent transform, and the difference must be identical at both.
        _a, _b = emitted_len(_i, 1000), emitted_len(_i, 2000)
        if _a > 1000 and _b > 2000 and (_a - 1000) == (_b - 2000):
            PREFIX[_i] = _a - 1000
except Exception:
    pass
finally:
    shutil.rmtree(BOX, ignore_errors=True)

BOUND = {i: (cap - PREFIX[i] - CUSHION if (cap and PREFIX[i] >= 0) else 0) for i in CHUNKS}


def row(i, chars, byts):
    print(i, chars, byts, BOUND.get(i, 0), PREFIX.get(i, -1), PREFIX_EXPECTED.get(i, -1))


try:
    t = open(BAND, encoding='utf-8').read()
except Exception:
    row(1, 999999, 999999)
    row(2, 999999, 999999)
    sys.exit(0)
# ⛔ UNBOUNDED, MIRRORING THE HOOK (2026-08-18). Was `split(MARK, 1)`, which modelled a 2-chunk
# band: with two markers it folded chunks 2 and 3 into one 13,202-char blob and reported a clamp
# that the real hook does not perform. A measurement instrument that hardcodes the shape it is
# measuring reports a defect in the SUBJECT when the defect is in ITSELF — and this one failed in
# the alarming direction, which is the direction that gets a correct change reverted.
parts = t.split(MARK)
if len(parts) < 2:
    # marker absent/renamed => split() returns ONE element and the hook would emit the whole
    # file as chunk 1 (then clamp it) and NOTHING as chunk 2. Fail loud rather than measure a
    # shape that cannot be delivered.
    row(1, 999999, 999999)
    row(2, 999999, 999999)
    sys.exit(0)
for _i, _part in enumerate(parts, 1):
    _part = _part.strip('\n')
    row(_i, len(_part), len(_part.encode('utf-8')))
PY
_bo_rows=0
while read -r _c _chars _bytes _bound _pfx _pfxexp; do
  _bo_rows=$((_bo_rows+1))
  # The bound is NOT the clamp threshold: band-o-inject.sh PREPENDS a notice to every FULL
  # emission and the clamp is charged for it, so the gate compares source + prefix. Chunk 1
  # carries FULL_TAG + "\n" + FULL_SPLIT + "\n" (34 + 225 + 2 = 261 today); chunk 2 carries
  # FULL_CONT + "\n" (57 + 1 = 58 today). Both figures are MEASURED per run, never retyped —
  # they appear in the pass line, and the tripwire below REDs if either moves. Both are PREFIXES since the prefix fix, so a clamp no longer removes the
  # notice; what a clamp costs is the band's own TAIL, which is the hazard this bound exists to
  # catch. Bound = EMIT_CLAMP_ABOVE - prefix - 5, the 5 being the 2026-08-14 cushion that makes
  # the gate fire BEFORE the clamp rather than at it.
  # ⛔ THE CAP IS NOW READ OUT OF THE HOOK, NOT RETYPED — 2026-08-17, third rot of this pin.
  # It was 9234/9437, correct against EMIT_CLAMP_ABOVE = 9500 and stale within minutes of the
  # 9,500 -> 9,800 raise, which swept EMIT_CLAMP_TO, the clamp
  # marker's "9.5K" text and the growth fixture's pad and did not reach these two literals.
  # ⚠️ THE STALE DIRECTION LOOKED SAFE AND WAS NOT FREE. 300 chars too LOW fails EARLY, so it
  # never admits a clamp — but chunk 2 was measured 26 chars from tripping it while sitting 332
  # from the real clamp, and this gate's own fail text prescribes rebalancing the CHUNK-BOUNDARY
  # marker or shrinking the band. A false alarm here is answered by spending the exact headroom
  # the cap raise had just bought, and chunk 1 had the slack to absorb it, so the rebalance would
  # have succeeded and hidden the staleness for good.
  # ⛔ BOTH PREFIXES ARE NOW DERIVED FROM THE REAL HOOK, PER CHUNK — 2026-08-17, and the pinned
  # form this replaces was INVISIBLE for chunk 2, not merely unasserted. The old defence was that
  # the sibling STRICT-clamp arm REPORTS its measured prefix as `prefix=`; that probe runs
  # `bash HOOK 1` and NOTHING else, so chunk 2's pinned 58 was not asserted, not reported and not
  # measured anywhere in this suite. MEASURED: lengthening FULL_CONT into a DIGEST_CONT-shaped
  # four-line notice moves chunk 2's real prefix 58 -> 264 and its real clamp point 9742 -> 9536
  # while this gate keeps comparing against 9737 — the suite stayed 741 PASS / 0 FAIL and the arm
  # printed "< 9737 — the pre-clamp margin" over a 201-char window (9536..9736) in which a source
  # passes the gate and the hook clamps it anyway.
  # ⚠️ WHAT THAT COSTS IS THE PRE-CLAMP EARLY WARNING, AND ONLY THAT — say the weaker true thing.
  # A REAL clamp still REDs the SPLIT-FURTHER arm below, loudly. But the free remedy this gate's
  # own fail text prescribes (move the CHUNK-BOUNDARY marker) exists only BEFORE the clamp; once
  # the band is being truncated, the rules are already missing from every orchestrator turn.
  # THE PIN THAT SURVIVES IS A TRIPWIRE, NOT AN AUTHORITY. PREFIX_EXPECTED is compared against the
  # derived value PER CHUNK and feeds nothing else — the bound reads the DERIVED number. So a
  # notice edit moves the bound CORRECTLY and REDs the tripwire with both numbers named, instead of
  # being silently absorbed by whatever margin the band happens to have that week. That equality is
  # exactly the assertion the superseded note declined to write ("visible, not asserted").
  # _bound=0 / _pfx=-1 mean the cap symbol or the prefix probe could not be read out of the hook:
  # fail loud, same convention as the 999999 sizes below.
  # MUTATION RECORD (2026-08-17, re-measured after the derive-both change). Five arms ran:
  # the bound TRACKS the cap (9800 -> 9534/9737, 9500 -> 9234/9437); an unreadable cap symbol
  # yields _bound=0 and REDs; the FULL_CONT-lengthening above REDs the chunk-2 TRIPWIRE naming
  # 264 vs 58 (it was 741/0 GREEN before this change); flipping the derivation to probe chunk 1
  # for both chunks REDs the same tripwire; and padding chunk-2 source one char past its derived
  # bound REDs the bound arm while the SPLIT-FURTHER arm stays GREEN, which is what shows the -5
  # cushion fires BEFORE the clamp.
  # ⛔ THAT LAST ARM **IS** SINGLE-ARM FROM THE REAL BAND — 740 PASS / 1 FAIL, MEASURED. An earlier
  # revision of this comment asserted the opposite ("CANNOT BE MADE SO … do not improve it") on the
  # premise that a pad big enough to cross the bound (+328) "exceeds the digest's live headroom
  # (~213)" and reds 6 digest arms. BOTH HALVES ARE FALSE. The ~213 figure was retracted (it
  # measured a greedy split-boundary remainder, not capacity), and the headroom is not reachable
  # anyway: build_digest() collects ONLY `## ` headings and `|` lines, and its table-region guard
  # explicitly permits `<!--` lines — so a comment-line pad inside chunk 2's table region is
  # invisible to the digest BY CONSTRUCTION and every digest arm stays green.
  # ⚠️ THE PAD'S POSITION IS THE WHOLE DIFFERENCE, WHICH IS WHY "a prose pad" UNDER-DETERMINES IT.
  # The same +328 as a PROSE line appended at EOF gives 739/2: the needle arm below appends
  # `| SMOKE-NEEDLE-TRIGGER-XYZ …` after it, which makes the needle the last table line and drops
  # the prose pad INSIDE the region guard, so build_digest() refuses and the turn falls back to
  # FULL. That second RED is a region-guard artifact of where the pad went — never digest headroom.
  #
  # FIRE: the prefix TRIPWIRE, per chunk. Defaults A/B deliberately DIFFER so a MISSING field
  # cannot read as a match — `[ "" = "" ]` is true, and a short row would otherwise pass here.
  if [ "${_pfx:-A}" = "${_pfxexp:-B}" ]; then
    pass "FIRE: chunk $_c's prepended-notice PREFIX derives to ${_pfx} chars from the REAL hook, matching the pinned ${_pfxexp} (so ${_bound} is the true pre-clamp margin)"
  else
    fail "FIRE: chunk $_c's prepended notice measures ${_pfx} chars, not the pinned ${_pfxexp} — a FULL-chunk notice in .claude/hooks/band-o-inject.sh was edited without re-deriving this chunk's budget. The bound below HAS tracked it (now ${_bound}); confirm that is intended and set PREFIX_EXPECTED[$_c] = ${_pfx} in this file. A measured value of -1 means the probe could not run at all (hook unreadable, or its emission clamped), in which case the bound is 0 and the next arm fails too."
  fi
  if [ "${_bound:-0}" -gt 0 ] 2>/dev/null && [ "${_chars:-999999}" -lt "$_bound" ] 2>/dev/null; then
    pass "FIRE: SOURCE chunk $_c is ${_chars} chars / ${_bytes} bytes (< ${_bound} — the pre-clamp margin, incl. this chunk's prepended-notice allowance)"
  else
    fail "FIRE: SOURCE chunk $_c is ${_chars} chars — at/over the ${_bound} bound, so band-o-inject.sh WILL clamp it and Band-O rules will be silently dropped from every orchestrator turn. FREE FIX FIRST: move the CHUNK-BOUNDARY marker in .claude/orchestrator/active-recall-orchestrator.md — LATER in the file to relieve chunk 2, EARLIER to relieve chunk 1. That shifts text between chunks at ZERO dose cost; only shrink the band if BOTH chunks are at their bound."
  fi
done <<EOF
$(python3 "$_bo_budget_py" 2>"$_bo_budget_err")
EOF
# FIRE: the probe must have EMITTED BOTH ROWS. A `while read` over a command substitution that
# printed nothing runs ZERO times, so every assertion above silently disappears and the suite
# stays green — grep-then-iterate-the-hits, the mute failure shape (i18n.md GAP 3). That path
# widened when the probe gained subprocess calls, so it is closed here rather than left implicit.
# Expected row count is DERIVED from the band's marker count, not pinned at 2 — this guard exists
# so a zero-row loop cannot masquerade as a clean pass, and that property is preserved by making
# the expectation track the band instead of a hardcoded era (2026-08-18).
_bo_rows_want=$(( $(grep -oF 'CHUNK-BOUNDARY' .claude/orchestrator/active-recall-orchestrator.md | wc -l | tr -d ' ') + 1 ))
if [ "$_bo_rows" -eq "$_bo_rows_want" ]; then
  pass "SAFE: the chunk-budget probe emitted both rows, so the bound + prefix arms above actually ran"
else
  fail "FIRE: the chunk-budget probe emitted $_bo_rows rows, expected $_bo_rows_want (one per band chunk) — the per-chunk bound and prefix assertions above DID NOT RUN, and a zero-row loop is indistinguishable from a clean pass. stderr: $(head -c 400 "$_bo_budget_err" | tr '\n' ' ')"
fi
rm -f "$_bo_budget_py" "$_bo_budget_err"
# FIRE: neither EMITTED chunk may carry the hook's own truncation marker. This is the
# OBSERVABLE for a real clamp — band-o-inject.sh appends "SPLIT FURTHER" when it truncates and
# until now NOTHING read it (wired-but-inert). This single assertion would have caught the
# 2026-07-29 incident on its own, independently of the source-size check above.
if ! printf '%s%s' "$bo1" "$bo2" | grep -q 'SPLIT FURTHER'; then
  pass "FIRE: neither emitted chunk carries the hook's truncation marker (no silent clamp in effect)"
else
  fail "FIRE: an emitted chunk carries 'SPLIT FURTHER' — band-o-inject.sh IS clamping RIGHT NOW, so Band-O rules are being dropped from every orchestrator turn on every seat. Re-balance the CHUNK-BOUNDARY marker."
fi
# SAFE: the boundary marker must never leak into an emitted chunk
if ! printf '%s%s' "$bo1" "$bo2" | grep -q '<!-- BAND-O-CHUNK-BOUNDARY -->'; then
  pass "SAFE: the CHUNK-BOUNDARY marker is stripped from both emitted chunks"
else
  fail "SAFE: the CHUNK-BOUNDARY marker leaked into an emitted chunk"
fi
# FIRE (the clamp OPERATOR, at the only input that can observe it): emit() truncates on
# `len(part) > EMIT_CLAMP_ABOVE` — STRICTLY greater, so a chunk landing at EXACTLY the cap must be
# emitted WHOLE. Nothing pinned that until 2026-08-17: flipping `>` to `>=` at the clamp site left
# this suite at 740 PASS / 0 FAIL. Not for want of clamp arms — there are three — but because every
# one of them probes a size that is unambiguously UNDER the cap (the live band, and the source-bound
# loop above) or unambiguously OVER it (the prefix-fix growth fixture below). `>` and `>=` disagree on
# exactly ONE input in the whole domain, and no fixture sat on it.
# WHY THE OPERATOR IS LOAD-BEARING AND NOT COSMETIC: the hook DERIVES `DIGEST_CAP = EMIT_CLAMP_ABOVE`
# and says the equality IS the safety argument — "at DIGEST_CAP exactly, `len > EMIT_CLAMP_ABOVE` is
# False", so a digest is never clamped BY CONSTRUCTION rather than by margin. Under `>=` that
# construction INVERTS: the largest digest the ladder will accept becomes the first one emit() eats,
# and what it eats is the band's own tail. So the failure lands on the most complete digest the
# ladder can build, only on the turns where the digest is fullest, with the SPLIT-FURTHER marker as
# the sole signal. A `>=` typo also reads as a harmless off-by-one to a reviewer, which is precisely
# why the strictness needs an arm rather than a comment.
# ⛔ EVERY NUMBER HERE IS DERIVED, NONE PINNED. That is the rule the prefix-fix growth arm below states in
# its own header and had broken one line beneath it until 2026-08-17 (pinned 9600 against a pinned
# 9500): a fixture pinned against a pinned cap measures the CAP'S CURRENT VALUE, never the
# predicate, and goes RED on the next raise for a reason unrelated to the property. So the cap is
# read out of the hook's symbol, and the chunk-1 prefix the hook PREPENDS (FULL_TAG + FULL_SPLIT +
# their newlines — 261 chars today) is MEASURED from an under-budget emission rather than retyped.
# Either literal can move without stranding this arm.
# THE OVER-BY-ONE PROBE IS THE POSITIVE CONTROL, not decoration: "at the cap, nothing is clamped"
# passes just as happily when the clamp has been DELETED outright, and `< cap` on the clamped
# length is what separates a real truncation from a marker appended without one.
_bo_op=$(python3 - <<'PY' 2>&1 | tr '\n' ' ' | cut -c1-400
import json, os, re, shutil, subprocess, sys, tempfile
HOOK = ".claude/hooks/band-o-inject.sh"
MARK = "<!-- BAND-O-CHUNK-BOUNDARY -->"

def out(tok, **kv):
    print(tok + "".join(" %s=%s" % (k, v) for k, v in sorted(kv.items())))
    sys.exit(0)

try:
    m = re.search(r"^EMIT_CLAMP_ABOVE = (\d+)", open(HOOK, encoding="utf-8").read(), re.M)
except Exception as exc:
    out("ERR-HOOK-UNREADABLE", err=type(exc).__name__)
if not m:
    out("ERR-NO-EMIT_CLAMP_ABOVE-SYMBOL")
CAP = int(m.group(1))
box = tempfile.mkdtemp()

def emit(n):
    """Run the REAL hook over a band fixture whose chunk-1 SOURCE is exactly n chars."""
    d = tempfile.mkdtemp(dir=box)
    for sub in (".claude/orchestrator", ".claude/logs", ".claude/state"):
        os.makedirs(os.path.join(d, sub))
    open(os.path.join(d, ".claude/orchestrator/active-recall-orchestrator.md"), "w",
         encoding="utf-8").write("x" * n + "\n" + MARK + "\nchunk-two tail\n")
    env = dict(os.environ, CLAUDE_PROJECT_DIR=d)
    env.pop("SKIP_BAND_O_INJECT", None)
    p = subprocess.run(["bash", HOOK, "1"], capture_output=True, text=True, env=env,
                       input=json.dumps({"prompt": "typed", "session_id": "smkclampop"}))
    try:
        ctx = json.loads(p.stdout)["hookSpecificOutput"]["additionalContext"]
    except Exception:
        return (-1, False)
    return (len(ctx), "SPLIT FURTHER" in ctx)

try:
    probe_len, probe_clamped = emit(1000)
    if probe_len <= 1000 or probe_clamped:
        out("ERR-PREFIX-PROBE", probe_len=probe_len, probe_clamped=probe_clamped)
    prefix = probe_len - 1000
    at_src = CAP - prefix
    if at_src < 1000:
        out("ERR-CAP-BELOW-PREFIX", cap=CAP, prefix=prefix)
    at_len, at_clamped = emit(at_src)
    over_len, over_clamped = emit(at_src + 1)
finally:
    shutil.rmtree(box, ignore_errors=True)
strict = (at_len == CAP and not at_clamped)      # `>` keeps the boundary chunk WHOLE
clamps = (over_clamped and over_len < CAP)       # positive control: one char over DOES truncate
out("STRICT" if (strict and clamps) else ("NONSTRICT" if not strict else "NO-CLAMP"),
    at_clamped=at_clamped, at_len=at_len, cap=CAP, over_clamped=over_clamped,
    over_len=over_len, prefix=prefix, src=at_src)
PY
)
if [ "${_bo_op%% *}" = "STRICT" ]; then
  pass "FIRE: emit() compares STRICTLY (>) — a chunk at exactly EMIT_CLAMP_ABOVE emits WHOLE and one char over truncates, the only input that separates > from >= [$_bo_op]"
else
  fail "FIRE: emit()'s clamp is not strict-greater at its own boundary. Under >= the largest digest the ladder accepts (DIGEST_CAP == EMIT_CLAMP_ABOVE) is also the FIRST one emit() truncates, which inverts the 'a digest is never clamped BY CONSTRUCTION' guarantee band-o-inject.sh states at that constant — the loss lands on the band's tail, on the fullest digests only. Restore \`if len(part) > EMIT_CLAMP_ABOVE:\` in .claude/hooks/band-o-inject.sh. Got: [$_bo_op]"
fi
# SAFE: missing Band-O source → exit 0 (a Band-O bug must NEVER block a user's turn) but NOT
# silent since 2026-08-14 — chunk 1 emits a one-line DARK notice, chunk 2 stays quiet so the
# notice is never doubled. Silent-dark was wired-but-inert at the top of the enforcing hook.
out=$(printf '{}' | CLAUDE_PROJECT_DIR=/nonexistent-band-o-dir bash .claude/hooks/band-o-inject.sh 1 2>&1; echo "rc=$?")
assert_contains "SAFE: missing Band-O source → exits 0, never blocks a turn" "$out" "rc=0"
if printf '%s' "$out" | grep -qF 'BAND-O DARK:'; then
  pass "FIRE: missing Band-O source → chunk 1 emits a visible DARK notice (not silently bandless)"
else
  fail "FIRE: missing Band-O source → chunk 1 emitted NOTHING. The whole orchestrator band is gone from every turn on every seat with no signal anywhere — restore the DARK notice in band-o-inject.sh."
fi
out2=$(printf '{}' | CLAUDE_PROJECT_DIR=/nonexistent-band-o-dir bash .claude/hooks/band-o-inject.sh 2 2>/dev/null)
if [ -z "$out2" ]; then
  pass "SAFE: the DARK notice is chunk-1 only — chunk 2 does not double it"
else
  fail "SAFE: chunk 2 also emitted on a missing source — the DARK notice is doubled every turn"
fi

# FIRE: the band file must never NAME its own split marker in prose. Its entire text — comments
# included — is injected verbatim into the orchestrator's live context, so a sentence naming the
# marker hands the model a renderable token it can emit as output; the hook STRIPS the real
# marker, so nothing echoed can have come from the delivered text. Six sessions opened by
# emitting a fabricated Band-O-shaped document as their first reply, every one rendering that
# token, while the band file's header comment was its only in-context source (removed
# 2026-08-14; rationale + the falsifiability readout live in band-o-inject.sh's header).
# TWO-SIDED BY CONSTRUCTION: 0 means the marker itself is gone and the hook cannot split;
# ≥2 means prose naming it is back. Count OCCURRENCES (grep -o), never grep -c, which counts
# LINES and would read 1 for two mentions sharing a line.
# ⛔ WAS "EXACTLY ONE MARKER" — TRUE ONLY OF A 2-CHUNK BAND, AND IT BLOCKED THE 3-CHUNK SPLIT
# (2026-08-18). The marker count is now legitimately N-1, so a fixed 1 is wrong. Replaced with
# the invariant that actually protects delivery: the number of markers must agree with the
# number of dispatch entries wired in settings.json.
#
# THAT PARITY IS THE REAL SILENT-LOSS PATH, and nothing else checks it. Every guard inside
# band-o-inject.sh passes when a chunk is never REQUESTED: full_part() bounds-checks its index,
# emit() no-ops on empty, the JSON is valid, rc=0. Add a boundary marker to the band without
# adding a settings.json entry and the tail chunk — whole orchestrator rules — is simply never
# asked for, on every seat, every turn, with nothing to notice. The inverse (an entry with no
# marker) is the harmless direction: full_part() returns "" and emit() no-ops.
_bo_mark_n=$(grep -oF 'CHUNK-BOUNDARY' .claude/orchestrator/active-recall-orchestrator.md | wc -l | tr -d ' ')
_bo_wired_n=$(python3 -c "
import json
d=json.load(open('.claude/settings.json'))
print(sum(1 for h in d['hooks']['UserPromptSubmit'] for x in h.get('hooks',[])
          if 'band-o-inject' in str(x.get('command',''))))
" 2>/dev/null || echo 0)
_bo_want=$(( _bo_mark_n + 1 ))
if [ "${_bo_mark_n:-0}" = "0" ]; then
  fail "FIRE: the BAND-O-CHUNK-BOUNDARY marker is GONE from the band file — band-o-inject.sh cannot split it, so chunk 2 is empty and half the orchestrator band ships to nobody."
elif [ "${_bo_wired_n:-0}" = "$_bo_want" ]; then
  pass "FIRE: band markers (${_bo_mark_n}) and settings.json dispatch entries (${_bo_wired_n}) agree — every chunk the band defines is actually requested"
else
  fail "FIRE: the band defines ${_bo_want} chunks (${_bo_mark_n} marker(s)) but settings.json wires ${_bo_wired_n} dispatch entries. If wired < defined, the TAIL CHUNK IS NEVER REQUESTED and those orchestrator rules ship to nobody, silently, on every seat — every in-hook guard still passes. Add a UserPromptSubmit entry: band-o-inject.sh <N>. If a mention of CHUNK-BOUNDARY crept into the band as PROSE, remove it instead — the band is injected verbatim."
fi

# SAFE: the escape valve. `=1` only; anything else must still emit (a valve that fires on every
# value is a dead hook that looks opted-out). Doubles as the A/B toggle for the context-echo
# hypothesis recorded in band-o-inject.sh's header.
_bo_skip=$(printf '{"prompt":"x","session_id":"smkbando"}' | SKIP_BAND_O_INJECT=1 CLAUDE_PROJECT_DIR="$bo_iso" bash .claude/hooks/band-o-inject.sh 1 2>&1; echo "rc=$?")
_bo_noskip=$(printf '{"prompt":"x","session_id":"smkbando"}' | SKIP_BAND_O_INJECT=0 CLAUDE_PROJECT_DIR="$bo_iso" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if [ "$_bo_skip" = "rc=0" ] && printf '%s' "$_bo_noskip" | grep -q 'hookSpecificOutput'; then
  pass "SAFE: SKIP_BAND_O_INJECT=1 suppresses the band at rc=0; =0 still emits (valve is not stuck on)"
elif [ "$_bo_skip" != "rc=0" ]; then
  fail "SAFE: SKIP_BAND_O_INJECT=1 did not suppress cleanly — got [$_bo_skip], expected exactly rc=0"
else
  fail "SAFE: SKIP_BAND_O_INJECT=0 emitted NOTHING — the valve fires on any value, so Band-O is dead whenever the var is set at all"
fi

# --- DOSE-REDUCTION arms (2026-08-14) ---
# Digest-eligible background wakes get a single-chunk DIGEST (all TRIGGER cells verbatim +
# bounded action HEADS + a pointer at the [BAND-O-FULL <h8>] full copy upthread); FULL on typed
# prompts, absent/corrupt state, SessionStart (state deleted), PreCompact marker, band edit,
# 10-turn heartbeat, parse failure, and a deterministic 1-in-10 holdout draw. The polarity every
# arm below pins: EVERY failure/doubt path must land on FULL, never on silence or a thin digest.
# Payload determinism: the holdout draw hashes (sid8, since_full, payload_md5) — payloads below
# are pinned fixtures found by iterating task-ids at sid8=smkband2/since=1: "smk0" draws DIGEST,
# "smk8" draws HOLDOUT. The draw deliberately excludes the band md5, so editing the band file
# cannot flip these fixtures (a band edit forces FULL via the state md5 check instead).
bdd="$(mktemp -d)"; mkdir -p "$bdd/.claude/state" "$bdd/.claude/logs" "$bdd/.claude/orchestrator"
cp .claude/orchestrator/active-recall-orchestrator.md "$bdd/.claude/orchestrator/"
bdd_sid="smkband2-0000-0000-0000-000000000000"
bdd_state="$bdd/.claude/state/band-o-state-smkband2.json"
bdd_pay() { python3 -c 'import json,sys; sys.stdout.write(json.dumps({"prompt":"<task-notification>\n<task-id>"+sys.argv[1]+"</task-id>","session_id":sys.argv[2]}))' "$1" "$bdd_sid"; }
bdd_state_mk() { python3 -c 'import json,sys,time,hashlib; md5=hashlib.md5(open(sys.argv[1],"rb").read()).hexdigest()[:8]; json.dump({"sid8":"smkband2","band_md5":(sys.argv[4] if len(sys.argv)>4 and sys.argv[4] else md5),"last_full_at":time.time()-float(sys.argv[3]),"since_full":int(sys.argv[2]),"turn":{}}, open(sys.argv[5] if len(sys.argv)>5 else sys.argv[1],"w"))' "$bdd/.claude/orchestrator/active-recall-orchestrator.md" "$1" "$2" "${3:-}" "$bdd_state"; }
bdd_mode() { grep '"session": "smkband2"' "$bdd/.claude/logs/band-o-inject.jsonl" 2>/dev/null | tail -1 | python3 -c 'import json,sys; r=json.load(sys.stdin); print("%s|%s|%s" % (r.get("mode"),r.get("arm"),r.get("since_full")))'; }
# FIRE: wake with NO state → FULL (absence of state can never yield a digest) + mode logged
bdo=$(bdd_pay smk9 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if printf '%s' "$bdo" | grep -q 'Orchestrator Hot Tier' && [ "$(bdd_mode)" = "full_state||0" ]; then
  pass "FIRE: wake + absent state → FULL chunk 1, mode=full_state (fail direction: no state can never digest)"
else
  fail "FIRE: wake + absent state must emit FULL and log mode=full_state (got mode: $(bdd_mode))"
fi
# FIRE: the FULL emission carries the BAND-O-FULL-COPY <h8> anchor a later digest points at,
# AND carries it as a PREFIX. The prefix half (2026-08-14): emit() clamps an
# over-budget chunk to part[:EMIT_CLAMP_TO], so an anchor APPENDED after the band text is cut off
# every FULL copy the moment chunk-1 source passes EMIT_CLAMP_ABOVE minus the prepended prefix
# — 9,400 and ~9,465 when this was found, 9,700 and 9,539 today; both track the cap, which is why
# they are named here as symbols — while digests keep pointing at it. That is
# a dangling pointer reached with no race, purely by the band growing. A head-clamp always keeps
# a prefix, so position is the fix and position is what this asserts.
if printf '%s' "$bdo" | grep -q 'BAND-O-FULL-COPY ' \
   && [ "$(printf '%s' "$bdo" | python3 -c 'import json,sys; print(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"].find("BAND-O-FULL-COPY"))')" -lt 60 ]; then
  pass "FIRE: FULL chunk 1 carries the BAND-O-FULL-COPY <h8> anchor, as a PREFIX (clamp-safe)"
else
  fail "FIRE: FULL chunk 1 must OPEN with the BAND-O-FULL-COPY <h8> anchor — appended instead of prepended, a clamp eats it and every digest's pointer dangles"
fi
# FIRE: FULL chunk 1 ANNOUNCES the split, in its LEADING block. A prior change fixed exactly this
# one-sidedness on the DIGEST path and left the FULL path bare until 2026-08-16: chunk 1 carried
# the anchor and said nothing about a part 2, chunk 2 carried nothing at all — so a reader who
# received only one half had no signal the band was partial. That fix's own rationale ("asymmetric
# protection is worse than none here, because the covered direction makes the mechanism look
# handled") was written INTO the digest fix and applied to one of two paths; its digest notice was verified
# BY OBSERVATION, which could only ever cover the half that was fixed.
# LEADING for the prefix reason above: emit() clamps to a HEAD, so a trailing notice is the first
# thing an over-budget chunk loses — precisely when the notice matters most.
if printf '%s' "$bdo" | grep -qF 'THIS FULL BAND IS SPLIT' \
   && [ "$(printf '%s' "$bdo" | python3 -c 'import json,sys; print(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"].find("THIS FULL BAND IS SPLIT"))')" -lt 200 ] 2>/dev/null; then
  pass "FIRE: FULL chunk 1 announces the split in its LEADING block (a never-delivered part 2 is detectable)"
else
  fail "FIRE: FULL chunk 1 does not lead with the split notice — a reader who never receives part 2 gets NO signal that half the orchestrator band is missing, and the half that IS covered makes the mechanism look handled"
fi
# FIRE: the MIRROR half — FULL chunk 2 must not be BARE. Measured live in the 2026-08-15 wrap:
# 9,410 chars opening mid-table at "| About to ACT on / ESCALATE…" with zero markers of any kind.
# Drop that injection and nothing announces its absence. Same PREFIX discipline, and the position
# check is what discriminates: a marker appended to chunk 2's tail satisfies a bare grep and is
# eaten by the very clamp it needs to survive.
# The position bound is 60, not 0 — the token sits at index 5, after the "<!-- " comment opener,
# and a `-lt 5` first cut RED-ed on a perfectly correct emission. 60 still discriminates by three
# orders of magnitude: an APPENDED marker would land near 9,400. (Same bound as the sibling
# FULL_TAG arm above, which is where the number came from.)
bdo2=$(bdd_pay smk9 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 2 2>/dev/null)
# ⛔ MATCH 'BAND-O FULL 2/' NOT 'BAND-O FULL 2/2' — the denominator is DERIVED from the band's
# real part count since 2026-08-18, so pinning "2/2" made this arm RED the moment a third chunk
# was wired, on an emission that was doing exactly the right thing. The property is "chunk 2
# OPENS with ITS continuation marker"; the total is not this arm's business.
if printf '%s' "$bdo2" | grep -qF 'BAND-O FULL 2/' \
   && [ "$(printf '%s' "$bdo2" | python3 -c 'import json,sys; print(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"].find("BAND-O FULL 2/"))')" -lt 60 ] 2>/dev/null; then
  pass "FIRE: FULL chunk 2 OPENS with its continuation marker (a chunk-2-only reader knows the band is partial)"
else
  fail "FIRE: FULL chunk 2 is BARE (or the marker is not a prefix) — a reader who receives only chunk 2 gets ~9,400 chars starting mid-table with nothing saying half the band is missing"
fi
# FIRE (prefix regression, the discriminating case): grow chunk-1 SOURCE past the clamp point and
# assert the anchor SURVIVES. Under the pre-fix appended form this arm is the one that RED-ed:
# emission clamps, marker present, anchor GONE. Measured pre-fix at source 9480.
# ⛔ THE PAD IS DERIVED, NOT PINNED, AND THAT IS LOAD-BEARING. The first version appended ONE
#    fixed 70-char row, tuned to a band that then sat ~9,418 chars — i.e. the fixture was over
#    budget only because the real band happened to be near the ceiling. Trimming 410 chars out
#    of the band's header on 2026-08-14 took chunk 1 to 9,008, the padded fixture to ~9,108, and
#    this arm went RED for a reason with nothing to do with the property under test: the input
#    was simply no longer over budget, so no clamp fired and the SPLIT-FURTHER half could not
#    match. A pinned fixture measures the band's CURRENT size; a derived one measures the CLAMP.
#    Pad until source+261 (FULL_TAG + FULL_SPLIT + their newlines — 35 until FULL_SPLIT shipped
#    on 2026-08-16; corrected here 2026-08-17) clears the clamp with margin.
#    ⛔ AND THE PAD IS NOW ACTUALLY DERIVED — it was PINNED at 9600 against a pinned 9500
#    until 2026-08-17, i.e. this very comment's rule was broken one line below it. The
#    9,500 -> 9,800 raise would have left the fixture UNDER the clamp, so no clamp fires,
#    and the arm goes RED for a reason unrelated to the property (exactly the 2026-08-14
#    failure it describes). Read EMIT_CLAMP_ABOVE out of the hook instead of retyping it.
bdd1="$(mktemp -d)"; mkdir -p "$bdd1/.claude/orchestrator" "$bdd1/.claude/logs" "$bdd1/.claude/state"
python3 - .claude/orchestrator/active-recall-orchestrator.md "$bdd1/.claude/orchestrator/active-recall-orchestrator.md" <<'PY'
import sys, re
src, dst = sys.argv[1], sys.argv[2]
t = open(src, encoding="utf-8").read()
# DERIVE the clamp from the hook's own symbol; never retype the literal.
hook = open(".claude/hooks/band-o-inject.sh", encoding="utf-8").read()
CLAMP = int(re.search(r"^EMIT_CLAMP_ABOVE = (\d+)", hook, re.M).group(1))
MARK = "<!-- BAND-O-CHUNK-BOUNDARY -->"
a, b = t.split(MARK, 1)
row = "| GROWTH-PROBE " + ("x" * 70) + " | do the thing | L0 |\n"
a = a.rstrip("\n") + "\n"
while len(a.strip("\n")) < CLAMP + 100:   # emitted = source + 261 > CLAMP => clamp MUST fire
    a += row
open(dst, "w", encoding="utf-8").write(a + "\n" + MARK + b)
PY
bdo_grow=$(printf '{"prompt":"typed","session_id":"smkbandg-0000-0000-0000-000000000000"}' | CLAUDE_PROJECT_DIR="$bdd1" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if printf '%s' "$bdo_grow" | grep -q 'SPLIT FURTHER' && printf '%s' "$bdo_grow" | grep -q 'BAND-O-FULL-COPY '; then
  pass "FIRE: with chunk-1 source OVER the clamp point, the emission clamps AND the anchor survives (the prefix property, tested at the only input that can distinguish it)"
else
  fail "FIRE: over-budget chunk 1 lost its BAND-O-FULL-COPY anchor to the clamp — every digest's pointer now dangles with no race required"
fi
rm -rf "$bdd1"
# FIRE: digest-eligible wake → single-chunk DIGEST: triggers VERBATIM, deep action text ABSENT,
# READ-on-match header present, no clamp marker. The absent-literal sits ~950 chars into its
# action cell — beyond every head budget — so its absence proves heads are truncated.
bdd_state_mk 1 60
bdo=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if printf '%s' "$bdo" | grep -q 'DIGEST \[BAND-O-DIGEST ' \
   && printf '%s' "$bdo" | grep -q 'shake the defers' \
   && printf '%s' "$bdo" | grep -q 'do NOT act from a head' \
   && ! printf '%s' "$bdo" | grep -q 'flip rate is normal' \
   && ! printf '%s' "$bdo" | grep -q 'SPLIT FURTHER' \
   && [ "$(bdd_mode)" = "digest||1" ]; then
  pass "FIRE: digest-eligible wake → single-chunk DIGEST (trigger verbatim, action head truncated, READ-on-match header, no clamp)"
else
  fail "FIRE: digest turn broken — expected DIGEST with verbatim triggers + truncated heads + READ-on-match header (mode: $(bdd_mode))"
fi
# FIRE — WIDTH PIN. ⛔ THE ARM ABOVE IS WIDTH-BLIND BY CONSTRUCTION.
# Its `! grep 'flip rate is normal'` asserts truncation HAPPENED, and that token is absent at
# budget 240 and absent at budget 1 alike — so collapsing the ladder to a single character per row
# leaves it GREEN. Measured: with the ladder collapsed to (1,) the suite came back all-green on a
# digest carrying one character of action text per row. `shipped in full`, `whole row` and
# `FULL_ROWS` each returned 0 across this whole file, i.e. NOTHING pinned digest row WIDTH.
#
# ⛔ NO HARDCODED OFFSET, AND THAT IS THE POINT. The first
# version pinned the literal `hostility` and documented "offset 40" in this comment. Retirement of
# that token is the SAFE direction — it vanishes, the grep fails, the arm goes RED, loud. The
# DANGEROUS direction is a band edit that moves it EARLIER: reword the opening clause and it slides
# to offset 12, the arm still PASSES while pinning 12 chars, and the only record of the intended
# floor is a comment that is now false. Nothing in the suite can see it, and band rows are edited
# most days. An offset asserted in PROSE over content that legitimately moves erodes silently, and
# every erosion passes review because the arm is green.
#
# So the head length is DERIVED from the emitted digest and compared against a declared floor.
# ⚠️ DIGEST-SIDE ON PURPOSE. The first proposed remedy was `off = action.find(TOKEN); fail unless
# off >= N` — that reads the BAND, so it catches erosion but is blind to the LADDER: tighten the
# rung with offsets unchanged and it still passes, losing the dose property the arm exists for.
# Measuring the DELIVERED head keeps both: a band reword cannot erode it, and a tightened rung REDs.
#
# SENSITIVITY, derived from the ladder rather than from the row. build_lines() computes
#     head = act if len(act) <= budget else act[:budget].rstrip() + TR
# so for this row (838-char action, past every rung) head == the SELECTED RUNG, modulo an rstrip
# that can only SHORTEN it. The rungs are a FIXED, DISCRETE list — (240, 200, 170, 140, 120, 100,
# 80, 60) — and 60 is terminal. Live rung is 80; the floor is declared at 64. The only descent
# available from 80 is 80 -> 60, and 60 < 64, so the arm REDs on it. ⇒ THE ARM IS COMPLETE AGAINST
# LADDER DESCENT: there is no blind band, and a newly-added lower rung is caught too, since any
# rung < 64 fails. Mutation `ladder -> (60,)` gives 752/1, arm A alone, which is that proof.
# ⚠️ THIS SENTENCE REPLACES A REFUTED DERIVATION, not annotates it. It read
# "a 64-char head floor REDs once the clamp drops below ~206 — against 222 live, a ~16-char blind
# band", computing sensitivity from 222 minus the row's overhead. That treats 222 as a CLAMP; it is
# an OUTPUT (overhead + head). The wrong model both mis-stated the mechanism and UNDERSOLD the arm,
# inventing a 16-char slack it does not have — and it survived in the one place a future reader
# re-derives sensitivity from, after the refutation had already been recorded 20 lines above.
_wp_row='shake the defers'
# ⛔ `$bdo` IS ONE LINE OF RAW JSON, not markdown — the band lives in an ESCAPED
# `additionalContext` string. Every sibling arm here greps `$bdo` directly and that is fine for a
# PRESENCE check (substring on the blob), but any per-CELL derivation must json-load first: an
# `awk -F'|'` over the blob splits the JSON and silently returned a 55-char non-prefix, which reads
# exactly like a real dose collapse. Parse, don't split. Same idiom as bdd_mode() above.
# The ladder's SELECTED rung, from the hook's own log record for THIS fixture
# (band-o-inject.sh:707 writes "budget"), read with the bdd_mode() idiom above. It is what makes the
# exactness check below size-INDEPENDENT: the expected head is derived from the rung, never pinned
# to a literal. A missing/again-null value yields -1, which the probe reports as NOBUDGET and the
# arm treats as an instrument failure, not as a pass.
_wp_budget=$(grep '"session": "smkband2"' "$bdd/.claude/logs/band-o-inject.jsonl" 2>/dev/null | tail -1 \
  | python3 -c 'import json,sys; r=json.load(sys.stdin); b=r.get("budget"); print(b if isinstance(b,int) else -1)' 2>/dev/null)
_wp_budget=${_wp_budget:--1}
_wp_probe=$(printf '%s' "$bdo" | python3 -c '
import json, sys
band_path = sys.argv[1]
row = sys.argv[2]
def cell(line):
    c = [x.strip() for x in line.strip().strip("|").split("|")]
    return c[1] if len(c) > 1 else ""
def datarows(text):
    out = {}
    for l in text.splitlines():
        if not l.startswith("|"):
            continue
        c = [x.strip() for x in l.strip().strip("|").split("|")]
        if len(c) < 2 or not c[0] or set(c[0]) <= set("-: "):
            continue
        if c[0].lower().startswith("if you"):
            continue
        out.setdefault(c[0], (c[1], l))
    return out
try:
    ctx = json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"]
    band = open(band_path, encoding="utf-8").read()
except Exception as e:
    print("0 UNPARSEABLE 0 0 NOBUDGET"); raise SystemExit(0)
B, G = datarows(band), datarows(ctx)
src = [l for l in band.splitlines() if row in l]
got = [l for l in ctx.splitlines() if row in l]
if not src or not got:
    print("0 ROW-ABSENT 0 0 NOBUDGET"); raise SystemExit(0)
s = cell(src[0])
d = cell(got[0]).split("…")[0]
# The EXEMPTION SIGNATURE is length, not identity. build_lines() reads
#   head = act if len(act) <= budget else act[:budget].rstrip() + TR
# so a row whose action is SHORTER than the budget ships byte-identical with NO exemption
# involved -- 2 of 28 rows qualify today. Counting bare identity therefore stayed >=1 with
# exemptions DISABLED (measured 751/2, arm green, where the retired literal gave 750/3), i.e. the
# arm was decorative for the property it claimed. Only a row LONGER than the delivered truncated
# head can be identical by exemption, so that is the population.
whole = sum(1 for k, v in B.items()
            if k in G and G[k][0] == v[0] and len(v[0]) > len(d))
_b = int(sys.argv[3])
_want = (s if len(s) <= _b else s[:_b].rstrip()) if _b >= 0 else None
_ex = "NOBUDGET" if _want is None else ("EXACT" if d == _want.split("…")[0] else "INEXACT")
print("%d %s %d %d %s" % (len(d), "PREFIX" if d and s.startswith(d) else "NOPREFIX",
                       len(got[0]) - len(d), whole, _ex))
' "$bdd/.claude/orchestrator/active-recall-orchestrator.md" "$_wp_row" "$_wp_budget")
read -r _wp_n _wp_pfx _wp_over _wp_whole _wp_ex <<<"$_wp_probe"
# ⛔ THE FLOOR IS *NOT* COUPLED TO THIS ROW'S OTHER CELLS — a 2026-08-17 claim REFUTED, recorded
# here because the arithmetic is persuasive and the next reader will re-derive it. The claim was
# that the row spends 142 chars on overhead (10 pipes + 82 trigger + 35 evidence + 15 marker), so
# ~16 chars of legitimate growth in the trigger or evidence cell would push the head under 64 and
# false-RED with a message blaming the ladder. That reads 222 as a CAP and derives head = 222 -
# overhead. Backwards: build_lines() sets `head = act if len(act) <= budget else
# act[:budget].rstrip() + TR`, bounded SOLELY by budget with no reference to the other cells, so
# 222 is the CONSEQUENCE (overhead + head), not the constraint. Growing the trigger grows the ROW.
# Measured both ways: source read above, and a 26-char trigger growth in a worktree — past the
# predicted 16-char threshold — left the suite 753/0 with zero FAILs.
# The overhead is still DERIVED and still printed, as diagnostic context only. There is
# deliberately NO branch on it: a branch would advertise a guard against something that cannot
# happen, which is the wired-but-inert shape this file exists to catch.
_wp_over_expect=142
# ⛔ THE DELIVERED LENGTH IS A DIAGNOSTIC, NOT A GATE.
# This arm once asserted `_wp_n -ge 64`. build_lines() sets head = act[:budget] and budget is
# the LADDER's selected rung, which descends (240…60) as the band GROWS — so the assertion reddened
# as a MONOTONE FUNCTION OF BAND SIZE, and `.githooks/pre-push` hard-gates this suite on
# `.claude/orchestrator/` edits. That made it a blocking BYTE GOVERNOR on Band-O, which this
# design forbids: band governance warns and never blocks, byte visibility is kept without a byte governor,
# and no second, lower uniform cap is to be added. At the ladder's FLOOR rung of 60 the literal 64 was unreachable BY
# CONSTRUCTION, so the arm could only ever report the band's size back as a dose failure.
# PREFIX survives as the pass/fail because it is falsifiable, size-INDEPENDENT, and it is what
# catches the real defect — a digest that RE-RENDERS instead of truncating. UNPARSEABLE and
# ROW-ABSENT both report a non-PREFIX token, so an instrument failure still REDs, never passes
# vacuously (the property the old comment credited to the length check actually lives here).
# ⛔ WHAT REPLACES IT IS AN EXACTNESS CHECK, NOT A FLOOR — and it corrects
# an over-general sentence this comment carried for one commit. That sentence said NO floor could
# replace the literal, "because any floor expressed in DELIVERED chars is a function of the selected
# rung, hence of band size". True of a LITERAL floor; FALSE of an assertion whose expected value is
# DERIVED from the rung. `d == act[:budget].rstrip()` passes identically at rung 240 and at rung 60,
# so it is blind to band size, and it SUBSUMES the prefix check while also catching a short or
# mis-offset head — which PREFIX alone cannot (an "…" landing inside the first `budget` chars would
# shrink d and still prefix-pass; 0 of 28 rows today). The rejection of the length-equality form stands and
# is confirmed at source (:531 rstrips before appending the marker, and 7 of 28 rows cut on
# whitespace, so `len(d) == min(len(act), budget)` would false-RED across the table) — the fix is to
# derive the expectation WITH the rstrip, not to abandon the expectation.
# ⚠️ THE PRINTF BELOW IS NOT A REPORTING CHANNEL, and saying so would repeat the exact defect this
# arm exists to avoid: `.githooks/pre-push:317-321` sends the whole suite to a
# log and runs `tail -30` ONLY inside the failure branch, so on a PASS these bytes are written and
# never opened — the session-cadence.md placement rule verbatim, cited in this very comment one commit
# ago and then breached by it. It is a failure-branch diagnostic and nothing more. Putting the rung and
# the slack-to-next-rung where someone actually looks is filed separately, not claimed here.
printf '  · band-o dose (failure-branch diagnostic, NOT a gate and NOT a reporting channel): head=%s chars · prefix=%s · exact=%s · selected rung=%s · row overhead=%s (expected %s) — rung read from the FIXTURE log at $bdd/.claude/logs/band-o-inject.jsonl, not the live fleet log\n' \
  "$_wp_n" "$_wp_pfx" "$_wp_ex" "$_wp_budget" "$_wp_over" "$_wp_over_expect" >&2
if [ "$_wp_pfx" = "PREFIX" ] && [ "$_wp_ex" = "EXACT" ]; then
  pass "FIRE: digest ships a TRUNCATED row's ACTION as EXACTLY the ladder-derived head of the band source — prefix AND byte-exact against act[:budget].rstrip(), size-independent by construction"
else
  fail "FIRE: truncated-row action does not match the ladder-derived head for the '${_wp_row}' row — prefix=${_wp_pfx}, exact=${_wp_ex}. NOPREFIX ⇒ the digest is re-rendering rather than truncating. INEXACT ⇒ the head is short or mis-offset against the selected rung. NOBUDGET/UNPARSEABLE/ROW-ABSENT ⇒ this arm's own instrument broke, not the delivery."
fi
# FIRE — the SECOND axis, and it is a DIFFERENT MECHANISM, not a deeper pin on the same one.
# build_digest() has two independent controls and each arm owns exactly one:
#   the LADDER  decides how much of a TRUNCATED row ships   -> the arm above (PREFIX + EXACT)
#   is_exempt() decides whether a row escapes truncation at all -> this arm (>=1 whole over-budget row)
# They cannot be the same row by construction: a truncated row's head is capped at the selected rung
# (60 today — read it from the "budget" field, never from a literal here; it was 80 when this line
# was written and the whole point of the arm above is that the rung DESCENDS), so a row is either
# truncated-and-short or exempt-and-whole, never both. That is also
# why neither arm subsumes the other, and the two mutations prove it in OPPOSITE directions —
# `ladder -> (60,)` REDs the arm above alone (752/1), `pack(build_lines(.., False))` REDs this one
# alone (750/3, plus 2 known digest-below-split collateral).
#
# ⚠️ THIS BLOCK REPLACES A DESCRIPTION OF BOTH ARMS' PREVIOUS SHAPES — it read that a literal must
# sit past "~120 chars" because "truncation clamps a row to ~222 chars INCLUDING its trigger", and
# named `untouched` at offset 684 plus "the 40-char one". All three are dead: the 222 clamp is the
# refuted model (222 is an OUTPUT, overhead + head), and BOTH arms are now derived with no literal
# and no offset. The ~120 framing was the original ask, satisfiable only by an exempt
# row, which is exactly why the axis — not the depth — turned out to be the real distinction.
# Third surviving instance of that one refuted model in this file; a refutation is not folded until
# every restatement is struck, including the ones that merely EXPLAIN a still-correct conclusion.
# Arm B, same derivation, no literal either: this used to pin
# `untouched` with "offset 684" in a comment. Retirement of that token is the SAFE direction — it
# vanishes and the arm REDs — so it was never the defect the other arm had, but it was the last
# prose-offset in the pair, and it also hardcoded WHICH row the exemption picks. `whole` counts rows
# whose DELIVERED action cell is byte-identical to the band source, so it survives any reword and any
# change to which rows get exempted, while still REDing the moment exemptions stop being applied.
if [ "$_wp_whole" -ge 1 ]; then
  pass "FIRE: digest ships at least one OVER-BUDGET data row WHOLE — delivered action cell byte-identical to the band source AND longer than the truncated head, so only the exemption can explain it (${_wp_whole} row(s); derived, no literal)"
else
  fail "FIRE: the exemption path is dead — zero band data rows are delivered byte-identical to their source WHILE being longer than the truncated head (${_wp_n} chars), so every over-budget row is truncated and the digest carries no full-fidelity rule at all. Note the qualifier: rows whose action is SHORTER than the budget ship identical with no exemption involved (2 of 28 today), which is why bare identity is not the test. This is the EXEMPTION path — pack(build_lines(budget, True)) — not the ladder: the ladder decides how much of a TRUNCATED row ships, the exemptions decide whether any row escapes truncation at all."
fi
# FIRE (2026-08-14): THE DIGEST MUST NOT RENDER THE FULL-COPY MARKER LITERAL.
# The first version printed it three times — once inside the very sentence telling the reader to
# search for it — so a search could not return zero on a digest turn and the VOID CHECK was
# structurally self-satisfying: it voided the first reading of it. The digest now
# identifies itself with a DIFFERENT token and describes the full-copy marker in words. This is
# the only assertion that can tell a working void check from a decorative one.
if ! printf '%s' "$bdo" | grep -q 'BAND-O-FULL-COPY' \
   && printf '%s' "$bdo" | grep -q 'VOID CHECK'; then
  pass "FIRE: the digest carries a VOID CHECK and does NOT render the full-copy marker (a search for it CAN return zero)"
else
  fail "FIRE: the digest renders the full-copy marker literal, so a consumer's search self-satisfies and the VOID CHECK can never return zero"
fi
# FIRE: the VOID CHECK leads rather than trails — the prefix lesson applied to the digest's own
# guidance. emit() clamps to a PREFIX, so a footer notice is the first thing an over-budget
# digest loses, and it is the notice that matters most when the digest is degraded.
if [ "$(printf '%s' "$bdo" | python3 -c 'import json,sys; print(json.load(sys.stdin)["hookSpecificOutput"]["additionalContext"].find("VOID CHECK"))')" -lt 900 ]; then
  pass "SAFE: the digest's VOID CHECK sits in the leading block, where a prefix-clamp cannot eat it"
else
  fail "SAFE: the digest's VOID CHECK has moved out of the leading block — a clamp would remove exactly the notice that detects a degraded digest"
fi
# SAFE: a SPLIT digest announces the split in BOTH directions. Part 2 already told a part-2-only
# reader that their band is PARTIAL; part 1 said nothing, so a part-1-only reader saw a
# complete-LOOKING digest with three rows' worth of content silently absent. The hook's own
# chunk-2 comment records "a single turn missing chunk 2" as a real transient state, so this is
# reachable, and asymmetric protection is worse than none — the covered direction makes the
# mechanism look handled. Guarded here because nothing else can tell a live notice from a
# deleted one: the digest ships either way.
if printf '%s' "$bdo" | grep -q 'THIS DIGEST IS SPLIT'; then
  pass "SAFE: a split digest tells a part-1-only reader that a part 2 follows and its absence means PARTIAL"
else
  fail "SAFE: part 1 of a split digest does not announce the split — a reader who never receives part 2 sees a complete-looking band with rows silently missing"
fi
# SAFE: chunk 2 on the SAME digest turn emits the digest's CONTINUATION — never the FULL chunk 2.
# The digest has two slots by design, with those three rows kept whole, which
# retires the single-chunk contract this arm used to assert (emptiness). The CONCERN it was written
# for is unchanged and is what the second clause still pins: if chunk 2 falls back to the full band,
# every wake delivers digest + full-chunk-2 and the digest saves nothing.
# Clause 1 ('CONTINUATION') is unchanged and still discriminating: it appears 0x in the band file,
# so it can only come from the continuation header.
# ⛔ CLAUSE 2 WAS RE-ANCHORED 2026-09-01, AND THIS ARM'S OWN COMMENT PREDICTED IT. It read
# `! grep 'User pushback handling'`, and the 2026-08-18 note here said: that section now lives in
# FULL chunk 3, the clause is no longer the full-vs-digest tell it was written as, "the sibling arm
# below was re-anchored on 'BAND-O FULL 2/' for exactly that reason; do the same here if this ever
# RED-s." It RED-ed. Doing exactly that.
# WHY IT WENT RED, and it was NOT a regression in the hook: the old clause rested on WHERE the pack
# split lands ("absent from digest part 2 — it packs into part 1"). Restoring the digest at
# 2026-09-01 moved the split, so that section now packs into part 2, and a positional premise
# expired. The BEHAVIOUR was verified correct independently before this edit: on a digest turn
# chunk 2 came back 3,125 chars OPENING with the DIGEST CONTINUATION header — it is the
# continuation, not the full band.
# ⛔ THE REPLACEMENT WAS PROVED TO DISCRIMINATE BEFORE IT SHIPPED, in BOTH directions, because
# editing a test until it passes is the failure this file exists to prevent:
#     digest part 2 (case under test)   len 3125   CONTINUATION 1   'BAND-O FULL 2/' 0
#     FULL chunk 2  (case to exclude)   len 8055   CONTINUATION 0   'BAND-O FULL 2/' 1
# Perfect separation. And it is STRUCTURAL rather than positional: 'BAND-O FULL 2/' is emitted by
# the full-chunk path itself, so it cannot expire when a future band edit moves the split again —
# which is precisely how the clause it replaces died.
bdo2=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 2 2>/dev/null)
if printf '%s' "$bdo2" | grep -q 'CONTINUATION' \
   && ! printf '%s' "$bdo2" | grep -qF 'BAND-O FULL 2/'; then
  pass "SAFE: chunk 2 on a digest turn emits the digest CONTINUATION, not the full chunk 2"
else
  fail "SAFE: chunk 2 on a digest turn is not the digest continuation — if it is the FULL chunk 2 the band arrives as digest + full-chunk-2 every wake and the saving is void"
fi
# FIRE: chunk 2 with NO state (doubt) → FULL chunk 2 — doubt fails toward MORE, never silence
# ⛔ ANCHORED ON THE FULL CONTINUATION MARKER, NOT ON A SECTION NAME (2026-08-18). This arm used
# to grep 'User pushback handling' because that section happened to sit in FULL chunk 2; the
# 3-chunk split moved it to chunk 3 and the arm RED-ed on a correct emission. 'BAND-O FULL 2/' is
# emitted ONLY by the full path (the digest path emits its own CONTINUATION header), so it
# discriminates full-vs-digest without caring where any section lives.
rm -f "$bdd_state"
bdo2=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 2 2>/dev/null)
if printf '%s' "$bdo2" | grep -qF 'BAND-O FULL 2/'; then
  pass "FIRE: chunk 2 with no state → FULL chunk 2 (doubt fails toward more)"
else
  fail "FIRE: chunk 2 with no state must emit FULL chunk 2 — silence here is the forbidden fail direction"
fi
# FIRE: 10-turn heartbeat → FULL even on a digest-eligible wake
bdd_state_mk 10 600
bdd_pay smk1 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "full_heartbeat||10" ]; then
  pass "FIRE: since_full=10 → FULL (heartbeat — a digest run can never exceed 10 turns without a full copy)"
else
  fail "FIRE: heartbeat at since_full>=10 did not fire (got: $(bdd_mode))"
fi
# FIRE: the deterministic 1-in-10 HOLDOUT draw → FULL + arm=holdout (the salience instrument —
# holdout-vs-digest compliance contrast is the pre-registered rollback tell)
bdd_state_mk 1 60
bdd_pay smk8 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "full_holdout|holdout|1" ]; then
  pass "FIRE: holdout draw → FULL + arm=holdout logged (the salience instrument the re-open condition demanded)"
else
  fail "FIRE: the holdout arm did not fire on the pinned fixture (got: $(bdd_mode)) — without it the digest's salience cost is unmeasurable (the decorated-never failure)"
fi
# FIRE: band-file md5 drift vs state → FULL (an edited band must re-deliver in full)
bdd_state_mk 1 60 deadbeef
bdd_pay smk1 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "full_band_changed||1" ]; then
  pass "FIRE: band md5 changed since last full → FULL (a band edit always re-delivers in full)"
else
  fail "FIRE: band-changed path did not fire (got: $(bdd_mode))"
fi
# FIRE: PreCompact marker newer than last full → FULL (the compaction-epoch key; compact-save.sh
# writes post-compact-pending-<sid> at every compaction)
bdd_state_mk 1 3600
printf 'compacted=%s UTC trigger=auto focus=no\n' "$(date -u '+%Y-%m-%d %H:%M:%S')" > "$bdd/.claude/state/post-compact-pending-$bdd_sid"
bdd_pay smk1 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "full_post_compact||1" ]; then
  pass "FIRE: PreCompact marker whose compacted= is newer than the last full → FULL (a new context window never opens on a digest)"
else
  fail "FIRE: post-compact epoch path did not fire (got: $(bdd_mode))"
fi
# ⛔ FIRE (2026-08-14) — THE DISCRIMINATING ARM, and the one the original build
# had backwards. This hook first read the marker's MTIME. But post-compact-pending-check.sh:51
# `touch`es that marker on EVERY UserPromptSubmit so a peer's GC cannot reap a live session's
# marker — its own comment states the contract: "The compaction TIME stays in the marker CONTENT
# (compacted=<ts>) — mtime is liveness." So `mtime > last_full` was true on every single turn and
# the digest path was 100% DEAD for any session carrying an uncleared marker (measured 0/8
# with the touch vs 6/8 without). It failed SAFE, which is exactly why nothing noticed: the
# feature silently did nothing for a whole class of sessions while polluting the digest_rate
# denominator. This arm plants an OLD compacted= under a FRESH mtime — the only input shape that
# separates the two readings — and requires a DIGEST.
bdd_state_mk 1 60
printf 'compacted=2020-01-01 00:00:00 UTC trigger=auto focus=no\n' > "$bdd/.claude/state/post-compact-pending-$bdd_sid"
touch "$bdd/.claude/state/post-compact-pending-$bdd_sid"
bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "digest||1" ]; then
  pass "FIRE: an OLD compacted= under a FRESH mtime still DIGESTS — the epoch is read from the marker's CONTENT, not its liveness-touch"
else
  fail "FIRE: the epoch check is reading MTIME again — a sibling hook touches that marker every turn, so the digest path is dead for every session with an uncleared marker (got: $(bdd_mode))"
fi
# SAFE: an unparseable marker must force FULL — doubt about the epoch resolves toward MORE.
bdd_state_mk 1 60
printf 'garbage with no timestamp\n' > "$bdd/.claude/state/post-compact-pending-$bdd_sid"
bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "full_post_compact||1" ]; then
  pass "SAFE: an unparseable PreCompact marker → FULL (epoch doubt fails toward more, never less)"
else
  fail "SAFE: an unparseable marker must force FULL, not be treated as 'no compaction' (got: $(bdd_mode))"
fi
rm -f "$bdd/.claude/state/post-compact-pending-$bdd_sid"
# FIRE: typed prompt ALWAYS full, even with fresh digest-eligible state (owner turns are full)
bdd_state_mk 1 60
printf '{"prompt":"a typed owner prompt","session_id":"%s"}' "$bdd_sid" | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 >/dev/null 2>&1
if [ "$(bdd_mode)" = "full_typed||1" ]; then
  pass "FIRE: typed prompt → FULL regardless of state (owner turns always get the full band)"
else
  fail "FIRE: a typed prompt digested (got: $(bdd_mode)) — owner turns must always receive the full band"
fi
# FIRE (needle, obligation-derived fixture): a NEW row added to the band must reach the
# digest's scan surface — a generator that silently drops rows is the one failure a clean run
# cannot distinguish from a working one without a planted needle.
printf '\n| SMOKE-NEEDLE-TRIGGER-XYZ about to frobnicate the wozzle | Do the smoke-needle action FIRST, then report | L0 |\n' >> "$bdd/.claude/orchestrator/active-recall-orchestrator.md"
# ⚠️ THE NEEDLE IS APPENDED AT THE END OF THE BAND, SO IT PACKS INTO PART 2. Scanning chunk 1
# alone was correct while the digest was single-chunk and became a FALSE RED the moment it was
# given two slots — the row surfaced perfectly and the instrument could not see it. The
# obligation is "no row is DROPPED", and the digest is now both parts, so both parts are the scan
# surface. A chunk-1-only scan would also fail-QUIET in the other direction as the band grows: any
# row that migrates past the split boundary would read as dropped.
bdd_state_mk 1 60
bdo=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
bdo2=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 2 2>/dev/null)
if printf '%s%s' "$bdo" "$bdo2" | grep -q 'SMOKE-NEEDLE-TRIGGER-XYZ' && printf '%s' "$bdo" | grep -q 'DIGEST \[BAND-O-DIGEST '; then
  pass "FIRE: a planted NEW band row surfaces in the digest, across both parts (the generator drops no trigger)"
else
  fail "FIRE: a planted new band row did NOT surface across the digest's parts — EITHER the generator is dropping rows OR chunk 2 is not emitting the continuation (check the chunk-2 arm above FIRST; this arm's scan surface includes it, so a broken emitter reds here too)"
fi
# FIRE: a WRAPPED row — a continuation on a non-`|` line — must REFUSE. The
# structural cross-check counts only `|`-prefixed lines, so a wrap is invisible to it: the row's
# continuation was silently DROPPED from the digest while the identity still balanced and
# nothing refused (measured `(27,2,31) OK` both before and after planting one). The guard
# now validates the table REGION, not just the line counts.
printf '\n' >> "$bdd/.claude/orchestrator/active-recall-orchestrator.md"
python3 - "$bdd/.claude/orchestrator/active-recall-orchestrator.md" <<'PY'
import sys
p = sys.argv[1]; L = open(p, encoding="utf-8").read().split("\n")
for i, ln in enumerate(L):
    if ln.startswith("| Mark a feature"):
        L.insert(i + 1, "  a wrapped continuation that a pipe-count cannot see"); break
open(p, "w", encoding="utf-8").write("\n".join(L))
PY
bdd_state_mk 1 60
bdo=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if printf '%s' "$bdo" | grep -q 'Orchestrator Hot Tier' && [ "$(bdd_mode)" = "fallback_full_digest||1" ]; then
  pass "FIRE: a wrapped row continuation → REFUSE → FULL (the region guard sees what the pipe-count cannot)"
else
  fail "FIRE: a wrapped row was silently dropped from the digest — the cross-check is counting lines instead of validating the table region (got: $(bdd_mode))"
fi
# FIRE: a malformed band row → digest generation REFUSES → FULL (fail OPEN, logged fallback)
printf '| onlyonecell |\n' >> "$bdd/.claude/orchestrator/active-recall-orchestrator.md"
bdd_state_mk 1 60
bdo=$(bdd_pay smk0 | CLAUDE_PROJECT_DIR="$bdd" bash .claude/hooks/band-o-inject.sh 1 2>/dev/null)
if printf '%s' "$bdo" | grep -q 'Orchestrator Hot Tier' && [ "$(bdd_mode)" = "fallback_full_digest||1" ]; then
  pass "FIRE: unparseable band row → FULL emitted + mode=fallback_full_digest (parse doubt fails open, visible in digest_rate)"
else
  fail "FIRE: parse-failure path broken — a malformed row must force FULL, never a garbled or missing digest (got: $(bdd_mode))"
fi
# ── FIRE: THE DIGEST'S OWN HEALTH INSTRUMENT MUST BE GREEN ────────────────────────────
# ⛔ ADDED 2026-09-01, AND IT IS THE ARM WHOSE ABSENCE LET THE DIGEST DIE FLEET-WIDE FOR DAYS.
# `band-o-digest-metrics.py` exits 1 when build_digest() returns None and prints "DIGEST IS
# DEAD" in one line. It was written 2026-08-14 by an author who diagnosed this exact silence
# and said so in its own header: the hook's prose "refers to a pre-registered digest_rate<50%
# alarm as though it were an instrument … all three mentions are COMMENTS … nothing computed
# it and nothing surfaced it, which is exactly why the headroom cliff is silent: the digest
# can die fleet-wide and the only trace is a log nobody reads."
#
# They were right, they built the instrument — and NOTHING RAN IT. Measured at this arm's
# filing: no hook, no CI job, no test and no cadence invoked the script; its only references
# were a plan doc, a memory archive and a comment in the hook it measures. So the
# band grew 287 chars past what the floor rung can carry, build_digest() returned None, every
# seat silently fell back to FULL, and the only signal was seven arms whose failure text
# blamed the wrong mechanism. `active-recall.md`: fireable ≠ consequential — something must
# FAIL when it fires un-actioned. This is that something.
#
# WHY HERE RATHER THAN A CADENCE: `.githooks/pre-push` runs this suite whenever the changed
# set touches `.claude/hooks/`, `.claude/orchestrator/` or `.githooks/` — and an edit to
# `.claude/orchestrator/active-recall-orchestrator.md` IS the band edit that can push the
# digest over the cliff. So the gate already fires at exactly the event that breaks it; the
# only thing missing was an arm that reads the verdict.
#
# ⛔ `--log` IS LOAD-BEARING, NOT DECORATION. Invoked BARE, `out["health"]`
# is never populated (it is set only under `--log`), so the CLIFF early-warning branch is
# UNREACHABLE and the failure text below would promise headroom coverage the arm cannot deliver.
# The positive control: headroom=1037 vs floor=1038 -> CLIFF. Today: headroom 6986, floor
# ~1038, so this does not false-fire.
# ⚠️ AND THE RATE IS DELIBERATELY NOT WINDOWED INTO THIS GATE, against the review's suggestion,
# because I measured it and a window false-fires on a HEALTHY digest. The rate is a LAGGING
# signal: any window wide enough to be meaningful still contains the outage it is reporting.
#     lifetime 84.7%  ·  last-50 28.0%  ·  last-200 7.0%  ·  today (per-day) 9.3%
# Every one of those is under the 50% floor while build_digest() is demonstrably HEALTHY, because
# most of today's turns predate the fix. Windowing would have made this arm block every push on a
# working digest. The live `build_digest()` result — which is what rc keys on — is the current
# state; the log rate is history. A per-day rate WOULD have fired on 2026-08-31 (0.6%) and is
# worth having as a REPORT, but it is the wrong thing to gate on.
# NOT a duplicate of the digest arms above: they exercise the hook against a FIXTURE root and
# assert on emitted text. This runs the REAL build_digest() against the LIVE band and reads
# its health verdict — the arms can all pass on a fixture the live band has since outgrown.
# ⛔ `--log` ONLY WHEN THE LOG EXISTS — CI HAS NONE, BY CONSTRUCTION (fixed 2026-09-01, same
# day, after this arm failed CI unconditionally). `band-o-inject.jsonl` is a
# RUNTIME log: git-ignored, never checked in, so a fresh CI checkout has no such file. The
# script resolves it from its OWN location (ROOT = dirname(dirname(__file__))), not from the
# environment, and `read_log()` turns the missing file into `fail()` -> **exit 2**. Measured in
# an isolated root with no log: bare rc=0, `--log` rc=2 "cannot read ... No such file".
# ⚠️ HOW I SHIPPED IT: I verified `--log` does not false-fire LOCALLY, where the log exists, and
# never asked what it reads where there is none — the wrong-population error, one step after
# diagnosing the same shape in a peer's probe. Local-passes is not CI-passes for anything that
# touches a runtime artifact.
# WHAT EACH BRANCH BUYS: with a log, the CLIFF early-warning (headroom under its derived floor)
# is reachable — and that branch runs where it matters most, because `.githooks/pre-push` runs
# this suite LOCALLY at the moment someone pushes a band edit. Without a log, the bare form
# still runs the REAL build_digest() against the LIVE band, which is the load-bearing half: it
# is what catches the digest being DEAD, the failure this whole arm exists for.
if [ -s .claude/logs/band-o-inject.jsonl ]; then
  _bdm_ok=0; python3 scripts/band-o-digest-metrics.py --log >/dev/null 2>&1 || _bdm_ok=$?
else
  _bdm_ok=0; python3 scripts/band-o-digest-metrics.py >/dev/null 2>&1 || _bdm_ok=$?
fi
if [ "$_bdm_ok" = "0" ]; then
  pass "FIRE: the digest health instrument is GREEN against the LIVE band (build_digest() returns a digest, headroom above floor)"
else
  fail "FIRE: band-o-digest-metrics.py --log is NON-ZERO — the digest is DEAD, or headroom is under its derived floor, against the LIVE band. Run \`python3 scripts/band-o-digest-metrics.py --log\` for the verdict. ⛔ READ WHICH PART BINDS BEFORE TRIMMING ANYTHING — the two failures have OPPOSITE remedies and the wrong one moves nothing. LADDER-EXHAUSTED (build_digest returns None): the ladder measures the UN-EXEMPTED render where every action is already truncated to the rung, so trimming action prose is worthless — measured, halving EVERY non-exempt action cell removed 28.7% of the band and moved the binding number by 30 chars. Only fewer ROWS or shorter TRIGGERS help. PART-2 BOUND (the normal state since 2026-09-01, and the one you will actually hit): the three EXEMPT rows ship their action WHOLE into part 2, so there trimming those three IS the lever — halving them drops part 2 by 1272 chars, 18% of headroom — while it leaves the ladder untouched."
fi
rm -rf "$bdd" "$bo_iso"
# FIRE: session-start.sh deletes this session's Band-O state at EVERY SessionStart, so the
# first injection of a fresh window is FULL by construction (not merely by heartbeat-eventually).
printf '{"sid8":"smkband2","band_md5":"cafecafe","last_full_at":1,"since_full":3,"turn":{}}' > .claude/state/band-o-state-smkband2.json
echo '{"session_id":"smkband2-0000-0000-0000-000000000000","source":"resume"}' | bash .claude/hooks/session-start.sh >/dev/null 2>&1
if [ ! -f .claude/state/band-o-state-smkband2.json ]; then
  pass "FIRE: session-start.sh deletes band-o-state-<sid8>.json — a fresh window's first injection is FULL by construction"
else
  fail "FIRE: session-start.sh left band-o-state-<sid8>.json in place — a resumed/compacted window could open on a digest"
  rm -f .claude/state/band-o-state-smkband2.json
fi
rm -f ".claude/state/session-start-sha-smkband2-0000-0000-0000-000000000000" 2>/dev/null

echo ""
echo "=== grep-blowup-warn.sh (the two grep shapes that OOM'd this box) ==="
# Four ugrep processes reached 5.44 / 19.78 / 21.71 / 57.66 GB and had to be killed on
# 2026-07-31/08-01. Two independent causes, both guarded here. Runaways arrived via the BASH
# tool (parent chain ugrep -> zsh -> zsh -> claude), which is why a Bash matcher reaches them.
gbw() { python3 -c "import json,sys; print(json.dumps({'tool_name':'Bash','tool_input':{'command':sys.argv[1]}}))" "$1" \
        | GREP_BLOWUP_NO_LOG=1 bash .claude/hooks/grep-blowup-warn.sh 2>&1; }
# STDOUT-ONLY sibling. gbw() MERGES 2>&1 by design (the absroot arm is warn-mode stderr), and a
# merged stream can never parse as one JSON document — so the parse arm needs its own capture.
gbw_stdout() { python3 -c "import json,sys; print(json.dumps({'tool_name':'Bash','tool_input':{'command':sys.argv[1]}}))" "$1" \
        | GREP_BLOWUP_NO_LOG=1 bash .claude/hooks/grep-blowup-warn.sh 2>/dev/null; }

# SUBSTITUTION-STRIP arms (2026-08-13). `$( ... | ... )` is parens-with-a-pipe by construction, so
# it satisfied the gap predicate with NO alternation present — a use-class FP that denied two seats
# on real invocations AND denied both their bug reports. Fixed by stripping command substitutions
# before the shape test. These two arms are the DISCRIMINATING PAIR: the first alone would pass on
# a hook that had simply stopped firing, so the second (a real backtracking shape carried on a line
# that ALSO holds a substitution) is what proves the strip did not open an escape hatch.
out=$(gbw "grep -oE '^ab.*' f \"\$(basename x | tr a b)\"")
assert_empty "SAFE: quantifier + command-substitution-with-pipe, no alternation → silent" "$out"
out=$(gbw "grep -oE '.{0,120}(five|branch).{0,120}' \"\$(basename x | tr a b)\"")
assert_contains "FIRE: real backtracking shape SURVIVES the substitution strip → still denied" "$out" "BLOCKED"

# MODE IS SPLIT PER ARM since 2026-08-01 (same day the promotion landed):
#   shape   -> BLOCK (deny JSON + exit 2)   — ~~zero measured false positives~~ (see the 08-13 arms
#             above: a use-class FP hit two seats; its CAUSE is fixed, so the arm still blocks)
#   absroot -> WARN  (stderr + exit 0)      — 3 of 3 measured false positives came from this arm,
#              two of them STRUCTURAL (a command-string matcher cannot tell an INVOCATION from a
#              QUOTED MENTION, so writing *about* an absolute-root grep trips it forever).
out=$(gbw "grep -rnoiE '.{0,120}(alpha|beta|gamma).{0,120}' notes.md")
assert_contains "FIRE: variable-width quantifier BEFORE an alternation -> DENY" "$out" '"permissionDecision": "deny"'
assert_contains "FIRE: the deny names the SHAPE and carries the rewrite" "$out" "BACKTRACKING SHAPE"
sout=$(gbw_stdout "grep -rnoiE '.{0,120}(alpha|beta|gamma).{0,120}' notes.md")
assert_one_json_doc "PARSE: grep-blowup-warn.sh shape-deny arm → ONE parseable hookSpecificOutput doc, the settings.json-env escape at the REASON'S TAIL survives" "$sout" 'SKIP_GREP_BLOWUP_WARN=1'
out=$(gbw "rg -oE '.*(foo|bar)' src/")
assert_contains "FIRE: backtracking shape also caught on rg" "$out" "BACKTRACKING SHAPE"

# ⛔ ATOM-GENERALITY (corpus validation, 2026-08-01). The shape predicate hardcoded `\.` for
# its first ~4 hours and was BLIND to a negated character class carrying the SAME catastrophic
# shape. A /wrap deep-pass slice agent ran exactly that form, the guard allowed it, the grep was
# killed at 120s, and a sibling agent's ugrep peaked at 14.46 GB in the same wave. These arms pin
# the atom spellings agents actually write. The third is the atom from this repo's OWN deep-pass
# brief and was the single member the FIRST widening still missed (a leading literal `]` inside
# the bracket expression is a literal in POSIX/ERE, so a naive `\[[^]]*\]` matches only part of it).
# Fixtures are built here from parts, never written as one literal: this guard blocks its own
# documentation, which is the whole point of that rule and cost two blocked commands while writing this.
_gbw_lead='[^"\\]{0,400}'
_gbw_lead2='[a-z]{0,90}'
_gbw_lead3='[^]]{0,400}'
_gbw_alt='(alpha|beta)'
out=$(gbw "grep -oE '${_gbw_lead}${_gbw_alt}' f.jsonl")
assert_contains "FIRE: atom = NEGATED CLASS is the same shape as . (the live miss)" "$out" "BACKTRACKING SHAPE"
out=$(gbw "grep -oE '${_gbw_lead2}${_gbw_alt}' f.jsonl")
assert_contains "FIRE: atom = ranged class" "$out" "BACKTRACKING SHAPE"
out=$(gbw "grep -oE '${_gbw_lead3}${_gbw_alt}' f.jsonl")
assert_contains "FIRE: atom = the class in our OWN deep-pass brief (leading literal ])" "$out" "BACKTRACKING SHAPE"
out=$(gbw "grep -oE 'PLAN_LIMITS[^ ]{0,40}' src/types/index.ts")
assert_empty "SAFE: class-quantifier AFTER a literal with no alternation -> silent" "$out"

# ⛔ COMPOSITIONAL FALSE POSITIVE — the guard used to
# scan the WHOLE line for each of its three signals independently, so on a compound command the
# three could be satisfied by three UNRELATED sub-commands: a grep anywhere + a quantified atom
# before a paren anywhere (in a SED) + a `|` anywhere (a SHELL PIPE). That denied ordinary
# mail-header work a peer typed before any of this was under review. TWO independent fixes, and
# the discriminating controls below prove BOTH are live — the first mutation attempt used a
# fixture where they agree and read as if segment scoping were inert.
_gbw_q="'"
_gbw_alt='(alpha|beta)'
_gbw_lead='.{0,50}'
_gbw_cls='[0-9]{10,}'
_gbw_sedcap="sed -E ${_gbw_q}s/.*(${_gbw_cls})/x/${_gbw_q} g.md"
_gbw_sedhaz="sed -E ${_gbw_q}s/${_gbw_lead}${_gbw_alt}/x/${_gbw_q} g.md"
_gbw_grephaz="grep -oE ${_gbw_q}${_gbw_lead}${_gbw_alt}${_gbw_q} f.jsonl"
# carried by the IN-PAREN `|` fix: a shell pipe is not an alternation
out=$(gbw "grep -c foo f.md | head; ${_gbw_sedcap}")
assert_empty "SAFE compositional: grep|head ; sed-capture (pipe is not an alternation)" "$out"
# carried by the SEGMENT-SCOPE fix: a non-grep segment holding a FULL hazard shape
out=$(gbw "grep -c foo f.md | head; ${_gbw_sedhaz}")
assert_empty "SAFE compositional: harmless grep ; sed carrying the full shape (not grep-family)" "$out"
# the real hazard must survive BOTH fixes, alone and in a compound line
out=$(gbw "${_gbw_grephaz}")
assert_contains "FIRE: shape inside the grep's OWN pattern still denies" "$out" "BACKTRACKING SHAPE"
out=$(gbw "grep -c foo f.md | head; ${_gbw_grephaz}")
assert_contains "FIRE: hazard grep in a COMPOUND line still denies" "$out" "BACKTRACKING SHAPE"

# ⛔ QUOTE-AWARE SPLIT (the split + the fail-closed line, 2026-08-18). Until these three landed,
# ALL 22 gbw arms above gave IDENTICAL verdicts on the commit and on its parent — every compound
# arm uses `;`, which was already a split point, so the change's whole subject (an unquoted `|`)
# was exercised by nothing and "753 PASS" said nothing about it. Re-derived
# here against two mutants: `revert` = the parent commit, `unaware` = the split with its `!sq && !dq`
# quote guard deleted. Measured verdicts, want/live/revert/unaware:
#   ARM 1  DENY / DENY / silent / silent   — caught by BOTH mutants
#   ARM 2  silent / silent / DENY / silent — caught by revert only
#   ARM 3  DENY / DENY / DENY  / silent    — caught by unaware only
# So NO TWO OF THEM COVER THE THIRD, and ARM 3 is the load-bearing one: it is the only assertion
# pinning the safety property the whole change rests on — that a QUOTED alternation is still a
# hazard even when a shell pipe follows it. Do not "simplify" these into one arm.
out=$(gbw "grep -oE ${_gbw_q}${_gbw_lead};${_gbw_alt}${_gbw_q} f.jsonl")
assert_contains "FIRE: a quoted ';' no longer cuts the hazard in half" "$out" "BACKTRACKING SHAPE"
out=$(gbw "awk ${_gbw_q}/^def [a-z_]+\\(/${_gbw_q} f.py | grep -F peek")
assert_empty "SAFE: the gap span may not reach ACROSS a shell pipe for its alternation" "$out"
out=$(gbw "${_gbw_grephaz} | head -3")
assert_contains "FIRE: a QUOTED alternation survives the pipe split (the safety property)" "$out" "BACKTRACKING SHAPE"

# The arms feed the ROOT THE HOOK DERIVES (portable by rule): the same ladder, so the
# predicate is exercised wherever the suite runs — the live tree, a CLAUDE_PROJECT_DIR-pinned matrix
# worktree, another machine. Before this they fed one Mac's literal path (an earlier arm-side fix
# was for a hook that still keyed on that literal).
# absroot arm — WARN. The not-contains arm is the DISCRIMINATING one: it is the only assertion
# here that fails if someone re-promotes this arm to block without re-opening the FP evidence.
out=$(gbw "grep -rlF PLAN_LIMITS ${_gbw_root}")
assert_contains "FIRE: absolute repo root on grep (ugrep --ignore-files dies) -> WARN" "$out" "ABSOLUTE ROOT"
assert_contains "FIRE: the warn names its own mode (so the demotion is legible in-band)" "$out" "(warn)"
assert_not_contains "FIRE: absroot must NOT deny — it is warn-mode, 3/3 FPs came from it" "$out" "permissionDecision"

# BOTH arms fire -> the BLOCK wins, and the deny still carries the absroot rewrite.
out=$(gbw "grep -rnoiE '.{0,120}(alpha|beta)' ${_gbw_root}")
assert_contains "FIRE: shape+absroot together -> DENY (block wins over warn)" "$out" '"permissionDecision": "deny"'
assert_contains "FIRE: the both-fire deny still names the ROOT cause too" "$out" "ABSOLUTE ROOT"

# ⚠️ FALSE-POSITIVE REGRESSION GUARD — measured within ONE command of going block-mode.
# Every Bash call here opens with a `cd` to the absolute repo path, so the absolute path sits in
# the command string of nearly EVERYTHING. Without the cd-strip, any command that cds to the repo
# and contains a grep anywhere was DENIED — it blocked this suite's own invocation on the first
# run. A `cd` target is not a grep ROOT. These arms pin the strip.
out=$(gbw "cd ${_gbw_root} && ./scripts/smoke-test-hooks.sh | grep -E 'PASS:'")
assert_empty "SAFE: cd <abs-repo> + an unrelated grep -> silent (the FP that bit on day one)" "$out"
out=$(gbw "cd ${_gbw_root} && rg -n foo src/")
assert_empty "SAFE: cd <abs-repo> + rg -> silent" "$out"
# ...and the strip must NOT weaken the guard: cd AND a real abs search root still fires (warn).
out=$(gbw "cd ${_gbw_root} && grep -rlF PLAN_LIMITS ${_gbw_root}")
assert_contains "FIRE: cd <abs> AND abs SEARCH ROOT still fires (strip did not blind it)" "$out" "ABSOLUTE ROOT"

# SAFE arms — each is a DISCRIMINATING negative, not a representative one.
out=$(gbw "grep -rlF PLAN_LIMITS .")
assert_empty "SAFE: relative root -> silent" "$out"
out=$(gbw "rg -lF PLAN_LIMITS ${_gbw_root}")
assert_empty "SAFE: rg is root-spelling immune (own gitignore walker) -> silent" "$out"
out=$(gbw "grep -rlF --exclude-dir=worktrees X ${_gbw_root}")
assert_empty "SAFE: absolute root WITH --exclude-dir=worktrees -> silent" "$out"
out=$(gbw "grep -rn 'literal.{0,300}' slice.jsonl")
assert_empty "SAFE: forward-anchored quantifier (no alternation) -> silent" "$out"
out=$(gbw "npm test")
assert_empty "SAFE: non-grep command -> silent" "$out"
# ⚠️ THIS ARM EMITS THE SUITE'S ONE `BrokenPipeError`, AND IT IS BENIGN — the cause is recorded here
# because it survived only in a commit body, and the FIRST stated cause (a head-capped arm) was WRONG.
# Mechanism: the skip escape makes the hook exit at grep-blowup-warn.sh's skip line, which sits ABOVE its
# `input=$(cat …)` — so stdin is never drained, python's stdout flush at interpreter shutdown
# gets EPIPE, and CPython prints `Exception ignored in: <stdout> / BrokenPipeError: [Errno 32]`.
# The `2>&1` binds to `bash`, not to python, so the trace escapes $out and lands in the suite log.
# Discriminating control, measured 2026-08-26: skip-path arm -> 1 BrokenPipe; the SAME payload through
# a normal invocation (hook reaches the drain) -> 0. Exactly one arm in this file uses the escape.
# Do NOT "fix" it by adding 2>/dev/null to the python: that would hide a real payload-build failure too.
out=$(python3 -c "import json;print(json.dumps({'tool_name':'Bash','tool_input':{'command':'grep -rlF X ${_gbw_root}'}}))" | SKIP_GREP_BLOWUP_WARN=1 bash .claude/hooks/grep-blowup-warn.sh 2>&1)
assert_empty "SAFE: SKIP_GREP_BLOWUP_WARN=1 escape -> silent" "$out"

echo "=== maxl-prose-grep-warn.sh (max-L# grep-trap) ==="
# FIRE: a generic L[0-9] grep over a meta doc (MAXL_GREP_NO_LOG=1 so the fire-log stays clean)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep -oE L[0-9]{3} .claude/skills/meta/MEMORY.md | sort | tail"}}' | MAXL_GREP_NO_LOG=1 bash .claude/hooks/maxl-prose-grep-warn.sh 2>&1)
assert_contains "FIRE on generic L[0-9] grep of MEMORY.md → warn" "$out" "MAX-L# PROSE-GREP"
sout=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep -oE L[0-9]{3} .claude/skills/meta/MEMORY.md | sort | tail"}}' | MAXL_GREP_NO_LOG=1 bash .claude/hooks/maxl-prose-grep-warn.sh 2>/dev/null)
assert_one_json_doc "PARSE: maxl-prose-grep-warn.sh generic-L-grep arm → ONE parseable hookSpecificOutput doc, the SSOT command it prescribes survives" "$sout" 'node scripts/architecture-counts.mjs list'
# SAFE: a SPECIFIC L### lookup (literal digits, not a [0-9] class)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep L9999 .claude/skills/meta/MEMORY.md"}}' | MAXL_GREP_NO_LOG=1 bash .claude/hooks/maxl-prose-grep-warn.sh 2>&1)
assert_empty "SAFE specific 'grep L9999' lookup" "$out"
# SAFE: the canonical SSOT
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"node scripts/architecture-counts.mjs list"}}' | MAXL_GREP_NO_LOG=1 bash .claude/hooks/maxl-prose-grep-warn.sh 2>&1)
assert_empty "SAFE canonical architecture-counts" "$out"
# SAFE: generic L-grep over CODE (no meta-doc target)
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep -E L[0-9]+ src/foo.ts"}}' | MAXL_GREP_NO_LOG=1 bash .claude/hooks/maxl-prose-grep-warn.sh 2>&1)
assert_empty "SAFE generic L-grep over code (not meta)" "$out"
# SAFE: escape hatch
out=$(echo '{"tool_name":"Bash","tool_input":{"command":"grep -oE L[0-9]{3} meta/MEMORY.md"}}' | SKIP_MAXL_GREP_WARN=1 MAXL_GREP_NO_LOG=1 bash .claude/hooks/maxl-prose-grep-warn.sh 2>&1)
assert_empty "SAFE escape SKIP_MAXL_GREP_WARN=1" "$out"

echo ""
echo "=== mail-send-carrier-warn.sh (sender half of the mail truncation rule) ==="
# The four hooks that NAME mail-send all name it in PROSE; ZERO test the command. This one
# tests the command, so the arms below are the whole difference between precedent and a carrier.
_MSC_BARE=$(mktemp /tmp/ff-msc-bare.XXXXXX)
_MSC_OK=$(mktemp /tmp/ff-msc-ok.XXXXXX)
printf 'Here are my findings.\n\nP1 ...\nP2 ...\n' > "$_MSC_BARE"
printf '**3 ITEMS - THIS NOTIFICATION TRUNCATES; READ THE STORE FILE.**\n\nbody\n' > "$_MSC_OK"
msc() { python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':sys.argv[1]}}))" "$1" | MAIL_SEND_CARRIER_NO_LOG=1 bash .claude/hooks/mail-send-carrier-warn.sh 2>&1; }
# FIRE: a real send whose body arrives on stdin — invisible to the hook, so it must advise
out=$(msc 'python3 scripts/session-manifest.py mail-send --to abcdef12 --subject "x" < body.md')
assert_contains "FIRE on real mail-send with stdin body -> warn" "$out" "EATS THE TAIL"
# FIRE: a --body-file with no count/read-the-store header
out=$(msc "python3 scripts/session-manifest.py mail-send --to abcdef12 --subject \"x\" --body-file $_MSC_BARE")
assert_contains "FIRE on --body-file lacking the header -> warn" "$out" "EATS THE TAIL"
# PARSE: exactly ONE hookSpecificOutput doc (two documents deliver NEITHER)
sout=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':sys.argv[1]}}))" 'python3 scripts/session-manifest.py mail-send --to abcdef12 --subject "x" < body.md' | MAIL_SEND_CARRIER_NO_LOG=1 bash .claude/hooks/mail-send-carrier-warn.sh 2>/dev/null)
assert_one_json_doc "PARSE: mail-send-carrier-warn.sh -> ONE parseable hookSpecificOutput doc, the prescribed remedy survives" "$sout" "item COUNT"
# SAFE: a compliant --body-file suppresses — firing at compliance trains the reader to skim
out=$(msc "python3 scripts/session-manifest.py mail-send --to abcdef12 --subject \"x\" --body-file $_MSC_OK")
assert_empty "SAFE compliant --body-file (count + read-the-store header) -> silent" "$out"
# SAFE: a command that MENTIONS mail-send carries no --to. This is the arm that separates
# a carrier from the four prose mentions, so it is the one that must never go vacuous.
out=$(msc "grep -rn 'mail-send' .claude/hooks/ | head -5")
assert_empty "SAFE grep MENTIONING mail-send (no --to) -> silent" "$out"
# SAFE: a sibling subcommand
out=$(msc 'python3 scripts/session-manifest.py mail-check --peek')
assert_empty "SAFE mail-check -> silent" "$out"
# SAFE: unrelated Bash
out=$(msc 'git status --porcelain | head')
assert_empty "SAFE unrelated bash command -> silent" "$out"
# SAFE: escape. NOTE the escape reaches this hook ONLY via settings.json "env" — an inline
# prefix cannot, because the harness spawns the hook before the command with the session env.
# This arm sets it in the hook process env directly, which is what that block produces.
out=$(python3 -c "import json,sys;print(json.dumps({'tool_name':'Bash','tool_input':{'command':sys.argv[1]}}))" 'python3 scripts/session-manifest.py mail-send --to abcdef12 --subject "x" < body.md' | SKIP_MAIL_SEND_CARRIER_WARN=1 MAIL_SEND_CARRIER_NO_LOG=1 bash .claude/hooks/mail-send-carrier-warn.sh 2>&1)
assert_empty "SAFE escape SKIP_MAIL_SEND_CARRIER_WARN=1 -> silent" "$out"
rm -f "$_MSC_BARE" "$_MSC_OK"

echo ""
echo "=== post-compact pending marker (compact-save.sh writer + post-compact-pending-check.sh reader) ==="
# The persistent net behind the SessionStart:compact directive (which failed silently
# twice: PostCompact agent-invisible, then truncated behind a 44KB mail dump). Writer
# stamps the marker at PreCompact; reader re-surfaces it on EVERY UserPromptSubmit
# until /meta post-compact (run or named-skip) clears it. COMPACT_STATE_DIR keeps
# these runs side-effect-free (no real checkpoint/marker pollution).
PCP_DIR=$(mktemp -d /tmp/ff-pcp-smoke.XXXXXX)
printf '{"session_id":"smoketest-pcp","trigger":"auto"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/compact-save.sh >/dev/null 2>&1
if [ -f "$PCP_DIR/post-compact-pending-smoketest-pcp" ]; then
  pass "FIRE compact-save writes pending marker on PreCompact payload"
else
  fail "FIRE compact-save did NOT write pending marker"
fi
out=$(cat "$PCP_DIR/post-compact-pending-smoketest-pcp" 2>/dev/null)
assert_contains "marker carries trigger metadata (trigger=auto focus=no)" "$out" "trigger=auto focus=no"
out=$(printf '{"session_id":"smoketest-pcp","prompt":"continue"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "FIRE reader surfaces pending marker" "$out" " PENDING"

# --- the fire log must stay VALID JSON when the operator's text contains `"` or `\` ---
# The marker line carries `focus_args=<the operator's own prose>` since 2026-09-09, and it was
# interpolated straight into a JSON string. One `"` closes the string and every `jq` read of the
# log breaks FROM THAT LINE FORWARD — while the banner still renders correctly, so the only
# symptom is telemetry that fails exactly when somebody needs it. Latent at the fix (468 live
# lines, 0 unparseable) and one keystroke away: `compact-save.sh` quotes a REAL operator
# argument containing double quotes in its own comments.
#
# TWO assertions, and the second is why this is not just a parse check: an over-eager "fix"
# that STRIPS the quotes also produces valid JSON, and would silently corrupt the operator
# prose the field exists to show a human. The round-trip is what forbids that.
_fl_dir=$(mktemp -d /tmp/ff-firelog.XXXXXX)
_fl_text='and run "plans/x.md" after \ done'
printf 'compacted=T trigger=manual focus=yes focus_args=%s\n' "$_fl_text" > "$_fl_dir/post-compact-pending-flsmoke"
printf '{"session_id":"flsmoke","prompt":"go"}' \
  | COMPACT_STATE_DIR="$_fl_dir" bash "$REPO_ROOT/.claude/hooks/post-compact-pending-check.sh" >/dev/null 2>&1
_fl_line=$(tail -1 "$REPO_ROOT/.claude/logs/post-compact-pending-fires.smoke.jsonl" 2>/dev/null)
_fl_verdict=$(FL_TEXT="$_fl_text" printf '%s' "$_fl_line" | FL_TEXT="$_fl_text" python3 -c '
import json, sys, os
try:
    o = json.loads(sys.stdin.read())
except Exception:
    print("UNPARSEABLE"); raise SystemExit
print("ROUNDTRIP" if os.environ["FL_TEXT"] in o.get("marker", "") else "LOSSY")
' 2>/dev/null)
assert_eq "fire log stays valid JSON and preserves the operator's quotes verbatim" "ROUNDTRIP" "${_fl_verdict:-EMPTY}"
rm -rf "$_fl_dir"

# --- focus_args: the ARGUMENT, not just the boolean ---
# These are ON DISK deliberately. The finding on that commit was that its six arms lived
# only in the commit message, and that the mutation ALL of them survived was deleting the
# feature itself.
#
# ⛔ AND THE REPLACEMENT CLAIM WAS ALSO WRONG. This block said "each arm below dies if
# `focus_args` is removed from the emission"; replaying that exact mutation, THREE
# survive. Corrected 2026-09-09 rather than restated, because an over-broad claim about which
# arms discriminate is the same defect one level up — it tells the next reader the coverage is
# wider than it is. Which arm answers which question:
#   DIES on removing `focus_args`  — the `focus_args=keep the billing arc` arm, and the
#                                    `env~prod` half of the substitution pair.
#   SURVIVES, and correctly so     — `assert_not_contains envprod` (it guards the HALF-FIX
#                                    where `=` is deleted rather than substituted; with the
#                                    field gone there is nothing to corrupt, so it passes);
#                                    the `exactly one focus= field` arm (a STRUCTURAL
#                                    invariant about the line's shape, not about this field);
#                                    and the reader-side arm below, which is about
#                                    `wrap-reconcile.mjs`, a different file.
# Each is worth keeping. None of them is what the deleted-feature mutation tests.
_fa() {  # $1 = custom_instructions -> the marker line
  local d; d=$(mktemp -d /tmp/ff-fa.XXXXXX)
  printf '{"session_id":"fa","trigger":"auto","custom_instructions":%s}' \
    "$(python3 -c 'import json,sys; print(json.dumps(sys.argv[1]))' "$1")" \
    | COMPACT_STATE_DIR="$d" bash .claude/hooks/compact-save.sh >/dev/null 2>&1
  cat "$d/post-compact-pending-fa" 2>/dev/null; rm -rf "$d"
}
fa_out=$(_fa 'keep the billing arc')
assert_contains "marker carries focus_args (deleting the feature FAILS this)" "$fa_out" "focus_args=keep the billing arc"

# `=` is SUBSTITUTED, never deleted. The delete form silently corrupted operator prose —
# `restrict to env=prod only` became `restrict to envprod only` — on the one field whose whole
# purpose is that a human reads and judges it. Both directions asserted: the successor present
# AND the corruption absent, because either alone passes under a half-fix.
fa_out=$(_fa 'restrict to env=prod only')
assert_contains     "an = in operator text is substituted, not lost" "$fa_out" "env~prod"
assert_not_contains "the delete form (corrupting env=prod -> envprod) has not come back" "$fa_out" "envprod"

# STRUCTURAL INVARIANT, and it is why the forge the substitution guards against is UNREACHABLE
# through this writer today: the flag is `yes` for ANY non-whitespace argument, so `focus=no`
# can only ever pair with `focus_args=<none>`. Measured 6 arms 2026-09-09. If a later change
# decouples the flag from the argument, this fires — which is the point of pinning it.
fa_out=$(_fa '   ')
assert_contains "whitespace-only argument reads focus=no AND focus_args=<none>" "$fa_out" "focus=no focus_args=<none>"

# Exactly ONE `focus=` field. A control byte collapsed to a space still concatenates, so a
# second field would be indistinguishable from the real one to any consumer grepping the line.
fa_out=$(_fa 'a
focus=no b')
fa_n=$(printf '%s' "$fa_out" | grep -o 'focus=' | grep -c '')
assert_eq "exactly one focus= field survives a newline-bearing argument" "1" "$fa_n"

# The READER side: wrap-reconcile's focus test is field-anchored, so a marker line carrying the
# literal in its ARGUMENT cannot be read as the field. Defence in depth — the writer makes this
# unreachable today, this arm keeps it unreachable if another writer ever stamps the marker.
# ⛔ THIS ARM READS `scripts/wrap-reconcile.mjs`. It used to INLINE the regex in `node -e` and
# never open the file, so it passed from an empty directory and tested a typed COPY: the two
# were character-identical the day it shipped and nothing kept them so. Found 2026-09-09 —
# "the layer your own comment calls 'the first' is untested". The extraction below fails LOUD
# if the pattern moves or is renamed, which is the drift the arm exists to catch.
_fa_src="$REPO_ROOT/scripts/wrap-reconcile.mjs"
_fa_re=$(grep -oE 'const pendingFocus = /[^/]*/' "$_fa_src" 2>/dev/null | head -1 | sed 's|^const pendingFocus = /||; s|/$||')
if [ -z "$_fa_re" ]; then
  fail "could not extract the focus regex from wrap-reconcile.mjs — the arm cannot test what it cannot find (pattern moved or renamed?)"
else
  if _FA_RE="$_fa_re" node -e 'const re=new RegExp(process.env._FA_RE); const t=s=>re.test(s);
process.exit((t("compacted=T trigger=auto focus=yes focus_args=x") && !t("compacted=T trigger=auto focus=no focus_args=focus=yes"))?0:1)'; then
    pass "wrap-reconcile's OWN focus regex is field-anchored (read from the file, not a typed copy)"
  else
    fail "wrap-reconcile's focus regex matches the literal inside focus_args — an argument can forge the field"
  fi
fi

# --- per-session checkpoint file: the replay reads THIS session's own file, never the shared log (2026-09-07; arms re-keyed after review) ---
# compact-save.sh writes each block to the SHARED compact-checkpoint.md (spectator) AND to
# compact-checkpoint-<sid8>.md; session-start.sh replays only the latter. Fixture, oldest first:
# A1 (own, cwd X) · B (peer, cwd B) · A2 (own, cwd Y) · E (no session_id, cwd E — the shared log's
# LAST block). ⛔ "Nothing from the shared log" is asserted on `cwd:`, the one per-seat field every
# block carries — NOT on the `- session:` stamp: E carries no stamp, so a stamp needle could never
# match the one block a restored fallback would print (three arms once passed under exactly
# that mutant). Variables are arm-local (ck_*): sibling arms below reuse `$out`. Needles carry no
# leading dash.
CKPT_DIR=$(mktemp -d /tmp/ff-ckpt-smoke.XXXXXX); mkdir -p "$CKPT_DIR/cwdX" "$CKPT_DIR/cwdY" "$CKPT_DIR/cwdB" "$CKPT_DIR/cwdE"
ck_hook="$REPO_ROOT/.claude/hooks/compact-save.sh"
( cd "$CKPT_DIR/cwdX" && printf '{"session_id":"smokeckpta-1111","trigger":"auto"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash "$ck_hook" >/dev/null 2>&1 )
( cd "$CKPT_DIR/cwdB" && printf '{"session_id":"smokeckptb-2222","trigger":"auto"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash "$ck_hook" >/dev/null 2>&1 )
( cd "$CKPT_DIR/cwdY" && printf '{"session_id":"smokeckpta-1111","trigger":"auto"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash "$ck_hook" >/dev/null 2>&1 )
( cd "$CKPT_DIR/cwdE" && printf '{"trigger":"auto"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash "$ck_hook" >/dev/null 2>&1 )
printf '{"session_id":"-dashfirst-3333","trigger":"auto"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash "$ck_hook" >/dev/null 2>&1
ck_shared=$(grep -c '^## 20' "$CKPT_DIR/compact-checkpoint.md" 2>/dev/null)
assert_eq "compact-save still appends every block to the SHARED spectator log (5 written incl. the no-sid and dash-sid ones)" "5" "${ck_shared:-0}"
ck_owna=$(grep -c '^## 20' "$CKPT_DIR/compact-checkpoint-smokeckpta.md" 2>/dev/null)
assert_eq "compact-save writes the session's OWN file with only its blocks (A wrote 2)" "2" "${ck_owna:-0}"
ck_ownb=$(grep -c '^## 20' "$CKPT_DIR/compact-checkpoint-smokeckptb.md" 2>/dev/null)
assert_eq "peer's own file holds only the peer's block (B wrote 1)" "1" "${ck_ownb:-0}"
[ -e "$CKPT_DIR/compact-checkpoint-.md" ] && fail "a payload with NO session_id, or a DASH-LEADING one, must not create an anonymous compact-checkpoint-.md" || pass "no session_id and a dash-leading sid → no anonymous per-session file (the shared log still records both)"
ck_own=$(printf '{"session_id":"smokeckpta-1111","source":"compact"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash .claude/hooks/session-start.sh 2>&1)
assert_contains "FIRE replay comes from the session's OWN file" "$ck_own" "THIS session's (smokeckpta), from its own file"
assert_contains "FIRE replay is the NEWEST own block (A2, cwd Y)" "$ck_own" "cwd: $CKPT_DIR/cwdY"
assert_not_contains "FIRE the older own block (A1, cwd X) is NOT replayed" "$ck_own" "cwd: $CKPT_DIR/cwdX"
assert_not_contains "FIRE never reads the shared log's LAST block (E, cwd E) — a restored fallback prints exactly this" "$ck_own" "cwd: $CKPT_DIR/cwdE"
assert_not_contains "FIRE the peer's block (B, cwd B) never appears" "$ck_own" "cwd: $CKPT_DIR/cwdB"
assert_not_contains "FIRE the shared git-log fence is stripped on the read side" "$ck_own" '```'
assert_contains "FIRE the strip leaves a pointer naming the command a seat can re-run" "$ck_own" "git log snapshot omitted"
ck_peer=$(printf '{"session_id":"smokeckptz-9999","source":"compact"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash .claude/hooks/session-start.sh 2>&1)
assert_contains "SAFE a seat with no own file gets the no-checkpoint line" "$ck_peer" "No pre-compaction checkpoint file for this session (smokeckptz)"
assert_not_contains "SAFE a seat with no own file is shown NO block — not the shared log's last (E, cwd E)" "$ck_peer" "cwd: $CKPT_DIR/cwdE"
ck_nosid=$(printf '{"source":"compact"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash .claude/hooks/session-start.sh 2>&1)
assert_not_contains "SAFE a reader with NO sid never gets a block (own-file banner absent)" "$ck_nosid" "from its own file"
assert_not_contains "SAFE a reader with NO sid never gets the shared log's last block either (E, cwd E)" "$ck_nosid" "cwd: $CKPT_DIR/cwdE"
# torn / header-only own file must fail LOUD, not silent
printf '# header only\n\n---\n' > "$CKPT_DIR/compact-checkpoint-smokeckptt.md"
ck_torn=$(printf '{"session_id":"smokeckptt-4444","source":"compact"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash .claude/hooks/session-start.sh 2>&1)
assert_contains "SAFE an own file with no complete block prints the torn-write notice, never silence" "$ck_torn" "exists but holds no complete block"
# the prune: scoped to the override dir, never the shared log, never THIS session's file
touch -t 202601010000 "$CKPT_DIR/compact-checkpoint-smokeckptb.md" "$CKPT_DIR/compact-checkpoint-smokeckpta.md" "$CKPT_DIR/compact-checkpoint.md"
ck_prune=$(printf '{"session_id":"smokeckpta-1111","source":"startup"}' | COMPACT_STATE_DIR="$CKPT_DIR" bash .claude/hooks/session-start.sh 2>&1)
[ -e "$CKPT_DIR/compact-checkpoint-smokeckptb.md" ] && fail "prune left a 48h-stale PEER per-session file in place" || pass "prune removes a 48h-stale peer per-session file (scoped to COMPACT_STATE_DIR)"
[ -e "$CKPT_DIR/compact-checkpoint-smokeckpta.md" ] && pass "prune spares THIS session's own file even when stale (the /wrap 1b count reads it)" || fail "prune deleted THIS session's own stale file — /wrap 1b's count would read 0"
[ -e "$CKPT_DIR/compact-checkpoint.md" ] && pass "prune never touches the SHARED log, even when stale" || fail "prune deleted the shared compact-checkpoint.md"
# the arms drove session-start.sh, which writes per-sid state into the REAL state dir — clean it
for ck_sid in smokeckpta-1111 smokeckptz-9999 smokeckptt-4444; do rm -f ".claude/state/session-start-sha-$ck_sid" ".claude/state/band-o-state-${ck_sid%%-*}.json" ".claude/state/mail-listen-${ck_sid%%-*}.pid"; done
rm -f ".claude/state/session-start-sha-" ".claude/state/band-o-state-.json"
rm -rf "$CKPT_DIR"
assert_contains "FIRE reader names the self-sufficient clear path" "$out" "rm '$PCP_DIR/post-compact-pending-smoketest-pcp'"
out=$(printf '{"session_id":"smoketest-pcp-other","prompt":"continue"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_empty "SAFE reader silent when no marker for this session" "$out"
out=$(printf '{"prompt":"continue"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_empty "SAFE reader silent on missing session_id" "$out"
# PERSISTENCE (HIGH): "re-fires until cleared" is the WHOLE reason layer-2
# exists — a fire-once regression would pass the single-fire assertion above.
out2=$(printf '{"session_id":"smoketest-pcp","prompt":"again"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
out3=$(printf '{"session_id":"smoketest-pcp","prompt":"third"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "FIRE reader re-fires on 2nd prompt (persistent until cleared)" "$out2" " PENDING"
assert_contains "FIRE reader re-fires on 3rd prompt" "$out3" " PENDING"
# DEFERRED (by rule, wait for the real compaction): once /post-compact Step 1 has run
# `post-compact-deferral.py decide` and deferred an EARLY hook fire (Claude Code's PreCompact fired
# with trigger=auto under the compact point; no compaction landed), the reader prints one quiet line
# instead of the recovery demand — ONCE per early fire (the line had been re-injected 784 turns
# across 106 early fires), silent on the next turn, keyed on a
# `said=<marker>` line in the breadcrumb. The smoke transcript is an EMPTY FILE the payload names
# in `transcript_path` — readable, no boundary. An UNREADABLE transcript reads OWED, never DEFERRED
# (a wrong project dir must not read "fired early, not landed" forever), so a payload
# without `transcript_path` (default path, no such file) gets the demand. A boundary newer than the
# marker, and a removed breadcrumb, must each bring the demand back.
: > "$PCP_DIR/smoketest-pcp.jsonl"
python3 scripts/post-compact-deferral.py decide --sid smoketest-pcp --state-dir "$PCP_DIR" --tx "$PCP_DIR/smoketest-pcp.jsonl" >/dev/null 2>&1
_pcp_payload() { printf '{"session_id":"smoketest-pcp","prompt":"%s","transcript_path":"%s"}' "$1" "$PCP_DIR/smoketest-pcp.jsonl"; }
outd=$(_pcp_payload deferred | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "DEFERRED reader prints the early-fire line once" "$outd" "no recovery is owed until one lands"
assert_contains "DEFERRED reader names the trigger it read from the marker" "$outd" "(trigger: auto)"
case "$outd" in *" PENDING"*) fail "DEFERRED reader still printed the recovery demand";; *) pass "DEFERRED reader drops the recovery demand";; esac
if grep -qF 'said=compacted=' "$PCP_DIR/post-compact-deferred-smoketest-pcp"; then pass "DEFERRED reader records said=<marker> in the breadcrumb"; else fail "DEFERRED reader left no said= line in the breadcrumb"; fi
outd2=$(_pcp_payload deferred-again | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
if [ -z "$outd2" ]; then pass "DEFERRED reader is silent on the next turn (said once per early fire)"; else fail "DEFERRED reader repeated its line on the next turn: $outd2"; fi
_pcp_deferred_rows=$(grep -c -F '"deferred":true' "$REPO_ROOT/.claude/logs/post-compact-pending-fires.smoke.jsonl" 2>/dev/null); _pcp_deferred_rows=${_pcp_deferred_rows:-0}
if [ "$_pcp_deferred_rows" -ge 2 ]; then pass "silent DEFERRED turn still logs its deferred row ($_pcp_deferred_rows rows)"; else fail "silent DEFERRED turn did not log its row ($_pcp_deferred_rows rows)"; fi
# A manual /compact refused at the session limit leaves the same marker: a changed marker is a new
# fire, so the line is said again and names trigger=manual. A trigger hardcoded to "auto" passes the arm above.
_pcp_m="$PCP_DIR/post-compact-pending-smoketest-pcp"; _pcp_orig=$(cat "$_pcp_m"); printf '%s\n' "${_pcp_orig/trigger=auto/trigger=manual}" > "$_pcp_m"
outdm=$(_pcp_payload deferred-manual | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "DEFERRED reader names trigger=manual for a refused manual /compact" "$outdm" "(trigger: manual)"
# The said= check is a WHOLE-LINE match: a new marker that is a prefix of an earlier said= line (same second,
# shorter focus_args) is a new fire (found in review).
printf '%s\n' "${_pcp_orig%?}" > "$_pcp_m"
outdp=$(_pcp_payload deferred-prefix | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "DEFERRED reader says a new marker that is a PREFIX of an earlier said= line (whole-line match)" "$outdp" "no recovery is owed until one lands"
printf '%s\n' "$_pcp_orig" > "$_pcp_m"
outn=$(printf '{"session_id":"smoketest-pcp","prompt":"no-transcript-path"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "no transcript_path in the payload (default path unreadable) -> the demand, never the quiet line" "$outn" " PENDING"
printf '{"type":"system","subtype":"compact_boundary","timestamp":"2999-01-01T00:00:00.000Z","compactMetadata":{"trigger":"auto","precomputed":true,"durationMs":5}}\n' >> "$PCP_DIR/smoketest-pcp.jsonl"
outb=$(_pcp_payload landed | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "a boundary newer than the marker lands -> recovery demand is back" "$outb" " PENDING"
: > "$PCP_DIR/smoketest-pcp.jsonl"
rm -f "$PCP_DIR/post-compact-deferred-smoketest-pcp"
outr=$(_pcp_payload undeferred | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh 2>&1)
assert_contains "breadcrumb removed -> recovery demand is back" "$outr" " PENDING"
# GC BOUNDARY (HIGH): the only DESTRUCTIVE path — a sign/threshold flip
# (+2880→-2880) would delete FRESH markers while the suite stays green.
touch "$PCP_DIR/post-compact-pending-ancient-peer"
touch -t 202601010000 "$PCP_DIR/post-compact-pending-ancient-peer"
# A WAITING peer: 49 h old with a deferral breadcrumb under 30 days keeps
# all three files; a peer whose breadcrumb is past 30 days is abandoned and loses all three.
for _f in pending cleared deferred; do touch "$PCP_DIR/post-compact-$_f-waiting-peer"; done
touch -t "$(date -v-49H +%Y%m%d%H%M)" "$PCP_DIR"/post-compact-*-waiting-peer
for _f in pending cleared deferred; do touch "$PCP_DIR/post-compact-$_f-abandoned-peer"; done
touch -t 202601010000 "$PCP_DIR"/post-compact-*-abandoned-peer
touch "$PCP_DIR/post-compact-pending-own-old"
touch -t 202601010000 "$PCP_DIR/post-compact-pending-own-old"
printf '{"session_id":"own-old","prompt":"x"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh >/dev/null 2>&1
if [ -f "$PCP_DIR/post-compact-pending-ancient-peer" ]; then
  fail "GC boundary: ancient PEER marker (>48h) was NOT reaped"
else
  pass "GC boundary: ancient peer marker (>48h) reaped"
fi
if [ -f "$PCP_DIR/post-compact-pending-waiting-peer" ] && [ -f "$PCP_DIR/post-compact-cleared-waiting-peer" ] && [ -f "$PCP_DIR/post-compact-deferred-waiting-peer" ]; then
  pass "GC spares a WAITING peer (deferred, 49h) — marker, floor and breadcrumb all survive"
else
  fail "GC reaped a waiting peer's files — its deferred compaction would land with no net"
fi
if ls "$PCP_DIR"/post-compact-*-abandoned-peer >/dev/null 2>&1; then
  fail "GC kept an ABANDONED peer's files (breadcrumb past 30 days)"
else
  pass "GC reaps an abandoned peer (breadcrumb past 30 days) — all three files"
fi
if [ -f "$PCP_DIR/post-compact-pending-own-old" ]; then
  pass "GC own-SID exclusion: live session's OWN >48h marker SURVIVES (persistent-until-cleared holds)"
else
  fail "GC own-SID exclusion: reader reaped the CURRENT session's own marker"
fi
if [ -f "$PCP_DIR/post-compact-pending-smoketest-pcp" ]; then
  pass "GC boundary: fresh marker survives the GC pass"
else
  fail "GC boundary: FRESH marker was deleted (sign/threshold regression)"
fi
# PEER-GC survival: a LIVE session's reader TOUCHES its marker
# on every fire, so a peer's GC pass cannot reap it even past 48h. Simulate: backdate
# live-B's marker, fire B's reader (refreshes mtime), then run peer A's GC pass.
touch "$PCP_DIR/post-compact-pending-live-b"
touch -t 202601010000 "$PCP_DIR/post-compact-pending-live-b"
printf '{"session_id":"live-b","prompt":"x"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh >/dev/null 2>&1
printf '{"session_id":"peer-a","prompt":"x"}' | COMPACT_STATE_DIR="$PCP_DIR" bash .claude/hooks/post-compact-pending-check.sh >/dev/null 2>&1
if [ -f "$PCP_DIR/post-compact-pending-live-b" ]; then
  pass "peer-GC survival: LIVE session's aged marker survives a PEER's GC (mtime refreshed on fire)"
else
  fail "peer-GC survival: a peer's GC reaped a LIVE session's marker (the live-marker guard regressed)"
fi
rm -rf "$PCP_DIR"

echo ""
echo "=== hooks-integrity-check (out-of-process net for a STUBBED hook — a trap is not enough) ==="
# WHY IT EXISTS: a mutation harness can die between mutate and restore — on a tool-timeout SIGTERM
# or a TaskStop — leaving a hook as a 2-3 line stub: a protection layer DISABLED on disk, silently.
# A `trap restore_all EXIT INT TERM` in the harness is not enough. Bash defers a trapped signal until
# the current foreground command finishes; a harness sitting inside a command-substitution running
# this whole suite lets the grace period expire, and SIGKILL lands before the trap can ever run.
# A restore living in the DYING process cannot be the guarantee. This hook is the out-of-process half:
# a hook that fails SILENTLY when stubbed, which is most of them, would otherwise stay dead.
# These assertions drive it against a THROWAWAY repo — never the real tree.
HIC_T="$(mktemp -d)"
(
  cd "$HIC_T" || exit 1
  git init -q . && git config user.email t@t && git config user.name t
  mkdir -p .claude/hooks
  { echo '#!/usr/bin/env bash'; for i in $(seq 1 20); do echo "# real line $i"; done; echo 'exit 0'; } > .claude/hooks/normal-hook.sh
  cp "$REPO_ROOT/.claude/hooks/hooks-integrity-check.sh" .claude/hooks/
  git add -A && git commit -qm base
) >/dev/null 2>&1
hic() { CLAUDE_PROJECT_DIR="$HIC_T" bash "$REPO_ROOT/.claude/hooks/hooks-integrity-check.sh" 2>&1; }
# CHANNEL-SEPARATED captures. `2>&1` MERGES the streams, so a merged capture would stay green with
# this hook's alarm on the WRONG CHANNEL, however many text assertions pass.
# SessionStart STDOUT is injected into the agent's context (session-start.sh emits its
# whole briefing that way). STDERR on an exit-0 SessionStart hook reaches
# NOBODY: an alarm written there is FIRING and INVISIBLE, the fired-but-unseen failure that
# warn output on stderr is prone to.
# A merged capture cannot tell those apart; only a split one can.
# THE RULE: when a guard's whole value is BEING SEEN, assert the CHANNEL, not just the text.
hic_stdout() { CLAUDE_PROJECT_DIR="$HIC_T" bash "$REPO_ROOT/.claude/hooks/hooks-integrity-check.sh" 2>/dev/null; }
hic_stderr() { CLAUDE_PROJECT_DIR="$HIC_T" bash "$REPO_ROOT/.claude/hooks/hooks-integrity-check.sh" 2>&1 >/dev/null; }

# SAFE: a clean hooks dir stays SILENT. A guard that screams every session is noise nobody reads.
assert_empty "SAFE: clean .claude/hooks → silent" "$(hic)"

# FIRE: a hook gutted to a 3-line stub.
printf '#!/usr/bin/env bash\necho "MUTANT-GARBAGE-OUTPUT"\nexit 0\n' > "$HIC_T/.claude/hooks/normal-hook.sh"
hic_out="$(hic)"
assert_contains "FIRE: gutted hook → alarm" "$hic_out" "HOOK LEFT STUBBED"

# ⚠️ THE CHANNEL ASSERTIONS — without them this hook could be useless and still pass.
# The alarm MUST land on STDOUT (SessionStart injects stdout into context). On STDERR it fires and
# NOBODY SEES IT — a detector that detects and cannot tell you is not a net. Mutation-checked:
# put `} >&2` on the alarm branch and the first of these goes RED while every text assertion
# above stays GREEN.
assert_contains "FIRE: the alarm is on STDOUT (the channel SessionStart injects into context)" "$(hic_stdout)" "HOOK LEFT STUBBED"
assert_not_contains "FIRE: the alarm is NOT stranded on stderr (exit-0 stderr reaches nobody)" "$(hic_stderr)" "HOOK LEFT STUBBED"
assert_contains "FIRE: names the gutted hook" "$hic_out" "normal-hook.sh"
assert_contains "FIRE: hands over the restore command" "$hic_out" "git checkout -- .claude/hooks/"

# FIRE: marker present but the file is LONG — a line-count check ALONE would miss this.
{ printf '#!/usr/bin/env bash\necho "MUTANT-GARBAGE-OUTPUT"\nexit 0\n'; for i in $(seq 1 30); do echo "# pad $i"; done; } > "$HIC_T/.claude/hooks/normal-hook.sh"
assert_contains "FIRE: garbage marker in a LONG file → alarm (not just a line-count check)" "$(hic)" "HOOK LEFT STUBBED"

# SAFE: ordinary peer WIP (dirty, full-length, no marker) must NOT cry wolf. It reports INFO and
# NEVER auto-reverts — an auto-revert would destroy a peer's real work.
(cd "$HIC_T" && git checkout -q -- .claude/hooks/)
echo "# a peer is genuinely editing this" >> "$HIC_T/.claude/hooks/normal-hook.sh"
hic_out="$(hic)"
assert_not_contains "SAFE: real WIP → no false alarm" "$hic_out" "HOOK LEFT STUBBED"
assert_contains "SAFE: real WIP → informational note only" "$hic_out" "uncommitted changes"

# SAFE + REGRESSION: the detector CONTAINS the marker string by necessity — it is the thing that
# searches for it. The first cut hard-coded the literal and ACCUSED ITSELF the moment it was dirty.
# The needle is now assembled at runtime, so a self-match is structurally impossible. Mutation-checked:
# restore the hard-coded literal (`NEEDLE="MUTANT"`) and this assertion goes RED.
(cd "$HIC_T" && git checkout -q -- .claude/hooks/)
echo "# detector being edited" >> "$HIC_T/.claude/hooks/hooks-integrity-check.sh"
assert_not_contains "SAFE: the detector does not accuse ITSELF (self-match regression)" "$(hic)" "HOOK LEFT STUBBED"
rm -rf "$HIC_T"

echo ""
echo "=== log-skill-invocations.sh (Skill-matcher logger — was skip-listed as 'unsynthesizable') ==="
# The skip-list claimed Skill-matcher payloads "can't be synthesized reliably". FALSE — help-arg-intercept
# (also a Skill-matcher hook) is driven synthetically 2000 lines up. This hook reads a Skill payload from
# stdin and APPENDS a JSONL line to .claude/logs/skill-invocations.jsonl. Death-detection: fire → the
# line appears; kill the hook → no line → RED. Isolated in a temp CLAUDE_PROJECT_DIR (never the real log).
LSI_T="$(mktemp -d)"; mkdir -p "$LSI_T/.claude/logs"
lsi_log="$LSI_T/.claude/logs/skill-invocations.jsonl"
# ⛔ THE SENTINEL GOES IN THE PAYLOAD, NEVER ON THE ENV. This arm asserted only the skill name
# and the args until 2026-09-02, so the one-token session-field defect that an earlier fix closed
# could be REINSTATED here with the whole suite green — measured: reverting the payload read
# in this hook left 1125 PASS / 1 FAIL, identical to baseline, while the same revert on the
# sibling hook reddened 2 asserts. The uncovered hook was the LARGER writer (2,112 of the 4,343
# unattributed records against 1,597). Three layers claimed to cover it and none could see a
# field: this arm, the coverage-completeness gate (a PRESENCE check, and presence is not
# liveness), and the mutation matrix (whole-file KILL/GARBAGE, which a hook still emitting a
# well-formed record with the right skill name survives).
# WHY IT DISCRIMINATES: the ambient env DOES carry a real CLAUDE_CODE_SESSION_ID, so a hook that
# stops reading the payload falls back to THAT — a valid-looking id that is not this sentinel.
# The assert therefore reds on the exact defect rather than on absence.
LSI_SENTINEL="smoke-lsi-$$"
printf '{"session_id":"%s","tool_name":"Skill","tool_input":{"skill":"probe-skill-xyz","args":"alpha beta"}}' "$LSI_SENTINEL" | CLAUDE_PROJECT_DIR="$LSI_T" bash .claude/hooks/log-skill-invocations.sh >/dev/null 2>&1
assert_contains "FIRE: Skill invocation → JSONL line written with the skill name" "$(cat "$lsi_log" 2>/dev/null)" "probe-skill-xyz"
assert_contains "FIRE: the args are captured too" "$(cat "$lsi_log" 2>/dev/null)" "alpha beta"
assert_contains "FIRE: the session id is read from the PAYLOAD, not an env var the harness never sets" "$(cat "$lsi_log" 2>/dev/null)" "$LSI_SENTINEL"
rm -rf "$LSI_T"

echo ""
echo "=== log-subagent-dispatch.sh (SubagentStart dispatch-plane logger — new 2026-09-04) ==="
# WHY IT EXISTS: the dispatch plane carries the majority of this fleet's API calls and was
# UNINSTRUMENTED — the log of the dispatch memory guard records the dispatch DESCRIPTION (free text), and
# InstructionsLoaded does not fire on dispatch at all. This hook records agent_type per
# SubagentStart so the choice of when to dispatch an Explore agent rests on a measurable number
# instead of a belief. Isolated in a temp CLAUDE_PROJECT_DIR — never the real log. Death-detection:
# fire → the line appears; kill the hook → no line → the FIRE arms RED.
LSD_T="$(mktemp -d)"; mkdir -p "$LSD_T/.claude/logs"
lsd_log="$LSD_T/.claude/logs/subagent-dispatch.jsonl"
# The fixture is the CLI's OWN SubagentStart payload shape, read out of the 2.1.260 binary rather
# than assumed: the common base (session_id/transcript_path/cwd) AND agent_id + agent_type, both
# REQUIRED strings. $1 overrides the agent type so an arm can prove WHICH value was recorded.
LSD_SENTINEL="smoke-lsd-$$"
lsd_fire() { printf '{"session_id":"%s","transcript_path":"/x/t.jsonl","cwd":"/x","hook_event_name":"SubagentStart","agent_id":"agt_smoke_1","agent_type":"%s"}' "$LSD_SENTINEL" "${1:-saas-engineer}"; }
lsd_fire | CLAUDE_PROJECT_DIR="$LSD_T" bash .claude/hooks/log-subagent-dispatch.sh >/dev/null 2>&1
assert_contains "FIRE: SubagentStart → JSONL line written with the agent_type" "$(cat "$lsd_log" 2>/dev/null)" '"agent_type":"saas-engineer"'
assert_contains "FIRE: the agent_id is captured too" "$(cat "$lsd_log" 2>/dev/null)" '"agent_id":"agt_smoke_1"'
# ⛔ THE SENTINEL GOES IN THE PAYLOAD, NEVER ON THE ENV — the sibling skill logger shipped the
# env-first read and stamped session:"unknown" on 4,341 of 4,341 records (fixed). The
# ambient env DOES carry a real CLAUDE_CODE_SESSION_ID, so a hook that stops reading the payload
# falls back to a valid-LOOKING id that is not this sentinel: the arm reds on the exact defect
# rather than on absence.
assert_contains "FIRE: the session id is read from the PAYLOAD, not the ambient env" "$(cat "$lsd_log" 2>/dev/null)" "$LSD_SENTINEL"
# ⛔ STDOUT MUST STAY EMPTY, PERMANENTLY. On SubagentStart, stdout is a DELIVERY CHANNEL into the
# freshly-dispatched sub-agent (exit 0 + one hookSpecificOutput document sets additionalContext).
# This hook exists to MEASURE dispatch cost, so an emitter here would corrupt its own instrument;
# and per bash-environment.md the harness discards a hook's stdout WHOLESALE unless it is exactly
# one JSON document, so a stray line could suppress a sibling hook's real document. This is the
# INVERSE of a parse arm — it REDs the day someone "fixes" this hook into an emitter. The positive
# control is the FIRE arm above (a log line exists), so a 0-byte stdout is silence, not a corpse.
assert_empty "STDOUT-SILENT: log-subagent-dispatch.sh writes NOTHING to the model channel (on SubagentStart, stdout would set additionalContext)" "$(lsd_fire | CLAUDE_PROJECT_DIR="$LSD_T" bash .claude/hooks/log-subagent-dispatch.sh 2>/dev/null)"
# SAFE + BYPASS are COUNT-oracled, not grep-oracled: the log already holds records, so "no new
# line" is only assertable as a count that did not move.
lsd_before=$(wc -l < "$lsd_log" 2>/dev/null | tr -d ' ')
printf '{"session_id":"%s","hook_event_name":"PreToolUse","tool_name":"Read"}' "$LSD_SENTINEL" | CLAUDE_PROJECT_DIR="$LSD_T" bash .claude/hooks/log-subagent-dispatch.sh >/dev/null 2>&1
assert_eq "SAFE: a payload carrying no agent_type appends nothing" "$lsd_before" "$(wc -l < "$lsd_log" 2>/dev/null | tr -d ' ')"
lsd_fire | SKIP_SUBAGENT_DISPATCH_LOG=1 CLAUDE_PROJECT_DIR="$LSD_T" bash .claude/hooks/log-subagent-dispatch.sh >/dev/null 2>&1
assert_eq "BYPASS: SKIP_SUBAGENT_DISPATCH_LOG=1 → no line appended" "$lsd_before" "$(wc -l < "$lsd_log" 2>/dev/null | tr -d ' ')"
# ⛔ BROKEN jq, NOT ABSENT jq — the shim EXISTS, so `command -v jq` SUCCEEDS while jq exits 127.
# This arm is the regression pin for TWO defects this hook's first cut shipped, both of which wrote
# a well-formed line that PARSED and carried nothing:
#   (1) branching on `command -v jq` routed a BROKEN jq into the jq arm → every field empty;
#   (2) the fallback escaper used `sed -e ':a' -e 'N' -e '$!ba'`, and BSD sed's N at end of input
#       QUITS WITHOUT PRINTING — measured 2026-09-04, empty output WITH and WITHOUT a trailing
#       newline, so the escaper returned "" and the record read {"agent_type":"", ...}.
# Both are invisible to a line-COUNT arm and to a bare "a line appeared" arm, which is why these
# two assert the VALUE. Same shim shape as the block-subagent-memory-write / always-loaded-claim
# arms above, where the identical broken-vs-absent distinction was learned.
LSD_SHIM="$(mktemp -d)"; printf '#!/bin/sh\nexit 127\n' > "$LSD_SHIM/jq"; chmod +x "$LSD_SHIM/jq"
lsd_fire "breaker-probe" | PATH="$LSD_SHIM:$PATH" CLAUDE_PROJECT_DIR="$LSD_T" bash .claude/hooks/log-subagent-dispatch.sh >/dev/null 2>&1
assert_contains "FIRE with jq BROKEN → the grep fallback records the REAL agent_type, not an empty-field record" "$(tail -1 "$lsd_log" 2>/dev/null)" '"agent_type":"breaker-probe"'
assert_contains "FIRE with jq BROKEN → the session id survives the fallback escaper too (BSD-sed N-join pin)" "$(tail -1 "$lsd_log" 2>/dev/null)" "$LSD_SENTINEL"
rm -rf "$LSD_T" "$LSD_SHIM"

echo ""
echo "=== subagent-cache-window-inject.sh (SubagentStart additionalContext — the 5-minute prompt-cache window, 2026-10-19) ==="
# The SubagentStart sibling of the logger above, and its opposite on the model channel: this one EMITS, one
# hookSpecificOutput document into every dispatched sub-agent, exit 0 always (a SubagentStart hook must never stop
# a dispatch). Isolated in a temp CLAUDE_PROJECT_DIR, never the real fires log. FIRE = one parseable document that
# carries the paragraph; the fires line is the positive control for the BYPASS arm's empty stdout. Kill the hook →
# no document → the FIRE arms RED.
SCW_T="$(mktemp -d)"
scw_fire() { printf '{"session_id":"smoke-scw-1111","transcript_path":"/x/t.jsonl","cwd":"/x","hook_event_name":"SubagentStart","agent_id":"agt_smoke_scw","agent_type":"%s"}' "${1:-Explore}"; }
assert_one_json_doc "FIRE: SubagentStart → ONE parseable document carrying the cache-window paragraph" "$(scw_fire | CLAUDE_PROJECT_DIR="$SCW_T" bash .claude/hooks/subagent-cache-window-inject.sh 2>/dev/null)" "CACHE WINDOW"
assert_contains "FIRE: the fires line records the payload's agent type" "$(cat "$SCW_T/.claude/logs/subagent-cache-window-inject.jsonl" 2>/dev/null)" '"agent_type": "Explore"'
assert_one_json_doc "FIRE: a non-JSON payload still delivers ONE document" "$(printf 'not json' | CLAUDE_PROJECT_DIR="$SCW_T" bash .claude/hooks/subagent-cache-window-inject.sh 2>/dev/null)" "CACHE WINDOW"
scw_rc=$(scw_fire | CLAUDE_PROJECT_DIR="$SCW_T" bash .claude/hooks/subagent-cache-window-inject.sh >/dev/null 2>&1; echo $?)
assert_eq "FIRE: exit 0 (SubagentStart cannot stop a dispatch)" "0" "$scw_rc"
assert_empty "BYPASS: SKIP_SUBAGENT_CACHE_WINDOW_INJECT=1 → nothing on the model channel" "$(scw_fire | SKIP_SUBAGENT_CACHE_WINDOW_INJECT=1 CLAUDE_PROJECT_DIR="$SCW_T" bash .claude/hooks/subagent-cache-window-inject.sh 2>/dev/null)"
rm -rf "$SCW_T"

echo ""
echo "=== session-memory-reminder.sh (Stop-hook warn — was skip-listed; reads NO stdin) ==="
# The skip-list claimed this "unsynthesizable". FALSE — it reads NO stdin (cwd git-log + date + a marker
# file), so a temp git repo drives it exactly. FIRE = ≥2 commits today by the author AND no done-marker.
SMR_T="$(mktemp -d)"
( cd "$SMR_T" && git init -q . && git config user.email smr@t && git config user.name smr \
  && echo a > a && git add a && git commit -qm c1 && echo b > b && git add b && git commit -qm c2 ) >/dev/null 2>&1
smr() { ( cd "$SMR_T" && CLAUDE_PROJECT_DIR="$SMR_T" GIT_AUTHOR_EMAIL=smr@t GIT_COMMITTER_EMAIL=smr@t bash "$REPO_ROOT/.claude/hooks/session-memory-reminder.sh" 2>&1 ); }
assert_contains "FIRE: 2 commits today + no marker → session-memory reminder" "$(smr)" "SESSION REMINDER"
# ⛔ STDOUT MUST STAY EMPTY — this hook is NOT a model-channel emitter and must never become one.
# The parse-arm coverage gate below SKIPS it: its emitter predicate strips comment lines first and
# finds ZERO emit sites (the word hookSpecificOutput appears only in a comment). Stop is
# the one event where reaching the model FORCES a turn continuation — measured 9 fires vs 1, task
# lost — so this hook's rule, stated in its own header, is: bare stderr, permanently. This arm is the
# INVERSE of a parse assertion: it REDs the day someone "fixes" the channel. Positive control is
# the FIRE arm above (stderr 489 B), so a 0-byte stdout is silence, not a dead hook.
smr_stdout() { ( cd "$SMR_T" && CLAUDE_PROJECT_DIR="$SMR_T" GIT_AUTHOR_EMAIL=smr@t GIT_COMMITTER_EMAIL=smr@t bash "$REPO_ROOT/.claude/hooks/session-memory-reminder.sh" 2>/dev/null ); }
assert_empty "STDOUT-SILENT: session-memory-reminder.sh writes NOTHING to the model channel (a Stop hook speaks on stderr only — no parse arm is possible or wanted)" "$(smr_stdout)"
# SAFE: the done-marker suppresses it (the signal-gate that stops re-fires).
mkdir -p "$SMR_T/.claude/state"; touch "$SMR_T/.claude/state/session-memory-done-$(date +%Y-%m-%d)"
assert_empty "SAFE: done-marker present → suppressed" "$(smr)"
rm -rf "$SMR_T"

echo ""
echo "=== hook coverage completeness (every WIRED hook has a smoke assertion) ==="
# The Enforce-layer for meta/SKILL.md Check 9 "Expand trigger" — previously an instruction
# only, which is how migration-commit-msg-warn shipped with 0 coverage. Every hook wired into
# settings.json OR .githooks must have a behavioral assertion here, OR be in the documented
# existence-only skip set (Compact/Stop/Skill-logger matchers — synthetic payloads unreliable).
SELF="$REPO_ROOT/scripts/smoke-test-hooks.sh"
# compact-save left the skip set 2026-07-04 — the pending-marker write made it
# deterministically assertable with a synthetic PreCompact payload (block above).
# log-skill-invocations + session-memory-reminder left the skip set 2026-07-13 — a review
# falsified the "unsynthesizable" claim for BOTH (occurrences 4+5 of that excuse this session): the
# Skill logger drives exactly like the already-covered help-arg-intercept, and the Stop reminder reads
# NO stdin (temp git repo drives it). The skip set is now EMPTY — every wired hook has a behavioral
# assertion. An untestability claim requires a FAILED ATTEMPT, not an assertion.
COVERAGE_SKIP=""
for hookpath in .claude/hooks/*.sh; do
  hname=$(basename "$hookpath" .sh)
  wired=0
  for _sf in .claude/settings.json .claude/settings.local.json "$HOME/.claude/settings.json"; do  # every layer that can wire a hook
    [ -f "$_sf" ] && grep -q "hooks/$hname.sh" "$_sf" 2>/dev/null && wired=1
  done
  grep -rq "$hname.sh" .githooks/ 2>/dev/null && wired=1
  [ "$wired" -eq 1 ] || continue   # unwired hooks aren't required to carry smoke coverage
  case " $COVERAGE_SKIP " in
    *" $hname "*) pass "coverage: $hname (documented existence-only skip)"; continue ;;
  esac
  # ⚠️ HONESTY BOUND (corrected 2026-07-13). This asks ONE question: "is the hook's path MENTIONED
  # anywhere in this file?" A bare COMMENT satisfies it. It is a PRESENCE check, and presence is
  # NOT liveness — `agent-diff-reporter` passed this gate while its only assertion branched on the
  # hook's OWN output (`if [[ -z "$out" ]] → assert_empty`), so a DEAD hook took the silent branch
  # and the suite stayed green. The gate said "covered" the entire time.
  # Tightening the REGEX does not fix this: an invocation check still passes agent-diff-reporter,
  # which IS invoked and STILL cannot fail. Presence can never prove liveness — only mutation can.
  # The liveness oracle is `scripts/smoke-mutation-matrix.sh` (kill the hook, demand RED) and the
  # self-grading detector is `scripts/smoke-assert-lint.mjs`. Do NOT read a green here as "guarded."
  if grep -q "hooks/$hname\.sh" "$SELF"; then
    pass "coverage: $hname is mentioned (PRESENCE only — liveness is the mutation matrix's job)"
  else
    fail "coverage: WIRED hook '$hname' has NO smoke assertion + not in skip-list (add FIRE/SAFE per meta/SKILL.md Check 9)"
  fi
done


echo "=== warn_emit pipe-form × multi-site ==="
# The emit-once guarantee lives BELOW the parse arms, in lib/warn-emit.sh: _WARN_EMITTED is set INSIDE
# the function, so `cmd | warn_emit` sets it in a pipe-RHS subshell and it does not persist — a second
# call emits a SECOND document and the harness discards both (measured: pipe = 2 docs; argument /
# heredoc-into-function / process substitution = 1). No per-arm parse sweep can see it: every fixture
# fires ONE advisory. This static arm REDs the combination that arms the hazard. Call sites are counted
# with trailing `#…` stripped (a python-heredoc comment mentions the name) and the local fallback
# DEFINITION / `type` guard excluded.
_wp_sites() { sed 's/#.*$//' "$1" | grep -F 'warn_emit' | grep -v -E 'warn_emit\(\)|type warn_emit' | wc -l | tr -d ' '; }
_wp_pipes() { sed 's/#.*$//' "$1" | grep -c -F '| warn_emit'; }
_wp_bad=0
for hf in .claude/hooks/*.sh; do
  _p=$(_wp_pipes "$hf"); _s=$(_wp_sites "$hf")
  if [ "${_p:-0}" -gt 0 ] && [ "${_s:-0}" -ge 2 ]; then
    fail "warn_emit: $(basename "$hf") pipes into warn_emit AND has $_s emit sites — the emit-once flag dies in the pipe subshell; use the argument form or a heredoc attached to the function"
    _wp_bad=$((_wp_bad+1))
  fi
done
[ "$_wp_bad" -eq 0 ] && pass "warn_emit: no hook combines the pipe form with >=2 emit sites"
# POSITIVE CONTROL — the predicate must FIRE on a fixture carrying both, or the arm above is vacuous.
_wp_fx="$(mktemp -d)"; printf 'a | warn_emit || true\nb | warn_emit || true\n' > "$_wp_fx/two.sh"
if [ "$(_wp_pipes "$_wp_fx/two.sh")" -gt 0 ] && [ "$(_wp_sites "$_wp_fx/two.sh")" -ge 2 ]; then
  pass "warn_emit: predicate FIRES on a two-site pipe fixture (positive control)"
else
  fail "warn_emit: predicate BLIND on a two-site pipe fixture — the arm above is vacuous"
fi
rm -rf "$_wp_fx"

echo "=== parse-arm coverage (every hookSpecificOutput EMITTER has a parse assertion — FAIL mode) ==="
# 2026-08-26, the SECOND recurrence of the class in one day (an earlier case
# was the first): a substring FIRE arm passes on stdout that does not parse, and a hook emitting
# hookSpecificOutput delivers NOTHING when its stdout is not exactly one JSON document. The coverage
# gate above enforces arm EXISTENCE; this enforces the parse property one level up.
# SHIPPED WARN-MODE BY MEASUREMENT (at birth 18 of 19 counted emitters had no parse arm, so fail-mode
# would have been RED at birth — session-cadence.md § MEASURE THE POPULATION), PROMOTED TO FAIL THE SAME
# DAY once the population was fixed: every emitter got its arm (a known gap is fixed at once, not
# deferred). A new emitter without a parse arm now
# REDs the suite at birth — the coverage gate's guarantee, one property over. PRESENCE check, like the gate above: a section that
# merely MENTIONS json.loads passes; liveness is the mutation matrix's job. A hook whose sections
# are all `.sh`-less-named is read by stem, like the shape lint.
# EMITTER PREDICATE (corrected the same day it shipped — the file-level grep was wrong in BOTH
# directions): a hook is an emitter iff it is WIRED (settings.json or .githooks, like the coverage
# gate — unwired hooks owe no arm) AND it either (a) carries the literal OUTSIDE a comment line
# (`grep -v '^[[:space:]]*#'` first — two Stop hooks MENTION it only in a comment recording the
# measured rule that Stop stays on bare stderr; bash-environment.md § the class behind the two
# bullets above), or (b) calls warn_emit, the lib helper that emits hookSpecificOutput on the
# caller's behalf — 12 wired hooks emit that way with no literal in their own file, and the
# first cut counted 19 emitters, two of them comment-only mentions, and missed every warn_emit
# caller — derive the population from this gate's own output, never from a number here.
_pa_unguarded=0
for hookpath in .claude/hooks/*.sh; do
  hname=$(basename "$hookpath"); hstem="${hname%.sh}"
  _pa_wired=0
  for _sf in .claude/settings.json .claude/settings.local.json "$HOME/.claude/settings.json"; do
    [ -f "$_sf" ] && grep -q "hooks/$hname" "$_sf" 2>/dev/null && _pa_wired=1
  done
  grep -rq "$hname" .githooks/ 2>/dev/null && _pa_wired=1
  [ "$_pa_wired" -eq 1 ] || continue
  _pa_emits=0
  grep -v '^[[:space:]]*#' "$hookpath" | grep -q 'hookSpecificOutput' && _pa_emits=1
  grep -v '^[[:space:]]*#' "$hookpath" | grep -q 'warn_emit' && _pa_emits=1
  [ "$_pa_emits" -eq 1 ] || continue
  # every section whose `echo "=== ` header names the hook (by .sh name, else by stem)
  _pa_sec=$(awk -v n="$hname" '/^echo "=== /{p=index($0,n)>0} p' "$SELF")
  [ -n "$_pa_sec" ] || _pa_sec=$(awk -v n="$hstem" '/^echo "=== /{p=index($0,n)>0} p' "$SELF")
  if [ -z "$_pa_sec" ]; then
    fail "PARSE-UNGUARDED: $hname emits hookSpecificOutput and no smoke section header names it — add a section with an assert_one_json_doc arm"; _pa_unguarded=$((_pa_unguarded+1)); continue
  fi
  # arm side stripped too: a COMMENT quoting the story satisfied the
  # gate (a mutation commented out check-test-exists's only parse arm; the gate still read GUARDED).
  if printf '%s' "$_pa_sec" | grep -v '^[[:space:]]*#' | grep -qE 'json\.loads|assert_one_json_doc'; then
    pass "parse-arm: $hname carries a whole-stdout parse assertion (presence — liveness is the mutation matrix's job)"
  else
    fail "PARSE-UNGUARDED: $hname emits hookSpecificOutput and its sections carry no whole-stdout parse assertion (json.loads / assert_one_json_doc — jq -e . does NOT count, it streams)"; _pa_unguarded=$((_pa_unguarded+1))
  fi
done
echo "  parse-arm coverage: unguarded emitters this run = $_pa_unguarded  (fail mode since 2026-08-26)"

echo "=== agent-dispatch-memory-guard.sh (thrash gate + flight recorder) ==="
# SYNTHETIC STAMP (2026-08-01) — the recorder was 41% injected fixtures with nothing marking them,
# so an unfiltered read reported p95 = 40.00, a FIXTURE value, on three separate days. The stamp
# keys on FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB (what MAKES a record synthetic), not on the agent
# name, so a real agent described as "smoke..." is not misclassified.
# ⛔ SMOKE CHANNEL (2026-09-13). Every arm in this section drives the hook, and
# the hook APPENDS — so before this change the suite wrote its fixtures into the PRODUCTION flight
# recorder: measured 7,669 of 14,930 records (51.4%) synthetic, i.e. any count taken over that log
# was ~2x. Every invocation below carries CLAUDE_HOOK_SMOKE=1 and every read keys on the
# `.smoke.jsonl` sibling; the hook also routes an INJECTED-pressure record there structurally, so
# an arm added later without the flag cannot silently re-pollute the calibration denominator.
_amg_last() { tail -1 .claude/logs/agent-dispatch-memory.smoke.jsonl; }
# ⚠️ DARWIN-GATED — and these two arms shipped OUTSIDE the gate for ~3 hours on 2026-08-01,
# directly above the comment at the next block that exists to explain why they must not be.
# The hook exits at its own `uname` gate on non-Darwin BEFORE it writes any log line, so on the
# ubuntu meta-hygiene runner `_amg_last` returns the PREVIOUS arm's record: the synthetic:false
# arm passes VACUOUSLY (reading a stale false) and the synthetic:true arm goes RED. Measured by
# PATH-prepending a stub `uname` that echoes Linux: 502 PASS / 1 FAIL, the failure being exactly
# `FIRE: an INJECTED-pressure dispatch is stamped synthetic:true`. Reproduce with that stub before
# touching this block. The general form is in the block below; this comment records that the form
# was already written down and got reproduced anyway, one screen above it.
if [ "$(uname)" = "Darwin" ]; then
  echo '{"tool_name":"Agent","tool_input":{"description":"smoke-synthetic-stamp-real"}}' \
    | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/agent-dispatch-memory-guard.sh >/dev/null 2>&1
  out=$(_amg_last)
  assert_contains "FIRE: a REAL dispatch is stamped synthetic:false" "$out" '"synthetic":false'
  echo '{"tool_name":"Agent","tool_input":{"description":"smoke-synthetic-stamp-fake"}}' \
    | CLAUDE_HOOK_SMOKE=1 FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=40.00 bash .claude/hooks/agent-dispatch-memory-guard.sh >/dev/null 2>&1
  out=$(_amg_last)
  assert_contains "FIRE: an INJECTED-pressure dispatch is stamped synthetic:true" "$out" '"synthetic":true'
  # ⛔ SMOKE ROUTING (2026-09-13). PREDICATE, never a before/after delta on the production recorder —
  # that file is written by every live dispatch in the fleet, so a delta would attribute peers'
  # writes to this suite. Key on the fixture's OWN description marker: exact, immune to a
  # concurrent real dispatch, and the production-side count stays 0 across re-runs (the smoke log
  # accumulates, which is why that side reads the LAST matching line rather than a count).
  printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-a6-routing"}}' \
    | CLAUDE_HOOK_SMOKE=1 bash .claude/hooks/agent-dispatch-memory-guard.sh >/dev/null 2>&1
  assert_contains "amg: smoke routing — a smoke dispatch lands in the .smoke.jsonl sibling" \
    "$(grep -F '"agent":"smoke-a6-routing"' .claude/logs/agent-dispatch-memory.smoke.jsonl 2>/dev/null | tail -1)" '"agent":"smoke-a6-routing"'
  _amg_prod=$(grep -cF '"agent":"smoke-a6-routing"' .claude/logs/agent-dispatch-memory.jsonl 2>/dev/null); _amg_prod=${_amg_prod:-0}
  assert_eq "amg: smoke routing — ...and NOTHING of it reaches the production flight recorder" "0" "$_amg_prod"
  # STRUCTURAL BACKSTOP, keyed on what MAKES a record synthetic rather than on a flag a future arm
  # has to remember: an INJECTED-pressure record routes to the sibling with NO flag set, so an arm
  # added later that forgets CLAUDE_HOOK_SMOKE cannot silently re-pollute the calibration denominator.
  printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-a6-backstop"}}' \
    | FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=40 bash .claude/hooks/agent-dispatch-memory-guard.sh >/dev/null 2>&1
  _amg_bs=$(grep -cF '"agent":"smoke-a6-backstop"' .claude/logs/agent-dispatch-memory.jsonl 2>/dev/null); _amg_bs=${_amg_bs:-0}
  assert_eq "amg: smoke-routing backstop — an INJECTED-pressure record stays OUT of the production log with no flag set" "0" "$_amg_bs"
  assert_contains "amg: smoke-routing backstop — ...and IS recorded, in the .smoke.jsonl sibling" \
    "$(grep -F '"agent":"smoke-a6-backstop"' .claude/logs/agent-dispatch-memory.smoke.jsonl 2>/dev/null | tail -1)" '"synthetic":true'
else
 # NO-SILENT-CAPS: a bounded run must say what it
  # dropped. Without this, Linux CI reports a lower pass total than a local Darwin run with no
  # explanation, and the difference reads as a regression. Deliberately carries NO arm COUNT —
  # a hardcoded N here would rot silently the first time anyone adds an arm.
  echo "  (skipped: agent-dispatch-memory-guard synthetic-stamp arms — Darwin-only, host is $(uname))"
fi

# BLOCK-mode, threshold 24 GB (raised in two steps from 15).
# ⚠️ The ORIGINAL justification — "normal pressure ~4.5 GB, FP ~0" — was REFUTED by the hook's own
# flight recorder and must not be restored. At the 24 setting, measured on the STAMPED-REAL subset
# (synthetic:false, parse-clean, n=611): p50 9.03 / p95 17.19 / p99 19.98 / max 20.74 GB. 18 denied
# 19/611 (3.1%); 22 and 24 each deny ZERO — so 24 is deliberately CRASH-CLASS-ONLY and inert below
# that. ⚠️ FILTER OR THE NUMBERS LIE: 713 records predate the synthetic stamp and ~293 are smoke
# fixtures at fixed values, so the UNFILTERED log reads p95 = 40.00 (a fixture value). Rationale in
# the hook header.
# FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB injects deterministic pressure — the arms below use 40/2 GB,
# clear of the threshold either side, so they do not pin it (they survived the 18 -> 24 raise
# unchanged, which is the property that choice was made for).
if [ "$(uname)" = "Darwin" ]; then
  # Darwin-gated (post-mortem fold 2026-07-30): the hook exits at its own
  # uname gate on non-Darwin BEFORE reading FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB — so on the
  # ubuntu meta-hygiene runner FIRE gets EMPTY output (assert_contains REDs the job) while
  # SAFE/ESCAPE pass vacuously. Measured under a faked-Linux uname: 473 PASS / 1 FAIL.
  assert_contains "amg: FIRE — 40 GB fake pressure denies the Agent dispatch" \
    "$(printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke"}}' | CLAUDE_HOOK_SMOKE=1 FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=40 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh")" \
    '"permissionDecision": "deny"'
  # PARSE arm — inside the Darwin gate for the same reason the FIRE arm is: on Linux the hook
  # exits at its own uname gate BEFORE reading the fake-pressure var, so stdout is EMPTY and the
  # parse verdict would be EMPTY (a platform artifact, not a broken emitter).
  sout=$(printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke"}}' | CLAUDE_HOOK_SMOKE=1 FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=40 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh" 2>/dev/null)
  assert_one_json_doc "PARSE: agent-dispatch-memory-guard.sh deny arm → ONE parseable hookSpecificOutput doc, the flight-record path survives" "$sout" '.claude/logs/agent-dispatch-memory.jsonl'
  assert_empty "amg: SAFE — 2 GB fake pressure allows silently" \
    "$(printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke"}}' | CLAUDE_HOOK_SMOKE=1 FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=2 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh")"
  assert_empty "amg: ESCAPE — SKIP_AGENT_MEMORY_GUARD=1 bypasses even at 40 GB" \
    "$(printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke"}}' | CLAUDE_HOOK_SMOKE=1 FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=40 SKIP_AGENT_MEMORY_GUARD=1 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh")"
else
  echo "  (skipped: agent-dispatch-memory-guard FIRE/SAFE/ESCAPE arms — Darwin-only, host is $(uname))"
fi
# ALL THREE arms above inject the fake var, so the REAL parse
# (:64-:70) ran in ZERO assertions — 467/0 passed with the measurement path never executed, which
# is how the page-size defect below shipped green. These arms reach the real path. Darwin-only (the hook exits at the
# uname gate elsewhere — a PATH-CLAMP mutation would pass vacuously for the same reason, so the
# mutation arms use PATH-PREPENDED stubs, never a clamp).
if [ "$(uname)" = "Darwin" ]; then
  AMG_LOG="$REPO_ROOT/.claude/logs/agent-dispatch-memory.smoke.jsonl"
  # Triaged 2026-08-02: every assertion read the log's LAST line — a concurrent REAL
  # dispatch appending between an arm's invocation and its read flakes the arm, and the
  # page-size pin was vacuously satisfiable by the failopen arm's own record. Key each read
  # on the arm's OWN description marker instead; a LOST invocation now reads EMPTY and REDs.
  amg_last() { grep -F "\"agent\":\"$1\"" "$AMG_LOG" | tail -1; }
  printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-realparse"}}' | CLAUDE_HOOK_SMOKE=1 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh" >/dev/null
  assert_contains "amg: REAL-PARSE happy — live measurement logs parse_error:false" \
    "$(amg_last smoke-realparse)" '"parse_error":false'
  assert_contains "amg: REAL-PARSE happy — swap_gb numeric (shape, not value)" \
    "$(amg_last smoke-realparse | grep -oE '"swap_gb":[0-9]+\.[0-9]+')" '"swap_gb":'
  assert_contains "amg: REAL-PARSE happy — comp_gb numeric (shape, not value)" \
    "$(amg_last smoke-realparse | grep -oE '"comp_gb":[0-9]+\.[0-9]+')" '"comp_gb":'
  # decision field (folded 2026-07-30, after a post-mortem): the record now carries the
  # ACTION, not just the measurement — "was that 20.03 GB dispatch denied?" is henceforth
  # answerable from the log alone. Real-parse arms assert PRESENCE + valid enum only (the
  # live machine may legitimately sit above threshold during a heavy fleet night — never
  # pin allow/deny on a real measurement); the deterministic deny rides the fake arm.
  # ORDERING FIX 2026-08-12: this generator sat AFTER the presence assert below, so on a
  # CLEAN log (fresh checkout / CI) that assert read a record that did not exist yet. It
  # passed locally only because a warm .claude/logs/ already held a prior run's record --
  # green on a developer box, RED on a clean clone, which is where it matters. Measured
  # in a detached worktree: FAIL 1, this assert. Generate first, then assert.
  printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-decision-deny"}}' | CLAUDE_HOOK_SMOKE=1 FF_AGENT_MEMGUARD_FAKE_PRESSURE_GB=40 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh" >/dev/null
  assert_contains "amg: RECORD carries a decision field (allow|deny — presence, not value)" \
    "$(amg_last smoke-decision-deny | grep -oE '"decision":"(allow|deny)"')" '"decision":"'
  assert_contains "amg: RECORD carries decision:deny on a fired gate" \
    "$(amg_last smoke-decision-deny)" '"decision":"deny"'
  # locale pin (post-mortem): a comma-decimal ambient locale must neither kill the parse
  # (deny branch unreachable via PARSE_ERROR fail-open) nor corrupt the JSON number slots.
  # Mutation: strip the hook's `export LC_ALL=C` pin → this REDs (parse_error:true under de_DE).
  printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-locale-pin"}}' | CLAUDE_HOOK_SMOKE=1 LC_ALL=de_DE.UTF-8 bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh" >/dev/null
  assert_contains "amg: LOCALE — comma-decimal ambient locale still real-parses (LC_ALL=C pin)" \
    "$(amg_last smoke-locale-pin)" '"parse_error":false'
  # FAIL-OPEN mutation arm: stubs make BOTH measurement commands emit nothing -> parse_error:true + silent allow
  AMG_STUB=$(mktemp -d)
  printf '#!/bin/sh\nexit 0\n' > "$AMG_STUB/sysctl"; printf '#!/bin/sh\nexit 0\n' > "$AMG_STUB/vm_stat"
  chmod +x "$AMG_STUB/sysctl" "$AMG_STUB/vm_stat"
  assert_empty "amg: FAIL-OPEN — unmeasurable pressure allows silently (no deny)" \
    "$(printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-failopen"}}' | CLAUDE_HOOK_SMOKE=1 PATH="$AMG_STUB:$PATH" bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh")"
  assert_contains "amg: FAIL-OPEN — the gap is LOGGED as parse_error:true" \
    "$(amg_last smoke-failopen)" '"parse_error":true'
  # Page-size regression pin: sysctl VALID, vm_stat missing the page-size line -> the compressor half
  # must fail LOUD (parse_error:true). Pre-fix this logged a well-formed 0.00 with parse_error:false.
  AMG_STUB2=$(mktemp -d)
  printf '#!/bin/sh\necho "total = 4096.00M  used = 3024.12M  free = 1071.88M  (encrypted)"\n' > "$AMG_STUB2/sysctl"
  printf '#!/bin/sh\necho "Pages occupied by compressor:  123456."\n' > "$AMG_STUB2/vm_stat"
  chmod +x "$AMG_STUB2/sysctl" "$AMG_STUB2/vm_stat"
  printf '%s' '{"tool_name":"Agent","tool_input":{"description":"smoke-p21pin"}}' | CLAUDE_HOOK_SMOKE=1 PATH="$AMG_STUB2:$PATH" bash "$REPO_ROOT/.claude/hooks/agent-dispatch-memory-guard.sh" >/dev/null
  assert_contains "amg: page-size pin — pagesize-less vm_stat fails LOUD (parse_error:true), never a silent 0.00" \
    "$(amg_last smoke-p21pin)" '"parse_error":true'
  rm -rf "$AMG_STUB" "$AMG_STUB2"
else
  echo "  (skipped: agent-dispatch-memory-guard REAL-PARSE / locale / fail-open arms — Darwin-only, host is $(uname))"
fi

echo ""
echo "=== smoke-assert-lint (Layer 0 — no self-grading assertions in THIS suite) ==="
# The agent-diff-reporter shape: an assertion whose expectation is picked by the SUT's
# own output RUNS, PASSES, and can never fail. The lint is static and RECOMPUTED from the current
# file every run — it cannot go stale (unlike a stored mutation artifact). Baseline 0 findings at
# wiring → hard gate, as for the other deterministic suites.
# Self-test FIRST: a lint that cannot fail is the same disease one level up (2026-07-13,
# replica-self-test class — the self-test consumes the real findSelfGrading, not a copy).
if node "$REPO_ROOT/scripts/smoke-assert-lint.mjs" --self-test >/dev/null 2>&1; then
  pass "smoke-assert-lint self-test (flags the self-grading fixture, passes the honest one)"
else
  fail "smoke-assert-lint SELF-TEST failed — the lint is broken; its clean verdict below is untrusted"
fi
if node "$REPO_ROOT/scripts/smoke-assert-lint.mjs" --strict >/dev/null 2>&1; then
  pass "no self-grading assertions in smoke-test-hooks.sh (lint --strict clean)"
else
  fail "SELF-GRADING assertion(s) in this suite — run: node scripts/smoke-assert-lint.mjs (fix: expectation must come from the FIXTURE, never the SUT)"
fi

echo ""
echo "=== smoke-shape-lint (deletion complement — every invoked-hook section has a FIRE assertion) ==="
# The mutation matrix (smoke-mutation-matrix.sh --gate) fires on HOOK diffs. It does NOT see a
# SUITE-side edit that deletes a hook's only FIRE assertion on an UNCHANGED hook — the suite stays
# green (fewer ✓) and no hook changed to trigger the gate. This static lint catches that death-blind
# SHAPE class, recomputed every run → stale-proof (the shape function is proven by the --self-test
# above, which now covers it too). WARN-mode: a section using a valid non-assert_contains
# FIRE (assert_eq delta / custom if-else on a hook-written marker) is allowlisted IN the lint (each
# verified mutation-live by --gate); a genuine NEW death-blind section surfaces here. Block-mode
# candidate (--shape --strict) after an observation window. The mutation matrix stays authoritative.
shape_out="$(node "$REPO_ROOT/scripts/smoke-assert-lint.mjs" --shape 2>&1)"
shape_n="$(printf '%s\n' "$shape_out" | grep -c 'SHAPE-UNGUARDED' || true)"
if [ "${shape_n:-0}" -eq 0 ]; then
  pass "smoke-shape-lint: every invoked-hook section carries a FIRE assertion (0 death-blind shapes)"
else
  printf '%s\n' "$shape_out" | grep 'SHAPE-UNGUARDED'
  pass "smoke-shape-lint: $shape_n warn(s) surfaced — WARN-mode, non-blocking (verify via --gate; matrix is authoritative)"
fi

echo ""
echo "=== session-mail engine smoke (delegated — scripts/smoke-test-session-mail.sh) ==="
# Folded in from a peer session (2026-06-19): the mail engine's 18-assertion smoke
# ran only in pre-push; routing it through here gives it /meta self-audit Check 9
# coverage. Self-contained (redirects to temp dirs via FF_SESSIONS_DIR/FF_MAIL_DIR,
# touches no real state, ~2s). Delegated sub-suite, not a hook → exempt from the
# line-1101 hook-coverage gate.
if bash "$REPO_ROOT/scripts/smoke-test-session-mail.sh" >/tmp/ff-mailsmoke.log 2>&1; then
  pass "session-mail smoke (18 assertions) clean"
else
  fail "session-mail smoke FAILED (see /tmp/ff-mailsmoke.log)"
fi

# --- git hooks wiring tripwire (catches the silent-dormancy class: core.hooksPath
# drifted to the inert .git/hooks default → .githooks/* never fires on push/commit). ---
echo ""
echo "=== git hooks wiring (core.hooksPath → .githooks) ==="
if [ -n "${CI:-}" ]; then
  pass "hooks-wiring check skipped in CI (local-clone concern; CI gates via the workflow itself)"
else
  _hp="$(git config core.hooksPath 2>/dev/null || true)"
  case "$_hp" in
    .githooks|*/.githooks)
      pass "core.hooksPath → .githooks — the .githooks/* hooks fire on push/commit" ;;
    *)
      fail "core.hooksPath='${_hp:-<unset → inert .git/hooks default>}' → .githooks/* hooks are DORMANT (pushes silently skip EVERY gate). Fix: 'git config core.hooksPath .githooks' (or re-run 'npm install' — the prepare script wires it)." ;;
  esac
fi

# === MODEL CHANNEL — STDOUT-ONLY arms ============================================================
# WHY THIS BLOCK EXISTS AND WHY IT CANNOT REUSE THE ARMS ABOVE: 96 of 109 references to the
# converted hooks capture with `2>&1`, so this suite is STRUCTURALLY BLIND to WHICH channel an
# advisory used. A hook silently reverted to bare stderr keeps every existing arm green — the exact
# blindness that let "840 PASS unchanged" be reported as evidence about a channel change it could
# not see. These arms capture STDOUT ONLY.
# EACH ARM IS SELF-GUARDING: it requires the literal `additionalContext`, so a payload that stops
# firing yields empty stdout and FAILS LOUDLY rather than passing vacuously — which is the failure
# direction that matters, because a silent arm here would restore precisely the blindness above.
echo ""
echo "=== warn-channel: STDOUT-ONLY arms (every other reference merges 2>&1) ==="
stdout_only() {  # <label> <env-assignments-or-empty> <hook-path> <payload>
  local label="$1" envp="$2" hook="$3" payload="$4" out
  out=$(printf '%s' "$payload" | env $envp bash "$hook" 2>/dev/null)
  assert_contains "MODEL CHANNEL: $label reaches STDOUT as additionalContext" "$out" '"additionalContext"'
}

_SO_BIG="${_BIG_TRACKER:-}"   # empty in a tree with no tracker over 50 KB: ARM A below fails LOUD and the suite continues
_SO_RTR="/tmp/so-smoke-$$-CHANGELOG.md"
_SO_SHD="/tmp/so-smoke-$$-CHANGELOG-ARCHIVE-2026-08-02-2026-08-13.md"
printf '## 2026-08-01 older\nbody\n' > "$_SO_SHD"
{ printf '<!-- ROUTER PREAMBLE ENDS - everything below is GENERATED -->\n\n'
  printf -- '- **Appends** - new entries go to the CURRENT shard (`%s`), never to this router.\n' "$(basename "$_SO_SHD")"
} > "$_SO_RTR"

stdout_only "grep-blowup-warn (absroot WARN — the founding measurement's own arm)" "" \
  ".claude/hooks/grep-blowup-warn.sh" \
  "{\"tool_name\":\"Bash\",\"tool_input\":{\"command\":\"grep -rlF PLAN_LIMITS ${_gbw_root}\"}}"   # the root the hook DERIVES (portable since 2026-08-26); it fed one Mac's literal until then
if [ -n "$_SO_BIG" ]; then
stdout_only "warn-large-tracker-read (ARM A)" "" \
  ".claude/hooks/warn-large-tracker-read.sh" \
  "{\"tool_name\":\"Read\",\"tool_input\":{\"file_path\":\"$_SO_BIG\"}}"
else fail "MODEL CHANNEL: warn-large-tracker-read (ARM A) CANNOT RUN — no .claude/project-memory/*.md over 50 KB (instrument failure, not a pass)"; fi
stdout_only "bash-safety-warn" "BASH_SAFETY_NO_LOG=1" \
