  '{"tool_name":"Bash","tool_input":{"command":"git add -A"}}'
stdout_only "check-test-exists" "" \
  ".claude/hooks/check-test-exists.sh" \
  "{\"tool_name\":\"Edit\",\"tool_input\":{\"file_path\":\"$REPO_ROOT/src/lib/smoke-stdout-nonexistent-$$.ts\"}}"
stdout_only "maxl-prose-grep-warn" "MAXL_GREP_NO_LOG=1" \
