# A ping turn must not trigger the per-turn reminders (each would turn one cheap read into a working turn).
for _kw_h in mail-listen-arm-reminder working-plan-reminder trigger-index-match; do
  _kw_o=$(printf '{"session_id":"kwsmoke2-0000","prompt":"[keep-warm] should we git stash this","transcript_path":"/nonexistent"}' | bash ".claude/hooks/$_kw_h.sh" 2>/dev/null)
  assert_empty "SAFE: $_kw_h.sh is silent on a [keep-warm] ping" "$_kw_o"
  # Over-fire control: the exit is anchored to the prompt START, so an owner prompt that only mentions the
