  _kw_o=$(printf '{"session_id":"kwsmoke2-0000","prompt":"why did the [keep-warm] ping fire? should we git stash this","transcript_path":"/nonexistent"}' | bash ".claude/hooks/$_kw_h.sh" 2>/dev/null)
