echo ""
echo "=== agent-dispatch-session-limit-guard.py (PreToolUse Agent + SendMessage: no helpers, and no batch of cold resumes, above 90% of the session limit) ==="
_sl_state=$(cd "$(mktemp -d)" && pwd -P)
_sl_now=$(date +%s)
_sl_rec() { printf '{"ts": %s, "five_hour_pct": %s, "five_hour_resets_at": %s}' "$1" "$2" "$3" > "$_sl_state/statusline-slsmoke1.json"; }
_sl_run() { printf '%s' "$1" | CLAUDE_HOOK_SMOKE=1 CLAUDE_PROJECT_DIR="$_sl_state" FF_STATE_DIR="$_sl_state" python3 .claude/hooks/agent-dispatch-session-limit-guard.py 2>/dev/null; }
# Every arm reads rc AND stdout: a silent arm that checked stdout alone was green under an `exit 2` on that
# branch, and exit 2 on PreToolUse BLOCKS the launch with an empty reason (6 such mutants survived).
_sl_call() { _sl_o=$(_sl_run "$1"); _sl_rc=$?; }
_sl_silent() { assert_empty "$1" "$_sl_o"; assert_eq "$1 — rc 0 (exit 2 would block the launch)" "0" "$_sl_rc"; }
_sl_in='{"session_id":"slsmoke1-0000","tool_name":"Agent","tool_input":{"description":"smoke helper","prompt":"read the file"}}'
_sl_ord='{"session_id":"slsmoke1-0000","tool_name":"Agent","tool_input":{"description":"smoke helper","prompt":"read the file\nOWNER-ORDERED: run the panel now"}}'
_sl_mention='{"session_id":"slsmoke1-0000","tool_name":"Agent","tool_input":{"description":"smoke helper","prompt":"a brief that mentions the OWNER-ORDERED: escape mid-line"}}'
_sl_bare='{"session_id":"slsmoke1-0000","tool_name":"Agent","tool_input":{"description":"smoke helper","prompt":"read the file\nOWNER-ORDERED:"}}'
_sl_rec "$_sl_now" 95 $((_sl_now + 3600)); _sl_call "$_sl_in"
assert_one_json_doc "PARSE: session-limit guard at 95% → ONE parseable PreToolUse deny doc, its reason survives" "$_sl_o" "Session limit at 95%"
assert_contains "FIRE: session-limit guard at 95% → permissionDecision deny" "$_sl_o" '"permissionDecision": "deny"'
assert_contains "FIRE: the deny reason tells the seat to tell the owner" "$_sl_o" "Tell the owner in one line"
assert_eq "FIRE: the deny exits 0 (on exit 2 the harness drops the JSON reason)" "0" "$_sl_rc"
_sl_rec "$_sl_now" 91 $((_sl_now + 3600)); _sl_call "$_sl_in"
assert_contains "FIRE: session-limit guard at 91% (just above the line) → deny" "$_sl_o" '"permissionDecision": "deny"'
_sl_rec "$_sl_now" 90 $((_sl_now + 3600)); _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard at exactly 90% → silent (the line is ABOVE 90)"
_sl_rec "$_sl_now" 95 $((_sl_now + 3600)); _sl_call "$_sl_ord"
_sl_silent "SAFE: session-limit guard at 95% with an OWNER-ORDERED: line → silent"
assert_contains "FIRE: an ordered launch is logged WITH the owner's words (the audit trail of the escape)" "$(tail -1 "$_sl_state/.claude/logs/session-limit-dispatch-fires.smoke.jsonl" 2>/dev/null)" '"order": "run the panel now"'
_sl_call "$_sl_bare"
assert_contains "FIRE: a bare OWNER-ORDERED: line with no words quotes nothing → still deny" "$_sl_o" '"permissionDecision": "deny"'
_sl_call '{"session_id":"slsmoke1-0000","tool_name":"Agent","tool_input":{"description":"smoke helper","prompt":"read the file\nOWNER-ORDERED:   "}}'
assert_contains "FIRE: an OWNER-ORDERED: line with only spaces after it quotes nothing → still deny" "$_sl_o" '"permissionDecision": "deny"'
_sl_call "$_sl_mention"
assert_contains "FIRE: OWNER-ORDERED: quoted mid-line is not an order → still deny" "$_sl_o" '"permissionDecision": "deny"'
_sl_rec $((_sl_now - 700)) 95 $((_sl_now + 3600)); _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard on a reading older than 10 minutes → silent"
_sl_rec "$_sl_now" 95 $((_sl_now - 60)); _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard after the window reset → silent"
_sl_rec "$_sl_now" NaN $((_sl_now + 3600)); _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard on a non-finite percentage → silent (unreadable, not 'above 90')"
_sl_rec "$_sl_now" 95 1e20; _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard whose deny text cannot be built (reset out of range → an exception) → silent"
_sl_rec "$_sl_now" 95 $((_sl_now + 3600)); _sl_o=$(printf '%s' "$_sl_in" | SKIP_AGENT_SESSION_LIMIT_GUARD=1 FF_STATE_DIR="$_sl_state" CLAUDE_PROJECT_DIR="$_sl_state" python3 .claude/hooks/agent-dispatch-session-limit-guard.py 2>/dev/null); _sl_rc=$?
_sl_silent "SAFE: SKIP_AGENT_SESSION_LIMIT_GUARD=1 (the owner's whole-session escape) at 95% → silent"
_sl_call '{"session_id":"slsmoke1-0000","tool_name":"Bash","tool_input":{"command":"ls"}}'
_sl_silent "SAFE: a non-Agent tool call at 95% → silent (the guard reads only Agent and SendMessage)"
rm -f "$_sl_state/statusline-slsmoke1.json"; _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard with no status-line state → silent"
printf 'not json' > "$_sl_state/statusline-slsmoke1.json"; _sl_call "$_sl_in"
_sl_silent "SAFE: session-limit guard on an unparseable state file → silent"
_sl_o=$(printf 'garbage' | FF_STATE_DIR="$_sl_state" python3 .claude/hooks/agent-dispatch-session-limit-guard.py 2>/dev/null); _sl_rc=$?
assert_eq "SAFE: session-limit guard on malformed hook input exits 0 (never 2)" "0" "$_sl_rc"
# The weekly line: at 97% or more of the weekly limit the guard asks the owner, without blocking,
# instead of refusing. No other arm here sets seven_day_pct, so without these `--for` on this guard reads the same with or
# without the weekly code.
_sl_wk() { printf '{"ts": %s, "five_hour_pct": null, "five_hour_resets_at": null, "seven_day_pct": %s}' "$_sl_now" "$1" > "$_sl_state/statusline-slsmoke1.json"; }
_sl_wk 98; _sl_call "$_sl_in"
assert_one_json_doc "PARSE: the guard at 98% of the weekly limit → ONE parseable deny doc, its question survives" "$_sl_o" "Weekly limit (all models) at 98%"
assert_contains "FIRE: the weekly reason is a confirmation request, not a refusal" "$_sl_o" "This is a confirmation request, not a refusal"
assert_contains "FIRE: the weekly reason forbids a question that waits for an answer" "$_sl_o" "never with AskUserQuestion"
assert_contains "FIRE: the weekly question is logged as ask-weekly" "$(tail -1 "$_sl_state/.claude/logs/session-limit-dispatch-fires.smoke.jsonl" 2>/dev/null)" '"decision": "ask-weekly"'
assert_eq "FIRE: the weekly question exits 0" "0" "$_sl_rc"
_sl_wk 96.9; _sl_call "$_sl_in"
_sl_silent "SAFE: the guard at 96.9% of the weekly limit → silent (the weekly line is AT 97)"
# Producer contract: every arm above hand-builds the state record, so a rename or unit change in
# statusline.py write_state would leave them green while the live guard went permanently silent. Let the
# real producer write the file and read it through the guard's own path, CLAUDE_PROJECT_DIR/.claude/state,
# with no FF_STATE_DIR override. The producer reads the five-hour figures from Claude Code's own stdin
# (rate_limits); HOME is pointed away and its opt-in usage lookup left off (the shipped default), so it
# touches nothing real.
_sl_proj="$_sl_state/proj"; mkdir -p "$_sl_proj/.claude/state"
env -u STATUSLINE_USAGE_FETCH HOME="$_sl_state" python3 -c 'import importlib.util as u, sys, time
s = u.spec_from_file_location("sl", "scripts/statusline.py"); m = u.module_from_spec(s); s.loader.exec_module(m)
now = time.time()
m.write_state({"session_id": "slsmoke2-0000", "workspace": {"project_dir": sys.argv[1]},
               "rate_limits": {"five_hour": {"used_percentage": 95, "resets_at": int(now) + 3600}}}, now)' "$_sl_proj" 2>/dev/null
_sl_o=$(printf '%s' '{"session_id":"slsmoke2-0000","tool_name":"Agent","tool_input":{"prompt":"read the file"}}' | CLAUDE_HOOK_SMOKE=1 CLAUDE_PROJECT_DIR="$_sl_proj" python3 .claude/hooks/agent-dispatch-session-limit-guard.py 2>/dev/null)
assert_contains "FIRE: the record scripts/statusline.py write_state actually writes at 95% → deny (producer→guard contract)" "$_sl_o" "Session limit at 95%"
# The producer that RUNS must be that file: the project settings' statusLine runs the repo's scripts/statusline.py, never
# a copy elsewhere (a home-directory copy once ran instead, byte-identical by luck, so a change here passed every arm while
# the guard read the old copy's record). Reads only this repo's own settings.
# Two checks, each closing what the other lets through. A substring check on the string passed a
# home-dir copy under any /scripts/ path, a pinned main-checkout path and a cwd-relative path. The exact pin catches any
# edit, including ones a stub cannot see (an appended side effect, `:-` turned into `-`, the `|| pwd` fallback dropped);
# running the command against a stub checkout catches an edit that re-pins both sides to a command that does not run
# this checkout's file.
_sl_cmd=$(python3 -c 'import json; print(json.load(open(".claude/settings.json")).get("statusLine", {}).get("command", ""))' 2>/dev/null)
assert_eq "WIRING: the project settings' statusLine is exactly the command that runs the repo's scripts/statusline.py" 'python3 "${CLAUDE_PROJECT_DIR:-$(git rev-parse --show-toplevel 2>/dev/null || pwd)}/scripts/statusline.py"' "$_sl_cmd"
_sl_stub="$_sl_state/slcmd"; mkdir -p "$_sl_stub/scripts" "$_sl_stub/sub"; git -C "$_sl_stub" init -q 2>/dev/null
printf 'print("SL-STUB-RAN")\n' > "$_sl_stub/scripts/statusline.py"
assert_eq "WIRING: the project statusLine runs CLAUDE_PROJECT_DIR/scripts/statusline.py (cwd /)" "SL-STUB-RAN" "$(cd / && CLAUDE_PROJECT_DIR="$_sl_stub" bash -c "$_sl_cmd" </dev/null 2>/dev/null)"
assert_eq "WIRING: unset CLAUDE_PROJECT_DIR → the git top-level's scripts/statusline.py (cwd a subdirectory)" "SL-STUB-RAN" "$(cd "$_sl_stub/sub" && env -u CLAUDE_PROJECT_DIR -u GIT_DIR -u GIT_WORK_TREE bash -c "$_sl_cmd" </dev/null 2>/dev/null)"
# Source: Anthropic, Claude Code status line documentation, 2026, for the vendor fact restated here.
# The status line is redrawn on events, and events can stop while the main session sits idle (waiting on
# background agents, say): without the timer the record ages past MAX_AGE_S and the guard fails open.
assert_eq "WIRING: statusLine refreshInterval is an int in 1..min(guard MAX_AGE_S, keep-warm STATUS_FRESH_S)" "ok" "$(python3 -c '
import importlib.util as u, json
def load(p):
    s = u.spec_from_file_location("m", p); m = u.module_from_spec(s); s.loader.exec_module(m); return m
v = json.load(open(".claude/settings.json")).get("statusLine", {}).get("refreshInterval")
top = min(load(".claude/hooks/agent-dispatch-session-limit-guard.py").MAX_AGE_S, load(".claude/hooks/keep-warm-gate.py").STATUS_FRESH_S)
print("ok" if type(v) is int and 1 <= v <= top else "bad %r (max %r)" % (v, top))' 2>&1)"
assert_eq "WIRING: scripts/statusline.py exists for that statusLine to run" "yes" "$([ -f scripts/statusline.py ] && echo yes || echo no)"
# Resumes (above 90% a resume goes ahead when the helper's cache is warm OR it is not one
# of a batch — fewer than BATCH_OTHERS=10 other dead helpers waiting on a resume). Fixture transcripts in the shape
# scripts/limit-recovery.py scans; the guard reads that real scan (found beside the hook, not under the project dir).
_sl_lrst=$(cd "$(mktemp -d)" && pwd -P)
_sl_mk() {  # $1 subagents dir, $2 agent id, $3 minutes since its last live call (and its death), $4 model (default opus), $5 error text
  python3 - "$1" "$2" "$3" "$_sl_now" "${4:-claude-opus-5-5}" "${5:-}" <<'PY2'
import json, os, sys, time
d, aid, mins, now, model, err = sys.argv[1], sys.argv[2], float(sys.argv[3]), float(sys.argv[4]), sys.argv[5], sys.argv[6]
err = err or "You've hit your session limit · resets 3pm"
os.makedirs(d, exist_ok=True)
t = lambda m: time.strftime("%Y-%m-%dT%H:%M:%S.000Z", time.gmtime(now - m * 60))
recs = [{"type": "user", "timestamp": t(mins + 5), "message": {"content": [{"type": "text", "text": "brief"}]}},
        {"type": "assistant", "timestamp": t(mins), "message": {"model": model, "content": [{"type": "text", "text": "working"}]}},
        {"type": "assistant", "timestamp": t(mins), "isApiErrorMessage": True,
         "message": {"model": "<synthetic>", "content": [{"type": "text", "text": err}]}}]
with open(os.path.join(d, "agent-%s.jsonl" % aid), "w") as f:
    f.write("".join(json.dumps(r) + "\n" for r in recs))
json.dump({"agentType": "general-purpose", "description": "smoke " + aid}, open(os.path.join(d, "agent-%s.meta.json" % aid), "w"))
PY2
}
