_sfl_rc=$(bash "$_sfl_self" --only 'git hooks wiring' --only 'zz-no-such-section-zz' >/dev/null 2>&1; echo $?)
assert_eq "section filter: one dead term among live ones still refuses (per-term, never aggregate)" "2" "$_sfl_rc"
# The path is assembled at run time: written out whole, it would be a body mention in THIS section, and --for
