assert_eq "section filter: a --for path no section names refuses with exit 2" "2" "$_sfl_rc"
_sfl_out=$(bash "$_sfl_self" --for .claude/hooks/lib/warn-emit.sh 2>&1); _sfl_rc=$?
assert_eq "section filter: --for a shared hook lib refuses" "2" "$_sfl_rc"
assert_contains "section filter: ...and demands the full suite" "$_sfl_out" "needs the FULL suite"
_sfl_rc=$(bash "$_sfl_self" --for .claude/settings.json >/dev/null 2>&1; echo $?)
assert_eq "section filter: --for settings.json refuses (the wiring reaches every section)" "2" "$_sfl_rc"
for _sfl_sp in warn-emit.sh lib/warn-emit.sh .claude//settings.json .claude/hooks/../settings.json pre-push; do
  _sfl_rc=$(bash "$_sfl_self" --for "$_sfl_sp" >/dev/null 2>&1; echo $?)
  assert_eq "section filter: --for $_sfl_sp (another spelling of a full-suite file) refuses" "2" "$_sfl_rc"
done
# The other two FULL_ONLY classes, and per-term refusal for --for (each survived a mutant without these arms).
# Paths are assembled at run time for the same reason as _sfl_ghost: a whole basename here is a body mention.
_sfl_rc=$(bash "$_sfl_self" --for ".githooks/pre-""push" >/dev/null 2>&1; echo $?)
assert_eq "section filter: --for a git hook refuses (.githooks/* needs the full suite)" "2" "$_sfl_rc"
_sfl_rc=$(bash "$_sfl_self" --for "scripts/smoke-test-""hooks.sh" >/dev/null 2>&1; echo $?)
assert_eq "section filter: --for the suite itself refuses" "2" "$_sfl_rc"
_sfl_rc=$(bash "$_sfl_self" --only 'git hooks wiring' --for ".claude/hooks/${_sfl_ghost}.sh" >/dev/null 2>&1; echo $?)
assert_eq "section filter: one dead --for among live terms still refuses (per-term)" "2" "$_sfl_rc"
_sfl_rc=$(bash "$_sfl_self" --onyl x >/dev/null 2>&1; echo $?)
assert_eq "section filter: an unknown argument refuses rather than running the full suite" "2" "$_sfl_rc"
_sfl_rc=$(bash "$_sfl_self" --only >/dev/null 2>&1; echo $?)
assert_eq "section filter: --only with no value refuses" "2" "$_sfl_rc"
_sfl_rc=$(SMOKE_FILTER_DEPTH=2 bash "$_sfl_self" --only 'git hooks wiring' >/dev/null 2>&1; echo $?)
assert_eq "section filter: a third nesting level refuses (recursion guard)" "2" "$_sfl_rc"
_sfl_list=$(bash "$_sfl_self" --list 2>/dev/null)
assert_eq "section filter: --list prints one line per section header" \
  "$(grep -cE '^echo "(\\n)?=== .* ==="$' "$_sfl_self")" "$(printf '%s\n' "$_sfl_list" | grep -c '')"
assert_not_contains "section filter: every CORE entry still matches a section header" "$(bash "$_sfl_self" --list 2>&1 >/dev/null)" "CORE entry"
assert_eq "section filter: --list marks exactly 11 CORE sections (a dropped CORE entry reds here)" "11" \
  "$(printf '%s\n' "$_sfl_list" | awk '$2 == "core"' | grep -c '')"
# The hoister takes the FIRST column-0 definition of a name; a bare run uses the last one above the caller.
# They agree only while no name is defined twice, so pin that premise (0 duplicates of 98 on 2026-10-07).
assert_empty "section filter: no function is defined twice at column 0 (the hoister would pick the wrong body)" \
  "$(grep -oE '^[A-Za-z_][A-Za-z0-9_]*[[:space:]]*\(\)[[:space:]]*\{' "$_sfl_self" | sed 's/[[:space:]]*(.*//' | LC_ALL=C sort | LC_ALL=C uniq -d)"
_sfl_out=$(bash "$_sfl_self" --only 'git hooks wiring' 2>/dev/null); _sfl_rc=$?
assert_eq "section filter: a live selection runs and exits 0" "0" "$_sfl_rc"
assert_contains "section filter: ...says PARTIAL on its FIRST line" "$(printf '%s\n' "$_sfl_out" | head -1)" "PARTIAL RUN, NOT THE FULL SUITE"
assert_contains "section filter: ...and on the line just above the tally" \
  "$(printf '%s\n' "$_sfl_out" | grep -B1 '^  PASS: ' | head -1)" "PARTIAL RUN, NOT THE FULL SUITE"

_sfl_fx="$(mktemp -d)"
mkdir -p "$_sfl_fx/scripts"
_sfl_first=$(grep -nE '^echo "(\\n)?=== .* ==="$' "$_sfl_self" | head -1 | cut -d: -f1)
_sfl_tally=$(grep -nxF 'echo "  PASS: $PASS"' "$_sfl_self" | tail -1 | cut -d: -f1)
{
  sed -n "1,$((_sfl_first - 1))p" "$_sfl_self"
  # Each fixture line carries a leading | so its === header === is not a header of THIS file (the filter and
  # the parse-arm gate both find sections by a column-0 echo).
  sed 's/^|//' <<'FX'
|echo "=== fx-alpha ==="
|# names fx-target.sh, so --for <any dir>/fx-target.sh selects this section and no other
|pass "fx-alpha: one arm"
|_fx_helper() { echo helped; }
|
|echo "=== fx-uses-helper ==="
|assert_eq "fx-uses-helper: the helper an unselected section defines is there" "helped" "$(_fx_helper)"
|
|echo "=== fx-unbound ==="
|_fx_got="$(echo "${_fx_never_set}")"
|pass "fx-unbound: reached past the unbound read"
|
|echo "=== fx-crash ==="
|pass "fx-crash: one arm, then the section dies"
|exit 0
|
|echo "=== fx-empty ==="
|: no arms in this section
|
|echo "=== fx-cnf-quiet ==="
|_fx_o=$(_fx_no_such_cmd_zz 2>/dev/null)
|pass "fx-cnf-quiet: one arm after a silenced missing command"
|
|echo "=== fx-stem ==="
|for _fx_s in fx-stemmed; do _fx_o="$(echo ".claude/hooks/$_fx_s.sh")"; done
|pass "fx-stem: one arm"
|
FX
  sed -n "${_sfl_tally},\$p" "$_sfl_self"
} > "$_sfl_fx/scripts/smoke-test-hooks.sh"
_sfl_out=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --only fx-uses-helper 2>/dev/null); _sfl_rc=$?
assert_eq "section filter: a helper defined in an unselected section is hoisted (exit 0)" "0" "$_sfl_rc"
assert_contains "section filter: ...and the banner names it" "$_sfl_out" "hoisted from unselected sections: _fx_helper()"
_sfl_out=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --only fx-unbound 2>&1 >/dev/null); _sfl_rc=$?
assert_eq "section filter: an unbound read in a running section makes the exit 3, not 0" "3" "$_sfl_rc"
assert_contains "section filter: ...and names the variable" "$_sfl_out" "_fx_never_set: unbound variable"
_sfl_out=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --only fx-crash 2>&1 >/dev/null); _sfl_rc=$?
assert_eq "section filter: a section that exits before the tally makes the exit 3, even at rc 0" "3" "$_sfl_rc"
assert_contains "section filter: ...and says it ABORTED" "$_sfl_out" "ABORTED before the tally"
_sfl_rc=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --only fx-empty >/dev/null 2>&1; echo $?)
assert_eq "section filter: a selection that runs ZERO arms refuses with exit 2" "2" "$_sfl_rc"
_sfl_out=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --for some/dir/fx-target.sh 2>/dev/null); _sfl_rc=$?
assert_eq "section filter: --for selects by a body mention and exits 0" "0" "$_sfl_rc"
assert_contains "section filter: ...selecting the section that names the file" "$_sfl_out" "+ fx-alpha"
assert_not_contains "section filter: ...and no section that does not" "$_sfl_out" "+ fx-uses-helper"
_sfl_rc=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --only fx-cnf-quiet >/dev/null 2>&1; echo $?)
assert_eq "section filter: a missing command inside a silenced command substitution makes the exit 3, not 0" "3" "$_sfl_rc"
_sfl_out=$(bash "$_sfl_fx/scripts/smoke-test-hooks.sh" --for some/dir/fx-stemmed.sh 2>/dev/null); _sfl_rc=$?
assert_eq "section filter: --for selects a section that reaches the file only by its stem (exit 0)" "0" "$_sfl_rc"
assert_contains "section filter: ...naming that section" "$_sfl_out" "+ fx-stem"
rm -rf "$_sfl_fx"

echo "=== limit-recovery-check.sh (UserPromptSubmit, warn-mode — names this session's sub-agents that died at a usage limit until a recovery is recorded) ==="
# Every arm runs against a FIXTURE transcript dir and a FIXTURE state dir through the script's own env
# overrides (LIMIT_RECOVERY_SUBAGENTS_DIR / LIMIT_RECOVERY_STATE_DIR), so nothing here reads the live
# transcript tree or writes .claude/state. The dead reader's transcript has the measured shape: a
# user brief, one live assistant tool_use, then an assistant record with isApiErrorMessage and a <synthetic>
# model carrying the harness's limit line, and no SubagentHandback tool_use anywhere.
_lr_dir="$(mktemp -d)"; mkdir -p "$_lr_dir/sub" "$_lr_dir/state"
printf '%s\n' \
  '{"type":"user","timestamp":"2026-10-12T05:00:00.000Z","message":{"content":[{"type":"text","text":"BRIEF read X"}]}}' \
  '{"type":"assistant","timestamp":"2026-10-12T05:01:00.000Z","message":{"model":"m","content":[{"type":"tool_use","id":"t1","name":"Read","input":{"file_path":"/x"}}]}}' \
  '{"type":"assistant","timestamp":"2026-10-12T05:02:00.000Z","isApiErrorMessage":true,"message":{"model":"<synthetic>","content":[{"type":"text","text":"You have hit your session limit - resets 9:10am"}]}}' \
  > "$_lr_dir/sub/agent-smkdead1.jsonl"
# the same death dated before the detector's start (DETECTION_EPOCH) — in its
# own dir, so the FIRE arms above still see exactly one death
mkdir -p "$_lr_dir/old"
sed 's/2026-10-12T05:0/2026-10-12T03:0/' "$_lr_dir/sub/agent-smkdead1.jsonl" > "$_lr_dir/old/agent-smkold1.jsonl"
printf '%s' '{"agentType":"general-purpose","description":"smoke dead reader"}' > "$_lr_dir/sub/agent-smkdead1.meta.json"
_lr() { printf '{"session_id":"%s","prompt":"x"}' "$1" | LIMIT_RECOVERY_SESSION_MODEL= LIMIT_RECOVERY_SUBAGENTS_DIR="$2" LIMIT_RECOVERY_STATE_DIR="$_lr_dir/state" bash .claude/hooks/limit-recovery-check.sh 2>/dev/null; }
lr_fire="$(_lr smklr-0000 "$_lr_dir/sub")"
assert_one_json_doc "PARSE: limit-recovery-check.sh dead reader → ONE parseable UserPromptSubmit hookSpecificOutput doc naming the dead agent" "$lr_fire" "smoke dead reader"
assert_contains "FIRE: ...the doc carries the decision row (a cold, small death reads RESUME)" "$lr_fire" "RESUME"
assert_contains "FIRE: ...and routes the seat to the skill" "$lr_fire" "/limit-recovery"
assert_empty "SAFE: SKIP_LIMIT_RECOVERY_CHECK=1 silences the dead-reader fixture (escape hatch)" "$(printf '{"session_id":"smklr-0000"}' | SKIP_LIMIT_RECOVERY_CHECK=1 LIMIT_RECOVERY_SUBAGENTS_DIR="$_lr_dir/sub" LIMIT_RECOVERY_STATE_DIR="$_lr_dir/state" bash .claude/hooks/limit-recovery-check.sh 2>/dev/null)"
assert_eq "limit-recovery-check: the pre-cutoff fixture really is dated before the cutoff (control)" "3" "$(grep -cF '2026-10-12T03:0' "$_lr_dir/old/agent-smkold1.jsonl")"
assert_empty "SAFE: a death before the detector's start date is silent (handled by hand or not at all, and nothing records which)" "$(_lr smklr-0001 "$_lr_dir/old")"
assert_contains "limit-recovery.py: scan --all still lists the pre-cutoff death, flagged" "$(LIMIT_RECOVERY_SESSION_MODEL= LIMIT_RECOVERY_SUBAGENTS_DIR="$_lr_dir/old" LIMIT_RECOVERY_STATE_DIR="$_lr_dir/state" python3 scripts/limit-recovery.py scan --all --sid smklr-0001 2>&1)" "pre-epoch"
# a recorded recovery silences the hook — the detector's whole exit path
LIMIT_RECOVERY_SUBAGENTS_DIR="$_lr_dir/sub" LIMIT_RECOVERY_STATE_DIR="$_lr_dir/state" python3 scripts/limit-recovery.py mark smkdead1 --as fresh --sid smklr-0000 >/dev/null
assert_empty "SAFE: a death marked as recovered is silent" "$(_lr smklr-0000 "$_lr_dir/sub")"
assert_contains "limit-recovery.py: scan --all lists that death with its mark (the silence above is the mark, not a crash the hook swallows)" "$(LIMIT_RECOVERY_SESSION_MODEL= LIMIT_RECOVERY_SUBAGENTS_DIR="$_lr_dir/sub" LIMIT_RECOVERY_STATE_DIR="$_lr_dir/state" python3 scripts/limit-recovery.py scan --all --sid smklr-0000 2>&1)" "handled=fresh"
assert_empty "SAFE: a session with no transcript dir is silent" "$(_lr smklr-none "$_lr_dir/nope")"
lr_rc=$(printf 'not json' | LIMIT_RECOVERY_SUBAGENTS_DIR="$_lr_dir/nope" bash .claude/hooks/limit-recovery-check.sh >/dev/null 2>&1; echo $?)
assert_eq "limit-recovery-check: a malformed payload exits 0" "0" "$lr_rc"
assert_empty "limit-recovery-check: ...and is silent" "$(printf 'not json' | LIMIT_RECOVERY_SUBAGENTS_DIR="$_lr_dir/nope" bash .claude/hooks/limit-recovery-check.sh 2>/dev/null)"
assert_contains "limit-recovery.py: its own --self-test is clean (every decision-table row, the hook doc, the digest, the mark)" "$(python3 scripts/limit-recovery.py --self-test 2>&1)" "self-test: 0 failed"
rm -rf "$_lr_dir"

echo "  PASS: $PASS"
echo "  FAIL: $FAIL"

if [[ $FAIL -gt 0 ]]; then
  echo ""
  echo "Failures:"
  for f in "${FAILS[@]}"; do
    echo "  - $f"
  done
  exit 1
fi

exit 0
